{
  "timeline": [
    {
      "headline": "Operation Gibraltar",
      "text": "In August 1965, Pakistan launched Operation Gibraltar, an attempt to infiltrate forces into Jammu and Kashmir to incite an insurgency against Indian rule.",
      "date": "1965-08"
    },
    {
      "headline": "Start of the Indo-Pakistani War of 1965",
      "text": "The Indo-Pakistani War of 1965 began in August 1965 following the failure of Operation Gibraltar. The conflict escalated into a full-scale war between India and Pakistan.",
      "date": "1965-08"
    },
    {
      "headline": "Largest Tank Battle Since World War II",
      "text": "During the war, the largest tank battle since World War II took place, involving significant armoured engagements between Indian and Pakistani forces.",
      "date": "1965-09"
    },
    {
      "headline": "Ceasefire Declared",
      "text": "Hostilities between India and Pakistan ended after a ceasefire was declared on September 23, 1965, following diplomatic intervention by the Soviet Union and the United States.",
      "date": "1965-09-23"
    },
    {
      "headline": "UNSC Resolution 211",
      "text": "The ceasefire was facilitated by United Nations Security Council Resolution 211, which called for a cessation of hostilities and a return to pre-war positions.",
      "date": "1965-09"
    },
    {
      "headline": "Tashkent Declaration",
      "text": "The Tashkent Declaration was issued on January 10, 1966, following the war, where both countries agreed to withdraw to pre-August lines and restore economic and diplomatic relations.",
      "date": "1966-01-10"
    }
  ]
}

