{
  "timeline": [
    {
      "headline": "Founding of Albertsons",
      "text": "Albertsons was founded by Joe Albertson on July 21, 1939, in Boise, Idaho. The first store was located at 16th and State Streets.",
      "date": "1939-07-21"
    },
    {
      "headline": "Expansion in the 1950s",
      "text": "During the 1950s, Albertsons expanded its operations by opening new stores in neighboring states, including Oregon and Washington.",
      "date": "1950"
    },
    {
      "headline": "Public Offering",
      "text": "Albertsons went public in 1959, offering its stock on the American Stock Exchange.",
      "date": "1959"
    },
    {
      "headline": "Acquisition of Skaggs Companies",
      "text": "In 1963, Albertsons acquired the Skaggs Companies, which helped expand its presence in the grocery industry.",
      "date": "1963"
    },
    {
      "headline": "Introduction of Superstores",
      "text": "Albertsons introduced its first superstore in 1966, combining a grocery store with a drugstore.",
      "date": "1966"
    },
    {
      "headline": "Merger with American Stores Company",
      "text": "In 1999, Albertsons merged with American Stores Company, significantly increasing its size and market presence.",
      "date": "1999"
    },
    {
      "headline": "Sale to SuperValu and Cerberus Capital Management",
      "text": "In 2006, Albertsons was sold to SuperValu, Cerberus Capital Management, and CVS Pharmacy, with Cerberus acquiring a portion of the stores.",
      "date": "2006"
    },
    {
      "headline": "Acquisition of Safeway",
      "text": "Albertsons announced its acquisition of Safeway Inc. in 2014, a deal that was completed in January 2015, making it one of the largest grocery chains in the United States.",
      "date": "2015-01"
    },
    {
      "headline": "Attempted Merger with Rite Aid",
      "text": "In 2018, Albertsons announced a plan to merge with Rite Aid, but the deal was called off in August 2018 after facing opposition from shareholders.",
      "date": "2018-08"
    },
    {
      "headline": "Initial Public Offering",
      "text": "Albertsons Companies went public again on June 26, 2020, with an initial public offering on the New York Stock Exchange.",
      "date": "2020-06-26"
    }
  ]
}

