    },
    {
      "headline": "Voluntary Upgrade Program",
      "text": "In August 2017, SIG Sauer announced a voluntary upgrade program for the P320, addressing concerns about the pistol's drop safety.",
      "date": "2017-08"
    },
    {
      "headline": "Adoption by Other Military Forces",
      "text": "Following its adoption by the U.S. Army, the P320 was also adopted by various other military and law enforcement agencies around the world, including the Danish Ministry of Defense in 2018.",
      "date": "2018"
    },
    {
      "headline": "Introduction of the SIG Sauer P320 XCompact",
      "text": "In 2019, SIG Sauer introduced the P320 XCompact, a variant of the P320 designed for concealed carry with a smaller frame and slide.",
      "date": "2019"
    }
  ]
}

