{
  "timeline": [
    {
      "headline": "Early Use of Mockumentary Style",
      "text": "The mockumentary style can be traced back to the early 20th century, with early examples like the 1938 radio broadcast 'The War of the Worlds' by Orson Welles, which simulated a news broadcast.",
      "date": "1938"
    },
    {
      "headline": "First Use of the Term 'Mockumentary'",
      "text": "The term 'mockumentary' originated in the 1960s, though it was not widely used until later.",
      "date": "1960"
    },
    {
      "headline": "Release of 'This Is Spinal Tap'",
      "text": "The film 'This Is Spinal Tap', directed by Rob Reiner, was released in 1984. It is one of the most famous examples of a mockumentary and helped popularize the term.",
      "date": "1984"
    },
    {
      "headline": "Rise in Popularity of Mockumentaries",
      "text": "The 1990s and 2000s saw a rise in the popularity of mockumentaries, with television shows like 'The Office' (UK, 2001) and films like 'Best in Show' (2000) gaining critical acclaim.",
      "date": "2000"
    },
    {
      "headline": "Mockumentary in Modern Media",
      "text": "Mockumentaries continue to be a popular format in modern media, with shows like 'Parks and Recreation' (2009) and 'Modern Family' (2009) using the style to great effect.",
      "date": "2009"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Migration to Europe",
      "text": "Cro-Magnons, or European early modern humans (EEMH), began migrating from western Asia into Europe, continuously occupying the continent possibly from as early as 56,800 years ago.",
      "date": "-056800"
    },
    {
      "headline": "Interaction with Neanderthals",
      "text": "Cro-Magnons interacted and interbred with the indigenous Neanderthals of Europe and Western Asia, who went extinct between 40,000 to 35,000 years ago.",
      "date": "-040000"
    },
    {
      "headline": "Second Wave of Modern Humans",
      "text": "From 37,000 years ago, a second wave of modern humans succeeded in forming a single founder population, from which all subsequent Cro-Magnons descended and which contributes ancestry to present-day Europeans.",
      "date": "-037000"
    },
    {
      "headline": "Aurignacian Culture",
      "text": "Cro-Magnons produced Upper Palaeolithic cultures, the first major one being the Aurignacian culture.",
      "date": "-037000"
    },
    {
      "headline": "Gravettian Culture",
      "text": "By 30,000 years ago, the Aurignacian culture was succeeded by the Gravettian culture.",
      "date": "-030000"
    },
    {
      "headline": "Climatic Degradation and Cultural Split",
      "text": "Due to major climatic degradation during the Last Glacial Maximum, peaking 21,000 years ago, the Gravettian culture split into the Epi-Gravettian in the east and Solutrean in the west.",
      "date": "-021000"
    },
    {
      "headline": "Evolution into Magdalenian Culture",
      "text": "As Europe warmed, the Solutrean culture evolved into the Magdalenian culture by 20,000 years ago, and these peoples recolonised Europe.",
      "date": "-020000"
    },
    {
      "headline": "Transition to Mesolithic Cultures",
      "text": "The Magdalenian and Epi-Gravettian cultures gave way to Mesolithic cultures as big game animals were dying out and the Last Glacial Period drew to a close.",
      "date": "-012000"
    }
  ]
}

