{
  "timeline": [
    {
      "headline": "First Massacre at Babi Yar",
      "text": "On 29–30 September 1941, Nazi forces carried out the first and best-documented massacre at Babi Yar, where approximately 33,771 Jews were murdered.",
      "date": "1941-09-29"
    },
    {
      "headline": "Continued Massacres",
      "text": "Following the initial massacre, Babi Yar became the site of ongoing executions of various groups, including Soviet prisoners of war, communists, and Romani people. These continued throughout the German occupation of Kyiv.",
      "date": "1941"
    },
    {
      "headline": "Liberation of Kyiv",
      "text": "The city of Kyiv, including the site of Babi Yar, was liberated by Soviet forces on 6 November 1943, ending the period of Nazi occupation.",
      "date": "1943-11-06"
    },
    {
      "headline": "Post-War Recognition and Memorials",
      "text": "In the years following World War II, Babi Yar became a symbol of the Holocaust and the atrocities committed by the Nazis. Various memorials have been established to commemorate the victims.",
      "date": "1945"
    }
  ]
}

