{
  "timeline": [
    {
      "headline": "Swimming Debuts at the First Modern Olympics",
      "text": "Swimming was included as a sport at the first modern Olympic Games in Athens, Greece, in 1896. The events were held in open water, and only men were allowed to compete.",
      "date": "1896"
    },
    {
      "headline": "Introduction of Women's Swimming",
      "text": "Women's swimming events were introduced at the Stockholm Olympics in 1912, marking the first time women were allowed to compete in swimming at the Olympic Games.",
      "date": "1912"
    },
    {
      "headline": "First Indoor Swimming Pool at the Olympics",
      "text": "The 1908 London Olympics featured the first swimming events held in an indoor pool, which was 100 meters long.",
      "date": "1908"
    },
    {
      "headline": "Butterfly Stroke Introduced",
      "text": "The butterfly stroke was introduced as a separate event at the Melbourne Olympics in 1956, having previously been swum as a variant of the breaststroke.",
      "date": "1956"
    },
    {
      "headline": "Electronic Timing Introduced",
      "text": "Electronic timing was introduced at the 1968 Mexico City Olympics, providing more accurate timing for swimming events.",
      "date": "1968"
    },
    {
      "headline": "Michael Phelps Breaks Record",
      "text": "At the 2008 Beijing Olympics, Michael Phelps won eight gold medals, breaking the record for the most gold medals won by an individual in a single Olympic Games.",
      "date": "2008"
    },
    {
      "headline": "Mixed-Gender Relay Introduced",
      "text": "The 2020 Tokyo Olympics saw the introduction of the mixed-gender 4x100 meter medley relay, marking the first time men and women competed together in a swimming event at the Olympics.",
      "date": "2021"
    }
  ]
}

