  ]
}

{
  "timeline": [
    {
      "headline": "First Identified Outbreak",
      "text": "The first known outbreak of Ebola virus disease occurred in 1976 in two simultaneous outbreaks in Nzara, South Sudan, and Yambuku, Democratic Republic of the Congo. The latter was in a village near the Ebola River, from which the disease takes its name.",
      "date": "1976"
    },
    {
      "headline": "Discovery of Ebola Virus",
      "text": "The Ebola virus was first discovered in 1976 by a team led by Dr. Peter Piot in Yambuku, Democratic Republic of the Congo. The virus was named after the Ebola River, which is near the village where the outbreak occurred.",
      "date": "1976"
    },
    {
      "headline": "Ebola Outbreak in Kikwit",
      "text": "In 1995, a major outbreak of Ebola occurred in Kikwit, Democratic Republic of the Congo, resulting in 315 cases and 254 deaths.",
      "date": "1995"
    },
    {
      "headline": "Uganda Outbreak",
      "text": "In 2000, Uganda experienced an Ebola outbreak in the Gulu district, with 425 cases and 224 deaths.",
      "date": "2000"
    },
    {
      "headline": "Ebola Outbreak in West Africa",
      "text": "The largest outbreak of Ebola began in December 2013 in Guinea and spread to Liberia and Sierra Leone, causing widespread devastation. The World Health Organization declared it a Public Health Emergency of International Concern in August 2014.",
      "date": "2013-12"
    },
    {
      "headline": "Ebola Vaccine Approval",
      "text": "In December 2019, the US Food and Drug Administration (FDA) approved the first Ebola vaccine, Ervebo, which is effective against the Zaire ebolavirus species.",
      "date": "2019-12"
    }
  ]
}

