{
  "timeline": [
    {
      "headline": "Edo Period and Tokugawa Class System",
      "text": "During the Edo period (1603-1868), the Tokugawa shogunate established a rigid class system. The burakumin, consisting of eta and hinin, were considered outcasts and were assigned occupations associated with death and impurity, such as executioners, undertakers, and tanners.",
      "date": "1603"
    },
    {
      "headline": "Abolition of the Feudal System",
      "text": "In 1869, following the Meiji Restoration, the feudal class system was officially abolished. However, the burakumin continued to face social discrimination despite the legal changes.",
      "date": "1869"
    },
    {
      "headline": "Emancipation Edict",
      "text": "In 1871, the Emancipation Edict was issued, which aimed to eliminate the legal distinctions between the burakumin and other Japanese citizens. Despite this, social discrimination persisted.",
      "date": "1871"
    },
    {
      "headline": "Formation of the Levelers Association",
      "text": "In 1922, the Suiheisha (Levelers Association) was formed by burakumin leaders to advocate for the rights and social integration of the burakumin community.",
      "date": "1922"
    },
    {
      "headline": "Post-War Constitution and Human Rights",
      "text": "After World War II, the new Japanese Constitution of 1947 included provisions for equal rights and the prohibition of discrimination. However, the burakumin continued to face social challenges.",
      "date": "1947"
    },
    {
      "headline": "Dowa Policy",
      "text": "In 1969, the Japanese government implemented the Dowa policy, which aimed to improve living conditions and reduce discrimination against the burakumin through various social and economic measures.",
      "date": "1969"
    },
    {
      "headline": "End of Dowa Policy",
      "text": "In 2002, the Dowa policy officially ended, but efforts to address discrimination against the burakumin continued through other social initiatives.",
      "date": "2002"
    }
  ]
}

