{
  "timeline": [
    {
      "headline": "Foundation of the International Labour Organization",
      "text": "The International Labour Organization (ILO) was founded in October 1919 under the League of Nations. It was established to advance social and economic justice by setting international labour standards.",
      "date": "1919-10"
    },
    {
      "headline": "First International Labour Conference",
      "text": "The first International Labour Conference was held in Washington, D.C., in October 1919, shortly after the ILO's founding.",
      "date": "1919-10"
    },
    {
      "headline": "Adoption of the First International Labour Conventions",
      "text": "In 1919, the ILO adopted its first six International Labour Conventions, covering topics such as hours of work, unemployment, maternity protection, night work for women, minimum age, and night work for young persons in industry.",
      "date": "1919"
    },
    {
      "headline": "Nobel Peace Prize Award",
      "text": "The ILO was awarded the Nobel Peace Prize in 1969, recognizing its efforts to improve peace among classes, pursue decent work and justice for workers, and provide technical assistance to other developing nations.",
      "date": "1969"
    },
    {
      "headline": "Declaration on Fundamental Principles and Rights at Work",
      "text": "In 1998, the ILO adopted the Declaration on Fundamental Principles and Rights at Work, which commits member states to respect and promote principles and rights in four categories: freedom of association and the right to collective bargaining, the elimination of forced or compulsory labour, the abolition of child labour, and the elimination of discrimination in respect of employment and occupation.",
      "date": "1998"
    },
    {
      "headline": "ILO's 100th Anniversary",
      "text": "In 2019, the ILO celebrated its 100th anniversary, marking a century of efforts to improve working conditions and promote social justice worldwide.",
      "date": "2019"
    }
  ]
}

