{
  "timeline": [
    {
      "headline": "Formation of the 160th Special Operations Aviation Regiment",
      "text": "The 160th Special Operations Aviation Regiment (Airborne), also known as the Night Stalkers, was officially formed in 1981. The unit was established following the failed Operation Eagle Claw, the attempted rescue of American hostages in Iran, which highlighted the need for a dedicated special operations aviation unit.",
      "date": "1981"
    },
    {
      "headline": "Operation Urgent Fury",
      "text": "In October 1983, the 160th SOAR participated in Operation Urgent Fury, the U.S.-led invasion of Grenada. The regiment provided critical aviation support for special operations forces during the mission.",
      "date": "1983-10"
    },
    {
      "headline": "Operation Just Cause",
      "text": "In December 1989, the 160th SOAR played a significant role in Operation Just Cause, the invasion of Panama. The regiment's helicopters were used to insert special operations forces to capture key objectives.",
      "date": "1989-12"
    },
    {
      "headline": "Operation Desert Storm",
      "text": "During the Gulf War in 1991, the 160th SOAR was involved in Operation Desert Storm. The regiment provided aviation support for special operations missions in Iraq and Kuwait.",
      "date": "1991"
    },
    {
      "headline": "Battle of Mogadishu",
      "text": "In October 1993, the 160th SOAR participated in the Battle of Mogadishu in Somalia. The regiment's helicopters were involved in the mission to capture Somali warlord Mohamed Farrah Aidid, which resulted in a fierce battle.",
      "date": "1993-10"
    },
    {
      "headline": "Operation Enduring Freedom",
      "text": "Following the September 11 attacks in 2001, the 160th SOAR was deployed to Afghanistan as part of Operation Enduring Freedom. The regiment provided critical aviation support for special operations forces in the region.",
      "date": "2001"
    },
    {
      "headline": "Operation Iraqi Freedom",
      "text": "In 2003, the 160th SOAR was involved in Operation Iraqi Freedom, the U.S.-led invasion of Iraq. The regiment supported special operations missions throughout the conflict.",
      "date": "2003"
    }
  ]
}

