  "timeline": [
    {
      "headline": "Birth of Lisa del Giocondo",
      "text": "Lisa del Giocondo was born on June 15, 1479, in Florence, Italy. She was born into the Gherardini family, a noble family in Florence and Tuscany.",
      "date": "1479-06-15"
    },
    {
      "headline": "Marriage to Francesco del Giocondo",
      "text": "In 1495, Lisa married Francesco di Bartolomeo di Zanobi del Giocondo, a wealthy Florentine silk merchant. This marriage elevated her status in Florentine society.",
