      "headline": "Foundation of Yasukuni Shrine",
      "text": "Yasukuni Shrine was founded by Emperor Meiji in June 1869. It was established to commemorate those who died in service of Japan, starting with the Boshin War of 1868–1869.",
      "date": "1869-06"
    },
    {
      "headline": "Commemoration of Sino-Japanese War Dead",
      "text": "The shrine expanded its purpose to include those who died in the First Sino-Japanese War of 1894–1895.",
      "date": "1895"
    },
    {
      "headline": "Inclusion of Russo-Japanese War Dead",
      "text": "Yasukuni Shrine began to commemorate those who died in the Russo-Japanese War of 1904–1905.",
      "date": "1905"
    },
    {
      "headline": "Expansion to Include World War I Dead",
      "text": "The shrine's purpose was further expanded to include those who died in World War I (1914–1918).",
      "date": "1918"
    },
    {
      "headline": "Commemoration of Second Sino-Japanese War Dead",
      "text": "Yasukuni Shrine included those who died in the Second Sino-Japanese War of 1937–1945.",
      "date": "1945"
    },
    {
      "headline": "Inclusion of World War II Dead",
      "text": "The shrine expanded to commemorate those who died in World War II, including the Pacific War (1941–1945).",
      "date": "1945"
    },
    {
      "headline": "Inclusion of First Indochina War Dead",
      "text": "Yasukuni Shrine began to include those who died in the First Indochina War of 1946–1954.",
      "date": "1954"
    },
    {
      "headline": "Controversy Over War Criminals",
      "text": "The shrine became controversial due to the enshrinement of Class A war criminals from World War II in 1978.",
      "date": "1978"
    }
  ]
}

