{
  "timeline": [
    {
      "headline": "September 11 Attacks",
      "text": "On September 11, 2001, al-Qaeda executed a series of coordinated terrorist attacks on the United States, leading to the deaths of nearly 3,000 people.",
      "date": "2001-09-11"
    },
    {
      "headline": "United States Declares War on Terror",
      "text": "Following the September 11 attacks, the United States declared a global War on Terror, targeting al-Qaeda and its affiliates.",
      "date": "2001-09"
    },
    {
      "headline": "Invasion of Afghanistan Begins",
      "text": "On October 7, 2001, the United States, with support from the United Kingdom and other allies, launched a military invasion of Afghanistan to dismantle al-Qaeda and remove the Taliban from power.",
      "date": "2001-10-07"
    },
    {
      "headline": "Fall of Kabul",
      "text": "On November 13, 2001, Northern Alliance forces, supported by U.S. airstrikes, captured Kabul, the capital of Afghanistan, from the Taliban.",
      "date": "2001-11-13"
    },
    {
      "headline": "Battle of Tora Bora",
      "text": "In December 2001, U.S. and allied forces engaged in the Battle of Tora Bora, attempting to capture Osama bin Laden in the mountainous region of eastern Afghanistan.",
      "date": "2001-12"
    },
    {
      "headline": "Establishment of Interim Afghan Government",
      "text": "In December 2001, the Bonn Agreement led to the establishment of an interim Afghan government, with Hamid Karzai as its head.",
      "date": "2001-12"
    },
    {
      "headline": "Operation Anaconda",
      "text": "In March 2002, Operation Anaconda was launched as a major U.S.-led military offensive against Taliban and al-Qaeda forces in the Shahi-Kot Valley.",
      "date": "2002-03"
    },
    {
      "headline": "NATO Assumes Command of ISAF",
      "text": "In August 2003, NATO assumed command of the International Security Assistance Force (ISAF) in Afghanistan, marking its first operational commitment outside Europe.",
      "date": "2003-08"
    },
    {
      "headline": "Capture of Saddam Hussein",
      "text": "On December 13, 2003, U.S. forces captured Saddam Hussein in Iraq, shifting some focus away from Afghanistan.",
      "date": "2003-12-13"
    },
    {
      "headline": "Obama Announces Troop Surge",
      "text": "On December 1, 2009, President Barack Obama announced a surge of 30,000 additional U.S. troops to Afghanistan to combat the Taliban insurgency.",
      "date": "2009-12-01"
    },
    {
      "headline": "Death of Osama bin Laden",
      "text": "On May 2, 2011, Osama bin Laden was killed by U.S. Navy SEALs in Abbottabad, Pakistan, marking a significant milestone in the War on Terror.",
      "date": "2011-05-02"
    },
    {
      "headline": "End of U.S. Combat Mission",
      "text": "On December 28, 2014, the U.S. formally ended its combat mission in Afghanistan, transitioning to a support role for Afghan forces.",
      "date": "2014-12-28"
    },
    {
      "headline": "U.S. and Taliban Sign Peace Agreement",
      "text": "On February 29, 2020, the U.S. and the Taliban signed a peace agreement in Doha, Qatar, outlining the withdrawal of U.S. troops and the start of intra-Afghan negotiations.",
      "date": "2020-02-29"
    },
    {
      "headline": "U.S. Completes Withdrawal from Afghanistan",
      "text": "On August 30, 2021, the United States completed its military withdrawal from Afghanistan, ending nearly 20 years of military involvement.",
      "date": "2021-08-30"
    }
  ]
}

