    },
    {
      "headline": "Renovation and Expansion",
      "text": "During the reign of Empress Elizabeth, the Amber Room was expanded and renovated by Italian designer Bartolomeo Rastrelli.",
      "date": "1755"
    },
    {
      "headline": "Disappearance during World War II",
      "text": "In 1941, during World War II, the Amber Room was looted by Nazi Germany and transported to Königsberg (now Kaliningrad, Russia).",
      "date": "1941"
    },
    {
      "headline": "Destruction or Loss",
      "text": "The Amber Room was last seen in Königsberg in 1945, after which it was lost or destroyed during the final months of World War II.",
      "date": "1945"
