{
  "timeline": [
    {
      "headline": "Old English Period Begins",
      "text": "The earliest forms of English, a set of Anglo-Frisian dialects, were brought to Great Britain by Anglo-Saxon settlers in the 5th century.",
      "date": "0400"
    },
    {
      "headline": "Beowulf Composed",
      "text": "Beowulf, the most famous work in Old English, was composed. Despite being set in Scandinavia, it has achieved national epic status in England.",
      "date": "0700"
    },
    {
      "headline": "Norman Conquest of England",
      "text": "Following the Norman conquest of England in 1066, the written form of the Anglo-Saxon language became less common, and French became the standard language of courts, parliament, and polite society.",
      "date": "1066"
    },
    {
      "headline": "Middle English Period Begins",
      "text": "The English spoken after the Normans came is known as Middle English. This form of English lasted until the 1470s.",
      "date": "1100"
    },
    {
      "headline": "Geoffrey Chaucer's Birth",
      "text": "Geoffrey Chaucer, author of The Canterbury Tales, was born in 1343. He was a significant figure in developing the legitimacy of vernacular Middle English.",
      "date": "1343"
    },
    {
      "headline": "Geoffrey Chaucer's Death",
      "text": "Geoffrey Chaucer died in 1400. He was instrumental in legitimizing Middle English as a literary language.",
      "date": "1400"
    },
    {
      "headline": "Chancery Standard Becomes Widespread",
      "text": "The Chancery Standard, a London-based form of English, became widespread in the 1470s, marking the end of the Middle English period.",
      "date": "1470"
    },
    {
      "headline": "Invention of the Printing Press",
      "text": "The invention of the printing press by Johannes Gutenberg in 1439 helped to standardize the English language.",
      "date": "1439"
    },
    {
      "headline": "Publication of the King James Bible",
      "text": "The King James Bible was published in 1611, contributing to the standardization of the English language.",
      "date": "1611"
    },
    {
      "headline": "Great Vowel Shift",
      "text": "The Great Vowel Shift, a major change in the pronunciation of the English language, occurred between 1400 and 1600, significantly affecting the English language.",
      "date": "1400"
    }
  ]
}

