    },
    {
      "headline": "Evolution into House Ballroom",
      "text": "In the mid-20th century, as a response to racism in integrated drag spaces, the balls evolved into house ballroom culture. This allowed Black and Latino attendees to 'walk' in various categories for trophies and cash prizes.",
      "date": "1950"
    },
    {
      "headline": "Formation of Houses",
      "text": "Participants in ballroom culture began forming 'houses', which are chosen families of friends that provide support and community, often separate from their families of origin.",
      "date": "1950"
    },
    {
      "headline": "Influence on Popular Culture",
      "text": "Ballroom culture has significantly influenced dance, language, music, and popular culture, with its impact visible in various mainstream media and entertainment.",
      "date": "1980"
    },
    {
      "headline": "Ballroom Culture Today",
      "text": "The ballroom community continues to thrive today, maintaining its cultural significance and influence on contemporary society.",
      "date": "2023"
    }
  ]
}

