{
  "timeline": [
    {
      "headline": "Introduction of Favicons",
      "text": "Favicons were first introduced by Microsoft in Internet Explorer 5, released in March 1999. They were initially used to display a website's logo in the address bar and bookmarks.",
      "date": "1999-03"
    },
    {
      "headline": "Standardization of Favicons",
      "text": "In 2000, the World Wide Web Consortium (W3C) began to standardize the use of favicons, allowing them to be used across different web browsers.",
      "date": "2000"
    },
    {
      "headline": "Expansion of Favicon Usage",
      "text": "By the mid-2000s, favicons became widely supported by most major web browsers, including Mozilla Firefox and Google Chrome, enhancing user experience by providing visual cues for website identification.",
      "date": "2005"
    },
    {
      "headline": "Introduction of High-Resolution Favicons",
      "text": "With the advent of high-resolution displays, favicons evolved to support larger sizes and higher resolutions, such as 32x32 pixels and 64x64 pixels, to maintain clarity and quality.",
      "date": "2010"
    },
    {
      "headline": "Favicons in Mobile Browsing",
      "text": "As mobile browsing became prevalent, favicons were adapted for mobile devices, appearing in mobile browsers and as icons for web apps on home screens.",
      "date": "2015"
    }
  ]
}

