{
  "timeline": [
    {
      "headline": "Death of Diana, Princess of Wales",
      "text": "Diana, Princess of Wales, died in a car crash in the Pont de l'Alma tunnel in Paris on 31 August 1997.",
      "date": "1997-08-31"
    },
    {
      "headline": "French Investigation Conclusion",
      "text": "In 1999, a French investigation concluded that Diana died as the result of a crash. French investigator, Judge Hervé Stephan, concluded that the paparazzi were some distance from the Mercedes S280 when it crashed and were not responsible for manslaughter.",
      "date": "1999"
    },
    {
      "headline": "British Inquest Verdict",
      "text": "In 2008, after hearing evidence at the British inquest, a jury returned a verdict of 'unlawful killing' by driver Henri Paul and the paparazzi pursuing the car. The jury's verdict also stated that the death was contributed to by the fact that the deceased were not wearing a seat belt and by the fact that the Mercedes struck the pillar in the Pont de l'Alma tunnel.",
      "date": "2008"
    }
  ]
}

{
  "timeline": [
