      "headline": "Publication of The House of Mirth",
      "text": "Edith Wharton's novel The House of Mirth was published in 1905, bringing her significant acclaim.",
      "date": "1905"
    },
    {
      "headline": "Publication of Ethan Frome",
      "text": "In 1911, Edith Wharton published the novella Ethan Frome, which became one of her most famous works.",
      "date": "1911"
    },
    {
      "headline": "Divorce from Edward Wharton",
      "text": "Edith Wharton divorced Edward Wharton in 1913 after years of an unhappy marriage.",
      "date": "1913"
    },
    {
      "headline": "Publication of The Age of Innocence",
      "text": "In 1920, Edith Wharton published The Age of Innocence, which won the Pulitzer Prize for Fiction.",
      "date": "1920"
    },
    {
      "headline": "First Woman to Win the Pulitzer Prize for Fiction",
      "text": "In 1921, Edith Wharton became the first woman to win the Pulitzer Prize for Fiction for her novel The Age of Innocence.",
      "date": "1921"
    },
    {
      "headline": "Induction into the National Women's Hall of Fame",
      "text": "Edith Wharton was posthumously inducted into the National Women's Hall of Fame in 1996.",
      "date": "1996"
    },
    {
      "headline": "Death of Edith Wharton",
      "text": "Edith Wharton died on August 11, 1937, in Saint-Brice-sous-Forêt, France.",
      "date": "1937-08-11"
    }
  ]
}

