{
  "timeline": [
    {
      "headline": "Birth of Russell T Davies",
      "text": "Stephen Russell Davies, known professionally as Russell T Davies, was born on April 27, 1963, in Swansea, Wales.",
      "date": "1963-04-27"
    },
    {
      "headline": "Creation of Queer as Folk",
      "text": "In 1999, Russell T Davies created the groundbreaking series Queer as Folk, which aired until 2000. The series was notable for its portrayal of the lives of gay men in Manchester.",
      "date": "1999"
    },
    {
      "headline": "Creation of Bob & Rose",
      "text": "In 2001, Davies created the television series Bob & Rose, which focused on a gay man falling in love with a woman.",
      "date": "2001"
    },
    {
      "headline": "Creation of The Second Coming",
      "text": "In 2003, Davies wrote The Second Coming, a two-part television drama about the return of Jesus Christ in modern-day Manchester.",
      "date": "2003"
    },
    {
      "headline": "Creation of Casanova",
      "text": "In 2005, Davies created the television series Casanova, a historical drama about the life of the famous lover Giacomo Casanova.",
      "date": "2005"
    },
    {
      "headline": "Revival of Doctor Who",
      "text": "In 2005, Russell T Davies became the original showrunner and head writer for the revival of the BBC sci-fi series Doctor Who, a role he held until 2010.",
      "date": "2005"
    },
    {
      "headline": "Creation of Torchwood",
      "text": "In 2006, Davies created Torchwood, a Doctor Who spin-off series that aired until 2011.",
      "date": "2006"
    },
    {
      "headline": "Creation of The Sarah Jane Adventures",
      "text": "In 2007, Davies created The Sarah Jane Adventures, another Doctor Who spin-off series that aired until 2011.",
      "date": "2007"
    },
    {
      "headline": "Creation of Cucumber",
      "text": "In 2015, Davies created the television series Cucumber, which explored the lives of gay men in Manchester.",
      "date": "2015"
    },
    {
      "headline": "Creation of A Very English Scandal",
      "text": "In 2018, Davies wrote A Very English Scandal, a miniseries based on the true story of the Thorpe affair, a political scandal in 1970s Britain.",
      "date": "2018"
    },
    {
      "headline": "Creation of Years and Years",
      "text": "In 2019, Davies created Years and Years, a drama series that follows a family over a 15-year period as Britain is rocked by political, economic, and technological changes.",
      "date": "2019"
    },
    {
      "headline": "Creation of It's a Sin",
      "text": "In 2021, Davies created It's a Sin, a critically acclaimed drama series about the lives of a group of gay men and their friends during the HIV/AIDS crisis in the UK.",
      "date": "2021"
    },
    {
      "headline": "Return to Doctor Who",
      "text": "In 2023, Russell T Davies returned as the showrunner and head writer for the BBC sci-fi series Doctor Who.",
      "date": "2023"
    },
    {
      "headline": "Creation of Nolly",
      "text": "In 2023, Davies created Nolly, a drama series about the life of British actress Noele Gordon.",
      "date": "2023"
    }
  ]
}

