{
  "timeline": [
    {
      "headline": "Birth of Baháʼu'lláh",
      "text": "Baháʼu'lláh was born on November 12, 1817, in Tehran, Iran, into an aristocratic family.",
      "date": "1817-11-12"
    },
    {
      "headline": "Involvement with the Bábí Faith",
      "text": "In 1844, Baháʼu'lláh became a follower of the Báb, the founder of the Bábí Faith, which was a precursor to the Baháʼí Faith.",
      "date": "1844"
    },
    {
      "headline": "Imprisonment in the Síyáh-Chál",
      "text": "In August 1852, Baháʼu'lláh was imprisoned in the Síyáh-Chál, a notorious dungeon in Tehran, due to his involvement with the Bábí Faith.",
      "date": "1852-08"
    },
    {
      "headline": "Exile to Baghdad",
      "text": "In January 1853, Baháʼu'lláh was exiled to Baghdad, then part of the Ottoman Empire, as a result of his religious beliefs.",
      "date": "1853-01"
    },
    {
      "headline": "Declaration of Mission",
      "text": "In April 1863, Baháʼu'lláh declared his mission as the messenger of God in the Garden of Ridván in Baghdad.",
      "date": "1863-04"
    },
    {
      "headline": "Exile to Constantinople",
      "text": "In August 1863, Baháʼu'lláh was exiled from Baghdad to Constantinople (now Istanbul) by the Ottoman authorities.",
      "date": "1863-08"
    },
    {
      "headline": "Exile to Adrianople",
      "text": "In December 1863, Baháʼu'lláh was further exiled to Adrianople (now Edirne, Turkey).",
      "date": "1863-12"
    },
    {
      "headline": "Final Exile to Acre",
      "text": "In August 1868, Baháʼu'lláh was exiled to the prison city of Acre (now Akko, Israel), where he spent the remainder of his life.",
      "date": "1868-08"
    },
    {
      "headline": "Revelation of the Kitáb-i-Aqdas",
      "text": "Around 1873, Baháʼu'lláh revealed the Kitáb-i-Aqdas, the central book of Baháʼí laws.",
      "date": "1873"
    },
    {
      "headline": "Death of Baháʼu'lláh",
      "text": "Baháʼu'lláh passed away on May 29, 1892, in Bahjí, near Acre, in what is now Israel.",
      "date": "1892-05-29"
    }
  ]
}

