    {
      "headline": "Roth IRA Conversion Rules",
      "text": "In 2010, the income limit for converting a traditional IRA to a Roth IRA was eliminated, allowing more individuals to convert their retirement savings to a Roth IRA.",
      "date": "2010"
    },
    {
      "headline": "Introduction of Backdoor Roth IRA",
      "text": "The concept of a 'Backdoor Roth IRA' emerged, allowing high-income earners to contribute to a Roth IRA by first contributing to a traditional IRA and then converting it to a Roth IRA.",
      "date": "2010"
    },
    {
      "headline": "SECURE Act Changes",
      "text": "The Setting Every Community Up for Retirement Enhancement (SECURE) Act of 2019 made changes affecting Roth IRAs, including the elimination of the age limit for contributions.",
      "date": "2019"
    }
  ]
}

