{
  "timeline": [
    {
      "headline": "Introduction of the Volt",
      "text": "The volt was named in honor of the Italian physicist Alessandro Volta, who invented the voltaic pile, considered the first chemical battery, in 1800. The unit was later defined in the International System of Units (SI).",
      "date": "1800"
    },
    {
      "headline": "Establishment of the Volt as a Unit",
      "text": "The volt was established as a unit of electric potential and electromotive force in the International System of Units (SI) in 1960. It is defined as the potential difference across a conductor when a current of one ampere dissipates one watt of power.",
      "date": "1960"
    },
    {
      "headline": "Redefinition of the Volt",
      "text": "In 1990, the volt was redefined based on the Josephson effect, which relates the volt to fundamental constants of nature, providing a more precise definition.",
      "date": "1990"
    }
  ]
}

