{
  "timeline": [
    {
      "headline": "Emergence of Gestalt Psychology",
      "text": "Gestalt psychology emerged in the early twentieth century in Austria and Germany as a response to the elementalist and structuralist psychology of Wilhelm Wundt and Edward Titchener.",
      "date": "1900"
    },
    {
      "headline": "Max Wertheimer's Phi Phenomenon Study",
      "text": "In 1912, Max Wertheimer published his study on the phi phenomenon, which demonstrated that the perception of motion can occur without any actual movement, laying the groundwork for Gestalt psychology.",
      "date": "1912"
    },
    {
      "headline": "Founding of Gestalt Psychology",
      "text": "Gestalt psychology was formally founded in the 1910s by Max Wertheimer, Kurt Koffka, and Wolfgang Köhler, who were key figures in developing its principles.",
      "date": "1910"
    },
    {
      "headline": "Publication of 'Perception: An Introduction to the Gestalt-Theorie'",
      "text": "In 1922, Kurt Koffka published 'Perception: An Introduction to the Gestalt-Theorie', which introduced Gestalt psychology to the English-speaking world.",
      "date": "1922"
    },
    {
      "headline": "Wolfgang Köhler's Research on Insight Learning",
      "text": "In 1925, Wolfgang Köhler published his research on insight learning, based on his studies with chimpanzees, which became a significant contribution to Gestalt psychology.",
      "date": "1925"
    },
    {
      "headline": "Publication of 'Principles of Gestalt Psychology'",
      "text": "In 1935, Kurt Koffka published 'Principles of Gestalt Psychology', which became a comprehensive account of Gestalt theory.",
      "date": "1935"
    },
    {
      "headline": "Gestalt Psychology in the United States",
      "text": "During the 1930s and 1940s, many Gestalt psychologists, including Wertheimer, Koffka, and Köhler, emigrated to the United States due to the rise of Nazism in Germany, influencing American psychology.",
      "date": "1930"
    }
  ]
}

