{
  "timeline": [
    {
      "headline": "First Red Scare Begins",
      "text": "The First Red Scare in the United States began shortly after World War I, during the period of 1917-1920. It was characterized by widespread fear of Bolshevism and anarchism due to the Russian Revolution and anarchist bombings.",
      "date": "1917"
    },
    {
      "headline": "Palmer Raids",
      "text": "In 1919 and 1920, the Palmer Raids were conducted by the United States Department of Justice to capture, arrest, and deport suspected radical leftists, especially anarchists, from the United States.",
      "date": "1919"
    },
    {
      "headline": "Sacco and Vanzetti Trial",
      "text": "The trial of Italian anarchists Nicola Sacco and Bartolomeo Vanzetti began in 1920 and became a symbol of the Red Scare. They were convicted of murder and executed in 1927, amid widespread belief that their trial was unfair.",
      "date": "1920"
    },
    {
      "headline": "Second Red Scare Begins",
      "text": "The Second Red Scare occurred after World War II, lasting from the late 1940s through the 1950s. It was marked by fears of Communist influence in the U.S. government and society.",
      "date": "1947"
    },
    {
      "headline": "House Un-American Activities Committee (HUAC)",
      "text": "The HUAC hearings, beginning in 1947, investigated alleged disloyalty and subversive activities by private citizens, public employees, and organizations suspected of having Communist ties.",
      "date": "1947"
    },
    {
      "headline": "McCarthyism",
      "text": "Senator Joseph McCarthy became the face of the Second Red Scare in the early 1950s, leading investigations and hearings aimed at exposing Communist infiltration in the U.S. government.",
      "date": "1950"
    },
    {
      "headline": "Army-McCarthy Hearings",
      "text": "In 1954, the Army-McCarthy hearings were televised, leading to a decline in McCarthy's influence as the public saw his aggressive tactics. This marked the beginning of the end of the Second Red Scare.",
      "date": "1954"
    },
    {
      "headline": "End of the Second Red Scare",
      "text": "The Second Red Scare gradually declined in the late 1950s, as public opinion turned against the tactics used by McCarthy and others, and as the Supreme Court began to limit the scope of anti-Communist investigations.",
      "date": "1957"
    }
  ]
}

