    {
      "headline": "Development of the Saffir–Simpson Scale",
      "text": "In 1971, civil engineer Herbert Saffir and meteorologist Robert Simpson developed the Saffir–Simpson hurricane scale. The scale was created to categorize the intensity of hurricanes based on their wind speed, providing a clear and concise way to communicate the potential damage and flooding they could cause.",
      "date": "1971"
    },
    {
      "headline": "Adoption by the National Hurricane Center",
      "text": "The National Hurricane Center (NHC) adopted the Saffir–Simpson hurricane scale in 1973. This adoption helped standardize the classification of hurricanes and improved public understanding of hurricane risks.",
      "date": "1973"
    },
    {
      "headline": "Renaming to Saffir–Simpson Hurricane Wind Scale",
      "text": "In 2010, the scale was renamed the Saffir–Simpson Hurricane Wind Scale (SSHWS) to emphasize that it categorizes hurricanes based solely on wind speed, without considering other factors like storm surge or rainfall.",
      "date": "2010"
    }
  ]
}

