      "headline": "Introduction to Tibet",
      "text": "In the 8th century, Vajrayana Buddhism was introduced to Tibet, where it became a dominant form of Buddhism and developed into Tibetan Buddhism.",
      "date": "0700"
    },
    {
      "headline": "Development of Tibetan Buddhism",
      "text": "By the 11th century, Vajrayana had become well-established in Tibet, leading to the development of distinct Tibetan Buddhist schools and practices.",
      "date": "1000"
    },
    {
      "headline": "Spread to East Asia",
      "text": "Vajrayana Buddhism spread to East Asia, including China and Japan, where it influenced local Buddhist traditions and practices.",
      "date": "0800"
    },
    {
      "headline": "Influence on Japanese Buddhism",
      "text": "In Japan, Vajrayana influenced the development of Shingon Buddhism, a major school of Japanese esoteric Buddhism founded by Kūkai in the early 9th century.",
      "date": "0800"
    }
  ]
}

