{
  "timeline": [
    {
      "headline": "Origin of Arabic Script",
      "text": "The Arabic script is believed to have originated from the Nabataean script, which was used in the Arabian Peninsula. The transformation from Nabataean to Arabic script occurred gradually over several centuries, with the earliest known Arabic inscriptions dating back to the 4th century CE.",
      "date": "0400"
    },
    {
      "headline": "Development of the Kufic Script",
      "text": "The Kufic script, one of the earliest forms of Arabic calligraphy, developed around the 7th century CE. It was characterized by its angular and geometric style and was widely used in early Islamic manuscripts and architecture.",
      "date": "0700"
    },
    {
      "headline": "Adoption of the Arabic Script for the Quran",
      "text": "The Arabic script was adopted for writing the Quran, the holy book of Islam, during the 7th century CE. This significantly contributed to the spread and standardization of the script across the Islamic world.",
      "date": "0650"
    },
    {
      "headline": "Introduction of Diacritical Marks",
      "text": "Diacritical marks were introduced to the Arabic script in the 8th century CE to indicate short vowels and other phonetic nuances, aiding in the correct pronunciation and understanding of the text.",
      "date": "0750"
    },
    {
      "headline": "Spread of Arabic Script to Non-Arabic Languages",
      "text": "During the Islamic Golden Age (8th to 14th centuries CE), the Arabic script spread to various non-Arabic languages, including Persian, Urdu, and Turkish, becoming a significant cultural and linguistic influence.",
      "date": "0800"
    },
    {
      "headline": "Development of the Naskh Script",
      "text": "The Naskh script, a more cursive and legible form of Arabic calligraphy, was developed in the 10th century CE. It eventually became the standard script for writing Arabic texts.",
      "date": "0900"
    },
    {
      "headline": "Adoption of Arabic Script in Ottoman Empire",
      "text": "The Ottoman Empire adopted the Arabic script for writing Ottoman Turkish, further spreading its use across the empire's vast territories from the 14th century onwards.",
      "date": "1300"
    },
    {
      "headline": "Reforms and Changes in Modern Times",
      "text": "In the 20th century, several countries that used the Arabic script underwent script reforms. For example, Turkey switched to the Latin alphabet in 1928, while other countries adapted the script to better suit their languages.",
      "date": "1928"
    }
  ]
}

