{
  "timeline": [
    {
      "headline": "Viking Invasions Begin",
      "text": "The Viking invasions of England began in earnest in the late 8th century, with the first recorded raid occurring in 793 at the Lindisfarne monastery.",
      "date": "0793"
    },
    {
      "headline": "Great Heathen Army Arrives",
      "text": "In 865, the Great Heathen Army, a coalition of Norse warriors, landed in East Anglia and began a campaign of conquest across England.",
      "date": "0865"
    },
    {
      "headline": "Treaty of Wedmore",
      "text": "In 878, after a series of battles, King Alfred the Great of Wessex and the Viking leader Guthrum agreed to the Treaty of Wedmore, which established the Danelaw.",
      "date": "0878"
    },
    {
      "headline": "Establishment of the Danelaw",
      "text": "Following the Treaty of Wedmore, the Danelaw was established as a distinct region where Danish laws and customs were observed, covering parts of northern and eastern England.",
      "date": "0878"
    },
    {
      "headline": "Battle of Tettenhall",
      "text": "In 910, the Anglo-Saxons defeated a Viking army at the Battle of Tettenhall, marking a significant step in the reconquest of the Danelaw.",
      "date": "0910"
    },
    {
      "headline": "Reign of King Æthelstan",
      "text": "King Æthelstan, who reigned from 924 to 939, was the first king to effectively rule over all of England, including the Danelaw territories.",
      "date": "0924"
    },
    {
      "headline": "Conquest of the Danelaw",
      "text": "By the early 10th century, English kings had begun to reconquer the Danelaw territories, culminating in the complete integration of these areas into the Kingdom of England.",
      "date": "10th century"
    },
    {
      "headline": "First Recorded Use of 'Danelaw'",
      "text": "The term 'Danelaw' was first recorded in the early 11th century as 'Dena lage', referring to the legal practices in the areas settled by the Danes.",
      "date": "11th century"
    },
    {
      "headline": "Norman Conquest",
      "text": "In 1066, the Norman Conquest of England effectively ended the distinct legal practices of the Danelaw as Norman rule was established across the country.",
      "date": "1066"
    }
  ]
}

