    },
    {
      "headline": "Establishment of the Emirate of Córdoba",
      "text": "In 756, Abd al-Rahman I established the Emirate of Córdoba, marking the beginning of a significant Muslim presence in the Iberian Peninsula.",
      "date": "0756"
    },
    {
      "headline": "Ottoman Conquest of Constantinople",
      "text": "In 1453, the Ottoman Empire conquered Constantinople, marking the end of the Byzantine Empire and establishing a significant Muslim presence in Eastern Europe.",
      "date": "1453"
    },
    {
      "headline": "Battle of Mohács",
      "text": "In 1526, the Ottoman Empire defeated the Kingdom of Hungary at the Battle of Mohács, leading to the partition of Hungary and increased Ottoman influence in Central Europe.",
      "date": "1526"
    },
    {
      "headline": "Treaty of Karlowitz",
      "text": "In 1699, the Treaty of Karlowitz was signed, marking the end of Ottoman control over much of Central Europe and the beginning of Habsburg dominance in the region.",
      "date": "1699"
    },
    {
      "headline": "Bosnian War and Dayton Agreement",
      "text": "In 1995, the Dayton Agreement was signed, ending the Bosnian War and establishing Bosnia and Herzegovina as a country with a significant Muslim population.",
      "date": "1995"
    },
    {
      "headline": "Recognition of Islam in Austria",
      "text": "In 1912, Islam was officially recognized as a religion in Austria, following the annexation of Bosnia and Herzegovina, which had a significant Muslim population.",
      "date": "1912"
    },
    {
      "headline": "Muslim Immigration to Western Europe",
      "text": "Post-World War II, significant Muslim immigration to Western Europe began, primarily from former colonies and through labor migration agreements.",
      "date": "1945"
    }
  ]
}

