    {
      "headline": "Operation Iraqi Freedom",
      "text": "USCENTCOM launched Operation Iraqi Freedom on March 20, 2003, to remove Saddam Hussein from power and eliminate Iraq's alleged weapons of mass destruction.",
      "date": "2003-03-20"
