{
  "timeline": [
    {
      "headline": "Formation of the Kingdom of Judah",
      "text": "The Kingdom of Judah was established around 930 BCE after the split of the United Monarchy of Israel and Judah. It was centered in the region of Judea, with Jerusalem as its capital.",
      "date": "-0930"
    },
    {
      "headline": "Babylonian Conquest",
      "text": "In 586 BCE, the Kingdom of Judah was conquered by the Babylonian Empire under King Nebuchadnezzar II. Jerusalem was destroyed, and many inhabitants were exiled to Babylon.",
      "date": "-0586"
    },
    {
      "headline": "Persian Rule",
      "text": "In 539 BCE, the Persian Empire, under Cyrus the Great, conquered Babylon and allowed the Jewish exiles to return to Judea and rebuild the Temple in Jerusalem.",
      "date": "-0539"
    },
    {
      "headline": "Hellenistic Period",
      "text": "Following the conquests of Alexander the Great, Judea came under the control of the Hellenistic Seleucid Empire in 198 BCE.",
      "date": "-0198"
    },
    {
      "headline": "Maccabean Revolt",
      "text": "The Maccabean Revolt against Seleucid rule began in 167 BCE, leading to the establishment of the Hasmonean dynasty and Jewish independence in 140 BCE.",
      "date": "-0167"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 63 BCE, the Roman general Pompey captured Jerusalem, and Judea became a client kingdom of Rome.",
      "date": "-0063"
    },
    {
      "headline": "Herodian Dynasty",
      "text": "Herod the Great was appointed King of Judea by the Roman Senate in 37 BCE, marking the beginning of the Herodian dynasty.",
      "date": "-0037"
    },
    {
      "headline": "First Jewish–Roman War",
      "text": "The First Jewish–Roman War, also known as the Great Revolt, began in 66 CE and resulted in the destruction of the Second Temple in 70 CE.",
      "date": "0066"
    },
    {
      "headline": "Bar Kokhba Revolt",
      "text": "The Bar Kokhba Revolt against Roman rule occurred from 132 to 136 CE. It was the last of the Jewish–Roman wars and resulted in the renaming of the province to Syria Palaestina.",
      "date": "0132"
    }
  ]
}

