{
  "timeline": [
    {
      "headline": "Proposal of Planck Units",
      "text": "In 1899, German physicist Max Planck proposed a system of natural units, now known as Planck units, which are defined exclusively in terms of four universal physical constants: the speed of light in a vacuum (c), the gravitational constant (G), the reduced Planck constant (ħ), and the Boltzmann constant (kB).",
      "date": "1899"
    },
    {
      "headline": "Introduction of Planck Length",
      "text": "The Planck length, approximately 1.616×10^-35 meters, is the scale at which classical ideas about gravity and space-time cease to be valid, and quantum effects dominate. It is a fundamental unit in the system of Planck units.",
      "date": "1899"
    },
    {
      "headline": "Introduction of Planck Time",
      "text": "Planck time, approximately 5.39×10^-44 seconds, is the time it would take for light to travel, in a vacuum, a distance of one Planck length. It represents the 'quantum of time', the smallest measurement of time that has any meaning.",
      "date": "1899"
    },
    {
      "headline": "Introduction of Planck Mass",
      "text": "Planck mass, approximately 2.18×10^-8 kilograms, is the mass at which quantum gravitational effects become significant. It is a fundamental unit in the system of Planck units.",
      "date": "1899"
    },
    {
      "headline": "Introduction of Planck Temperature",
      "text": "Planck temperature, approximately 1.416808(33)×10^32 Kelvin, is the highest theoretically possible temperature. Beyond this, the laws of physics as currently understood cease to be useful.",
      "date": "1899"
    },
    {
      "headline": "Relevance in Quantum Gravity",
      "text": "Planck units are particularly relevant in research on unified theories such as quantum gravity, where they provide a natural scale for the phenomena being studied.",
      "date": "20th century"
    }
  ]
}

