    {
      "headline": "Founding of the Society for Effecting the Abolition of the Slave Trade",
      "text": "In 1787, the Society for Effecting the Abolition of the Slave Trade was founded in London. This organization aimed to end the transatlantic slave trade and was instrumental in raising public awareness and lobbying for legislative change.",
      "date": "1787"
    },
    {
      "headline": "Abolition of the Slave Trade Act",
      "text": "On March 25, 1807, the British Parliament passed the Abolition of the Slave Trade Act, which made it illegal to engage in the slave trade throughout the British Empire.",
      "date": "1807-03-25"
    },
    {
      "headline": "Founding of the American Anti-Slavery Society",
      "text": "In 1833, the American Anti-Slavery Society was founded in Philadelphia. This organization played a key role in advocating for the abolition of slavery in the United States.",
      "date": "1833"
    },
    {
      "headline": "Slavery Abolition Act",
      "text": "The Slavery Abolition Act was passed by the British Parliament on August 28, 1833, and came into effect on August 1, 1834. It abolished slavery in most of the British Empire.",
      "date": "1833-08-28"
    },
    {
      "headline": "Publication of 'Uncle Tom's Cabin'",
      "text": "In 1852, Harriet Beecher Stowe published 'Uncle Tom's Cabin', a novel that depicted the harsh realities of slavery and fueled the abolitionist movement in the United States.",
      "date": "1852"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "On January 1, 1863, President Abraham Lincoln issued the Emancipation Proclamation, declaring the freedom of all enslaved people in Confederate-held territory during the American Civil War.",
      "date": "1863-01-01"
    },
    {
      "headline": "Thirteenth Amendment to the United States Constitution",
      "text": "The Thirteenth Amendment, which abolished slavery in the United States, was passed by Congress on January 31, 1865, and ratified on December 6, 1865.",
      "date": "1865-12-06"
    },
    {
      "headline": "Brazil Abolishes Slavery",
      "text": "On May 13, 1888, Brazil passed the Lei Áurea (Golden Law), which abolished slavery in the country, making it the last nation in the Americas to do so.",
      "date": "1888-05-13"
    }
  ]
}

