  "timeline": [
    {
      "headline": "Roman Conquest of Dalmatia",
      "text": "In 156 BCE, the Romans began their conquest of the region known as Dalmatia, which was inhabited by the Illyrian tribes.",
      "date": "-0156"
    },
    {
      "headline": "Establishment of Roman Province of Dalmatia",
      "text": "In 9 CE, after a series of military campaigns, the Romans established the province of Dalmatia, integrating it into the Roman Empire.",
      "date": "0009"
    },
    {
      "headline": "Diocletian's Palace Built",
      "text": "Around 305 CE, Roman Emperor Diocletian built his palace in Split, Dalmatia, which later became the core of the city of Split.",
      "date": "0305"
    },
    {
      "headline": "Byzantine Control",
      "text": "In the 6th century, Dalmatia came under the control of the Byzantine Empire, following the fall of the Western Roman Empire.",
      "date": "0500"
    },
    {
      "headline": "Arrival of the Croats",
      "text": "In the 7th century, the Croats settled in Dalmatia, establishing a presence that would influence the region's cultural and political landscape.",
      "date": "0600"
    },
    {
      "headline": "Kingdom of Croatia",
      "text": "In 925, Tomislav became the first king of Croatia, and Dalmatia became part of the medieval Kingdom of Croatia.",
      "date": "0925"
    },
    {
      "headline": "Venetian Rule",
      "text": "In 1420, Dalmatia came under the rule of the Republic of Venice, which lasted until the late 18th century.",
      "date": "1420"
    },
    {
      "headline": "Austrian Control",
      "text": "In 1797, following the Treaty of Campo Formio, Dalmatia was ceded to the Austrian Empire after the fall of the Venetian Republic.",
      "date": "1797"
    },
    {
      "headline": "Part of the Kingdom of Yugoslavia",
      "text": "In 1918, after World War I, Dalmatia became part of the newly formed Kingdom of Serbs, Croats, and Slovenes, later known as the Kingdom of Yugoslavia.",
      "date": "1918"
    },
    {
      "headline": "World War II Occupation",
      "text": "During World War II, Dalmatia was occupied by Axis powers, with parts annexed by Italy and Germany.",
      "date": "1941"
    },
    {
      "headline": "Inclusion in Socialist Federal Republic of Yugoslavia",
      "text": "After World War II, Dalmatia became part of the Socialist Republic of Croatia within the Socialist Federal Republic of Yugoslavia.",
      "date": "1945"
    },
    {
      "headline": "Independence of Croatia",
      "text": "In 1991, following the breakup of Yugoslavia, Dalmatia became part of the independent Republic of Croatia.",
      "date": "1991"
    }
  ]
}

