{
  "timeline": [
    {
      "headline": "Founding of Toledo",
      "text": "Toledo was founded in 1833 on the west bank of the Maumee River, originally as part of Monroe County, Michigan Territory.",
      "date": "1833"
    },
    {
      "headline": "Toledo War",
      "text": "The Toledo War was a boundary dispute between the State of Ohio and the Michigan Territory during the early 1830s. It was resolved in 1836 when Toledo was awarded to Ohio.",
      "date": "1836"
    },
    {
      "headline": "City Incorporation",
      "text": "Toledo was incorporated as a city in 1837, following the resolution of the Toledo War.",
      "date": "1837"
    },
    {
      "headline": "Arrival of the Miami and Erie Canal",
      "text": "The Miami and Erie Canal was completed in 1845, connecting Toledo to Cincinnati and significantly boosting its economy.",
      "date": "1845"
    },
    {
      "headline": "Railroad Expansion",
      "text": "In the 1850s, Toledo became a major railroad hub, further enhancing its status as a transportation and trade center.",
      "date": "1850"
    },
    {
      "headline": "Glass Industry Boom",
      "text": "In the late 19th century, Toledo became known as the 'Glass City' due to its thriving glass industry, which began in the 1880s.",
      "date": "1880"
    },
    {
      "headline": "Automobile Industry Growth",
      "text": "In the early 20th century, Toledo became a center for automobile manufacturing, with companies like Willys-Overland establishing factories in the city.",
      "date": "1900"
    },
    {
      "headline": "Great Depression Impact",
      "text": "During the Great Depression in the 1930s, Toledo experienced significant economic hardship, with high unemployment and social unrest.",
      "date": "1930"
    },
    {
      "headline": "Post-War Economic Expansion",
      "text": "Following World War II, Toledo experienced economic growth and suburban expansion, driven by the automotive and glass industries.",
      "date": "1945"
    },
    {
      "headline": "Decline of Manufacturing",
      "text": "In the late 20th century, Toledo faced economic challenges due to the decline of manufacturing industries.",
      "date": "1970"
    },
    {
      "headline": "Revitalization Efforts",
      "text": "In the early 21st century, Toledo undertook efforts to revitalize its downtown and diversify its economy.",
      "date": "2000"
    },
    {
      "headline": "Population at 2020 Census",
      "text": "At the 2020 census, Toledo had a population of 270,871, making it the fourth-most populous city in Ohio.",
      "date": "2020"
    }
  ]
}

