{
  "timeline": [
    {
      "headline": "Emergence of the Métis",
      "text": "The Métis people emerged as a distinct group in the mid-18th century, during the early years of the North American fur trade. They are descendants of unions between European fur traders and Indigenous women.",
      "date": "1750"
    },
    {
      "headline": "Battle of Seven Oaks",
      "text": "On June 19, 1816, the Métis, led by Cuthbert Grant, clashed with the Hudson's Bay Company at the Battle of Seven Oaks, marking a significant assertion of Métis identity and resistance.",
      "date": "1816-06-19"
    },
    {
      "headline": "Red River Rebellion",
      "text": "In 1869-1870, the Métis, led by Louis Riel, resisted the transfer of the Red River Settlement to Canada, resulting in the establishment of a provisional government and the eventual creation of the province of Manitoba.",
      "date": "1869"
    },
    {
      "headline": "Creation of Manitoba",
      "text": "On July 15, 1870, the Manitoba Act was passed, creating the province of Manitoba and recognizing certain Métis rights, following the Red River Rebellion.",
      "date": "1870-07-15"
    },
    {
      "headline": "North-West Rebellion",
      "text": "In 1885, the Métis, again led by Louis Riel, took part in the North-West Rebellion, seeking to protect their rights and lands as settlers encroached on their territories.",
      "date": "1885"
    },
    {
      "headline": "Louis Riel's Execution",
      "text": "On November 16, 1885, Louis Riel was executed for treason, following his leadership in the North-West Rebellion, becoming a martyr for the Métis cause.",
      "date": "1885-11-16"
    },
    {
      "headline": "Recognition of Métis Rights",
      "text": "In the late 20th and early 21st centuries, Métis rights began to be more formally recognized in Canada, including the 1982 Constitution Act which acknowledged Métis as one of Canada's Aboriginal peoples.",
      "date": "1982"
    }
  ]
}

