{
  "timeline": [
    {
      "headline": "Emergence of Mercantilism",
      "text": "Mercantilism began to emerge in Europe in the late 15th century as nations sought to increase their wealth through trade and the accumulation of precious metals.",
      "date": "1490"
    },
    {
      "headline": "Mercantilism in England",
      "text": "In the 16th century, England adopted mercantilist policies, focusing on the export of woolen cloth and the import of raw materials.",
      "date": "1500"
    },
    {
      "headline": "Navigation Acts",
      "text": "In 1651, England passed the Navigation Acts, which were designed to tighten the government's control over trade between England, its colonies, and the rest of the world.",
      "date": "1651"
    },
    {
      "headline": "Colbert's Reforms in France",
      "text": "In the 1660s, Jean-Baptiste Colbert, the French Minister of Finances under King Louis XIV, implemented mercantilist policies to strengthen France's economy.",
      "date": "1660"
    },
    {
      "headline": "Peak of Mercantilism",
      "text": "By the 17th century, mercantilism had become the dominant economic theory in Europe, influencing trade policies and colonial expansion.",
      "date": "1600"
    },
    {
      "headline": "Criticism by Adam Smith",
      "text": "In 1776, Adam Smith published 'The Wealth of Nations', criticizing mercantilism and advocating for free trade and market economies.",
      "date": "1776"
    },
    {
      "headline": "Decline of Mercantilism",
      "text": "By the late 18th century, mercantilism began to decline as economic theories shifted towards classical economics and free trade.",
      "date": "1780"
    }
  ]
}

