    },
    {
      "headline": "Invasion of the Italian Mainland",
      "text": "The Allied invasion of the Italian mainland began on September 3, 1943, with the British 8th Army landing in Calabria during Operation Baytown.",
      "date": "1943-09-03"
    },
    {
      "headline": "Operation Avalanche",
      "text": "On September 9, 1943, the main invasion force landed at Salerno in Operation Avalanche, marking the start of the Allied campaign to liberate mainland Italy.",
      "date": "1943-09-09"
    },
    {
      "headline": "German Occupation of Italy",
      "text": "Following Italy's surrender, German forces quickly occupied much of Italy, establishing a defensive line across the country.",
      "date": "1943-09"
    },
    {
      "headline": "Battle of Monte Cassino",
      "text": "The Battle of Monte Cassino was a series of four assaults by the Allies against the Winter Line in Italy held by Axis forces. The battle took place from January 17 to May 18, 1944.",
      "date": "1944-01-17"
    },
    {
      "headline": "Allied Capture of Rome",
      "text": "On June 4, 1944, Allied forces captured Rome, marking a significant victory in the Italian campaign.",
      "date": "1944-06-04"
    },
    {
      "headline": "Gothic Line Offensive",
      "text": "The Gothic Line was the last major line of German defenses in the Italian Campaign. The Allies launched an offensive against it in August 1944.",
      "date": "1944-08"
    },
    {
      "headline": "Surrender of Axis Forces in Italy",
      "text": "On May 2, 1945, the German forces in Italy surrendered to the Allies, effectively ending the Italian Campaign.",
