{
  "timeline": [
    {
      "headline": "Birth of Jagadish Chandra Bose",
      "text": "Jagadish Chandra Bose was born on November 30, 1858, in Mymensingh, Bengal Presidency, British India (now in Bangladesh).",
      "date": "1858-11-30"
    },
    {
      "headline": "Education in Calcutta",
      "text": "In 1869, Bose was sent to Calcutta to attend the Hare School, and later St. Xavier's School.",
      "date": "1869"
    },
    {
      "headline": "Graduation from St. Xavier's College",
      "text": "Bose graduated with a Bachelor of Arts degree from St. Xavier's College, Calcutta, in 1879.",
      "date": "1879"
    },
    {
      "headline": "Study in London",
      "text": "Bose went to London in 1880 to study medicine at the University of London but had to quit due to health reasons. He then pursued a Bachelor of Science degree from Christ's College, Cambridge.",
      "date": "1880"
    },
    {
      "headline": "Return to India and Teaching Career",
      "text": "In 1885, Bose returned to India and joined the Presidency College, Calcutta, as a professor of physics.",
      "date": "1885"
    },
    {
      "headline": "Research on Radio Waves",
      "text": "In 1895, Bose demonstrated the wireless transmission of electromagnetic waves over a distance of 75 feet through walls, showcasing his pioneering work in radio microwave optics.",
      "date": "1895"
    },
    {
      "headline": "Presentation at the Royal Institution",
      "text": "In 1897, Bose presented his research on radio waves at the Royal Institution in London, gaining international recognition.",
      "date": "1897"
    },
    {
      "headline": "Invention of the Crescograph",
      "text": "In 1918, Bose invented the crescograph, an instrument to measure plant growth, contributing significantly to the field of botany.",
      "date": "1918"
    },
    {
      "headline": "Founding of the Bose Institute",
      "text": "Bose founded the Bose Institute in Calcutta in 1917, which became the first interdisciplinary research center in Asia.",
      "date": "1917"
    },
    {
      "headline": "Director of Bose Institute",
      "text": "Bose served as the Director of the Bose Institute from its inception in 1917 until his death in 1937.",
      "date": "1917"
    },
    {
      "headline": "Death of Jagadish Chandra Bose",
      "text": "Jagadish Chandra Bose passed away on November 23, 1937, in Giridih, Bihar, British India.",
      "date": "1937-11-23"
    }
  ]
}

