{
  "timeline": [
    {
      "headline": "Theoretical Concept of Computer Virus",
      "text": "The concept of a self-replicating computer program was first theorized by John von Neumann in the 1940s. He described the idea of a 'self-reproducing automaton' in his lectures and writings.",
      "date": "1940"
    },
    {
      "headline": "First Demonstration of a Computer Virus",
      "text": "In 1971, the first known computer virus, called the 'Creeper system', was created as an experimental self-replicating program by Bob Thomas at BBN Technologies.",
      "date": "1971"
    },
    {
      "headline": "The 'Elk Cloner' Virus",
      "text": "In 1982, the 'Elk Cloner' virus was created by Richard Skrenta. It was one of the first viruses to spread in the wild, infecting Apple II computers via floppy disks.",
      "date": "1982"
    },
    {
      "headline": "The 'Brain' Virus",
      "text": "In 1986, the 'Brain' virus was released. It was the first virus to target MS-DOS systems and was created by two brothers, Basit and Amjad Farooq Alvi, in Pakistan.",
      "date": "1986"
    },
    {
      "headline": "The 'Morris Worm' Incident",
      "text": "In 1988, the 'Morris Worm' was released by Robert Tappan Morris. It was one of the first worms distributed via the Internet, causing significant disruption.",
      "date": "1988"
    },
    {
      "headline": "The 'ILOVEYOU' Virus",
      "text": "In 2000, the 'ILOVEYOU' virus spread rapidly via email, causing widespread damage and highlighting the vulnerabilities of email systems.",
      "date": "2000"
    },
    {
      "headline": "The 'Stuxnet' Worm",
      "text": "In 2010, the 'Stuxnet' worm was discovered. It was a sophisticated virus that targeted industrial control systems and was reportedly used to disrupt Iran's nuclear program.",
      "date": "2010"
    }
  ]
}

