    {
      "headline": "Publication of 'Agricola'",
      "text": "In 98 AD, Tacitus published 'Agricola', a biography of his father-in-law, Gnaeus Julius Agricola, which also included ethnographic information about Britain.",
      "date": "0098"
    },
    {
      "headline": "Publication of 'Germania'",
      "text": "Also in 98 AD, Tacitus published 'Germania', an ethnographic work on the diverse set of Germanic tribes outside the Roman Empire.",
      "date": "0098"
    },
    {
      "headline": "Publication of 'Histories'",
      "text": "Tacitus began writing 'Histories' around 100 AD, covering the history of the Roman Empire from 69 to 96 AD.",
      "date": "0100"
    },
    {
      "headline": "Publication of 'Annals'",
      "text": "Tacitus wrote 'Annals' after completing 'Histories', covering the Roman Empire from the death of Augustus in 14 AD to the end of Nero's reign in 68 AD.",
      "date": "0116"
    },
    {
      "headline": "Death of Tacitus",
      "text": "Tacitus likely died around 120 AD, although the exact date and circumstances of his death are not recorded.",
