      "headline": "Old Norse Period",
      "text": "Old Norse was the common language of the Germanic peoples living in Scandinavia during the Viking Age, which lasted from approximately 793 to 1066.",
      "date": "0793"
    },
    {
      "headline": "Development of Old Norwegian",
      "text": "Old Norwegian began to develop from Old Norse around the 11th century, following the end of the Viking Age.",
      "date": "1100"
    },
    {
      "headline": "Middle Norwegian Period",
      "text": "The Middle Norwegian period lasted from around 1350 to 1550, during which the language underwent significant changes due to the influence of the Hanseatic League and the Black Death.",
      "date": "1350"
    },
    {
      "headline": "Dano-Norwegian Period",
      "text": "From 1536 to 1814, Norway was part of a union with Denmark, and Danish became the official written language, heavily influencing Norwegian.",
      "date": "1536"
    },
    {
      "headline": "Norwegian Independence from Denmark",
      "text": "In 1814, Norway declared independence from Denmark, which led to efforts to develop a distinct Norwegian written language.",
      "date": "1814"
    },
    {
      "headline": "Emergence of Bokmål and Nynorsk",
      "text": "In the 19th century, two written standards of Norwegian emerged: Bokmål, influenced by Danish, and Nynorsk, based on rural Norwegian dialects.",
      "date": "1800"
    },
    {
      "headline": "Official Language Status",
      "text": "Norwegian became the official language of Norway, with both Bokmål and Nynorsk recognized as official written standards.",
      "date": "1905"
    }
  ]
}

