{
  "timeline": [
    {
      "headline": "Invention of Camera Obscura",
      "text": "The concept of the camera obscura, a darkened room with a small hole or lens at one side through which an image is projected onto a wall or screen, was first described by Mozi, a Chinese philosopher, around the 5th century BCE.",
      "date": "-0500"
    },
    {
      "headline": "First Portable Camera Obscura",
      "text": "In 1685, Johann Zahn designed the first portable camera obscura, which was small enough to be practical for photography.",
      "date": "1685"
    },
    {
      "headline": "First Photograph",
      "text": "In 1826 or 1827, Joseph Nicéphore Niépce created the first permanent photograph using a camera obscura and a process called heliography.",
      "date": "1826"
    },
    {
      "headline": "Introduction of Daguerreotype",
      "text": "In 1839, Louis Daguerre announced the daguerreotype process, the first publicly available photographic process, which created images on silver-plated copper.",
      "date": "1839"
    },
    {
      "headline": "Calotype Process Developed",
      "text": "In 1841, William Henry Fox Talbot patented the calotype process, which used paper coated with silver iodide to create a negative image.",
      "date": "1841"
    },
    {
      "headline": "Invention of Collodion Process",
      "text": "In 1851, Frederick Scott Archer invented the collodion process, which allowed for the creation of glass negatives and sharper images.",
      "date": "1851"
    },
    {
      "headline": "Introduction of Dry Plates",
      "text": "In 1871, Richard Leach Maddox introduced the dry plate process, which used gelatin instead of collodion and allowed for more convenient photography.",
      "date": "1871"
    },
    {
      "headline": "Kodak Box Camera Released",
      "text": "In 1888, George Eastman released the Kodak box camera, which was the first camera to use roll film and made photography accessible to the general public.",
      "date": "1888"
    },
    {
      "headline": "Introduction of 35mm Film",
      "text": "In 1925, the Leica I, the first commercially successful 35mm camera, was introduced, popularizing the use of 35mm film.",
      "date": "1925"
    },
    {
      "headline": "First Polaroid Camera",
      "text": "In 1948, Edwin Land introduced the first Polaroid camera, which could produce instant photographs.",
      "date": "1948"
    },
    {
      "headline": "First Digital Camera",
      "text": "In 1975, Steven Sasson, an engineer at Eastman Kodak, invented the first digital camera, which used a CCD image sensor.",
      "date": "1975"
    },
    {
      "headline": "Introduction of Camera Phones",
      "text": "In 2000, the first commercial camera phone, the J-SH04 by Sharp, was released in Japan, marking the beginning of widespread mobile photography.",
      "date": "2000"
    }
  ]
}

