      "headline": "2014 AFC Championship Game",
      "text": "On January 18, 2015, the New England Patriots played against the Indianapolis Colts in the 2014 AFC Championship Game. The Patriots won the game 45-7.",
      "date": "2015-01-18"
    },
    {
      "headline": "Allegations of Deflated Footballs",
      "text": "Following the AFC Championship Game on January 18, 2015, allegations emerged that the New England Patriots had used under-inflated footballs during the game.",
      "date": "2015-01-18"
    },
    {
      "headline": "NFL Investigation",
      "text": "The NFL launched an investigation into the allegations of deflated footballs used by the New England Patriots during the AFC Championship Game. The investigation was led by attorney Ted Wells.",
      "date": "2015-01"
    },
    {
      "headline": "Wells Report Released",
      "text": "On May 6, 2015, the Wells Report was released. It concluded that it was 'more probable than not' that New England Patriots personnel deliberately deflated footballs and that quarterback Tom Brady was 'at least generally aware' of the misconduct.",
      "date": "2015-05-06"
    },
    {
      "headline": "NFL Punishment Announced",
      "text": "On May 11, 2015, the NFL announced its punishment for the New England Patriots and Tom Brady. Brady was suspended for four games, the Patriots were fined $1 million, and the team forfeited two draft picks (a first-round pick in 2016 and a fourth-round pick in 2017).",
      "date": "2015-05-11"
    },
    {
      "headline": "Brady's Suspension Overturned",
      "text": "On September 3, 2015, U.S. District Judge Richard M. Berman nullified Tom Brady's four-game suspension, allowing him to play in the 2015 season.",
      "date": "2015-09-03"
    },
    {
      "headline": "Brady's Suspension Reinstated",
      "text": "On April 25, 2016, the United States Court of Appeals for the Second Circuit reinstated Tom Brady's four-game suspension for the 2016 NFL season.",
      "date": "2016-04-25"
    },
    {
      "headline": "Brady Accepts Suspension",
      "text": "On July 15, 2016, Tom Brady announced that he would not appeal the decision to reinstate his suspension, and he accepted the four-game suspension for the 2016 NFL season.",
      "date": "2016-07-15"
    },
    {
      "headline": "Brady Returns to Play",
      "text": "Tom Brady returned to play on October 9, 2016, after serving his four-game suspension at the start of the 2016 NFL season.",
      "date": "2016-10-09"
    }
  ]
}

