{
  "timeline": [
    {
      "headline": "United States Constitutional Convention",
      "text": "The United States Constitutional Convention took place in 1787. During this convention, delegates debated various issues, including the representation of states in Congress.",
      "date": "1787"
    },
    {
      "headline": "Debate Over Slave Population Representation",
      "text": "During the 1787 Constitutional Convention, a significant debate arose over whether slaves should be counted as part of the population when determining representation in the House of Representatives. Slaveholding states wanted slaves to be fully counted to increase their representation, while free states opposed this since slaves did not have voting rights.",
      "date": "1787"
    },
    {
      "headline": "Three-fifths Compromise Reached",
      "text": "In 1787, the Three-fifths Compromise was reached. It determined that three-fifths of the slave population would be counted for the purposes of apportioning seats in the House of Representatives and for taxation. This compromise gave Southern states more power in the House relative to Northern states.",
      "date": "1787"
    },
    {
      "headline": "Impact on Southern Legislatures",
      "text": "The Three-fifths Compromise also affected the power dynamics within Southern legislatures, giving slaveholders more influence. This was a factor in the secession of West Virginia from Virginia in 1863.",
      "date": "1863"
    }
  ]
}

