{
  "timeline": [
    {
      "headline": "Initial Embargo Imposed",
      "text": "The United States imposed an arms embargo on Cuba on March 14, 1958, during the Fulgencio Batista regime. This was the first step towards a broader trade embargo.",
      "date": "1958-03-14"
    },
    {
      "headline": "Cuban Revolution",
      "text": "On January 1, 1959, Fidel Castro's revolutionary forces overthrew the Batista government, leading to significant changes in U.S.-Cuba relations.",
      "date": "1959-01-01"
    },
    {
      "headline": "Partial Trade Embargo",
      "text": "On October 19, 1960, the U.S. imposed a partial trade embargo on Cuba, prohibiting exports to Cuba except for food and medicine.",
      "date": "1960-10-19"
    },
    {
      "headline": "Full Trade Embargo",
      "text": "On February 7, 1962, President John F. Kennedy extended the embargo to include almost all exports, marking the start of the full trade embargo against Cuba.",
      "date": "1962-02-07"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "In October 1962, the Cuban Missile Crisis brought the world to the brink of nuclear war, further straining U.S.-Cuba relations.",
      "date": "1962-10"
    },
    {
      "headline": "Helms-Burton Act",
      "text": "On March 12, 1996, the Helms-Burton Act was signed into law, strengthening the embargo by penalizing foreign companies trading with Cuba.",
      "date": "1996-03-12"
    },
    {
      "headline": "Obama Administration Eases Restrictions",
      "text": "In December 2014, President Barack Obama announced a thaw in relations with Cuba, leading to some easing of travel and trade restrictions.",
      "date": "2014-12"
    },
    {
      "headline": "Re-establishment of Diplomatic Relations",
      "text": "On July 20, 2015, the United States and Cuba officially re-established diplomatic relations, reopening embassies in each other's capitals.",
      "date": "2015-07-20"
    },
    {
      "headline": "Trump Administration Reverses Policies",
      "text": "In June 2017, President Donald Trump announced a rollback of the Obama-era policies, tightening restrictions on travel and trade with Cuba.",
      "date": "2017-06"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of David Hockney",
      "text": "David Hockney was born on July 9, 1937, in Bradford, West Yorkshire, England.",
      "date": "1937-07-09"
    },
    {
      "headline": "Education at Bradford College of Art",
      "text": "David Hockney attended Bradford College of Art from 1953 to 1957, where he developed his foundational skills in art.",
      "date": "1953"
