    {
      "headline": "Studies at the Royal College of Art",
      "text": "From 1959 to 1962, Hockney studied at the Royal College of Art in London, where he became associated with the pop art movement.",
      "date": "1959"
    },
    {
      "headline": "Graduation and Gold Medal",
      "text": "In 1962, Hockney graduated from the Royal College of Art with a gold medal, despite initially being refused his diploma for not completing an essay requirement.",
      "date": "1962"
    },
    {
      "headline": "First Solo Exhibition",
      "text": "Hockney held his first solo exhibition in 1963 at the John Kasmin Gallery in London.",
      "date": "1963"
    },
    {
      "headline": "Move to Los Angeles",
      "text": "In 1964, Hockney moved to Los Angeles, where he created some of his most famous works, including his swimming pool paintings.",
      "date": "1964"
    },
    {
      "headline": "Creation of 'A Bigger Splash'",
      "text": "In 1967, Hockney painted 'A Bigger Splash', one of his most iconic works, depicting a swimming pool in Los Angeles.",
      "date": "1967"
    },
    {
      "headline": "Stage Design for Opera",
      "text": "In 1975, Hockney began working as a stage designer, creating sets for operas such as 'The Rake's Progress' by Igor Stravinsky.",
      "date": "1975"
    },
    {
      "headline": "Exploration of Photography",
      "text": "During the 1980s, Hockney explored photography, creating photo collages and 'joiners' that became a significant part of his work.",
      "date": "1980"
    },
    {
      "headline": "Return to Painting",
      "text": "In the late 1990s, Hockney returned to painting, focusing on landscapes and experimenting with new techniques.",
      "date": "1990"
    },
    {
      "headline": "Exhibition at the Royal Academy of Arts",
      "text": "In 2012, Hockney held a major exhibition at the Royal Academy of Arts in London, showcasing his landscape paintings.",
      "date": "2012"
    },
    {
      "headline": "Record-Breaking Auction Sale",
      "text": "In November 2018, Hockney's painting 'Portrait of an Artist (Pool with Two Figures)' sold for $90.3 million at auction, setting a record for a living artist.",
      "date": "2018-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Enactment of the Invention Secrecy Act",
      "text": "The Invention Secrecy Act was enacted on September 1, 1951. It was designed to prevent the disclosure of new inventions and technologies that could pose a threat to the economic stability or national security of the United States.",
      "date": "1951-09-01"
    },
    {
      "headline": "Implementation of Secrecy Orders",
      "text": "Under the Invention Secrecy Act, secrecy orders can be imposed on patent applications that contain sensitive information. These orders prevent the publication or disclosure of the invention.",
      "date": "1951"
    },
    {
      "headline": "Role of Federal Agencies",
      "text": "The Act allows selected federal agencies to review patent applications and determine if a secrecy order should be applied. This process is ongoing and part of the Act's implementation.",
      "date": "1951"
    },
    {
      "headline": "Annual Review of Secrecy Orders",
      "text": "Secrecy orders are subject to an annual review to determine if they should remain in effect. This ensures that only necessary orders are maintained.",
      "date": "1951"
    },
    {
      "headline": "Impact on Patent Applicants",
      "text": "Patent applicants affected by secrecy orders are prohibited from disclosing their inventions and may face restrictions on their ability to commercialize the technology.",
      "date": "1951"
    }
  ]
}

