      "headline": "Founding of Alexandria",
      "text": "Alexandria was founded in 1749. It was established as a port town on the Potomac River, primarily for the tobacco trade.",
      "date": "1749"
    },
    {
      "headline": "Incorporation as a Town",
      "text": "In 1779, Alexandria was incorporated as a town. This marked its official recognition and establishment as a municipal entity.",
      "date": "1779"
    },
    {
      "headline": "Retrocession to Virginia",
      "text": "In 1846, Alexandria was retroceded to Virginia from the District of Columbia. This was part of a larger movement to return the land originally ceded for the creation of the nation's capital.",
      "date": "1846"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Alexandria was incorporated as a city in 1852, further solidifying its status as an independent municipality.",
      "date": "1852"
    },
    {
      "headline": "Civil War Occupation",
      "text": "During the American Civil War, Alexandria was occupied by Union troops starting in 1861. The city served as a major supply depot and hospital center for the Union Army.",
      "date": "1861"
    },
    {
      "headline": "Becoming an Independent City",
      "text": "In 1870, Alexandria became an independent city, separating from Alexandria County, which was later renamed Arlington County.",
      "date": "1870"
    },
    {
      "headline": "Establishment of the George Washington Masonic National Memorial",
      "text": "The George Washington Masonic National Memorial was dedicated in 1932. It serves as a memorial to George Washington, the first President of the United States and a prominent Freemason.",
      "date": "1932"
    },
    {
      "headline": "Civil Rights Movement",
      "text": "During the 1960s, Alexandria was an active site for the Civil Rights Movement, with significant efforts to desegregate schools and public facilities.",
      "date": "1960"
    },
    {
      "headline": "Metro System Expansion",
      "text": "In 1983, the Washington Metro system expanded to include Alexandria, improving transportation and connectivity with the greater Washington, D.C. area.",
      "date": "1983"
    },
    {
      "headline": "Torpedo Factory Art Center Opening",
      "text": "The Torpedo Factory Art Center, a former munitions plant turned into an art center, opened to the public in 1974, becoming a major cultural attraction in Alexandria.",
      "date": "1974"
    }
  ]
}

