      "date": "1967"
    },
    {
      "headline": "Operation Salem House",
      "text": "In 1968, MACV-SOG conducted Operation Salem House, which involved intelligence gathering and reconnaissance missions in North Vietnam.",
      "date": "1968"
    },
    {
      "headline": "Operation Gauntlet",
      "text": "In 1970, MACV-SOG executed Operation Gauntlet, focusing on disrupting enemy logistics in Cambodia.",
      "date": "1970"
