{
  "timeline": [
    {
      "headline": "Ancient Settlement",
      "text": "Lesbos has been inhabited since the Neolithic period, with evidence of settlement dating back to around 3200 BCE.",
      "date": "-3200"
    },
    {
      "headline": "Aeolian Greeks Settlement",
      "text": "Around 1100 BCE, the Aeolian Greeks settled on Lesbos, establishing the island as an important cultural and economic center in the Aegean.",
      "date": "-1100"
    },
    {
      "headline": "Birth of Sappho",
      "text": "The poet Sappho, one of the most famous figures from Lesbos, was born around 630 BCE. She is known for her lyric poetry, often focused on themes of love and passion.",
      "date": "-0630"
    },
    {
      "headline": "Persian Rule",
      "text": "In 546 BCE, Lesbos fell under Persian rule as part of the Achaemenid Empire's expansion into the Aegean region.",
      "date": "-0546"
    },
    {
      "headline": "Ionian Revolt",
      "text": "Lesbos participated in the Ionian Revolt against Persian rule in 499 BCE, which ultimately failed but set the stage for the Greco-Persian Wars.",
      "date": "-0499"
    },
    {
      "headline": "Delian League Membership",
      "text": "In 478 BCE, Lesbos became a member of the Delian League, an alliance led by Athens against the Persian Empire.",
      "date": "-0478"
    },
    {
      "headline": "Mytilenean Revolt",
      "text": "In 428 BCE, the city of Mytilene led a revolt against Athenian control, which was suppressed by Athens in 427 BCE.",
      "date": "-0428"
    },
    {
      "headline": "Roman Rule",
      "text": "Lesbos came under Roman control in 146 BCE, following the Roman conquest of Greece.",
      "date": "-0146"
    },
    {
      "headline": "Byzantine Era",
      "text": "During the Byzantine period, Lesbos was an important center of trade and culture, particularly noted for its production of olive oil and wine.",
      "date": "0330"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "Lesbos was conquered by the Ottoman Empire in 1462, remaining under Ottoman control for nearly four centuries.",
      "date": "1462"
    },
    {
      "headline": "Liberation and Union with Greece",
      "text": "Lesbos was liberated from Ottoman rule and became part of Greece in 1912, following the Balkan Wars.",
      "date": "1912"
    },
    {
      "headline": "World War II Occupation",
      "text": "During World War II, Lesbos was occupied by Axis forces from 1941 to 1944.",
      "date": "1941"
    },
    {
      "headline": "Modern Era",
      "text": "In recent years, Lesbos has been a focal point for the European migrant crisis, with thousands of refugees arriving on the island.",
      "date": "2015"
    }
  ]
}

