{
  "timeline": [
    {
      "headline": "Early Settlement",
      "text": "Da Nang has been a site of human settlement for thousands of years, with evidence of early human habitation dating back to the Sa Huỳnh culture around 1000 BCE.",
      "date": "-1000"
    },
    {
      "headline": "Cham Kingdom",
      "text": "Da Nang was part of the Champa Kingdom, which flourished from the 2nd century CE until the 15th century. The Cham people built many temples and structures in the region.",
      "date": "0200"
    },
    {
      "headline": "Annexation by Đại Việt",
      "text": "In 1471, the Đại Việt kingdom, which later became Vietnam, annexed the region, including Da Nang, from the Champa Kingdom.",
      "date": "1471"
    },
    {
      "headline": "French Colonial Era",
      "text": "Da Nang was occupied by French forces in 1858, marking the beginning of French colonial rule in Vietnam. It became an important port city under French control.",
      "date": "1858"
    },
    {
      "headline": "World War II Japanese Occupation",
      "text": "During World War II, Da Nang was occupied by Japanese forces from 1940 until the end of the war in 1945.",
      "date": "1940"
    },
    {
      "headline": "First Indochina War",
      "text": "After World War II, Da Nang was a significant location during the First Indochina War between French forces and the Viet Minh, lasting from 1946 to 1954.",
      "date": "1946"
    },
    {
      "headline": "Vietnam War",
      "text": "Da Nang played a crucial role during the Vietnam War, serving as a major air base for the United States and South Vietnamese forces from 1965 until the end of the war in 1975.",
      "date": "1965"
    },
    {
      "headline": "Reunification of Vietnam",
      "text": "Following the fall of Saigon in 1975, Da Nang became part of the unified Socialist Republic of Vietnam.",
      "date": "1975"
    },
    {
      "headline": "Economic Reforms",
      "text": "In the late 20th century, Da Nang underwent significant economic reforms and development, becoming one of Vietnam's most important economic hubs.",
      "date": "1986"
    },
    {
      "headline": "Direct-Controlled Municipality",
      "text": "In 1997, Da Nang was designated as one of Vietnam's five direct-controlled municipalities, giving it greater autonomy and importance in national governance.",
      "date": "1997"
    }
  ]
}

