{
  "timeline": [
    {
      "headline": "Establishment of the New Kingdom",
      "text": "The New Kingdom of Egypt was established between 1570 BC and 1544 BC, marking the beginning of the Eighteenth Dynasty. This period followed the Second Intermediate Period.",
      "date": "-1570"
    },
    {
      "headline": "Reign of Ahmose I",
      "text": "Ahmose I reigned from approximately 1549 BC to 1524 BC. He is credited with expelling the Hyksos from Egypt and reuniting the country, thus initiating the New Kingdom.",
      "date": "-1549"
    },
    {
      "headline": "Reign of Hatshepsut",
      "text": "Hatshepsut reigned from 1479 BC to 1458 BC. She was one of the few female pharaohs and is known for her prosperous and peaceful reign, as well as her extensive building projects.",
      "date": "-1479"
    },
    {
      "headline": "Reign of Thutmose III",
      "text": "Thutmose III reigned from 1479 BC to 1425 BC. He is often referred to as the 'Napoleon of Egypt' due to his military conquests, which expanded Egypt's empire to its greatest extent.",
      "date": "-1479"
    },
    {
      "headline": "Reign of Amenhotep III",
      "text": "Amenhotep III reigned from 1386 BC to 1349 BC. His reign is noted for its artistic splendor and the construction of many monumental structures, including the Luxor Temple.",
      "date": "-1386"
    },
    {
      "headline": "Reign of Akhenaten",
      "text": "Akhenaten reigned from 1353 BC to 1336 BC. He is known for his religious revolution, in which he promoted the worship of Aten and attempted to establish monotheism.",
      "date": "-1353"
    },
    {
      "headline": "Reign of Tutankhamun",
      "text": "Tutankhamun reigned from 1332 BC to 1323 BC. He is one of the most famous pharaohs due to the discovery of his nearly intact tomb in 1922.",
      "date": "-1332"
    },
    {
      "headline": "Reign of Ramesses II",
      "text": "Ramesses II, also known as Ramesses the Great, reigned from 1279 BC to 1213 BC. His reign is marked by numerous military campaigns and extensive building projects, including the temples at Abu Simbel.",
      "date": "-1279"
    },
    {
      "headline": "Battle of Kadesh",
      "text": "The Battle of Kadesh took place in 1274 BC between the forces of the Egyptian Empire under Ramesses II and the Hittite Empire. It is one of the earliest battles in recorded history for which details of tactics and formations are known.",
      "date": "-1274"
    },
    {
      "headline": "Reign of Ramesses III",
      "text": "Ramesses III reigned from 1186 BC to 1155 BC. He is considered the last great pharaoh of the New Kingdom, known for defending Egypt against the Sea Peoples.",
      "date": "-1186"
    },
    {
      "headline": "End of the New Kingdom",
      "text": "The New Kingdom came to an end around 1077 BC, leading into the Third Intermediate Period. This period was marked by political instability and the division of Egypt.",
      "date": "-1077"
    }
  ]
}

