    {
      "headline": "Language Movement and Recognition of Bengali",
      "text": "On February 21, 1952, a protest in Dhaka led to the deaths of several students advocating for the recognition of Bengali as an official language. This movement eventually led to Bengali being recognized as one of the official languages of Pakistan.",
      "date": "1952-02-21"
    },
    {
      "headline": "Cyclone Bhola",
      "text": "On November 13, 1970, the Bhola cyclone struck East Pakistan, causing widespread devastation and killing an estimated 300,000 to 500,000 people. The government's inadequate response fueled discontent in the region.",
      "date": "1970-11-13"
    },
    {
      "headline": "1970 General Elections",
      "text": "In December 1970, the Awami League, led by Sheikh Mujibur Rahman, won a landslide victory in the general elections, securing 167 out of 169 seats allocated to East Pakistan in the National Assembly of Pakistan.",
      "date": "1970-12"
    },
    {
      "headline": "Operation Searchlight",
      "text": "On March 25, 1971, the Pakistani military launched Operation Searchlight, a brutal crackdown on the Bengali population in East Pakistan, leading to widespread atrocities and escalating the conflict.",
      "date": "1971-03-25"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On March 26, 1971, Sheikh Mujibur Rahman declared the independence of Bangladesh, marking the beginning of the Bangladesh Liberation War.",
      "date": "1971-03-26"
    },
    {
      "headline": "Indo-Pakistani War and Liberation of Bangladesh",
      "text": "On December 16, 1971, the Indo-Pakistani War of 1971 concluded with the surrender of Pakistani forces in East Pakistan, leading to the creation of the independent state of Bangladesh.",
      "date": "1971-12-16"
    }
  ]
}

