{
  "timeline": [
    {
      "headline": "Earliest Inhabitation",
      "text": "The greater area of Heraklion has been continuously inhabited since at least 7000 BCE, making it one of the oldest inhabited regions in Europe.",
      "date": "-7000"
    },
    {
      "headline": "Minoan Civilization Flourishes",
      "text": "The ancient Knossos Palace, located near Heraklion, becomes a major center of the Minoan civilization dating back to approximately 2000-1350 BCE. It is often considered Europe's oldest city.",
      "date": "-2000"
    },
    {
      "headline": "Destruction of Knossos",
      "text": "The palace of Knossos, a significant archaeological site near Heraklion, is believed to have been destroyed around 1350 BCE, marking the decline of the Minoan civilization.",
      "date": "-1350"
    },
    {
      "headline": "Arab Rule",
      "text": "Heraklion, known as Chandax, was captured by the Arabs in 824 AD and became the capital of the Emirate of Crete.",
      "date": "0824"
    },
    {
      "headline": "Byzantine Reconquest",
      "text": "In 961 AD, the Byzantine Empire recaptured Heraklion, ending the Arab rule.",
      "date": "0961"
    },
    {
      "headline": "Venetian Rule",
      "text": "In 1204, Heraklion came under Venetian control and was known as Candia. The Venetians fortified the city extensively.",
      "date": "1204"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "After a prolonged siege, Heraklion fell to the Ottoman Empire in 1669, marking the end of Venetian rule.",
      "date": "1669"
    },
    {
      "headline": "Union with Greece",
      "text": "Crete, including Heraklion, officially became part of Greece in 1913 after the Balkan Wars.",
      "date": "1913"
    },
    {
      "headline": "World War II",
      "text": "Heraklion was heavily bombed during the Battle of Crete in 1941, suffering significant damage.",
      "date": "1941"
    },
    {
      "headline": "Modern Era",
      "text": "Heraklion has grown to become the largest city and the administrative capital of the island of Crete, with a municipal population of 179,302 as of 2021.",
      "date": "2021"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of Saturn's Hexagon",
      "text": "Saturn's hexagon was first discovered by the Voyager spacecraft during its flyby of Saturn in 1980-1981. The hexagonal cloud pattern was observed around the north pole of Saturn.",
      "date": "1980"
    },
    {
      "headline": "Cassini Mission Observations",
      "text": "The Cassini spacecraft, which arrived at Saturn in 2004, provided detailed observations of Saturn's hexagon. Cassini's cameras captured images of the hexagon in various wavelengths, allowing scientists to study its structure and dynamics.",
      "date": "2004"
    },
    {
      "headline": "Hexagon's Color Change",
      "text": "In 2013, scientists observed that the color of Saturn's hexagon changed from a bluish hue to a more golden color. This change was attributed to seasonal changes in Saturn's atmosphere.",
      "date": "2013"
    },
    {
      "headline": "Study of Hexagon's Dynamics",
      "text": "Ongoing studies have suggested that the hexagon is a jet stream made of atmospheric gases moving at 320 km/h (200 mph). It rotates with a period of 10h 39m 24s, the same period as Saturn's radio emissions from its interior.",
      "date": "2013"
    }
  ]
}

