    },
    {
      "headline": "Battle of Rorke's Drift",
      "text": "Following the Battle of Isandlwana, the Battle of Rorke's Drift took place from January 22 to January 23, 1879, where a small British garrison successfully defended their position against a large Zulu force.",
      "date": "1879-01-22"
    },
    {
      "headline": "Battle of Kambula",
      "text": "On March 29, 1879, the British forces won a decisive victory at the Battle of Kambula, which marked a turning point in the war.",
      "date": "1879-03-29"
    },
    {
      "headline": "Battle of Gingindlovu",
      "text": "The Battle of Gingindlovu took place on April 2, 1879, resulting in another British victory over the Zulu forces.",
      "date": "1879-04-02"
    },
    {
      "headline": "Capture of King Cetshwayo",
      "text": "On August 28, 1879, King Cetshwayo, the leader of the Zulu Kingdom, was captured by British forces, effectively ending the war.",
      "date": "1879-08-28"
    },
    {
      "headline": "End of the Anglo-Zulu War",
      "text": "The Anglo-Zulu War officially ended in early July 1879, following the British victory at the Battle of Ulundi on July 4, 1879.",
