{
  "timeline": [
    {
      "headline": "Birth of Ethan Couch",
      "text": "Ethan Anthony Couch was born on April 11, 1997.",
      "date": "1997-04-11"
    },
    {
      "headline": "Fatal Drunk Driving Incident",
      "text": "On June 15, 2013, Ethan Couch, at the age of 16, killed four people while driving under the influence in Burleson, Texas. He was intoxicated and under the influence of drugs, driving on a restricted license, and speeding in a residential area. Couch lost control of his vehicle and collided with a group of people assisting another driver with a disabled SUV. The collision resulted in the deaths of four people and injuries to nine others. Two passengers in Couch's pickup truck suffered serious injuries, with one passenger suffering complete paralysis.",
      "date": "2013-06-15"
    },
    {
      "headline": "Trial and Sentencing",
      "text": "In December 2013, Ethan Couch was sentenced to 10 years of probation and therapy after his defense argued that he suffered from 'affluenza,' a condition where his wealthy upbringing prevented him from understanding the consequences of his actions.",
      "date": "2013-12"
    },
    {
      "headline": "Violation of Probation",
      "text": "In December 2015, a video surfaced allegedly showing Ethan Couch at a party where alcohol was being consumed, which was a violation of his probation terms. This led to a warrant being issued for his arrest.",
      "date": "2015-12"
    },
    {
      "headline": "Capture in Mexico",
      "text": "On December 28, 2015, Ethan Couch and his mother, Tonya Couch, were detained in Puerto Vallarta, Mexico, after fleeing the United States. They were captured by Mexican authorities and later deported back to the U.S.",
      "date": "2015-12-28"
    },
    {
      "headline": "Return to the United States",
      "text": "In January 2016, Ethan Couch was returned to the United States and was placed in a juvenile detention center.",
      "date": "2016-01"
    },
    {
      "headline": "Transfer to Adult Court",
      "text": "In April 2016, Ethan Couch was transferred to adult court and sentenced to serve 720 days in jail, 180 days for each of the four people killed in the crash.",
      "date": "2016-04"
    },
    {
      "headline": "Release from Jail",
      "text": "On April 2, 2018, Ethan Couch was released from jail after serving nearly two years.",
      "date": "2018-04-02"
    }
  ]
}

