{
  "timeline": [
    {
      "headline": "Establishment of Acadia",
      "text": "In 1604, Pierre Dugua, Sieur de Mons, established the first permanent European settlement in Acadia on Saint Croix Island, which is now part of Maine.",
      "date": "1604"
    },
    {
      "headline": "Port-Royal Settlement",
      "text": "In 1605, the settlement was moved to Port-Royal, which became the center of Acadian life and culture.",
      "date": "1605"
    },
    {
      "headline": "Capture by the British",
      "text": "In 1613, the British, led by Samuel Argall, captured and destroyed Port-Royal.",
      "date": "1613"
    },
    {
      "headline": "Treaty of Saint-Germain-en-Laye",
      "text": "In 1632, the Treaty of Saint-Germain-en-Laye returned Acadia to French control.",
      "date": "1632"
    },
    {
      "headline": "Founding of Fort Pentagouet",
      "text": "In 1635, Fort Pentagouet was established, serving as a trading post and military fortification.",
      "date": "1635"
    },
    {
      "headline": "King William's War",
      "text": "From 1688 to 1697, Acadia was involved in King William's War, a conflict between France and England in North America.",
      "date": "1688"
    },
    {
      "headline": "Treaty of Ryswick",
      "text": "In 1697, the Treaty of Ryswick ended King William's War and returned Acadia to France.",
      "date": "1697"
    },
    {
      "headline": "Queen Anne's War",
      "text": "From 1702 to 1713, Acadia was involved in Queen Anne's War, another conflict between France and England.",
      "date": "1702"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "In 1713, the Treaty of Utrecht ended Queen Anne's War, ceding Acadia to Great Britain.",
      "date": "1713"
    },
    {
      "headline": "Founding of Halifax",
      "text": "In 1749, the British founded Halifax as a counterbalance to the French presence in Louisbourg.",
      "date": "1749"
    },
    {
      "headline": "Expulsion of the Acadians",
      "text": "From 1755 to 1764, the British expelled the Acadians from their homeland in an event known as the Great Upheaval.",
      "date": "1755"
    },
    {
      "headline": "End of the French and Indian War",
      "text": "In 1763, the Treaty of Paris ended the French and Indian War, solidifying British control over former French territories in North America, including Acadia.",
      "date": "1763"
    }
  ]
}

