    {
      "headline": "Establishment of the FCC",
      "text": "The Federal Communications Commission (FCC) was established on June 19, 1934, as an independent agency of the United States government. It was created by the Communications Act of 1934 to regulate interstate and international communications by radio, television, wire, satellite, and cable.",
      "date": "1934-06-19"
    },
    {
      "headline": "First FCC Chairman",
      "text": "Eugene Sykes was appointed as the first chairman of the FCC in 1934. His leadership marked the beginning of the FCC's regulatory role in communications.",
      "date": "1934"
    },
    {
      "headline": "Television Licensing Begins",
      "text": "In 1941, the FCC issued the first commercial television licenses, marking the beginning of regulated television broadcasting in the United States.",
      "date": "1941"
    },
    {
      "headline": "Introduction of the Fairness Doctrine",
      "text": "The Fairness Doctrine was introduced by the FCC in 1949, requiring broadcasters to present controversial issues of public importance in a fair and balanced manner.",
      "date": "1949"
    },
    {
      "headline": "Communications Satellite Act",
      "text": "In 1962, the Communications Satellite Act was passed, leading to the creation of COMSAT and marking the beginning of satellite communications regulation by the FCC.",
      "date": "1962"
    },
    {
      "headline": "Public Broadcasting Act",
      "text": "The Public Broadcasting Act was enacted in 1967, leading to the establishment of the Corporation for Public Broadcasting and expanding the FCC's role in public broadcasting.",
      "date": "1967"
    },
    {
      "headline": "Deregulation of Telecommunications",
      "text": "The Telecommunications Act of 1996 was signed into law, significantly deregulating the telecommunications industry and expanding the FCC's role in promoting competition.",
      "date": "1996"
    },
    {
      "headline": "Net Neutrality Rules Adopted",
      "text": "In 2015, the FCC adopted net neutrality rules, classifying broadband internet as a public utility and prohibiting internet service providers from blocking or throttling traffic.",
      "date": "2015"
    },
    {
      "headline": "Repeal of Net Neutrality Rules",
      "text": "In 2017, the FCC voted to repeal the net neutrality rules established in 2015, shifting the regulatory framework for internet service providers.",
      "date": "2017"
    }
  ]
}

