{
  "timeline": [
    {
      "headline": "Introduction of the Enabling Act",
      "text": "On March 23, 1933, the Enabling Act, officially titled Gesetz zur Behebung der Not von Volk und Reich, was introduced in the Reichstag. This law was designed to give the German Cabinet, particularly the Chancellor, the power to enact laws without the Reichstag's consent.",
      "date": "1933-03-23"
    },
    {
      "headline": "Passage of the Enabling Act",
      "text": "The Enabling Act was passed on March 23, 1933, after intense negotiations and political maneuvering. The Act required a two-thirds majority to pass, which was achieved through the support of the Nazi Party and its allies, as well as the absence of Communist deputies who had been arrested or barred from voting.",
      "date": "1933-03-23"
    },
    {
      "headline": "Impact of the Enabling Act",
      "text": "Following its passage, the Enabling Act effectively gave Adolf Hitler, as Chancellor, dictatorial powers by allowing him to enact laws without the Reichstag's approval. This marked a critical step in the establishment of Nazi Germany and the dismantling of the Weimar Republic's democratic structures.",
      "date": "1933"
    },
    {
      "headline": "Renewal of the Enabling Act",
      "text": "The Enabling Act was renewed twice, in 1937 and 1941, each time extending Hitler's dictatorial powers and further entrenching the Nazi regime's control over Germany.",
      "date": "1937"
    },
    {
      "headline": "End of the Enabling Act",
      "text": "The Enabling Act remained in effect until the fall of Nazi Germany in 1945, when the Allied forces defeated Germany and dismantled the Nazi regime.",
      "date": "1945"
    }
  ]
}

