    {
      "headline": "Spanish-American War Influence",
      "text": "Yellow journalism is often cited as a factor that helped push the United States into the Spanish-American War in 1898, as sensationalized stories about Spanish atrocities in Cuba were published.",
      "date": "1898"
    },
    {
      "headline": "Decline of Yellow Journalism",
      "text": "By the early 20th century, yellow journalism began to decline as the public demanded more objective and factual reporting.",
      "date": "1900"
    }
  ]
}

