{
  "timeline": [
    {
      "headline": "Birth of Aaron",
      "text": "According to religious texts, Aaron was born in Egypt during the Israelite enslavement period. His birth is traditionally dated to around 1396 BCE.",
      "date": "-1396"
    },
    {
      "headline": "Aaron Becomes Moses' Spokesman",
      "text": "When Moses was called by God to lead the Israelites out of Egypt, Aaron was appointed as his spokesman because Moses was not eloquent. This event is traditionally dated to around 1446 BCE.",
      "date": "-1446"
    },
    {
      "headline": "Aaron's Role in the Exodus",
      "text": "Aaron played a significant role during the Exodus, assisting Moses in confronting Pharaoh and performing miracles, such as turning his staff into a serpent and initiating the plagues. This occurred around 1446 BCE.",
      "date": "-1446"
    },
    {
      "headline": "Appointment as High Priest",
      "text": "After the Exodus, Aaron was appointed as the first High Priest of the Israelites. This role was established during the Israelites' journey in the wilderness, around 1445 BCE.",
      "date": "-1445"
    },
    {
      "headline": "Incident of the Golden Calf",
      "text": "While Moses was on Mount Sinai, Aaron was persuaded by the Israelites to create a golden calf, which they worshipped. This event is traditionally dated to around 1446 BCE.",
      "date": "-1446"
    },
    {
      "headline": "Death of Aaron",
      "text": "Aaron died on Mount Hor during the Israelites' 40-year journey in the wilderness. His death is traditionally dated to 1407 BCE.",
      "date": "-1407"
    }
  ]
}

