{
  "timeline": [
    {
      "headline": "Prehistoric Europe",
      "text": "The history of Europe begins with the appearance of Homo sapiens in Europe around 45,000 years ago. The prehistoric period includes the Paleolithic, Mesolithic, Neolithic, and the Bronze and Iron Ages.",
      "date": "-45000"
    },
    {
      "headline": "Classical Antiquity",
      "text": "Classical antiquity in Europe is marked by the rise of ancient Greece and Rome. This period includes the establishment of the Greek city-states, the conquests of Alexander the Great, and the rise and fall of the Roman Empire.",
      "date": "-0800"
    },
    {
      "headline": "Fall of the Western Roman Empire",
      "text": "The Western Roman Empire officially fell in 476 AD when the last Roman emperor, Romulus Augustulus, was deposed by the Germanic king Odoacer.",
      "date": "0476"
    },
    {
      "headline": "The Middle Ages",
      "text": "The Middle Ages in Europe span from the fall of the Western Roman Empire to the beginning of the Renaissance and the Age of Discovery. This period includes the rise of feudalism, the spread of Christianity, and the Crusades.",
      "date": "0500"
    },
    {
      "headline": "The Renaissance",
      "text": "The Renaissance, beginning in the 14th century, was a period of renewed interest in art, science, and the classical world. It marked the transition from the Middle Ages to modernity.",
      "date": "1300"
    },
    {
      "headline": "The Age of Discovery",
      "text": "Starting in the late 15th century, European nations began exploring and colonizing other parts of the world, leading to significant global changes.",
      "date": "1492"
    },
    {
      "headline": "The Reformation",
      "text": "The Protestant Reformation began in 1517 with Martin Luther's Ninety-Five Theses, leading to religious and political upheaval across Europe.",
      "date": "1517"
    },
    {
      "headline": "The Enlightenment",
      "text": "The Enlightenment was an intellectual and philosophical movement that dominated Europe during the 18th century, emphasizing reason, individualism, and skepticism of traditional doctrines.",
      "date": "1700"
    },
    {
      "headline": "The French Revolution",
      "text": "The French Revolution began in 1789, leading to the rise of democracy and the decline of monarchies across Europe.",
      "date": "1789"
    },
    {
      "headline": "The Industrial Revolution",
      "text": "The Industrial Revolution, beginning in the late 18th century, transformed European economies from agrarian to industrial and urban.",
      "date": "1760"
    },
    {
      "headline": "World War I",
      "text": "World War I, also known as the Great War, was a global war originating in Europe that lasted from 1914 to 1918.",
      "date": "1914"
    },
    {
      "headline": "World War II",
      "text": "World War II was a global conflict that lasted from 1939 to 1945, involving most of the world's nations, including all of the great powers.",
      "date": "1939"
    },
    {
      "headline": "The European Union",
      "text": "The European Union was established by the Maastricht Treaty, which came into force on November 1, 1993, marking a new era of political and economic integration in Europe.",
      "date": "1993-11-01"
    }
  ]
}

