{
  "timeline": [
    {
      "headline": "Origins of Wuxia",
      "text": "The origins of Wuxia can be traced back to ancient Chinese literature, with early examples found in the 'Zhuangzi' and 'Records of the Grand Historian' by Sima Qian, which date back to the Han dynasty (206 BCE – 220 CE). These texts include stories of knights-errant and martial heroes.",
      "date": "-0206"
    },
    {
      "headline": "Development during Tang Dynasty",
      "text": "During the Tang dynasty (618–907), the genre began to take shape with the emergence of stories about youxia (wandering heroes) who upheld justice and fought against oppression.",
      "date": "0618"
    },
    {
      "headline": "Ming Dynasty Novels",
      "text": "In the Ming dynasty (1368–1644), Wuxia stories became more popular with the publication of novels such as 'Water Margin' and 'The Seven Heroes and Five Gallants', which featured martial arts and heroic themes.",
      "date": "1368"
    },
    {
      "headline": "Qing Dynasty and the Rise of Wuxia Fiction",
      "text": "The Qing dynasty (1644–1912) saw the rise of Wuxia fiction as a distinct genre, with serialized stories published in newspapers and magazines, gaining widespread popularity.",
      "date": "1644"
    },
    {
      "headline": "Republic of China Era",
      "text": "In the early 20th century, during the Republic of China era, Wuxia novels gained immense popularity, with authors like Jin Yong and Gu Long becoming prominent figures in the genre.",
      "date": "1912"
    },
    {
      "headline": "Wuxia in Film",
      "text": "The 1960s and 1970s saw the rise of Wuxia films, particularly in Hong Kong, with directors like King Hu and Chang Cheh bringing the genre to the silver screen, influencing global cinema.",
      "date": "1960"
    },
    {
      "headline": "Modern Adaptations",
      "text": "In the late 20th and early 21st centuries, Wuxia continued to evolve, with adaptations in television dramas, video games, and international films, such as 'Crouching Tiger, Hidden Dragon' (2000), which brought global attention to the genre.",
      "date": "2000"
    }
  ]
}

