    {
      "headline": "Ottoman Rule",
      "text": "Greece falls under Ottoman rule in the 15th century, following the fall of Constantinople in 1453.",
      "date": "1453"
    },
    {
      "headline": "Greek War of Independence",
      "text": "The Greek War of Independence begins in 1821, leading to the establishment of an independent Greek state in 1830.",
      "date": "1821"
