{
  "timeline": [
    {
      "headline": "Birth of Kit Carson",
      "text": "Christopher Houston Carson, known as Kit Carson, was born on December 24, 1809, in Madison County, Kentucky.",
      "date": "1809-12-24"
    },
    {
      "headline": "Move to Missouri",
      "text": "In 1811, Kit Carson's family moved to Franklin, Missouri, where he spent much of his childhood.",
      "date": "1811"
    },
    {
      "headline": "Apprenticeship as a Saddler",
      "text": "At the age of 14, in 1824, Kit Carson was apprenticed to a saddler in Franklin, Missouri, but he soon left to join a caravan of traders bound for Santa Fe.",
      "date": "1824"
    },
    {
      "headline": "First Expedition as a Trapper",
      "text": "In 1829, Carson joined his first expedition as a trapper, traveling to the Rocky Mountains and beginning his career as a mountain man.",
      "date": "1829"
    },
    {
      "headline": "Marriage to Singing Grass",
      "text": "In 1835, Kit Carson married an Arapaho woman named Singing Grass, with whom he had two children.",
      "date": "1835"
    },
    {
      "headline": "Guide for John C. Frémont",
      "text": "In 1842, Carson became a guide for John C. Frémont's first expedition to map the western territories of the United States.",
      "date": "1842"
    },
    {
      "headline": "Second Marriage to Making-Out-Road",
      "text": "After the death of his first wife, Carson married a Cheyenne woman named Making-Out-Road in 1841, but the marriage was short-lived.",
      "date": "1841"
    },
    {
      "headline": "Third Marriage to Josefa Jaramillo",
      "text": "In 1843, Carson married Josefa Jaramillo, a prominent Mexican woman from Taos, New Mexico.",
      "date": "1843"
    },
    {
      "headline": "Mexican-American War Service",
      "text": "During the Mexican-American War (1846-1848), Carson served as a guide and courier for the U.S. Army, playing a significant role in the conquest of California.",
      "date": "1846"
    },
    {
      "headline": "Appointment as Indian Agent",
      "text": "In 1854, Carson was appointed as the Indian agent for northern New Mexico, where he worked to maintain peace between settlers and Native American tribes.",
      "date": "1854"
    },
    {
      "headline": "Civil War Service",
      "text": "During the American Civil War, Carson served as a colonel in the Union Army, leading campaigns against the Navajo and other tribes.",
      "date": "1861"
    },
    {
      "headline": "Battle of Adobe Walls",
      "text": "In 1864, Carson led U.S. forces in the Battle of Adobe Walls against the Comanche and Kiowa, a significant engagement in the Indian Wars.",
      "date": "1864"
    },
    {
      "headline": "Death of Kit Carson",
      "text": "Kit Carson died on May 23, 1868, in Fort Lyon, Colorado, from an abdominal aortic aneurysm.",
      "date": "1868-05-23"
    }
  ]
}

