      "headline": "Birth of Robert Gould Shaw",
      "text": "Robert Gould Shaw was born on October 10, 1837, in Boston, Massachusetts, into a prominent abolitionist family.",
      "date": "1837-10-10"
    },
    {
      "headline": "Enlistment in the Union Army",
      "text": "In May 1861, Robert Gould Shaw enlisted in the Union Army, joining the 7th New York Militia and later the 2nd Massachusetts Infantry.",
      "date": "1861-05"
    },
    {
      "headline": "Promotion to Captain",
      "text": "Shaw was promoted to the rank of captain in the 2nd Massachusetts Infantry in 1862.",
      "date": "1862"
    },
    {
      "headline": "Command of the 54th Massachusetts Infantry Regiment",
      "text": "In March 1863, Shaw was offered and accepted the command of the 54th Massachusetts Infantry Regiment, the first all-black regiment in the Northeast.",
      "date": "1863-03"
    },
    {
      "headline": "Refusal of Unequal Pay",
      "text": "In June 1863, Shaw and his regiment refused their pay in protest of the unequal wages offered to black soldiers compared to their white counterparts.",
      "date": "1863-06"
    },
    {
      "headline": "Assault on Fort Wagner",
      "text": "On July 18, 1863, Shaw led the 54th Massachusetts in a courageous but deadly assault on Fort Wagner in South Carolina, where he was killed in action.",
      "date": "1863-07-18"
    },
    {
      "headline": "Death of Robert Gould Shaw",
      "text": "Robert Gould Shaw died on July 18, 1863, during the assault on Fort Wagner. He was buried in a mass grave with many of his men, a gesture intended as an insult by Confederate forces but later seen as a symbol of his solidarity with his troops.",
      "date": "1863-07-18"
    }
  ]
}

