    {
      "headline": "Foundation of Moldavia",
      "text": "Moldavia was founded as a principality in the 14th century by Dragoș, a Romanian voivode from Maramureș, who was sent by the Hungarian king to establish a defense line against the Tatars.",
      "date": "1300"
    },
    {
      "headline": "Reign of Bogdan I",
      "text": "Bogdan I, a voivode from Maramureș, led a rebellion against Hungarian rule and established Moldavia as an independent principality in 1359.",
      "date": "1359"
    },
    {
      "headline": "Reign of Stephen the Great",
      "text": "Stephen the Great became the ruler of Moldavia in 1457 and is known for his military successes and cultural achievements. He ruled until his death in 1504.",
      "date": "1457"
    },
    {
      "headline": "Battle of Vaslui",
      "text": "On January 10, 1475, Stephen the Great won a decisive victory against the Ottoman Empire at the Battle of Vaslui, which is considered one of his greatest military achievements.",
      "date": "1475-01-10"
    },
    {
      "headline": "Ottoman Suzerainty",
      "text": "In 1538, Moldavia became a vassal state of the Ottoman Empire, maintaining internal autonomy but paying tribute to the Ottomans.",
      "date": "1538"
    },
    {
      "headline": "Union with Wallachia",
      "text": "In 1859, Moldavia united with Wallachia under the rule of Alexandru Ioan Cuza, forming the basis of modern Romania.",
      "date": "1859"
    }
  ]
}

