{
  "timeline": [
    {
      "headline": "North Carolina v. Alford",
      "text": "The Alford plea originated from the Supreme Court case North Carolina v. Alford, decided on November 23, 1970. In this case, Henry Alford was charged with first-degree murder and faced the death penalty. He pleaded guilty to second-degree murder to avoid the death penalty, while maintaining his innocence.",
      "date": "1970-11-23"
    },
    {
      "headline": "Supreme Court Decision",
      "text": "The United States Supreme Court ruled that a defendant can enter a guilty plea while still asserting innocence if the plea is in the defendant's best interest. This decision established the legal precedent for the Alford plea.",
      "date": "1970-11-23"
    },
    {
      "headline": "Adoption of Alford Plea",
      "text": "Following the Supreme Court's decision, the Alford plea was adopted in various jurisdictions across the United States. It became a legal option for defendants who wish to plead guilty without admitting guilt.",
      "date": "1970s"
    }
  ]
}

