{
  "timeline": [
    {
      "headline": "Martin Luther's Birth",
      "text": "Martin Luther, a seminal figure in the Protestant Reformation, was born on November 10, 1483, in Eisleben, Germany.",
      "date": "1483-11-10"
    },
    {
      "headline": "Ninety-Five Theses",
      "text": "On October 31, 1517, Martin Luther nailed his Ninety-Five Theses to the door of the Wittenberg Castle church, challenging the Catholic Church's practices and sparking the Protestant Reformation.",
      "date": "1517-10-31"
    },
    {
      "headline": "Diet of Worms",
      "text": "In 1521, Martin Luther was summoned to the Diet of Worms, where he refused to recant his teachings, leading to his excommunication from the Catholic Church.",
      "date": "1521"
    },
    {
      "headline": "Publication of Luther's German Bible",
      "text": "In 1534, Martin Luther completed his translation of the Bible into German, making the scriptures more accessible to the general public and furthering the spread of Protestantism.",
      "date": "1534"
    },
    {
      "headline": "Peace of Augsburg",
      "text": "In 1555, the Peace of Augsburg was signed, allowing rulers within the Holy Roman Empire to choose either Lutheranism or Catholicism as the official confession of their state, marking a significant moment in the recognition of Protestantism.",
      "date": "1555"
    },
    {
      "headline": "John Calvin's Institutes of the Christian Religion",
      "text": "John Calvin published the first edition of his seminal work, 'Institutes of the Christian Religion,' in 1536, which became a foundational text for Reformed theology.",
      "date": "1536"
    },
    {
      "headline": "English Reformation",
      "text": "The English Reformation began in 1534 when King Henry VIII declared himself the Supreme Head of the Church of England, breaking away from the authority of the Pope and the Roman Catholic Church.",
      "date": "1534"
    },
    {
      "headline": "Council of Trent",
      "text": "The Council of Trent, held between 1545 and 1563, was the Catholic Church's response to the Protestant Reformation, leading to significant reforms within the Church.",
      "date": "1545"
    },
    {
      "headline": "Thirty Years' War",
      "text": "The Thirty Years' War, from 1618 to 1648, was a series of conflicts across Europe that were partly fueled by the tensions between Protestant and Catholic states.",
      "date": "1618"
    },
    {
      "headline": "Peace of Westphalia",
      "text": "The Peace of Westphalia, signed in 1648, ended the Thirty Years' War and marked the beginning of state sovereignty, recognizing the coexistence of Protestant and Catholic states in Europe.",
      "date": "1648"
    }
  ]
}

