{
  "timeline": [
    {
      "headline": "Earliest Hydroponic Practices",
      "text": "The earliest known use of hydroponics dates back to the Hanging Gardens of Babylon, one of the Seven Wonders of the Ancient World, which were built around 600 BCE. These gardens are believed to have used a form of hydroponics to grow plants.",
      "date": "-0600"
    },
    {
      "headline": "Francis Bacon's Hydroponics Research",
      "text": "In 1627, Francis Bacon published 'Sylva Sylvarum', which included early research on growing plants without soil, laying the groundwork for future hydroponic studies.",
      "date": "1627"
    },
    {
      "headline": "John Woodward's Experiments",
      "text": "In 1699, John Woodward conducted experiments with spearmint, demonstrating that plants could grow in water with added nutrients, contributing to the understanding of hydroponics.",
      "date": "1699"
    },
    {
      "headline": "Julius von Sachs' Nutrient Solution",
      "text": "In 1860, German botanist Julius von Sachs developed the first nutrient solution for plant growth, marking a significant advancement in hydroponic science.",
      "date": "1860"
    },
    {
      "headline": "William Frederick Gericke Coins 'Hydroponics'",
      "text": "In the 1930s, William Frederick Gericke of the University of California coined the term 'hydroponics' to describe the cultivation of plants in nutrient solutions.",
      "date": "1930"
    },
    {
      "headline": "Hydroponics in World War II",
      "text": "During World War II, hydroponics was used to supply fresh produce to troops stationed on non-arable islands in the Pacific, demonstrating its practical applications.",
      "date": "1940s"
    },
    {
      "headline": "NASA's CELSS Program",
      "text": "In the 1990s, NASA began researching hydroponics as part of its Controlled Ecological Life Support System (CELSS) program to grow food in space.",
      "date": "1990s"
    },
    {
      "headline": "Modern Commercial Hydroponics",
      "text": "In the 21st century, hydroponics has become a popular method for commercial agriculture, allowing for efficient, soil-free farming in urban and arid environments.",
      "date": "2000s"
    }
  ]
}

