    {
      "headline": "First Ascent of Manaslu",
      "text": "On May 9, 1956, Toshio Imanishi and Gyalzen Norbu, members of a Japanese expedition, became the first to reach the summit of Manaslu, the eighth-highest mountain in the world.",
      "date": "1956-05-09"
    },
    {
      "headline": "First Ascent of Nanga Parbat",
