{
  "timeline": [
    {
      "headline": "Russian Settlement Established",
      "text": "In 1799, Alexander Baranov, the chief manager of the Russian-American Company, established a settlement in Sitka, Alaska, which was then known as New Archangel.",
      "date": "1799"
    },
    {
      "headline": "Battle of Sitka",
      "text": "In 1804, the Battle of Sitka took place between the Tlingit people and Russian settlers. The Russians, with the help of Aleut allies, defeated the Tlingit, leading to Russian control over the area.",
      "date": "1804"
    },
    {
      "headline": "Capital of Russian America",
      "text": "In 1808, Sitka became the capital of Russian America, serving as the administrative center for Russian activities in the region.",
      "date": "1808"
    },
    {
      "headline": "Transfer of Alaska",
      "text": "On October 18, 1867, the United States formally took possession of Alaska from Russia in a ceremony held in Sitka, marking the transfer of the territory.",
      "date": "1867-10-18"
    },
    {
      "headline": "Alaska Purchase",
      "text": "The Alaska Purchase was finalized in 1867, with Sitka serving as the site of the transfer ceremony. The U.S. acquired Alaska from Russia for $7.2 million.",
      "date": "1867"
    },
    {
      "headline": "Sitka Becomes Part of the United States",
      "text": "Following the Alaska Purchase, Sitka became part of the United States and served as the capital of the Alaska Territory until 1906.",
      "date": "1867"
    },
    {
      "headline": "Capital Moved to Juneau",
      "text": "In 1906, the capital of the Alaska Territory was moved from Sitka to Juneau, reflecting the shift in economic and political focus.",
      "date": "1906"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Sitka was incorporated as a city in 1913, formalizing its status as a municipality within the Alaska Territory.",
      "date": "1913"
    },
    {
      "headline": "Unification of City and Borough",
      "text": "In 1971, the City of Sitka and the Greater Sitka Borough were unified, creating the City and Borough of Sitka.",
      "date": "1971"
    },
    {
      "headline": "Population in 2020 Census",
      "text": "According to the 2020 census, Sitka had a population of 8,458, making it the fifth-most populated city in the state of Alaska.",
      "date": "2020"
    }
  ]
}

