  "timeline": [
    {
      "headline": "Marin Mersenne Studies Mersenne Primes",
      "text": "In the early 17th century, Marin Mersenne, a French Minim friar, studied numbers of the form 2^n - 1, which are now known as Mersenne primes.",
      "date": "1600"
    },
    {
      "headline": "First Known Mersenne Prime",
      "text": "The first known Mersenne prime is 3, which is 2^2 - 1.",
      "date": "-0001"
    },
    {
      "headline": "Discovery of Mersenne Prime 7",
      "text": "The number 7 is a Mersenne prime, as it can be expressed as 2^3 - 1.",
      "date": "-0001"
    },
    {
      "headline": "Discovery of Mersenne Prime 31",
      "text": "The number 31 is a Mersenne prime, as it can be expressed as 2^5 - 1.",
      "date": "-0001"
    },
    {
      "headline": "Discovery of Mersenne Prime 127",
      "text": "The number 127 is a Mersenne prime, as it can be expressed as 2^7 - 1.",
      "date": "-0001"
    },
    {
      "headline": "Mersenne's Incorrect List",
      "text": "In 1644, Marin Mersenne incorrectly listed the exponents for which 2^n - 1 is prime, missing some and including some that are not primes.",
      "date": "1644"
    },
    {
      "headline": "Lucas-Lehmer Test Developed",
      "text": "In the 20th century, the Lucas-Lehmer test was developed, which is an efficient algorithm to test the primality of Mersenne numbers.",
      "date": "1900"
    },
    {
      "headline": "Electronic Computers Find Large Mersenne Primes",
      "text": "In the mid-20th century, electronic computers began to find large Mersenne primes, significantly increasing the known list.",
      "date": "1950"
    },
    {
      "headline": "Great Internet Mersenne Prime Search (GIMPS) Founded",
      "text": "In 1996, the Great Internet Mersenne Prime Search (GIMPS) was founded, utilizing distributed computing to search for large Mersenne primes.",
      "date": "1996"
    },
    {
      "headline": "Discovery of the Largest Known Mersenne Prime",
      "text": "As of December 2018, the largest known Mersenne prime is 2^82,589,933 - 1, discovered by GIMPS.",
      "date": "2018-12"
    }
  ]
}

