    {
      "headline": "Northwest Ordinance",
      "text": "In 1787, the Northwest Ordinance was enacted, prohibiting slavery in the Northwest Territory, which included areas that would become the states of Ohio, Indiana, Illinois, Michigan, and Wisconsin.",
      "date": "1787"
    },
    {
      "headline": "Fugitive Slave Act of 1793",
      "text": "In 1793, the Fugitive Slave Act was passed by the United States Congress, which allowed for the capture and return of runaway enslaved people within the territory of the United States.",
      "date": "1793"
    },
    {
      "headline": "Missouri Compromise",
      "text": "In 1820, the Missouri Compromise was enacted, admitting Missouri as a slave state and Maine as a free state to maintain the balance of power between slave and free states.",
      "date": "1820"
    },
    {
      "headline": "Compromise of 1850",
      "text": "In 1850, the Compromise of 1850 was passed, which included the admission of California as a free state and the enactment of a stricter Fugitive Slave Law.",
      "date": "1850"
    },
    {
      "headline": "Fugitive Slave Act of 1850",
      "text": "The Fugitive Slave Act of 1850 was part of the Compromise of 1850, strengthening the laws regarding the capture and return of runaway enslaved people.",
      "date": "1850"
    },
    {
      "headline": "Kansas-Nebraska Act",
      "text": "In 1854, the Kansas-Nebraska Act was passed, allowing the territories of Kansas and Nebraska to decide for themselves whether to allow slavery, effectively repealing the Missouri Compromise.",
      "date": "1854"
    },
    {
      "headline": "Dred Scott Decision",
      "text": "In 1857, the U.S. Supreme Court issued the Dred Scott decision, ruling that African Americans were not citizens and that Congress had no authority to prohibit slavery in federal territories.",
      "date": "1857"
    },
    {
      "headline": "Civil War Begins",
      "text": "In 1861, the American Civil War began, largely over the issues of slavery and states' rights.",
      "date": "1861"
    },
    {
      "headline": "Emancipation Proclamation",
      "text": "On January 1, 1863, President Abraham Lincoln issued the Emancipation Proclamation, declaring all slaves in Confederate-held territory to be free.",
      "date": "1863-01-01"
    },
    {
      "headline": "Thirteenth Amendment",
      "text": "In 1865, the Thirteenth Amendment to the United States Constitution was ratified, abolishing slavery throughout the United States.",
      "date": "1865"
    }
  ]
}

