{
  "timeline": [
    {
      "headline": "Rise of Barbary Pirates",
      "text": "The Barbary pirates began to rise in prominence in the late 15th century, following the Reconquista and the expulsion of Muslims from Spain. They established bases along the North African coast, known as the Barbary Coast.",
      "date": "1492"
    },
    {
      "headline": "Ottoman Influence",
      "text": "In the early 16th century, the Ottoman Empire began to exert influence over the Barbary states, providing them with naval support and integrating them into the Ottoman naval strategy.",
      "date": "1500"
    },
    {
      "headline": "Hayreddin Barbarossa's Leadership",
      "text": "Hayreddin Barbarossa, a prominent Ottoman admiral and privateer, became a leading figure among the Barbary pirates in the early 16th century, significantly expanding their operations.",
      "date": "1530"
    },
    {
      "headline": "Sack of Baltimore",
      "text": "On June 20, 1631, Barbary pirates raided the village of Baltimore in Ireland, capturing over 100 people and selling them into slavery in North Africa.",
      "date": "1631-06-20"
    },
    {
      "headline": "Treaty of Peace and Amity",
      "text": "In 1786, the United States attempted to negotiate peace treaties with the Barbary states to stop pirate attacks on American ships, leading to the Treaty of Peace and Amity with Morocco.",
      "date": "1786"
    },
    {
      "headline": "First Barbary War",
      "text": "The First Barbary War took place from 1801 to 1805, involving the United States and Sweden against the Barbary states of Tripoli and Algiers, aiming to end piracy against American vessels.",
      "date": "1801"
    },
    {
      "headline": "Second Barbary War",
      "text": "The Second Barbary War occurred in 1815, when the United States and European allies launched a military campaign against Algiers to stop piracy and free enslaved Europeans.",
      "date": "1815"
    },
    {
      "headline": "End of Barbary Piracy",
      "text": "The Barbary pirates' power was effectively ended in 1830 when France invaded and colonized Algiers, leading to the decline of piracy in the region.",
      "date": "1830"
    }
  ]
}

