{
  "timeline": [
    {
      "headline": "Formation of the Communist Party of Germany",
      "text": "The Communist Party of Germany (KPD) was founded on December 30, 1918, in Berlin. It was established by members of the Spartacus League and other radical left-wing groups.",
      "date": "1918-12-30"
    },
    {
      "headline": "Spartacist Uprising",
      "text": "In January 1919, the KPD participated in the Spartacist Uprising, an attempt to overthrow the Weimar government. The uprising was suppressed by the government with the help of the Freikorps.",
      "date": "1919-01"
    },
    {
      "headline": "Participation in the Weimar Republic Elections",
      "text": "The KPD participated in the elections of the Weimar Republic, becoming a significant political force in the Reichstag during the 1920s.",
      "date": "1920"
    },
    {
      "headline": "KPD's Role in the 1923 German October",
      "text": "In October 1923, the KPD attempted to initiate a revolution in Germany, inspired by the Bolshevik Revolution in Russia. The plan failed, and the party faced repression.",
      "date": "1923-10"
    },
    {
      "headline": "KPD's Resistance to Nazism",
      "text": "During the rise of the Nazi Party, the KPD was one of the main opponents of Adolf Hitler and the Nazis. After the Nazis came to power in 1933, the KPD was banned, and its members were persecuted.",
      "date": "1933"
    },
    {
      "headline": "KPD in Exile and Underground Resistance",
      "text": "After being banned in 1933, the KPD operated in exile and as an underground resistance movement against the Nazi regime throughout World War II.",
      "date": "1933-1945"
    },
    {
      "headline": "Re-establishment in Postwar Germany",
      "text": "After World War II, the KPD was re-established in both East and West Germany. In East Germany, it merged with the Social Democratic Party to form the Socialist Unity Party of Germany (SED).",
      "date": "1945"
    },
    {
      "headline": "Ban of the KPD in West Germany",
      "text": "On August 17, 1956, the Federal Constitutional Court of West Germany banned the KPD, citing its opposition to the democratic order.",
      "date": "1956-08-17"
    }
  ]
}

