    {
      "headline": "Emergence of Crocodilia",
      "text": "The order Crocodilia, which includes modern crocodilians, first appeared during the Late Cretaceous period, around 95 million years ago.",
      "date": "-0095000000"
    },
    {
      "headline": "Diversification of Crocodilians",
      "text": "Crocodilians diversified into various forms, including true crocodiles, alligators, caimans, and gharials, during the Cenozoic era following the extinction of the dinosaurs.",
      "date": "-0066000000"
    },
    {
      "headline": "Modern Crocodilian Families",
      "text": "Today, the order Crocodilia includes three families: Crocodylidae (true crocodiles), Alligatoridae (alligators and caimans), and Gavialidae (gharial and false gharial).",
      "date": "0000"
    }
  ]
}

