{
  "timeline": [
    {
      "headline": "Golden Age of Jewish Culture in Spain",
      "text": "During the 10th and 11th centuries, Sephardic Jews experienced a Golden Age in Spain, characterized by significant contributions to philosophy, science, medicine, and literature.",
      "date": "0911"
    },
    {
      "headline": "Almohad Conquest",
      "text": "In the 12th century, the Almohad conquest of Spain led to the persecution of Jews, forcing many to flee to other regions, including North Africa and the Middle East.",
      "date": "1147"
    },
    {
      "headline": "Expulsion from Spain",
      "text": "On March 31, 1492, the Alhambra Decree ordered the expulsion of practicing Jews from the Kingdoms of Castile and Aragon by July 31, 1492.",
      "date": "1492-03-31"
    },
    {
      "headline": "Expulsion from Portugal",
      "text": "In December 1496, King Manuel I of Portugal decreed the expulsion of Jews from Portugal, leading to forced conversions and emigration.",
      "date": "1496-12"
    },
    {
      "headline": "Settlement in the Ottoman Empire",
      "text": "Following their expulsion from Spain and Portugal, many Sephardic Jews found refuge in the Ottoman Empire, where they were welcomed and allowed to settle.",
      "date": "1500"
    },
    {
      "headline": "Establishment of Sephardic Communities in Amsterdam",
      "text": "In the 17th century, Sephardic Jews established thriving communities in Amsterdam, contributing to the city's economic and cultural life.",
      "date": "1600"
    },
    {
      "headline": "Sephardic Jews in the New World",
      "text": "Sephardic Jews were among the first Jewish settlers in the Americas, establishing communities in places like Brazil, Suriname, and the Caribbean during the 17th century.",
      "date": "1654"
    },
    {
      "headline": "Integration into Middle Eastern and North African Communities",
      "text": "Over the centuries, Sephardic Jews integrated with Jewish communities in the Middle East and North Africa, influencing local customs and practices.",
      "date": "1700"
    },
    {
      "headline": "Modern Sephardic Communities in Israel",
      "text": "In the 20th century, many Sephardic Jews immigrated to Israel, where they now form a significant part of the population.",
      "date": "1948"
    }
  ]
}

