      "headline": "Prehistoric Consumption",
      "text": "Archaeological evidence suggests that pancakes were probably eaten in prehistoric societies. This indicates the long-standing presence of pancakes in human diets.",
      "date": "-10000"
    },
    {
      "headline": "Otzi the Iceman",
      "text": "Otzi the Iceman, who lived around 3300 BCE, was found with remnants of a pancake-like food in his stomach, indicating the consumption of pancakes during this period.",
      "date": "-03300"
    },
    {
      "headline": "Ancient Greece and Rome",
      "text": "In Ancient Greece and Rome, pancakes were made from wheat flour, olive oil, honey, and curdled milk. They were a common breakfast food.",
      "date": "-0500"
    },
    {
      "headline": "Medieval Europe",
      "text": "During the medieval period, pancakes were made from ingredients such as barley, wheat, or buckwheat, and were a staple food across Europe.",
      "date": "1000"
    },
    {
      "headline": "Shrove Tuesday Tradition",
      "text": "By the 16th century, pancakes became associated with Shrove Tuesday, a day for using up rich foods before Lent in Christian tradition.",
      "date": "1500"
    },
    {
      "headline": "Introduction to America",
      "text": "Pancakes were introduced to America by European settlers, where they became a popular breakfast food.",
      "date": "1600"
    },
    {
      "headline": "Modern Pancake Variations",
      "text": "In the 19th and 20th centuries, pancakes evolved into various forms and recipes, including the American-style pancake, which is thicker and fluffier.",
      "date": "1900"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Neoplatonism",
      "text": "Neoplatonism was founded by the philosopher Plotinus in the 3rd century AD. Plotinus was born in Lycopolis, Egypt, and studied philosophy in Alexandria before moving to Rome, where he established a school.",
      "date": "0205"
    },
    {
      "headline": "Plotinus' Enneads",
      "text": "Around 270 AD, Plotinus' teachings were compiled into six groups of nine treatises, known as the Enneads, by his student Porphyry. These writings form the core of Neoplatonic philosophy.",
      "date": "0270"
    },
    {
      "headline": "Porphyry's Contributions",
      "text": "Porphyry, a student of Plotinus, expanded Neoplatonism by writing 'Isagoge', an introduction to Aristotle's categories, and other works that integrated Neoplatonism with Aristotelian logic.",
      "date": "0280"
    },
    {
      "headline": "Iamblichus' Influence",
      "text": "In the early 4th century, Iamblichus further developed Neoplatonism by incorporating religious and mystical elements. He emphasized theurgy, a practice of rituals intended to invoke the presence of gods.",
      "date": "0300"
    },
    {
      "headline": "Proclus' Systematization",
      "text": "Proclus, a prominent Neoplatonist philosopher, lived from 412 to 485 AD. He systematized Neoplatonic thought and wrote extensive commentaries on Plato and other philosophical works.",
      "date": "0412"
    },
    {
      "headline": "Closure of the Platonic Academy",
      "text": "In 529 AD, the Byzantine Emperor Justinian I closed the Platonic Academy in Athens, which was a major center for Neoplatonic thought, marking the decline of pagan philosophy in the Byzantine Empire.",
      "date": "0529"
    },
    {
      "headline": "Neoplatonism in the Islamic World",
      "text": "During the Islamic Golden Age, Neoplatonic ideas were integrated into Islamic philosophy, influencing thinkers like Al-Farabi, Avicenna, and Averroes.",
      "date": "0800"
    },
    {
      "headline": "Neoplatonism in the Renaissance",
      "text": "In the 15th century, Neoplatonism experienced a revival during the Renaissance, particularly in Florence, where thinkers like Marsilio Ficino translated and interpreted Neoplatonic texts.",
      "date": "1450"
    }
  ]
}

