{
  "timeline": [
    {
      "headline": "Start of the Northeast Blackout",
      "text": "The Northeast blackout of 2003 began on August 14, 2003, just after 4:10 p.m. EDT. It was a widespread power outage that affected parts of the Northeastern and Midwestern United States, and most parts of the Canadian province of Ontario.",
      "date": "2003-08-14"
    },
    {
      "headline": "Impact of the Blackout",
      "text": "The blackout affected an estimated 50 million people and covered an area of 24,000 square miles. Major cities like New York City, Cleveland, Detroit, and Toronto experienced significant disruptions.",
      "date": "2003-08-14"
    },
    {
      "headline": "Restoration of Power",
      "text": "Power began to be restored in some areas by the evening of August 14, 2003. However, full restoration took several days, with some areas regaining power by August 16, 2003.",
      "date": "2003-08-16"
    },
    {
      "headline": "Investigation and Cause",
      "text": "An investigation revealed that the blackout was caused by a software bug in the alarm system at a control room of FirstEnergy Corporation in Ohio. This prevented operators from being alerted to the need to redistribute power after overloaded transmission lines hit untrimmed foliage.",
      "date": "2003"
    },
    {
      "headline": "Aftermath and Reforms",
      "text": "The blackout led to significant changes in the electricity grid management and policies in both the United States and Canada. It highlighted the need for better grid reliability and prompted reforms to prevent future outages.",
      "date": "2003"
    }
  ]
}

