    {
      "headline": "Expansion of Doctoral Degrees",
      "text": "By the 14th century, the title of 'Doctor' had spread to other European universities, becoming a recognized academic title.",
      "date": "1300"
    },
    {
      "headline": "Doctorate in Law",
      "text": "The University of Bologna was particularly known for its doctorate in law, which became a model for other universities.",
      "date": "1300"
    },
    {
      "headline": "Doctorate in Medicine",
      "text": "The University of Paris became renowned for its doctorate in medicine, influencing medical education across Europe.",
      "date": "1300"
    },
    {
      "headline": "Doctorate in Theology",
      "text": "The title 'Doctor' was also used for theology, with the University of Paris being a prominent center for theological studies.",
      "date": "1300"
    },
