{
  "timeline": [
    {
      "headline": "Thomas Hobbes' Leviathan",
      "text": "In 1651, Thomas Hobbes published 'Leviathan', which is one of the earliest and most influential works on social contract theory. Hobbes argued that in the state of nature, life would be 'solitary, poor, nasty, brutish, and short', and that individuals consent to surrender some of their freedoms and submit to the authority of a ruler in exchange for protection of their remaining rights.",
      "date": "1651"
    },
    {
      "headline": "John Locke's Two Treatises of Government",
      "text": "In 1689, John Locke published 'Two Treatises of Government', which presented a different view of the social contract. Locke argued that individuals have natural rights to life, liberty, and property that must be preserved by the government. If a government fails to protect these rights, citizens have the right to overthrow it.",
      "date": "1689"
    },
    {
      "headline": "Jean-Jacques Rousseau's The Social Contract",
      "text": "In 1762, Jean-Jacques Rousseau published 'The Social Contract', which introduced the idea that legitimate political authority relies on a social contract agreed upon by all citizens for their mutual preservation. Rousseau's work emphasized the concept of the 'general will' and the idea that sovereignty should be in the hands of the people.",
      "date": "1762"
    },
    {
      "headline": "Immanuel Kant's Critique of Practical Reason",
      "text": "In 1788, Immanuel Kant published 'Critique of Practical Reason', where he discussed the social contract as a rational basis for moral and political philosophy. Kant's work influenced the development of modern political and ethical theory.",
      "date": "1788"
    },
    {
      "headline": "John Rawls' A Theory of Justice",
      "text": "In 1971, John Rawls published 'A Theory of Justice', which revived interest in social contract theory in the 20th century. Rawls introduced the idea of the 'original position' and the 'veil of ignorance' as a way to determine the principles of justice that should govern a society.",
      "date": "1971"
    }
  ]
}

