      "headline": "Formation of the Gang of Four",
      "text": "The Gang of Four, a political faction within the Chinese Communist Party, came to prominence during the Cultural Revolution. The group was led by Jiang Qing, the wife of Mao Zedong, and included Zhang Chunqiao, Yao Wenyuan, and Wang Hongwen.",
      "date": "1966"
    },
    {
      "headline": "Cultural Revolution Influence",
      "text": "Throughout the Cultural Revolution (1966-1976), the Gang of Four wielded significant power and influence, promoting Maoist policies and purging perceived enemies within the Communist Party.",
      "date": "1966"
    },
    {
      "headline": "Arrest of the Gang of Four",
      "text": "On October 6, 1976, shortly after the death of Mao Zedong, the Gang of Four was arrested by Hua Guofeng and other party leaders. This marked the end of their political influence.",
      "date": "1976-10-06"
    },
    {
      "headline": "Trial and Conviction",
      "text": "In 1981, the Gang of Four was put on trial for their crimes during the Cultural Revolution. They were charged with treason and other offenses, leading to their conviction.",
      "date": "1981"
    },
    {
      "headline": "Sentencing of the Gang of Four",
      "text": "Jiang Qing and Zhang Chunqiao were sentenced to death with a two-year reprieve, which was later commuted to life imprisonment. Yao Wenyuan and Wang Hongwen received lengthy prison sentences.",
      "date": "1981"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Introduction of Euro 1 Standards",
      "text": "The Euro 1 standards were introduced in July 1992. These were the first European emission standards, setting limits on emissions of nitrogen oxides (NOx), hydrocarbons (HC), carbon monoxide (CO), and particulate matter (PM) from vehicles.",
      "date": "1992-07"
    },
    {
      "headline": "Implementation of Euro 2 Standards",
      "text": "Euro 2 standards came into effect in January 1996. These standards further reduced the permissible levels of vehicle emissions, building on the foundation set by Euro 1.",
      "date": "1996-01"
    },
    {
      "headline": "Euro 3 Standards Enforced",
      "text": "In January 2000, Euro 3 standards were enforced. These standards introduced stricter limits on emissions and included separate limits for diesel and petrol engines.",
      "date": "2000-01"
    },
    {
      "headline": "Introduction of Euro 4 Standards",
      "text": "Euro 4 standards were introduced in January 2005. These standards required even lower emissions of NOx and PM, particularly from diesel vehicles.",
      "date": "2005-01"
    },
    {
      "headline": "Euro 5 Standards Implemented",
      "text": "Euro 5 standards were implemented in September 2009. These standards further tightened the limits on emissions, particularly focusing on reducing particulate matter from diesel engines.",
      "date": "2009-09"
    },
    {
      "headline": "Euro 6 Standards Enforced",
      "text": "Euro 6 standards came into effect in September 2014. These standards introduced the most stringent limits yet, particularly targeting NOx emissions from diesel vehicles.",
      "date": "2014-09"
    },
    {
      "headline": "Introduction of Euro 6d-TEMP",
      "text": "In September 2017, the Euro 6d-TEMP standards were introduced. These standards included real driving emissions (RDE) testing to ensure compliance under real-world conditions.",
      "date": "2017-09"
    },
    {
      "headline": "Implementation of Euro 6d Standards",
      "text": "Euro 6d standards were fully implemented in January 2020. These standards further refined the RDE testing procedures and limits.",
      "date": "2020-01"
    }
  ]
}

