{
  "timeline": [
    {
      "headline": "Foundation of Isuzu",
      "text": "Isuzu was founded in 1916 as the Tokyo Ishikawajima Shipbuilding and Engineering Co., Ltd. and Tokyo Gas and Electric Industrial Co.",
      "date": "1916"
    },
    {
      "headline": "First Vehicle Production",
      "text": "In 1922, Isuzu produced its first vehicle, the Wolseley A9, under a technical cooperation with Wolseley Motors Limited.",
      "date": "1922"
    },
    {
      "headline": "Isuzu Name Adoption",
      "text": "The company adopted the name 'Isuzu' in 1934, after the Isuzu River.",
      "date": "1934"
    },
    {
      "headline": "Isuzu Motors Limited Establishment",
      "text": "Isuzu Motors Limited was established in 1937, marking the company's official entry into the automotive industry.",
      "date": "1937"
    },
    {
      "headline": "Introduction of Diesel Engines",
      "text": "In 1936, Isuzu developed Japan's first air-cooled diesel engine, the DA6.",
      "date": "1936"
    },
    {
      "headline": "Post-War Expansion",
      "text": "After World War II, Isuzu expanded its production and began exporting vehicles, starting with the TX truck in 1949.",
      "date": "1949"
    },
    {
      "headline": "Partnership with General Motors",
      "text": "In 1971, Isuzu entered into a capital and technical partnership with General Motors, which helped expand its global reach.",
      "date": "1971"
    },
    {
      "headline": "Introduction of the Isuzu Gemini",
      "text": "In 1974, Isuzu introduced the Gemini, a compact car developed in collaboration with General Motors.",
      "date": "1974"
    },
    {
      "headline": "Isuzu Trooper Launch",
      "text": "The Isuzu Trooper, a popular SUV, was launched in 1981, marking Isuzu's entry into the SUV market.",
      "date": "1981"
    },
    {
      "headline": "End of Passenger Car Production",
      "text": "In 2002, Isuzu ceased production of passenger cars to focus on commercial vehicles and diesel engines.",
      "date": "2002"
    },
    {
      "headline": "Isuzu and GM Partnership Ends",
      "text": "The partnership between Isuzu and General Motors ended in 2006, with GM selling its remaining stake in Isuzu.",
      "date": "2006"
    },
    {
      "headline": "Isuzu Headquarters Relocation",
      "text": "In 2018, Isuzu relocated its headquarters to Yokohama, Kanagawa Prefecture.",
      "date": "2018"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Marie-Thérèse Charlotte",
      "text": "Marie-Thérèse Charlotte was born on December 19, 1778, at the Palace of Versailles in France. She was the eldest child of King Louis XVI and Queen Marie Antoinette.",
      "date": "1778-12-19"
    },
    {
      "headline": "Imprisonment during the French Revolution",
      "text": "In August 1792, during the French Revolution, Marie-Thérèse and her family were imprisoned in the Temple Tower in Paris.",
      "date": "1792-08"
    },
    {
      "headline": "Release from Imprisonment",
      "text": "Marie-Thérèse was released from imprisonment on December 18, 1795, as part of a prisoner exchange between revolutionary France and Austria.",
      "date": "1795-12-18"
    },
    {
      "headline": "Marriage to Louis Antoine, Duke of Angoulême",
      "text": "On June 10, 1799, Marie-Thérèse married her cousin Louis Antoine, Duke of Angoulême, in Mitau, Courland (now Jelgava, Latvia).",
      "date": "1799-06-10"
    },
    {
      "headline": "Return to France",
      "text": "Marie-Thérèse returned to France in April 1814 after the fall of Napoleon and the restoration of the Bourbon monarchy.",
      "date": "1814-04"
    },
    {
      "headline": "Brief Reign as Queen of France",
      "text": "Marie-Thérèse was briefly Queen of France for 20 minutes on August 2, 1830, when her husband, Louis Antoine, was technically King Louis XIX before abdicating in favor of his nephew.",
      "date": "1830-08-02"
    },
    {
      "headline": "Exile in Austria",
      "text": "Following the July Revolution of 1830, Marie-Thérèse went into exile in Austria, where she lived for the remainder of her life.",
      "date": "1830"
    },
    {
      "headline": "Death of Marie-Thérèse Charlotte",
      "text": "Marie-Thérèse Charlotte died on October 19, 1851, in Frohsdorf, Austria.",
      "date": "1851-10-19"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Design and Development",
      "text": "The America-class amphibious assault ships were designed to replace the Tarawa-class ships and are based on the design of USS Makin Island, the last ship of the Wasp class. The design emphasizes aviation capabilities, with no well decks and smaller hospitals to allow more space for aircraft operations.",
      "date": "2000s"
    },
    {
      "headline": "Construction of USS America (LHA-6)",
      "text": "Construction of the lead ship of the class, USS America (LHA-6), began. The ship was built by Huntington Ingalls Industries at their shipyard in Pascagoula, Mississippi.",
      "date": "2008"
    },
    {
      "headline": "Launch of USS America (LHA-6)",
      "text": "USS America (LHA-6) was launched on June 4, 2012, marking a significant milestone in the construction of the first ship of the America class.",
      "date": "2012-06-04"
    },
    {
      "headline": "Commissioning of USS America (LHA-6)",
      "text": "USS America (LHA-6) was commissioned into the United States Navy on October 11, 2014, in San Francisco, California. This marked the official entry of the first America-class ship into active service.",
      "date": "2014-10-11"
    },
    {
      "headline": "Construction of USS Tripoli (LHA-7)",
      "text": "Construction of the second ship of the class, USS Tripoli (LHA-7), began. Like its predecessor, it was built by Huntington Ingalls Industries.",
      "date": "2014"
    },
    {
      "headline": "Launch of USS Tripoli (LHA-7)",
      "text": "USS Tripoli (LHA-7) was launched on May 1, 2017, continuing the expansion of the America class.",
      "date": "2017-05-01"
    },
    {
      "headline": "Commissioning of USS Tripoli (LHA-7)",
      "text": "USS Tripoli (LHA-7) was commissioned into the United States Navy on July 15, 2020. The ship enhances the Navy's ability to project power and support Marine Corps operations.",
      "date": "2020-07-15"
    },
    {
      "headline": "Construction of USS Bougainville (LHA-8)",
      "text": "Construction of the third ship of the class, USS Bougainville (LHA-8), began. This ship is expected to include a well deck, unlike its predecessors.",
      "date": "2018"
    }
  ]
}

