{
  "timeline": [
    {
      "headline": "Opening of The Plaza Hotel",
      "text": "The Plaza Hotel officially opened on October 1, 1907. It was designed by Henry Janeway Hardenbergh and cost $12.5 million to build.",
      "date": "1907-10-01"
    },
    {
      "headline": "First Major Renovation",
      "text": "In 1929, The Plaza Hotel underwent its first major renovation, which included the addition of the famous Palm Court.",
      "date": "1929"
