    {
      "headline": "Conrad Hilton Purchase",
      "text": "In 1943, hotelier Conrad Hilton purchased The Plaza Hotel for $7.4 million.",
      "date": "1943"
    },
    {
      "headline": "Hilton Sells The Plaza",
      "text": "In 1955, Conrad Hilton sold The Plaza Hotel to Boston industrialist A.M. Sonnabend for $15 million.",
      "date": "1955"
    },
    {
      "headline": "Donald Trump Acquisition",
      "text": "Real estate developer Donald Trump purchased The Plaza Hotel for $407.5 million in 1988.",
      "date": "1988"
    },
    {
      "headline": "Trump Sells The Plaza",
      "text": "In 1995, Donald Trump sold The Plaza Hotel to a partnership between Prince Alwaleed bin Talal of Saudi Arabia and Millennium & Copthorne Hotels for $325 million.",
      "date": "1995"
    },
    {
      "headline": "Conversion to Condominiums",
      "text": "In 2005, The Plaza Hotel closed for extensive renovations and was partially converted into condominiums, reopening in 2008.",
      "date": "2005"
    },
    {
      "headline": "Reopening After Renovation",
      "text": "The Plaza Hotel reopened on March 1, 2008, after a $450 million renovation, featuring both hotel rooms and private residences.",
      "date": "2008-03-01"
    },
    {
      "headline": "Katara Hospitality Acquisition",
      "text": "In 2018, the Qatari firm Katara Hospitality acquired The Plaza Hotel for $600 million.",
      "date": "2018"
    }
  ]
}

{
