{
  "timeline": [
    {
      "headline": "Hitler's Euthanasia Note",
      "text": "In October 1939, Adolf Hitler signed a 'euthanasia note', backdated to 1 September 1939, authorizing his physician Karl Brandt and Reichsleiter Philipp Bouhler to begin the euthanasia program.",
      "date": "1939-09-01"
    },
    {
      "headline": "Establishment of Aktion T4 Headquarters",
      "text": "In early 1940, the Aktion T4 program established its headquarters at Tiergartenstraße 4 in Berlin, which became the administrative center for the euthanasia program.",
      "date": "1940"
    },
    {
      "headline": "Implementation of Aktion T4",
      "text": "Throughout 1940, Aktion T4 was implemented, involving the systematic killing of individuals deemed 'incurably sick' by selected German physicians.",
      "date": "1940"
