{
  "timeline": [
    {
      "headline": "Early Vegetarian Practices",
      "text": "The earliest known practice of vegetarianism can be traced back to ancient India and ancient Greece. In India, vegetarianism was promoted by religious groups such as Hinduism, Jainism, and Buddhism, which advocated non-violence towards animals.",
      "date": "-0500"
    },
    {
      "headline": "Pythagorean Diet",
      "text": "In ancient Greece, the philosopher Pythagoras promoted a diet that excluded meat, which later became known as the 'Pythagorean diet'. This was one of the earliest recorded instances of vegetarianism in Western culture.",
      "date": "-0500"
    },
    {
      "headline": "Vegetarianism in the Roman Empire",
      "text": "During the Roman Empire, some philosophers and religious groups, such as the followers of Neo-Platonism, practiced vegetarianism as part of their ethical beliefs.",
      "date": "0000"
    },
    {
      "headline": "Vegetarianism in the Middle Ages",
      "text": "Throughout the Middle Ages, vegetarianism was practiced by certain monastic orders in Europe, such as the Benedictines, who abstained from meat as part of their religious discipline.",
      "date": "1000"
    },
    {
      "headline": "The Vegetarian Society",
      "text": "The first Vegetarian Society was formed in England in 1847. It was the first organization dedicated to promoting vegetarianism and advocating for a meat-free diet.",
      "date": "1847"
    },
    {
      "headline": "Vegetarianism in the 20th Century",
      "text": "The 20th century saw a significant rise in the popularity of vegetarianism, particularly in Western countries, due to increased awareness of health, ethical, and environmental issues associated with meat consumption.",
      "date": "1900"
    },
    {
      "headline": "World Vegetarian Congress",
      "text": "The first World Vegetarian Congress was held in Chicago in 1953, bringing together vegetarians from around the world to discuss and promote vegetarianism.",
      "date": "1953"
    },
    {
      "headline": "Rise of Veganism",
      "text": "In the late 20th and early 21st centuries, veganism, a stricter form of vegetarianism that excludes all animal products, gained popularity alongside vegetarianism, driven by ethical, environmental, and health concerns.",
      "date": "2000"
    }
  ]
}

