{
  "timeline": [
    {
      "headline": "Purchase by Abraham",
      "text": "According to the Abrahamic religions, the Cave of the Patriarchs was purchased by Abraham as a burial plot for his wife Sarah. This event is traditionally dated to around 1800 BCE.",
      "date": "-1800"
    },
    {
      "headline": "Burial of the Patriarchs and Matriarchs",
      "text": "The cave is traditionally believed to be the burial site of the patriarchs Abraham, Isaac, and Jacob, and the matriarchs Sarah, Rebekah, and Leah. These burials are significant events in the religious traditions of Judaism, Christianity, and Islam.",
      "date": "-1800"
    },
    {
      "headline": "Herodian Structure",
      "text": "Around 20 BCE, King Herod the Great built a large, rectangular enclosure over the caves, which still stands today. This structure is one of the oldest continuously used prayer structures in the world.",
      "date": "-0020"
    },
    {
      "headline": "Byzantine Church",
      "text": "During the Byzantine period, a church was built on the site, reflecting its significance in Christianity.",
      "date": "0330"
    },
    {
      "headline": "Conversion to Mosque",
      "text": "Following the Muslim conquest of the Levant in the 7th century, the site was converted into a mosque, known as the Sanctuary of Abraham.",
      "date": "0637"
    },
    {
      "headline": "Crusader Control",
      "text": "In 1100, during the Crusades, the site was taken by the Crusaders and converted back into a church.",
      "date": "1100"
    },
    {
      "headline": "Ayyubid Restoration",
      "text": "In 1188, Saladin restored the site to a mosque after recapturing it from the Crusaders.",
      "date": "1188"
    },
    {
      "headline": "Ottoman Period",
      "text": "During the Ottoman period, the site continued to function as a mosque, with limited access for Jews and Christians.",
      "date": "1517"
    },
    {
      "headline": "1967 Six-Day War",
      "text": "After the Six-Day War in 1967, the site came under Israeli control, and arrangements were made to allow both Jews and Muslims to pray there.",
      "date": "1967"
    },
    {
      "headline": "Hebron Agreement",
      "text": "In 1997, the Hebron Agreement divided the city of Hebron into areas of Palestinian and Israeli control, affecting the administration of the Cave of the Patriarchs.",
      "date": "1997"
    }
  ]
}

