{
  "timeline": [
    {
      "headline": "Emergence of Vaporwave",
      "text": "Vaporwave emerged in the early 2010s as a microgenre of electronic music and a subgenre of hauntology. It is characterized by its use of slowed-down, chopped and screwed samples of smooth jazz, 1970s elevator music, R&B, and lounge music from the 1980s and 1990s.",
      "date": "2010"
    },
    {
      "headline": "Release of 'Floral Shoppe'",
      "text": "In December 2011, the album 'Floral Shoppe' by Macintosh Plus was released. It became one of the most iconic albums in the vaporwave genre, known for its track 'リサフランク420 / 現代のコンピュー'.",
      "date": "2011-12"
    },
    {
      "headline": "Vaporwave Gains Popularity",
      "text": "By 2012, vaporwave began to gain popularity on platforms like Bandcamp and SoundCloud, with artists like Vektroid, Saint Pepsi, and Blank Banshee contributing to its growth.",
      "date": "2012"
    },
    {
      "headline": "Vaporwave as an Internet Meme",
      "text": "Around 2015, vaporwave became well-known as an Internet meme, characterized by its nostalgic or surrealist engagement with popular entertainment, technology, and advertising from previous decades.",
      "date": "2015"
    },
    {
      "headline": "Vaporwave's Influence on Visual Art",
      "text": "Vaporwave's influence extended to visual art, incorporating early Internet imagery, late 1990s web design, glitch art, anime, stylized Ancient Greek or Roman sculptures, 3D-rendered objects, and cyberpunk tropes.",
      "date": "2015"
    }
  ]
}

