{
  "timeline": [
    {
      "headline": "Ever Given Runs Aground",
      "text": "On March 23, 2021, the Ever Given, a large container ship, ran aground in the Suez Canal, blocking the canal and halting traffic in both directions.",
      "date": "2021-03-23"
    },
    {
      "headline": "Efforts to Refloat the Ever Given",
      "text": "From March 23 to March 28, 2021, efforts were underway to refloat the Ever Given. These efforts included dredging sand and mud from around the ship and using tugboats to try to move it.",
      "date": "2021-03-23"
    },
    {
      "headline": "Ever Given is Partially Refloated",
      "text": "On March 29, 2021, the Ever Given was partially refloated, allowing for some movement of the ship.",
      "date": "2021-03-29"
    },
    {
      "headline": "Suez Canal Reopens",
      "text": "On March 29, 2021, the Ever Given was fully refloated and moved, allowing the Suez Canal to reopen for traffic.",
      "date": "2021-03-29"
    },
    {
      "headline": "Backlog of Ships Cleared",
      "text": "By April 3, 2021, the backlog of ships waiting to pass through the Suez Canal was cleared, restoring normal operations.",
      "date": "2021-04-03"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Murder of Ahmaud Arbery",
      "text": "On February 23, 2020, Ahmaud Arbery, a 25-year-old black man, was murdered during a racially motivated hate crime while jogging in Satilla Shores, a neighborhood near Brunswick in Glynn County, Georgia. Three white men, Travis McMichael, Gregory McMichael, and William 'Roddie' Bryan, pursued Arbery in their trucks. Travis McMichael fatally shot Arbery after a confrontation.",
      "date": "2020-02-23"
    },
    {
      "headline": "Video of the Murder Released",
      "text": "On May 5, 2020, a video recording of the murder, taken by William 'Roddie' Bryan, was publicly released, leading to widespread outrage and calls for justice.",
      "date": "2020-05-05"
    },
    {
      "headline": "Arrests of the McMichaels",
      "text": "On May 7, 2020, Travis McMichael and Gregory McMichael were arrested and charged with murder and aggravated assault.",
      "date": "2020-05-07"
    },
    {
      "headline": "Arrest of William 'Roddie' Bryan",
      "text": "On May 21, 2020, William 'Roddie' Bryan was arrested and charged with felony murder and criminal attempt to commit false imprisonment.",
      "date": "2020-05-21"
    },
    {
      "headline": "Federal Hate Crime Charges",
      "text": "On April 28, 2021, the three men were indicted on federal hate crime charges, including interference with rights and attempted kidnapping.",
      "date": "2021-04-28"
    },
    {
      "headline": "State Murder Trial Verdict",
      "text": "On November 24, 2021, Travis McMichael, Gregory McMichael, and William 'Roddie' Bryan were found guilty of murder and other charges in a state trial.",
      "date": "2021-11-24"
    },
    {
      "headline": "Sentencing in State Trial",
      "text": "On January 7, 2022, Travis McMichael, Gregory McMichael, and William 'Roddie' Bryan were sentenced to life in prison, with the McMichaels receiving life without the possibility of parole.",
      "date": "2022-01-07"
    },
    {
      "headline": "Federal Trial Verdict",
      "text": "On February 22, 2022, the three men were found guilty of federal hate crimes and other charges in a federal trial.",
      "date": "2022-02-22"
    },
    {
      "headline": "Sentencing in Federal Trial",
      "text": "On August 8, 2022, Travis McMichael, Gregory McMichael, and William 'Roddie' Bryan were sentenced to life in prison for federal hate crimes.",
      "date": "2022-08-08"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Maria Montessori",
      "text": "Maria Tecla Artemisia Montessori was born on August 31, 1870, in Chiaravalle, Italy.",
      "date": "1870-08-31"
    },
    {
      "headline": "Enrollment in Technical School",
      "text": "In 1883, Maria Montessori enrolled in an all-boys technical school with the initial aim of becoming an engineer.",
      "date": "1883"
    },
    {
      "headline": "Change of Career Path",
      "text": "Maria Montessori decided to pursue a career in medicine and began attending medical school at the Sapienza University of Rome in 1890.",
      "date": "1890"
    },
    {
      "headline": "Graduation from Medical School",
      "text": "In 1896, Maria Montessori graduated with honors from the Sapienza University of Rome, becoming one of the first women in Italy to earn a medical degree.",
      "date": "1896"
    },
    {
      "headline": "First International Women's Congress",
      "text": "In 1896, Maria Montessori represented Italy at the First International Women's Congress in Berlin, where she advocated for women's rights.",
      "date": "1896"
    },
    {
      "headline": "Work with Mentally Disabled Children",
      "text": "In 1897, Montessori began working with mentally disabled children, which led to her interest in education and pedagogy.",
      "date": "1897"
    },
    {
      "headline": "Director of Orthophrenic School",
      "text": "In 1900, Maria Montessori became the director of the Orthophrenic School, a school for training teachers of mentally disabled children.",
      "date": "1900"
    },
    {
      "headline": "Opening of the First Casa dei Bambini",
      "text": "On January 6, 1907, Maria Montessori opened the first Casa dei Bambini (Children's House) in Rome, applying her educational methods to children without disabilities.",
      "date": "1907-01-06"
    },
    {
      "headline": "Publication of 'The Montessori Method'",
      "text": "In 1909, Maria Montessori published 'Il Metodo della Pedagogia Scientifica applicato all'educazione infantile nelle Case dei Bambini' (The Montessori Method), which outlined her educational philosophy.",
      "date": "1909"
    },
    {
      "headline": "International Recognition",
      "text": "By 1913, Maria Montessori's educational methods gained international recognition, leading to the establishment of Montessori schools worldwide.",
      "date": "1913"
    },
    {
      "headline": "Exile from Italy",
      "text": "In 1934, due to her opposition to Mussolini's fascist regime, Maria Montessori left Italy and continued her work in Spain and later in the Netherlands.",
      "date": "1934"
    },
    {
      "headline": "Nomination for Nobel Peace Prize",
      "text": "Maria Montessori was nominated for the Nobel Peace Prize in 1949, 1950, and 1951 for her contributions to education and peace.",
      "date": "1949"
    },
    {
      "headline": "Death of Maria Montessori",
      "text": "Maria Montessori passed away on May 6, 1952, in Noordwijk, Netherlands.",
      "date": "1952-05-06"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Abiy Ahmed",
      "text": "Abiy Ahmed was born on August 15, 1976, in Beshasha, Ethiopia.",
      "date": "1976-08-15"
    },
    {
      "headline": "Joined the Ethiopian People's Revolutionary Democratic Front (EPRDF)",
      "text": "Abiy Ahmed joined the Ethiopian People's Revolutionary Democratic Front (EPRDF) and became an active member of the Oromo Democratic Party (ODP), one of the coalition parties of the EPRDF.",
      "date": "1991"
