    {
      "headline": "Formed the Prosperity Party",
      "text": "In December 2019, Abiy Ahmed dissolved the Ethiopian People's Revolutionary Democratic Front (EPRDF) and formed the Prosperity Party.",
      "date": "2019-12"
    },
    {
      "headline": "Awarded the Nobel Peace Prize",
      "text": "Abiy Ahmed was awarded the Nobel Peace Prize on October 11, 2019, for his efforts to achieve peace and international cooperation, particularly for resolving the border conflict with Eritrea.",
      "date": "2019-10-11"
    }
