{
  "timeline": [
    {
      "headline": "Conceptualization of the Seed Vault",
      "text": "The idea for the Svalbard Global Seed Vault was conceived in the early 1980s as a way to safeguard the world's crop diversity.",
      "date": "1980"
    },
    {
      "headline": "Construction Begins",
      "text": "Construction of the Svalbard Global Seed Vault began in 2006 on the Norwegian island of Spitsbergen.",
      "date": "2006"
    },
    {
      "headline": "Inauguration of the Seed Vault",
      "text": "The Svalbard Global Seed Vault was officially opened on February 26, 2008, providing a secure backup for the world's crop diversity.",
      "date": "2008-02-26"
    },
    {
      "headline": "First Withdrawal from the Vault",
      "text": "In September 2015, the first withdrawal of seeds was made from the Svalbard Global Seed Vault to replace seeds in a gene bank in Syria that were damaged due to the ongoing conflict.",
      "date": "2015-09"
    },
    {
      "headline": "Renovation and Upgrades",
      "text": "In 2017, the Norwegian government announced plans to upgrade the Seed Vault's facilities to improve its resilience against climate change impacts, following water intrusion into the entrance tunnel.",
      "date": "2017"
    },
    {
      "headline": "Completion of Upgrades",
      "text": "In 2019, the Norwegian government completed significant upgrades to the Svalbard Global Seed Vault, including a new access tunnel and service building.",
      "date": "2019"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Formation of the Tornado",
      "text": "On May 3, 1999, a powerful tornado formed in Grady County, Oklahoma. It was part of a larger outbreak of severe weather that affected the region.",
      "date": "1999-05-03"
    },
    {
      "headline": "Tornado Strikes Bridge Creek",
      "text": "The tornado first struck the town of Bridge Creek, Oklahoma, causing catastrophic damage. Parts of Bridge Creek were rendered unrecognizable.",
      "date": "1999-05-03"
    },
    {
      "headline": "Record Wind Speed Measured",
      "text": "While near Bridge Creek, the tornado reached a peak wind speed of 321 miles per hour (517 km/h), the highest wind speed ever recorded globally by a Doppler on Wheels radar.",
      "date": "1999-05-03"
    },
    {
      "headline": "Tornado Devastates Moore, Oklahoma",
      "text": "The tornado continued its path of destruction through the city of Moore, Oklahoma, causing extensive damage to homes and infrastructure.",
      "date": "1999-05-03"
    },
    {
      "headline": "Tornado Emergency Issued",
      "text": "The severity of the tornado prompted the National Weather Service to issue the first-ever tornado emergency statement, highlighting the extreme danger to life and property.",
      "date": "1999-05-03"
    },
    {
      "headline": "Tornado Dissipates",
      "text": "After traveling 38 miles (61 km) and lasting 85 minutes, the tornado finally dissipated. It left behind a trail of destruction, killing 36 people and causing US$1 billion in damage.",
      "date": "1999-05-03"
    }
  ]
}

