{
  "timeline": [
    {
      "headline": "Beginning of the Cenozoic Era",
      "text": "The Cenozoic Era began approximately 66 million years ago following the Cretaceous–Paleogene extinction event, which led to the extinction of many species, including non-avian dinosaurs.",
      "date": "-66000000"
    },
    {
      "headline": "Paleocene Epoch",
      "text": "The Paleocene Epoch, the first epoch of the Cenozoic Era, spanned from about 66 to 56 million years ago. It was characterized by the recovery of Earth's ecosystems following the mass extinction event.",
      "date": "-66000000"
    },
    {
      "headline": "Eocene Epoch",
      "text": "The Eocene Epoch lasted from about 56 to 34 million years ago. This period saw the emergence of early forms of many modern mammals and birds.",
      "date": "-56000000"
    },
    {
      "headline": "Oligocene Epoch",
      "text": "The Oligocene Epoch occurred from about 34 to 23 million years ago. It was marked by the development of grasslands and the further evolution of mammals.",
      "date": "-34000000"
    },
    {
      "headline": "Miocene Epoch",
      "text": "The Miocene Epoch, from about 23 to 5.3 million years ago, saw the expansion of grasslands and the diversification of grazing mammals.",
      "date": "-23000000"
    },
    {
      "headline": "Pliocene Epoch",
      "text": "The Pliocene Epoch lasted from about 5.3 to 2.6 million years ago. It was a time of significant climatic changes and the spread of hominins.",
      "date": "-5300000"
    },
    {
      "headline": "Pleistocene Epoch",
      "text": "The Pleistocene Epoch, from about 2.6 million to 11,700 years ago, was characterized by repeated glacial cycles and the evolution of Homo sapiens.",
      "date": "-2600000"
    },
    {
      "headline": "Holocene Epoch",
      "text": "The Holocene Epoch began approximately 11,700 years ago and continues to the present day. It is marked by the development of human civilizations and significant environmental changes.",
      "date": "-11700"
    }
  ]
}

