{
  "timeline": [
    {
      "headline": "End of Roman Britain",
      "text": "Roman rule in Britain ended in the early 5th century, around 410, as Roman legions withdrew to defend the empire's heartlands.",
      "date": "0410"
    },
    {
      "headline": "Anglo-Saxon Settlement",
      "text": "The Anglo-Saxon settlement of Britain began in the 5th century, with various tribes such as the Angles, Saxons, and Jutes migrating from continental Europe.",
      "date": "0500"
    },
    {
      "headline": "Battle of Mount Badon",
      "text": "Around 500, the Battle of Mount Badon was fought between the Britons and Anglo-Saxons, resulting in a significant victory for the Britons.",
      "date": "0500"
    },
    {
      "headline": "Formation of Anglo-Saxon Kingdoms",
      "text": "By the 7th century, several Anglo-Saxon kingdoms had formed, including Northumbria, Mercia, East Anglia, Essex, Kent, Sussex, and Wessex.",
      "date": "0600"
    },
    {
      "headline": "Christianization of Anglo-Saxon England",
      "text": "The Christianization of Anglo-Saxon England began in 597 with the arrival of Augustine of Canterbury, who converted King Æthelberht of Kent.",
      "date": "0597"
    },
    {
      "headline": "Synod of Whitby",
      "text": "In 664, the Synod of Whitby was held to decide whether the Northumbrian church would follow Roman or Celtic practices, resulting in the adoption of Roman practices.",
      "date": "0664"
    },
    {
      "headline": "Viking Invasions Begin",
      "text": "Viking raids on Anglo-Saxon England began in the late 8th century, with the first recorded raid occurring in 793 at Lindisfarne.",
      "date": "0793"
    },
    {
      "headline": "Alfred the Great's Reign",
      "text": "Alfred the Great became King of Wessex in 871 and successfully defended his kingdom against Viking invasions, eventually establishing a peace treaty known as the Danelaw.",
      "date": "0871"
    },
    {
      "headline": "Battle of Edington",
      "text": "In 878, Alfred the Great defeated the Viking army at the Battle of Edington, leading to the Treaty of Wedmore and the establishment of the Danelaw.",
      "date": "0878"
    },
    {
      "headline": "Unification of England",
      "text": "In 927, King Æthelstan unified the various Anglo-Saxon kingdoms into a single Kingdom of England.",
      "date": "0927"
    },
    {
      "headline": "Cnut the Great's Rule",
      "text": "Cnut the Great became King of England in 1016, forming the North Sea Empire, a personal union between England, Denmark, and Norway.",
      "date": "1016"
    },
    {
      "headline": "Norman Conquest",
      "text": "The Norman Conquest of England occurred in 1066, marking the end of Anglo-Saxon rule with the victory of William the Conqueror at the Battle of Hastings.",
      "date": "1066"
    }
  ]
}

