{
  "timeline": [
    {
      "headline": "Construction of the Great Mosque of Córdoba Begins",
      "text": "Construction of the Great Mosque of Córdoba began in 785 under the orders of Abd al-Rahman I, the first Emir of Córdoba, on the site of a former Visigothic church.",
      "date": "0785"
    },
    {
      "headline": "Completion of the Initial Mosque",
      "text": "The initial construction of the mosque was completed in 788, featuring a hypostyle hall with 11 aisles and a courtyard.",
      "date": "0788"
    },
    {
      "headline": "Expansion under Abd al-Rahman II",
      "text": "In 833, Abd al-Rahman II ordered the first major expansion of the mosque, extending the prayer hall and adding a new minaret.",
      "date": "0833"
    },
    {
      "headline": "Further Expansion by Al-Hakam II",
      "text": "Al-Hakam II expanded the mosque further in 961, adding a new mihrab and extending the prayer hall, enhancing the mosque's architectural grandeur.",
      "date": "0961"
    },
    {
      "headline": "Final Expansion by Almanzor",
      "text": "The last major expansion was carried out by Almanzor in 987, who extended the mosque to the east, making it one of the largest mosques in the world at the time.",
      "date": "0987"
    },
    {
      "headline": "Conversion to a Christian Cathedral",
      "text": "In 1236, following the Reconquista, the mosque was converted into a Christian cathedral by King Ferdinand III of Castile.",
      "date": "1236"
    },
    {
      "headline": "Construction of the Renaissance Cathedral Nave",
      "text": "In 1523, construction began on a Renaissance-style nave and transept within the mosque, which was completed in the 17th century.",
      "date": "1523"
    },
    {
      "headline": "Designation as a UNESCO World Heritage Site",
      "text": "In 1984, the Mosque–Cathedral of Córdoba was designated as a UNESCO World Heritage Site, recognizing its historical and architectural significance.",
      "date": "1984"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Indus Valley Civilization",
      "text": "The Sindh region was part of the Indus Valley Civilization, one of the world's earliest urban civilizations, which flourished around 3300 BCE to 1300 BCE.",
      "date": "-3300"
    },
    {
      "headline": "Achaemenid Empire Conquest",
      "text": "Sindh was conquered by the Achaemenid Empire under Darius I around 519 BCE, becoming part of the empire's easternmost territories.",
      "date": "-0519"
    },
    {
      "headline": "Alexander the Great's Invasion",
      "text": "In 326 BCE, Alexander the Great invaded the Sindh region, marking the beginning of Greek influence in the area.",
      "date": "-0326"
    },
    {
      "headline": "Maurya Empire Rule",
      "text": "After Alexander's death, Sindh became part of the Maurya Empire under Chandragupta Maurya around 305 BCE.",
      "date": "-0305"
    },
    {
      "headline": "Arrival of Islam",
      "text": "In 711 CE, Muhammad bin Qasim conquered Sindh, introducing Islam to the region and establishing Muslim rule.",
      "date": "0711"
    },
    {
      "headline": "British Colonial Rule",
      "text": "Sindh was annexed by the British Empire in 1843 after the Battle of Miani, becoming part of British India.",
      "date": "1843"
    },
    {
      "headline": "Partition of India",
      "text": "In 1947, the partition of India led to Sindh becoming part of the newly formed Pakistan, resulting in significant demographic changes as Hindu Sindhis migrated to India.",
      "date": "1947"
    },
    {
      "headline": "Formation of Sindh Province",
      "text": "Sindh became one of the provinces of Pakistan in 1955, following the dissolution of the One Unit policy.",
      "date": "1955"
    }
  ]
}

{
