{
  "timeline": [
    {
      "headline": "Start of the Mali War",
      "text": "On 16 January 2012, several insurgent groups began fighting a campaign against the Malian government for independence or greater autonomy for northern Mali, which they called Azawad.",
      "date": "2012-01-16"
    },
    {
      "headline": "MNLA Takes Control of Northern Mali",
      "text": "By April 2012, the National Movement for the Liberation of Azawad (MNLA), an organization fighting to make northern Mali an independent homeland for the Tuareg people, had taken control of the region.",
      "date": "2012-04"
    },
    {
      "headline": "Declaration of Independence",
      "text": "On 6 April 2012, the MNLA declared the independence of Azawad from Mali.",
      "date": "2012-04-06"
    },
    {
      "headline": "Islamist Groups Gain Influence",
      "text": "Throughout 2012, Islamist groups such as Ansar Dine and Al-Qaeda in the Islamic Maghreb gained influence in northern Mali, imposing strict Sharia law.",
      "date": "2012"
    },
    {
      "headline": "French Military Intervention",
      "text": "On 11 January 2013, France launched Operation Serval, a military intervention to help the Malian government regain control of the north.",
      "date": "2013-01-11"
    },
    {
      "headline": "Recapture of Northern Cities",
      "text": "By February 2013, French and Malian forces had recaptured key northern cities, including Timbuktu and Gao, from Islamist militants.",
      "date": "2013-02"
    },
    {
      "headline": "Peace Agreement Signed",
      "text": "On 15 May 2015, a peace agreement was signed between the Malian government and various rebel groups, although some factions refused to sign.",
      "date": "2015-05-15"
    },
    {
      "headline": "Continued Violence and Instability",
      "text": "Despite the peace agreement, violence and instability continued in Mali, with frequent attacks by jihadist groups and intercommunal violence.",
      "date": "2015"
    },
    {
      "headline": "Establishment of G5 Sahel Joint Force",
      "text": "In 2017, the G5 Sahel Joint Force was established to combat terrorism and organized crime in the region, including Mali.",
      "date": "2017"
    },
    {
      "headline": "French Troop Withdrawal Announced",
      "text": "In June 2021, French President Emmanuel Macron announced a significant reduction of French troops in the Sahel, transitioning to a more international effort.",
      "date": "2021-06"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Construction of Amber Fort Begins",
      "text": "The construction of Amber Fort began under the reign of Raja Man Singh I, a trusted general of the Mughal Emperor Akbar. The fort was built on the remnants of an earlier structure in the late 16th century.",
      "date": "1592"
    },
    {
      "headline": "Completion of Amber Fort",
      "text": "The fort was completed in its initial form by Raja Jai Singh I, the successor of Raja Man Singh I, in the early 17th century. The fort was expanded and modified over time by subsequent rulers.",
      "date": "1600"
    },
    {
      "headline": "Expansion and Renovation by Raja Jai Singh I",
      "text": "Raja Jai Singh I expanded and renovated the fort, adding several structures and enhancing its artistic elements. This period marked significant architectural developments in the fort.",
      "date": "1621"
    },
    {
      "headline": "Amer Fort Becomes the Capital",
      "text": "Amer Fort served as the capital of the Kachwaha Rajputs until the capital was moved to Jaipur in 1727 by Maharaja Sawai Jai Singh II.",
      "date": "1727"
    },
    {
      "headline": "Amer Fort Declared UNESCO World Heritage Site",
      "text": "In 2013, Amer Fort, along with five other forts of Rajasthan, was declared a UNESCO World Heritage Site as part of the group 'Hill Forts of Rajasthan'.",
      "date": "2013"
    }
  ]
}

{
  "timeline": [
