{
  "timeline": [
    {
      "headline": "Early Nubian Settlements",
      "text": "Nubians are believed to have originated from the early inhabitants of the central Nile valley, one of the earliest cradles of civilization. This region was inhabited by Nubian cultures as early as 3500 BCE.",
      "date": "-3500"
    },
    {
      "headline": "Formation of the Kingdom of Kerma",
      "text": "The Kingdom of Kerma, one of the earliest Nubian states, emerged around 2500 BCE. It became a major center of power and culture in Nubia.",
      "date": "-2500"
    },
    {
      "headline": "Conquest by Egypt",
      "text": "Around 1500 BCE, the Egyptian Pharaoh Thutmose I conquered Nubia, incorporating it into the Egyptian Empire. This led to significant cultural and political influence from Egypt.",
      "date": "-1500"
    },
    {
      "headline": "Rise of the Kingdom of Kush",
      "text": "After the decline of Egyptian control, the Kingdom of Kush emerged around 1070 BCE, with its capital at Napata. It became a powerful Nubian state.",
      "date": "-1070"
    },
    {
      "headline": "Kushite Dynasty in Egypt",
      "text": "In 747 BCE, the Kushite king Piye conquered Egypt, establishing the 25th Dynasty, known as the Kushite Dynasty, which ruled Egypt for nearly a century.",
      "date": "-0747"
    },
    {
      "headline": "Capital Moved to Meroë",
      "text": "Around 590 BCE, the capital of the Kingdom of Kush was moved from Napata to Meroë, marking the beginning of the Meroitic period.",
      "date": "-0590"
    },
    {
      "headline": "Decline of the Kingdom of Kush",
      "text": "By the 4th century CE, the Kingdom of Kush began to decline due to internal strife and external pressures, including invasions by the Aksumite Empire.",
      "date": "0400"
    },
    {
      "headline": "Islamic Influence and Arabization",
      "text": "From the 7th century onwards, Nubia experienced significant Islamic influence and Arabization, leading to cultural and linguistic changes.",
      "date": "0700"
    },
    {
      "headline": "Modern Nubian Identity",
      "text": "In contemporary times, Nubians are recognized as an ethnic group indigenous to northern Sudan and southern Egypt, maintaining their distinct cultural and linguistic heritage.",
      "date": "2000"
    }
  ]
}

