    {
      "headline": "Spanish Discovery",
      "text": "Key West was discovered by Spanish explorers in 1513. It was originally named 'Cayo Hueso', which means 'Bone Island'.",
      "date": "1513"
    },
    {
      "headline": "Transfer to British Control",
      "text": "In 1763, following the Treaty of Paris, Spain ceded Florida, including Key West, to Great Britain.",
      "date": "1763"
    },
    {
      "headline": "Return to Spanish Control",
      "text": "In 1783, after the American Revolutionary War, Florida was returned to Spain as part of the Treaty of Paris.",
      "date": "1783"
    },
    {
      "headline": "U.S. Acquisition",
      "text": "In 1821, the United States acquired Florida from Spain, including Key West.",
      "date": "1821"
    },
    {
      "headline": "Establishment of Key West",
      "text": "In 1822, Key West was officially claimed by the United States Navy officer Matthew C. Perry.",
      "date": "1822"
    },
    {
      "headline": "Incorporation as a City",
      "text": "Key West was incorporated as a city in 1828.",
      "date": "1828"
    },
    {
      "headline": "Civil War Era",
      "text": "During the American Civil War (1861-1865), Key West remained under Union control despite Florida's secession.",
      "date": "1861"
    },
    {
      "headline": "Completion of the Overseas Railroad",
      "text": "In 1912, the Overseas Railroad, connecting Key West to the mainland, was completed by Henry Flagler.",
      "date": "1912"
    },
    {
      "headline": "Hurricane of 1935",
      "text": "In 1935, a devastating hurricane destroyed much of the Overseas Railroad, leading to its conversion into the Overseas Highway.",
      "date": "1935"
    },
    {
      "headline": "Establishment of Naval Air Station",
      "text": "In 1940, the Naval Air Station Key West was established, significantly impacting the local economy.",
      "date": "1940"
    },
    {
      "headline": "Cuban Missile Crisis",
      "text": "In 1962, during the Cuban Missile Crisis, Key West was on high alert due to its proximity to Cuba.",
      "date": "1962"
    },
    {
      "headline": "Conch Republic Declaration",
      "text": "In 1982, Key West declared itself the 'Conch Republic' as a protest against a U.S. Border Patrol blockade.",
      "date": "1982"
    }
  ]
}

