    {
      "headline": "First Handprints and Footprints Ceremony",
      "text": "The tradition of celebrities leaving their handprints and footprints in the forecourt of the theatre began in 1927 with Norma Talmadge.",
      "date": "1927"
    },
    {
      "headline": "Acquisition by Mann Theatres",
      "text": "In 1973, Grauman's Chinese Theatre was purchased by Ted Mann, owner of Mann Theatres, and was renamed Mann's Chinese Theatre.",
      "date": "1973"
    },
    {
      "headline": "Renovation and Restoration",
      "text": "The theatre underwent a major renovation and restoration in 2001 to preserve its historic features while updating its facilities.",
      "date": "2001"
    },
    {
      "headline": "Renaming to TCL Chinese Theatre",
      "text": "In January 2013, the theatre was renamed TCL Chinese Theatre after the Chinese electronics manufacturer TCL Corporation purchased the naming rights.",
      "date": "2013-01"
