{
  "timeline": [
    {
      "headline": "Birth of Pyrrhus",
      "text": "Pyrrhus was born in 319/318 BCE, into the royal Aeacid house of Epirus.",
      "date": "-0318"
    },
    {
      "headline": "Ascension to the Throne of Epirus",
      "text": "In 306 BCE, Pyrrhus became the king of Epirus after the death of his father, Aeacides.",
      "date": "-0306"
    },
    {
      "headline": "Exile and Restoration",
      "text": "In 302 BCE, Pyrrhus was dethroned and went into exile. He was restored to the throne in 297 BCE with the help of Ptolemy I of Egypt.",
      "date": "-0297"
    },
    {
      "headline": "Marriage to Antigone",
      "text": "In 295 BCE, Pyrrhus married Antigone, the stepdaughter of Ptolemy I, which strengthened his political alliances.",
      "date": "-0295"
    },
    {
      "headline": "War with Demetrius I of Macedon",
      "text": "In 288 BCE, Pyrrhus invaded Macedonia and briefly became king of Macedon alongside Lysimachus.",
      "date": "-0288"
    },
    {
      "headline": "Campaign in Italy",
      "text": "In 280 BCE, Pyrrhus landed in Italy to aid the city of Tarentum against Rome, marking the beginning of the Pyrrhic War.",
      "date": "-0280"
    },
    {
      "headline": "Battle of Heraclea",
      "text": "In 280 BCE, Pyrrhus won the Battle of Heraclea against the Romans, but with heavy losses.",
      "date": "-0280"
    },
    {
      "headline": "Battle of Asculum",
      "text": "In 279 BCE, Pyrrhus achieved another costly victory against the Romans at the Battle of Asculum.",
      "date": "-0279"
    },
    {
      "headline": "Campaign in Sicily",
      "text": "In 278 BCE, Pyrrhus was invited to Sicily to help the Greek cities against Carthage, where he achieved several victories.",
      "date": "-0278"
    },
    {
      "headline": "Return to Italy",
      "text": "In 275 BCE, Pyrrhus returned to Italy and faced the Romans again at the Battle of Beneventum, which ended inconclusively.",
      "date": "-0275"
    },
    {
      "headline": "Return to Epirus",
      "text": "After his campaigns in Italy and Sicily, Pyrrhus returned to Epirus in 275 BCE.",
      "date": "-0275"
    },
    {
      "headline": "Invasion of Macedonia",
      "text": "In 274 BCE, Pyrrhus invaded Macedonia and briefly regained the throne.",
      "date": "-0274"
    },
    {
      "headline": "Death of Pyrrhus",
      "text": "Pyrrhus died in 272 BCE during a street fight in Argos, Greece.",
      "date": "-0272"
    }
  ]
}

