    },
    {
      "headline": "Ordination as Deacon",
      "text": "Bede was ordained as a deacon at the age of 19, which was earlier than the canonical age of 25, due to his exceptional abilities. This occurred around 691.",
      "date": "0691"
    },
    {
      "headline": "Ordination as Priest",
      "text": "Bede was ordained as a priest at the age of 30, around the year 703.",
      "date": "0703"
    },
    {
      "headline": "Completion of 'Ecclesiastical History of the English People'",
      "text": "In 731, Bede completed his most famous work, 'Historia ecclesiastica gentis Anglorum' (Ecclesiastical History of the English People), which is a key source for understanding early English history.",
      "date": "0731"
    },
    {
      "headline": "Death of Bede",
      "text": "Bede died on May 26, 735, at the monastery of Jarrow, where he had spent most of his life.",
      "date": "0735-05-26"
    }
  ]
}

