{
  "timeline": [
    {
      "headline": "Founding of PETA",
      "text": "People for the Ethical Treatment of Animals (PETA) was founded in March 1980 by Ingrid Newkirk and Alex Pacheco in Norfolk, Virginia.",
      "date": "1980-03"
    },
    {
      "headline": "Silver Spring Monkeys Case",
      "text": "In 1981, PETA gained national attention with the Silver Spring monkeys case, which involved allegations of animal cruelty in a research laboratory. This case marked the first police raid on an animal research laboratory in the United States.",
      "date": "1981"
    },
    {
      "headline": "First Undercover Investigation",
      "text": "In 1984, PETA conducted its first undercover investigation at a laboratory, which led to the closure of the facility and the first-ever conviction of an animal experimenter on charges of cruelty to animals.",
      "date": "1984"
    },
    {
      "headline": "Unveiling of the 'I'd Rather Go Naked Than Wear Fur' Campaign",
      "text": "In 1991, PETA launched its iconic 'I'd Rather Go Naked Than Wear Fur' campaign, which featured celebrities posing nude to protest the use of animal fur in fashion.",
      "date": "1991"
    },
    {
      "headline": "Victory in the General Motors Crash Tests",
      "text": "In 1994, PETA successfully campaigned against General Motors, leading the company to stop using live animals in crash tests.",
      "date": "1994"
    },
    {
      "headline": "McDonald's Campaign",
      "text": "In 1997, PETA launched a campaign against McDonald's to improve the welfare of animals in its supply chain. This led to significant changes in the company's animal welfare policies.",
      "date": "1997"
    },
    {
      "headline": "KFC Campaign",
      "text": "In 2003, PETA began a campaign against KFC, urging the company to adopt better animal welfare standards. This campaign included protests and negotiations with the company.",
      "date": "2003"
    },
    {
      "headline": "SeaWorld Campaign",
      "text": "In 2013, following the release of the documentary 'Blackfish,' PETA intensified its campaign against SeaWorld, calling for the release of captive orcas.",
      "date": "2013"
    }
  ]
}

