{
  "timeline": [
    {
      "headline": "LTE Project Initiation",
      "text": "The LTE project was initiated by NTT DoCoMo of Japan in 2004, with the aim to develop a new standard for wireless communication that would improve upon the existing 3G technology.",
      "date": "2004"
    },
    {
      "headline": "3GPP Release 8",
      "text": "In December 2008, the 3rd Generation Partnership Project (3GPP) completed the Release 8 standard, which included the specifications for LTE. This release marked the official standardization of LTE technology.",
      "date": "2008-12"
    },
    {
      "headline": "First LTE Network Launch",
      "text": "The world's first publicly available LTE service was launched by TeliaSonera in Stockholm and Oslo on December 14, 2009. This marked the beginning of commercial LTE deployment.",
      "date": "2009-12-14"
    },
    {
      "headline": "LTE Advanced Standardization",
      "text": "In March 2011, the 3GPP Release 10 was completed, which included LTE Advanced, an enhancement of the original LTE standard with improved data rates and network capacity.",
      "date": "2011-03"
    },
    {
      "headline": "Global LTE Adoption",
      "text": "By 2013, LTE had been adopted by numerous carriers worldwide, with over 200 networks in more than 75 countries, making it the fastest developing mobile system technology.",
      "date": "2013"
    },
    {
      "headline": "Introduction of VoLTE",
      "text": "Voice over LTE (VoLTE) technology was introduced to allow voice calls over LTE networks, providing higher quality voice calls and more efficient use of the network. This technology began rolling out in 2014.",
      "date": "2014"
    },
    {
      "headline": "LTE Advanced Pro",
      "text": "In 2015, 3GPP Release 13 introduced LTE Advanced Pro, which included further enhancements such as higher data rates, improved spectral efficiency, and support for new use cases.",
      "date": "2015"
    },
    {
      "headline": "LTE in Rural and Remote Areas",
      "text": "By 2018, LTE had expanded significantly into rural and remote areas, providing high-speed internet access to regions previously underserved by broadband technologies.",
      "date": "2018"
    },
    {
      "headline": "Transition to 5G",
      "text": "As of 2020, LTE networks continue to be widely used globally, but the transition to 5G technology has begun, promising even faster speeds and more advanced capabilities.",
      "date": "2020"
    }
  ]
}

