{
  "timeline": [
    {
      "headline": "Invention of the Telegraph",
      "text": "In the 1830s and 1840s, the telegraph was developed, allowing for the transmission of messages over long distances using electrical signals.",
      "date": "1830"
    },
    {
      "headline": "First Successful Transatlantic Telegraph Cable",
      "text": "In 1858, the first successful transatlantic telegraph cable was laid, allowing for communication between North America and Europe.",
      "date": "1858"
    },
    {
      "headline": "Invention of the Telephone",
      "text": "In 1876, Alexander Graham Bell was awarded the first US patent for the invention of the telephone, revolutionizing personal and business communication.",
      "date": "1876"
    },
    {
      "headline": "Invention of Radio",
      "text": "In the late 19th century, Guglielmo Marconi developed the first successful long-distance wireless telegraph and radio transmission systems.",
      "date": "1890"
    },
    {
      "headline": "First Commercial Radio Broadcast",
      "text": "In 1920, the first commercial radio broadcast was made by KDKA in Pittsburgh, Pennsylvania, marking the beginning of radio as a mass communication medium.",
      "date": "1920"
    },
    {
      "headline": "Introduction of Television",
      "text": "In the late 1920s, television was introduced, with the first public demonstration of a television set by John Logie Baird in 1926.",
      "date": "1926"
    },
    {
      "headline": "Launch of the First Communication Satellite",
      "text": "In 1962, Telstar, the first active communication satellite, was launched, enabling live transatlantic television broadcasts.",
      "date": "1962"
    },
    {
      "headline": "Introduction of Mobile Phones",
      "text": "In 1973, the first handheld mobile phone call was made by Martin Cooper of Motorola, marking the beginning of mobile telecommunications.",
      "date": "1973"
    },
