{
  "timeline": [
    {
      "headline": "Franco-Russian Alliance",
      "text": "The Franco-Russian Alliance was established in 1894 as a military alliance between the French Third Republic and the Russian Empire. This alliance laid the groundwork for the later formation of the Triple Entente.",
      "date": "1894"
    },
    {
      "headline": "Entente Cordiale",
      "text": "The Entente Cordiale was signed on April 8, 1904, between the United Kingdom and the French Third Republic. This agreement marked the end of centuries of conflict between the two nations and was a significant step towards the formation of the Triple Entente.",
      "date": "1904-04-08"
    },
    {
      "headline": "Anglo-Russian Entente",
      "text": "The Anglo-Russian Entente was signed on August 31, 1907, between the United Kingdom and the Russian Empire. This agreement resolved long-standing colonial disputes in Asia and completed the formation of the Triple Entente.",
      "date": "1907-08-31"
    },
    {
      "headline": "Formation of the Triple Entente",
      "text": "The Triple Entente was formed in 1907 as an informal understanding between the Russian Empire, the French Third Republic, and the United Kingdom. It served as a counterbalance to the Triple Alliance of Germany, Austria-Hungary, and Italy.",
      "date": "1907"
    },
    {
      "headline": "World War I Begins",
      "text": "World War I began on July 28, 1914. The Triple Entente played a crucial role in the war, with its member countries fighting against the Central Powers.",
      "date": "1914-07-28"
    },
    {
      "headline": "End of World War I",
      "text": "World War I ended on November 11, 1918, with the signing of the Armistice. The Triple Entente was instrumental in the defeat of the Central Powers.",
      "date": "1918-11-11"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Domestication of Bombyx mori",
      "text": "Bombyx mori, the domestic silk moth, was domesticated from its wild ancestor, Bombyx mandarina, in China. This process began around 5,000 years ago, during the Neolithic period, as humans began to selectively breed these moths for silk production.",
      "date": "-3000"
    },
    {
      "headline": "Silk Road Establishment",
      "text": "The Silk Road, a network of trade routes connecting the East and West, was established during the Han Dynasty (206 BCE – 220 CE). Bombyx mori played a crucial role in the trade of silk along these routes, significantly impacting the economies and cultures of the regions involved.",
      "date": "-0206"
    },
    {
      "headline": "Spread of Sericulture",
      "text": "Sericulture, the cultivation of silkworms for silk production, spread from China to Korea, Japan, and India by the 2nd century CE. Bombyx mori was central to this expansion, as its silk became highly sought after.",
      "date": "0200"
    },
    {
      "headline": "Introduction to the Byzantine Empire",
      "text": "In the 6th century, Bombyx mori was introduced to the Byzantine Empire. According to legend, monks smuggled silkworm eggs hidden in hollow bamboo canes, allowing the Byzantines to produce silk independently from China.",
      "date": "0550"
    },
    {
      "headline": "Silk Production in Europe",
      "text": "By the 13th century, Bombyx mori had been introduced to Italy and later to France, marking the beginning of European silk production. This development was crucial for the European textile industry.",
      "date": "1200"
    },
    {
      "headline": "Industrialization of Silk Production",
      "text": "During the 18th and 19th centuries, the industrialization of silk production began, with Bombyx mori at the center of this transformation. Innovations in spinning and weaving technologies increased silk production efficiency.",
      "date": "1700"
    },
    {
      "headline": "Modern Sericulture",
      "text": "Today, Bombyx mori remains a vital species for silk production worldwide. Advances in genetic research and breeding have continued to enhance silk yield and quality, maintaining its economic importance.",
      "date": "2023"
    }
  ]
}

