{
  "timeline": [
    {
      "headline": "Birth of Alexei Nikolaevich",
      "text": "Alexei Nikolaevich was born on August 12, 1904, in Peterhof Palace, Russia. He was the youngest child and only son of Tsar Nicholas II and Tsarina Alexandra Feodorovna.",
      "date": "1904-08-12"
    },
    {
      "headline": "Diagnosis of Hemophilia",
      "text": "Shortly after his birth, Alexei was diagnosed with hemophilia, a genetic disorder that prevents blood from clotting properly. This condition was inherited from his mother, Alexandra, who was a carrier of the disease.",
      "date": "1904"
    },
    {
      "headline": "Influence of Grigori Rasputin",
      "text": "Grigori Rasputin, a peasant faith healer, became a significant figure in the Romanov family due to his alleged ability to alleviate Alexei's hemophilia symptoms. His influence grew particularly strong around 1907 when he was first introduced to the family.",
      "date": "1907"
    },
    {
      "headline": "World War I and Alexei's Role",
      "text": "During World War I, Alexei was appointed honorary commander of a regiment and was often seen in military uniform. Despite his young age and health issues, he was involved in various ceremonial duties.",
      "date": "1914"
    },
    {
      "headline": "Abdication of Nicholas II",
      "text": "On March 15, 1917, Tsar Nicholas II abdicated the throne. Initially, he named Alexei as his successor, but later changed the decision in favor of his brother, Grand Duke Michael, due to Alexei's health issues.",
      "date": "1917-03-15"
    },
    {
      "headline": "House Arrest",
      "text": "Following the Russian Revolution, Alexei and his family were placed under house arrest by the Bolsheviks. They were initially held at the Alexander Palace and later moved to Tobolsk, Siberia.",
      "date": "1917"
    },
    {
      "headline": "Transfer to Yekaterinburg",
      "text": "In April 1918, the Romanov family, including Alexei, was transferred to the Ipatiev House in Yekaterinburg, where they were kept under strict surveillance.",
      "date": "1918-04"
    },
    {
      "headline": "Execution of the Romanov Family",
      "text": "On the night of July 16-17, 1918, Alexei Nikolaevich and his family were executed by Bolshevik forces in the basement of the Ipatiev House in Yekaterinburg.",
      "date": "1918-07-17"
    }
  ]
}

