    {
      "headline": "Origins of Giallo",
      "text": "The term 'giallo' originates from the yellow covers of crime-mystery novels published in Italy. These novels were popular in the 1920s and 1930s, setting the stage for the cinematic genre.",
      "date": "1920"
    },
    {
      "headline": "First Giallo Film",
      "text": "Mario Bava's 'The Girl Who Knew Too Much' is often considered the first giallo film, released in 1963. It established many of the genre's conventions.",
      "date": "1963"
    },
    {
      "headline": "Rise of Giallo Films",
      "text": "The late 1960s and early 1970s saw a surge in giallo films, with directors like Dario Argento and Lucio Fulci contributing significantly to the genre.",
      "date": "1970"
    },
    {
      "headline": "Dario Argento's Influence",
      "text": "Dario Argento's 'The Bird with the Crystal Plumage' (1970) was a major success and helped popularize the giallo genre internationally.",
      "date": "1970"
    },
    {
      "headline": "Peak Popularity",
      "text": "The early 1970s marked the peak of giallo's popularity, with numerous films being produced each year, blending mystery, horror, and eroticism.",
      "date": "1972"
    },
    {
      "headline": "Decline of Giallo",
      "text": "By the late 1970s and early 1980s, the popularity of giallo films began to decline as audiences shifted towards other horror subgenres.",
      "date": "1980"
    },
    {
      "headline": "Modern Revival",
      "text": "In the 2000s and 2010s, there was a renewed interest in giallo films, with directors paying homage to the classic style and themes of the genre.",
      "date": "2010"
    }
  ]
}

