{
  "timeline": [
    {
      "headline": "Kansas-Nebraska Act Passed",
      "text": "On May 30, 1854, the Kansas-Nebraska Act was passed by the U.S. Congress. This act allowed the territories of Kansas and Nebraska to decide for themselves whether or not to allow slavery within their borders through popular sovereignty.",
      "date": "1854-05-30"
    },
    {
      "headline": "First Territorial Elections",
      "text": "In November 1854, the first elections were held in the Kansas Territory. Pro-slavery forces from Missouri, known as 'Border Ruffians', crossed into Kansas to vote, leading to a pro-slavery legislature.",
      "date": "1854-11"
    },
    {
      "headline": "Sack of Lawrence",
      "text": "On May 21, 1856, pro-slavery forces attacked and looted the town of Lawrence, Kansas, which was known for its anti-slavery stance. This event is known as the Sack of Lawrence.",
      "date": "1856-05-21"
    },
    {
      "headline": "Pottawatomie Massacre",
      "text": "On May 24, 1856, abolitionist John Brown and his followers killed five pro-slavery settlers in Franklin County, Kansas, in what became known as the Pottawatomie Massacre.",
      "date": "1856-05-24"
    },
    {
      "headline": "Battle of Black Jack",
      "text": "On June 2, 1856, the Battle of Black Jack occurred near Baldwin City, Kansas. This was one of the first armed conflicts between pro-slavery and anti-slavery forces.",
      "date": "1856-06-02"
    },
    {
      "headline": "Marais des Cygnes Massacre",
      "text": "On May 19, 1858, pro-slavery forces captured and executed five free-state men in the Marais des Cygnes Massacre, further escalating tensions.",
      "date": "1858-05-19"
    },
    {
      "headline": "Wyandotte Constitution Adopted",
      "text": "On July 29, 1859, the Wyandotte Constitution was adopted, which prohibited slavery in Kansas. This constitution paved the way for Kansas to enter the Union as a free state.",
      "date": "1859-07-29"
    },
    {
      "headline": "Kansas Admitted to the Union",
      "text": "On January 29, 1861, Kansas was admitted to the Union as a free state, effectively ending the period known as Bleeding Kansas.",
      "date": "1861-01-29"
    }
  ]
}

