{
  "timeline": [
    {
      "headline": "Seizure of the Grand Mosque",
      "text": "On 1979-11-20, a group of up to 600 militants led by Juhayman al-Otaybi seized the Grand Mosque in Mecca, Saudi Arabia. The militants declared that the Mahdi, a messianic figure in Islam, had arrived in the form of Mohammed Abdullah al-Qahtani, one of their leaders.",
      "date": "1979-11-20"
    },
    {
      "headline": "Saudi Government Response",
      "text": "In response to the seizure, the Saudi government deployed the Saudi National Guard and the Saudi Arabian Army to surround the mosque. The government sought assistance from French special forces to plan a counter-assault.",
      "date": "1979-11-21"
    },
    {
      "headline": "Counter-Assault Begins",
      "text": "On 1979-11-25, Saudi forces, with the assistance of French special forces advisors, launched a counter-assault to retake the Grand Mosque. The operation involved the use of tear gas and other tactics to dislodge the militants.",
      "date": "1979-11-25"
    },
    {
      "headline": "End of the Siege",
      "text": "The siege ended on 1979-12-04 when Saudi forces successfully regained control of the Grand Mosque. The operation resulted in significant casualties, with hundreds of militants, hostages, and soldiers killed.",
      "date": "1979-12-04"
    },
    {
      "headline": "Aftermath and Executions",
      "text": "Following the end of the siege, Juhayman al-Otaybi and 67 of his followers were captured, tried, and executed by beheading on 1980-01-09. The event had significant impacts on Saudi society and led to increased religious conservatism.",
      "date": "1980-01-09"
    }
  ]
}

