{
  "timeline": [
    {
      "headline": "Origin of Corporatism",
      "text": "The concept of corporatism can be traced back to ancient societies where guilds and similar organizations played a role in economic and political life. The term itself is derived from the Latin word 'corpus', meaning 'body'.",
      "date": "-0500"
    },
    {
      "headline": "Medieval Guilds",
      "text": "During the Middle Ages, guilds in Europe were early forms of corporatist organizations, representing the interests of craftsmen and merchants in various industries.",
      "date": "1200"
    },
    {
      "headline": "Papal Encyclical 'Rerum Novarum'",
      "text": "On May 15, 1891, Pope Leo XIII issued the encyclical 'Rerum Novarum', which addressed the condition of the working classes and is considered a foundational text for modern Catholic corporatism.",
      "date": "1891-05-15"
    },
    {
      "headline": "Rise of Fascist Corporatism",
      "text": "In the early 20th century, corporatism became associated with fascist regimes, particularly in Italy under Benito Mussolini, who implemented a corporatist economic system.",
      "date": "1920"
    },
    {
      "headline": "Corporatism in Nazi Germany",
      "text": "The Nazi regime in Germany also adopted a form of corporatism, integrating various economic sectors into a state-controlled framework.",
      "date": "1933"
    },
    {
      "headline": "Post-World War II Corporatism",
      "text": "After World War II, corporatism evolved in various forms, influencing economic and social policies in countries like Sweden and Austria, where it became part of the social democratic model.",
      "date": "1945"
    },
    {
      "headline": "Neocorporatism",
      "text": "In the late 20th century, neocorporatism emerged as a model where labor, business, and government work together to create economic policies, seen in countries like Germany and the Netherlands.",
      "date": "1970"
    }
  ]
}

