{
  "timeline": [
    {
      "headline": "Enactment of HIPAA",
      "text": "The Health Insurance Portability and Accountability Act (HIPAA) was enacted by the 104th United States Congress and signed into law by President Bill Clinton on August 21, 1996. The act aimed to improve the portability and accountability of health insurance coverage and to protect the privacy and security of healthcare information.",
      "date": "1996-08-21"
    },
    {
      "headline": "HIPAA Privacy Rule",
      "text": "The HIPAA Privacy Rule was published on December 28, 2000, and established national standards to protect individuals' medical records and other personal health information. It required appropriate safeguards to protect the privacy of personal health information and set limits and conditions on the uses and disclosures that may be made of such information without patient authorization.",
      "date": "2000-12-28"
    },
    {
      "headline": "Compliance Deadline for HIPAA Privacy Rule",
      "text": "The compliance deadline for the HIPAA Privacy Rule was April 14, 2003. By this date, covered entities were required to comply with the standards set forth in the Privacy Rule to protect patients' personal health information.",
      "date": "2003-04-14"
    },
    {
      "headline": "HIPAA Security Rule",
      "text": "The HIPAA Security Rule was published on February 20, 2003, and established national standards to protect individuals' electronic personal health information that is created, received, used, or maintained by a covered entity. It required appropriate administrative, physical, and technical safeguards to ensure the confidentiality, integrity, and security of electronic protected health information.",
      "date": "2003-02-20"
    },
    {
      "headline": "Compliance Deadline for HIPAA Security Rule",
      "text": "The compliance deadline for the HIPAA Security Rule was April 20, 2005. Covered entities were required to comply with the standards to protect electronic personal health information by this date.",
      "date": "2005-04-20"
    },
    {
      "headline": "HIPAA Enforcement Rule",
      "text": "The HIPAA Enforcement Rule was published on February 16, 2006, and established procedures for investigations and penalties for HIPAA violations. It provided guidelines for the imposition of civil money penalties on covered entities that violate HIPAA rules.",
      "date": "2006-02-16"
    },
    {
      "headline": "HITECH Act and HIPAA",
      "text": "The Health Information Technology for Economic and Clinical Health (HITECH) Act was enacted on February 17, 2009, as part of the American Recovery and Reinvestment Act. It strengthened the enforcement of HIPAA rules by increasing penalties for violations and expanding the scope of privacy and security protections for health information.",
      "date": "2009-02-17"
    },
    {
      "headline": "Omnibus Rule",
      "text": "The HIPAA Omnibus Rule was published on January 25, 2013, and implemented a number of provisions of the HITECH Act to strengthen the privacy and security protections for health information. It also made changes to the HIPAA Privacy, Security, and Enforcement Rules to improve their workability and effectiveness.",
      "date": "2013-01-25"
    }
  ]
}

