    {
      "headline": "Canadian Confederation",
      "text": "On July 1, 1867, the British North America Act, 1867, came into effect, uniting the three separate colonies of the United Canadas, Nova Scotia, and New Brunswick into a single dominion within the British Empire called Canada.",
      "date": "1867-07-01"
    },
    {
      "headline": "First Dominion Day Celebrations",
      "text": "The first official celebrations of Dominion Day took place on July 1, 1868, marking the first anniversary of the Canadian Confederation.",
      "date": "1868-07-01"
    },
    {
      "headline": "Dominion Day Becomes a Statutory Holiday",
      "text": "In 1879, Dominion Day was established as a statutory holiday, allowing Canadians to officially celebrate the anniversary of Confederation.",
      "date": "1879"
    },
    {
      "headline": "First Nationwide Celebrations",
      "text": "In 1917, the 50th anniversary of Confederation was marked by nationwide celebrations, including the first official observance of Dominion Day across Canada.",
      "date": "1917"
    },
    {
      "headline": "Canada's Centennial",
      "text": "On July 1, 1967, Canada celebrated its 100th anniversary with large-scale events and celebrations across the country, marking a significant milestone in Canadian history.",
      "date": "1967-07-01"
    },
    {
      "headline": "Dominion Day Renamed to Canada Day",
      "text": "On October 27, 1982, the name of the holiday was officially changed from Dominion Day to Canada Day, reflecting the country's growing sense of independence and identity.",
      "date": "1982-10-27"
    },
    {
      "headline": "Canada Day 150th Anniversary",
      "text": "On July 1, 2017, Canada celebrated the 150th anniversary of Confederation with events and celebrations across the country, highlighting Canada's history and cultural diversity.",
      "date": "2017-07-01"
    }
  ]
}

