    {
      "headline": "Start of the Arab Revolt",
      "text": "The Arab Revolt in Palestine began in April 1936 as a response to growing tensions between Palestinian Arabs and Jewish immigrants, as well as dissatisfaction with British colonial rule.",
      "date": "1936-04"
    },
    {
      "headline": "Formation of Arab Higher Committee",
      "text": "In April 1936, the Arab Higher Committee was formed under the leadership of Amin al-Husseini to coordinate the revolt and represent Palestinian Arab interests.",
      "date": "1936-04"
    },
    {
      "headline": "General Strike",
      "text": "A general strike was declared by Palestinian Arabs in April 1936, lasting until October 1936, as a protest against British policies and Jewish immigration.",
      "date": "1936-04"
    },
    {
      "headline": "Peel Commission",
      "text": "In 1937, the British government established the Peel Commission to investigate the causes of the unrest and propose solutions. The commission recommended partitioning Palestine into separate Jewish and Arab states.",
      "date": "1937"
    },
    {
      "headline": "Renewed Violence",
      "text": "Following the rejection of the Peel Commission's partition plan, violence resumed in 1937, with increased attacks on British forces and Jewish communities.",
      "date": "1937"
    },
    {
      "headline": "Suppression of the Revolt",
      "text": "By 1939, the British had largely suppressed the Arab Revolt through military action and political measures, including the arrest and exile of Arab leaders.",
      "date": "1939"
    },
    {
      "headline": "End of the Arab Revolt",
      "text": "The Arab Revolt officially ended in 1939, with the British issuing the White Paper of 1939, which limited Jewish immigration and land purchases in Palestine.",
      "date": "1939"
    }
  ]
}

{
