{
  "timeline": [
    {
      "headline": "First Iconoclasm Begins",
      "text": "The First Iconoclasm began in the Byzantine Empire under Emperor Leo III, who issued a series of edicts against the veneration of icons, starting in 726.",
      "date": "0726"
    },
    {
      "headline": "Council of Hieria",
      "text": "In 754, the Council of Hieria was convened by Emperor Constantine V, which supported the iconoclastic policies and condemned the veneration of icons.",
      "date": "0754"
    },
    {
      "headline": "End of First Iconoclasm",
      "text": "The First Iconoclasm ended in 787 with the Second Council of Nicaea, which restored the veneration of icons in the Byzantine Empire.",
      "date": "0787"
    },
    {
      "headline": "Second Iconoclasm Begins",
      "text": "The Second Iconoclasm began in 814 under Emperor Leo V, who reinstated iconoclastic policies in the Byzantine Empire.",
      "date": "0814"
    },
    {
      "headline": "End of Second Iconoclasm",
      "text": "The Second Iconoclasm ended in 843 with the restoration of the veneration of icons by Empress Theodora, celebrated as the Triumph of Orthodoxy.",
      "date": "0843"
    },
    {
      "headline": "Iconoclasm in the Protestant Reformation",
      "text": "During the Protestant Reformation in the 16th century, iconoclasm re-emerged as reformers like Martin Luther and John Calvin criticized the use of religious images, leading to widespread destruction of icons in Protestant regions.",
      "date": "1500"
    }
  ]
}

