{
  "timeline": [
    {
      "headline": "Earliest Settlement",
      "text": "The city of Erbil is one of the oldest continuously inhabited cities in the world, with evidence of settlement dating back to at least 6000 BCE.",
      "date": "-6000"
    },
    {
      "headline": "Assyrian Period",
      "text": "Erbil was an important city in the Assyrian Empire, known as Arbela. It served as a major religious center dedicated to the goddess Ishtar.",
      "date": "-0900"
    },
    {
      "headline": "Battle of Gaugamela",
      "text": "In 331 BCE, the Battle of Gaugamela took place near Erbil, where Alexander the Great defeated Darius III of Persia, leading to the fall of the Achaemenid Empire.",
      "date": "-0331"
    },
    {
      "headline": "Sassanian Era",
      "text": "During the Sassanian Empire, Erbil was a significant city and a center for Christianity in the region.",
      "date": "0224"
    },
    {
      "headline": "Islamic Conquest",
      "text": "Erbil came under Muslim control in the 7th century during the Islamic conquests, becoming part of the Umayyad and later the Abbasid Caliphates.",
      "date": "0637"
    },
    {
      "headline": "Zengid Dynasty",
      "text": "In the 12th century, Erbil became the capital of the Zengid dynasty under the rule of Imad ad-Din Zengi.",
      "date": "1144"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Erbil became part of the Ottoman Empire in the 16th century, remaining under Ottoman control until the end of World War I.",
      "date": "1514"
    },
    {
      "headline": "Incorporation into Iraq",
      "text": "Following the collapse of the Ottoman Empire, Erbil became part of the newly established state of Iraq in 1920 under the British Mandate.",
      "date": "1920"
    },
    {
      "headline": "Autonomous Kurdistan Region",
      "text": "In 1991, following the Gulf War, Erbil became the capital of the autonomous Kurdistan Region in Iraq.",
      "date": "1991"
    },
    {
      "headline": "Recognition of Kurdistan Regional Government",
      "text": "In 2005, the Kurdistan Regional Government was officially recognized in the Iraqi constitution, solidifying Erbil's status as the capital of the Kurdistan Region.",
      "date": "2005"
    }
  ]
}

