    },
    {
      "headline": "Batavian Republic Established",
      "text": "In 1795, the Batavian Republic was established, marking the end of the Dutch Republic and leading to changes in colonial administration.",
      "date": "1795"
    },
    {
      "headline": "Establishment of the Kingdom of the Netherlands",
      "text": "In 1815, the Kingdom of the Netherlands was established, and the Dutch colonial empire continued under this new political structure.",
      "date": "1815"
    },
    {
      "headline": "Abolition of Slavery in Dutch Colonies",
      "text": "Slavery was abolished in the Dutch colonies on July 1, 1863, marking a significant social and economic change in the empire.",
      "date": "1863-07-01"
    },
    {
      "headline": "Indonesian Independence",
      "text": "Indonesia declared independence from the Netherlands on August 17, 1945, and after a struggle, it was recognized in 1949, marking the end of Dutch colonial rule in Indonesia.",
