    {
      "headline": "Formation of the Grand Duchy of Lithuania",
      "text": "The Grand Duchy of Lithuania was established in the 13th century, succeeding the Kingdom of Lithuania. It was founded by Lithuanians, a polytheistic nation of several united Baltic tribes from Aukštaitija.",
      "date": "1200"
    },
    {
      "headline": "Reign of Mindaugas",
      "text": "Mindaugas, the first and only King of Lithuania, ruled from 1236 to 1263. He was crowned as King in 1253, marking the official recognition of the Grand Duchy.",
      "date": "1253"
    },
    {
      "headline": "Union with Poland",
      "text": "In 1385, the Grand Duchy of Lithuania entered into a union with the Kingdom of Poland through the Union of Krewo. This union was formalized by the marriage of Grand Duke Jogaila to Queen Jadwiga of Poland.",
      "date": "1385"
    },
    {
      "headline": "Battle of Grunwald",
      "text": "On July 15, 1410, the Grand Duchy of Lithuania, in alliance with the Kingdom of Poland, defeated the Teutonic Knights at the Battle of Grunwald, one of the largest battles in medieval Europe.",
      "date": "1410-07-15"
    },
    {
      "headline": "Peak Territorial Expansion",
      "text": "By 1440, the Grand Duchy of Lithuania had become the largest European state, controlling an area from the Baltic Sea in the north to the Black Sea in the south.",
      "date": "1440"
    },
    {
      "headline": "Union of Lublin",
      "text": "In 1569, the Union of Lublin was signed, creating the Polish-Lithuanian Commonwealth. This marked a significant political change as the Grand Duchy of Lithuania and the Kingdom of Poland became a single state.",
      "date": "1569"
    },
    {
      "headline": "Partitions of Poland-Lithuania",
      "text": "The Grand Duchy of Lithuania was suppressed during the partitions of Poland-Lithuania, with the final partition occurring in 1795, leading to the dissolution of the state.",
      "date": "1795"
    }
  ]
}

