      "date": "2023"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Ilse Koch",
      "text": "Ilse Koch was born on September 22, 1906, in Dresden, Germany.",
      "date": "1906-09-22"
    },
    {
      "headline": "Marriage to Karl-Otto Koch",
      "text": "Ilse Koch married Karl-Otto Koch in 1936. Karl-Otto Koch was a high-ranking Nazi official and later became the commandant of Buchenwald concentration camp.",
      "date": "1936"
    },
    {
      "headline": "Arrival at Buchenwald",
      "text": "In 1937, Ilse Koch moved to Buchenwald concentration camp with her husband, Karl-Otto Koch, who was appointed as the commandant.",
      "date": "1937"
    },
    {
      "headline": "Infamous Acts at Buchenwald",
      "text": "During her time at Buchenwald, Ilse Koch became notorious for her cruelty towards prisoners. She was accused of selecting prisoners with distinctive tattoos to be killed and their skin preserved.",
      "date": "1937-1941"
    },
    {
      "headline": "Arrest by Nazi Authorities",
      "text": "In August 1943, Ilse Koch was arrested by the Nazi authorities and charged with embezzlement and other crimes. Her husband, Karl-Otto Koch, was also arrested and later executed.",
      "date": "1943-08"
    },
    {
      "headline": "Trial and Conviction by U.S. Military Tribunal",
      "text": "Ilse Koch was tried by a U.S. military tribunal in 1947 and sentenced to life imprisonment for war crimes.",
      "date": "1947"
    },
    {
      "headline": "Release and Re-arrest",
      "text": "Ilse Koch was released in 1949 due to lack of evidence but was re-arrested by German authorities and tried again.",
      "date": "1949"
    },
    {
      "headline": "Second Trial and Conviction",
      "text": "In 1951, Ilse Koch was tried by a West German court and sentenced to life imprisonment for her crimes at Buchenwald.",
      "date": "1951"
    },
    {
      "headline": "Death of Ilse Koch",
      "text": "Ilse Koch died by suicide on September 1, 1967, in Aichach prison, Bavaria, Germany.",
      "date": "1967-09-01"
    }
  ]
}

