    {
      "headline": "Formation of Crimean Tatars",
      "text": "The ethnogenesis of the Crimean Tatars began over 2500 years ago in Crimea and the Northern Black Sea region, uniting Mediterranean populations with those of the Eurasian Steppe.",
      "date": "-0500"
    },
    {
      "headline": "Golden Horde Influence",
      "text": "In the 13th century, the Crimean Peninsula came under the influence of the Golden Horde, a Mongol and later Turkicized khanate.",
      "date": "1200"
    },
    {
      "headline": "Establishment of the Crimean Khanate",
      "text": "In 1441, the Crimean Khanate was established by Hacı I Giray, marking the beginning of a distinct Crimean Tatar state.",
      "date": "1441"
    },
    {
      "headline": "Ottoman Protectorate",
      "text": "In 1475, the Crimean Khanate became a protectorate of the Ottoman Empire, maintaining a degree of autonomy while aligning with Ottoman interests.",
      "date": "1475"
    },
    {
      "headline": "Annexation by the Russian Empire",
      "text": "In 1783, the Russian Empire annexed Crimea, ending the independence of the Crimean Khanate and beginning a period of Russian control.",
      "date": "1783"
    },
    {
      "headline": "Deportation of Crimean Tatars",
      "text": "On May 18, 1944, the Soviet government forcibly deported the entire Crimean Tatar population to Central Asia, primarily Uzbekistan, accusing them of collaborating with Nazi Germany.",
      "date": "1944-05-18"
    },
    {
      "headline": "Return to Crimea",
      "text": "Following the dissolution of the Soviet Union in 1991, many Crimean Tatars began returning to Crimea, seeking to re-establish their communities and cultural heritage.",
      "date": "1991"
    }
  ]
}

