{
  "timeline": [
    {
      "headline": "Start of Volkswagen Emissions Scandal",
      "text": "In September 2015, the United States Environmental Protection Agency (EPA) issued a notice of violation of the Clean Air Act to Volkswagen Group. The EPA found that Volkswagen had intentionally programmed turbocharged direct injection (TDI) diesel engines to activate emissions controls only during laboratory testing, causing vehicles to meet US standards during tests but emit up to 40 times more NOx in real-world driving.",
      "date": "2015-09"
    },
    {
      "headline": "Volkswagen Admits to Cheating",
      "text": "On September 22, 2015, Volkswagen admitted to installing defeat devices in 11 million cars worldwide, including 500,000 in the United States, to manipulate emissions tests.",
      "date": "2015-09-22"
    },
    {
      "headline": "CEO Martin Winterkorn Resigns",
      "text": "On September 23, 2015, Volkswagen CEO Martin Winterkorn resigned amid the emissions scandal, taking responsibility for the irregularities found in diesel engines.",
      "date": "2015-09-23"
    },
    {
      "headline": "Volkswagen Announces Recall",
      "text": "In October 2015, Volkswagen announced plans to recall up to 8.5 million vehicles in Europe and 500,000 in the United States to address the emissions cheating issue.",
      "date": "2015-10"
    },
    {
      "headline": "Volkswagen Agrees to Settlement",
      "text": "On June 28, 2016, Volkswagen agreed to a $14.7 billion settlement in the United States to resolve claims related to the emissions scandal, including vehicle buybacks and environmental remediation.",
      "date": "2016-06-28"
    },
    {
      "headline": "Volkswagen Pleads Guilty",
      "text": "On January 11, 2017, Volkswagen pleaded guilty to three criminal felony counts, including conspiracy to commit fraud, obstruction of justice, and entry of goods by false statement, as part of a $4.3 billion settlement with the US Department of Justice.",
      "date": "2017-01-11"
    },
    {
      "headline": "Volkswagen Executives Charged",
      "text": "In January 2017, six Volkswagen executives were charged by the US Department of Justice for their roles in the emissions cheating scandal.",
      "date": "2017-01"
    },
    {
      "headline": "Volkswagen's Settlement with the European Union",
      "text": "In December 2018, Volkswagen reached a settlement with the European Union to pay €1 billion in fines for the emissions scandal.",
      "date": "2018-12"
    }
  ]
}

