{
  "timeline": [
    {
      "headline": "TGV Conceptualization",
      "text": "The TGV (Train à Grande Vitesse) was conceived in the 1960s as part of France's national policies to develop high-speed transportation, alongside projects like the Ariane rocket and Concorde.",
      "date": "1960"
    },
    {
      "headline": "TGV Prototype Development",
      "text": "In the early 1970s, the first TGV prototype, known as TGV 001, was developed. It was powered by gas turbines and served as a testbed for high-speed rail technology.",
      "date": "1972"
    },
    {
      "headline": "First TGV Line Construction",
      "text": "Construction of the first TGV line, the LGV Sud-Est, began in the mid-1970s. This line was designed to connect Paris and Lyon.",
      "date": "1976"
    },
    {
      "headline": "Inauguration of TGV Service",
      "text": "The TGV service was officially inaugurated on September 27, 1981, with the opening of the LGV Sud-Est line, connecting Paris and Lyon.",
      "date": "1981-09-27"
    },
    {
      "headline": "TGV Atlantique Record",
      "text": "On May 18, 1990, a TGV Atlantique train set a world speed record for rail vehicles, reaching 515.3 km/h (320.2 mph).",
      "date": "1990-05-18"
    },
    {
      "headline": "TGV Network Expansion",
      "text": "Throughout the 1990s and 2000s, the TGV network expanded significantly, with new lines such as the LGV Atlantique, LGV Nord, and LGV Méditerranée.",
      "date": "1990"
    },
    {
      "headline": "TGV Est Européen Opening",
      "text": "The TGV Est Européen line, connecting Paris to eastern France and beyond, was inaugurated on June 10, 2007.",
      "date": "2007-06-10"
    },
    {
      "headline": "TGV World Speed Record",
      "text": "On April 3, 2007, a TGV train set a new world speed record for conventional trains, reaching 574.8 km/h (357.2 mph).",
      "date": "2007-04-03"
    },
