{
  "timeline": [
    {
      "headline": "Birth of Satyendra Nath Bose",
      "text": "Satyendra Nath Bose was born on January 1, 1894, in Calcutta, Bengal Presidency, British India.",
      "date": "1894-01-01"
    },
    {
      "headline": "Graduation from Presidency College",
      "text": "In 1913, Satyendra Nath Bose graduated with a Bachelor of Science degree in mixed mathematics from Presidency College, Calcutta.",
      "date": "1913"
    },
    {
      "headline": "Master's Degree",
      "text": "In 1915, Bose completed his Master of Science in mixed mathematics from the University of Calcutta, securing the first position in the examination.",
      "date": "1915"
    },
    {
      "headline": "Lecturer at the University of Calcutta",
      "text": "In 1916, Bose was appointed as a lecturer in the physics department of the University of Calcutta.",
      "date": "1916"
    },
    {
      "headline": "Publication of Bose's Quantum Mechanics Paper",
      "text": "In 1924, Bose sent his paper on quantum mechanics to Albert Einstein, which led to the development of Bose-Einstein statistics.",
      "date": "1924"
    },
    {
      "headline": "Bose-Einstein Statistics",
      "text": "In 1924, Albert Einstein translated Bose's paper into German and submitted it to the Zeitschrift für Physik, leading to the formulation of Bose-Einstein statistics.",
      "date": "1924"
    },
    {
      "headline": "Professorship at Dhaka University",
      "text": "In 1926, Bose was appointed as a professor and head of the Department of Physics at the University of Dhaka.",
      "date": "1926"
    },
    {
      "headline": "Return to Calcutta University",
      "text": "In 1945, Bose returned to Calcutta University as the Khaira Professor of Physics.",
      "date": "1945"
    },
    {
      "headline": "Fellow of the Royal Society",
      "text": "In 1958, Satyendra Nath Bose was elected a Fellow of the Royal Society.",
      "date": "1958"
    },
    {
      "headline": "Awarded Padma Vibhushan",
      "text": "In 1954, Bose was awarded the Padma Vibhushan, India's second highest civilian award, by the Government of India.",
      "date": "1954"
    },
    {
      "headline": "Death of Satyendra Nath Bose",
      "text": "Satyendra Nath Bose passed away on February 4, 1974, in Calcutta, India.",
      "date": "1974-02-04"
    }
  ]
}

