{
  "timeline": [
    {
      "headline": "Planck Epoch",
      "text": "The Planck epoch is the earliest period of time in the history of the universe, from 0 to approximately 10^-43 seconds after the Big Bang. During this time, the four fundamental forces—gravity, electromagnetism, the weak nuclear force, and the strong nuclear force—were unified.",
      "date": "0"
    },
    {
      "headline": "Grand Unification Epoch",
      "text": "The Grand Unification Epoch began at approximately 10^-43 seconds after the Big Bang and lasted until about 10^-36 seconds. During this period, the strong nuclear force separated from the other fundamental forces.",
      "date": "0"
    },
    {
      "headline": "Inflationary Epoch",
      "text": "The Inflationary Epoch occurred from about 10^-36 to 10^-32 seconds after the Big Bang. The universe underwent exponential expansion, increasing in size by a factor of at least 10^26.",
      "date": "0"
    },
    {
      "headline": "Electroweak Epoch",
      "text": "The Electroweak Epoch lasted from 10^-36 seconds to 10^-12 seconds after the Big Bang. During this time, the electromagnetic force and weak nuclear force were unified.",
      "date": "0"
    },
    {
      "headline": "Quark Epoch",
      "text": "The Quark Epoch occurred from 10^-12 seconds to 10^-6 seconds after the Big Bang. The universe was filled with a hot, dense plasma of quarks, gluons, and leptons.",
      "date": "0"
    },
    {
      "headline": "Hadron Epoch",
      "text": "The Hadron Epoch began approximately 10^-6 seconds after the Big Bang and lasted until about 1 second. Quarks combined to form protons and neutrons.",
      "date": "0"
    },
    {
      "headline": "Lepton Epoch",
      "text": "The Lepton Epoch occurred from 1 second to 10 seconds after the Big Bang. Leptons dominated the mass of the universe.",
      "date": "0"
    },
    {
      "headline": "Photon Epoch",
      "text": "The Photon Epoch began around 10 seconds after the Big Bang and lasted until about 370,000 years. The universe was dominated by photons, and matter began to form neutral atoms.",
      "date": "0"
    },
    {
      "headline": "Recombination",
      "text": "Recombination occurred approximately 370,000 years after the Big Bang. Electrons combined with protons and neutrons to form neutral atoms, allowing photons to travel freely and leading to the Cosmic Microwave Background radiation.",
      "date": "0000370"
    },
    {
      "headline": "Dark Ages",
      "text": "The Dark Ages spanned from about 370,000 years to 150 million years after the Big Bang. The universe was filled with neutral hydrogen and helium atoms, with no stars or galaxies.",
      "date": "0000370"
    },
    {
      "headline": "Reionization",
      "text": "Reionization began around 150 million years after the Big Bang and lasted until about 1 billion years. The first stars and galaxies formed, ionizing the surrounding hydrogen gas.",
      "date": "0000150"
    },
    {
      "headline": "Formation of the Solar System",
      "text": "The Solar System formed approximately 9.2 billion years after the Big Bang, around 4.6 billion years ago.",
      "date": "00009200"
    },
    {
      "headline": "Present Day",
      "text": "The present day is approximately 13.8 billion years after the Big Bang. The universe continues to expand, with galaxies moving away from each other.",
      "date": "00013800"
    }
  ]
}

