{
  "timeline": [
    {
      "headline": "First Mention of Schönbrunn",
      "text": "The first mention of the name 'Schönbrunn' dates back to 1642, referring to an artesian well from which water was consumed by the court.",
      "date": "1642"
    },
    {
      "headline": "Construction of the Palace",
      "text": "Construction of Schönbrunn Palace began in 1696 under the orders of Emperor Leopold I, designed by architect Johann Bernhard Fischer von Erlach.",
      "date": "1696"
    },
    {
      "headline": "Completion of the Initial Construction",
      "text": "The initial construction of Schönbrunn Palace was completed in 1700, although it underwent several modifications and expansions in the following years.",
      "date": "1700"
    },
    {
      "headline": "Maria Theresa's Renovations",
      "text": "In 1743, Empress Maria Theresa commissioned major renovations and expansions of Schönbrunn Palace, transforming it into a grand summer residence.",
      "date": "1743"
    },
    {
      "headline": "Completion of Maria Theresa's Renovations",
      "text": "The renovations commissioned by Maria Theresa were completed in 1749, giving the palace much of its present appearance.",
      "date": "1749"
    },
    {
      "headline": "Napoleon's Occupation",
      "text": "Napoleon Bonaparte occupied Schönbrunn Palace twice during his campaigns, first in 1805 and again in 1809.",
      "date": "1805"
    },
    {
      "headline": "Second Occupation by Napoleon",
      "text": "Napoleon Bonaparte occupied Schönbrunn Palace for the second time in 1809 during the War of the Fifth Coalition.",
      "date": "1809"
    },
    {
      "headline": "Congress of Vienna",
      "text": "The Congress of Vienna, which reorganized Europe after the Napoleonic Wars, took place in 1814-1815, with Schönbrunn Palace playing a role in hosting events.",
      "date": "1814"
    },
    {
      "headline": "End of Habsburg Monarchy",
      "text": "The Habsburg monarchy ended in 1918 following World War I, and Schönbrunn Palace became the property of the newly established Republic of Austria.",
      "date": "1918"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1996, Schönbrunn Palace was designated as a UNESCO World Heritage Site, recognizing its historical and cultural significance.",
      "date": "1996"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Foundation of Girona",
      "text": "Girona was founded by the Iberians, an ancient people of the Iberian Peninsula. The exact date of foundation is not known, but it is believed to have been established before Roman times.",
      "date": "-0200"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 79 BCE, the Romans conquered the area and established the city of Gerunda, which became an important Roman settlement.",
      "date": "-0079"
    },
    {
      "headline": "Visigothic Rule",
      "text": "After the fall of the Roman Empire, Girona came under the control of the Visigoths in the 5th century.",
      "date": "0500"
    },
    {
      "headline": "Muslim Conquest",
      "text": "In 715, Girona was conquered by the Moors, becoming part of the Muslim territories in the Iberian Peninsula.",
      "date": "0715"
    },
    {
      "headline": "Frankish Conquest",
      "text": "In 785, Girona was captured by Charlemagne's Frankish forces, becoming part of the Carolingian Empire.",
      "date": "0785"
    },
    {
      "headline": "County of Girona",
      "text": "In the 9th century, Girona became the center of the County of Girona, a part of the Marca Hispanica established by the Carolingians.",
      "date": "0800"
    },
    {
      "headline": "Siege of Girona",
      "text": "In 1285, Girona was besieged by the French during the Aragonese Crusade, but the city successfully resisted the attack.",
      "date": "1285"
    },
    {
      "headline": "Jewish Expulsion",
      "text": "In 1492, following the Alhambra Decree, the Jewish community in Girona was expelled, marking the end of a significant Jewish presence in the city.",
      "date": "1492"
    },
    {
      "headline": "War of Spanish Succession",
      "text": "During the War of Spanish Succession, Girona was besieged several times between 1705 and 1711, suffering significant damage.",
      "date": "1705"
    },
    {
      "headline": "Napoleonic Wars",
      "text": "Girona was besieged by Napoleonic forces in 1809 during the Peninsular War, enduring a lengthy and devastating siege.",
      "date": "1809"
    },
    {
      "headline": "Modern Development",
      "text": "In the 19th and 20th centuries, Girona underwent significant urban development and modernization, becoming an important cultural and economic center in Catalonia.",
      "date": "1900"
    },
    {
      "headline": "Catalan Statute of Autonomy",
      "text": "In 1979, following the end of Francoist Spain, Girona became part of the autonomous community of Catalonia under the new Statute of Autonomy.",
      "date": "1979"
    },
    {
      "headline": "UNESCO World Heritage",
      "text": "In 1997, the historic center of Girona was declared a UNESCO World Heritage site, recognizing its cultural and historical significance.",
      "date": "1997"
    }
  ]
}

{
  "timeline": [
