    },
    {
      "headline": "Enrollment at École des Beaux-Arts",
      "text": "In 1855, Degas enrolled at the École des Beaux-Arts in Paris to study art.",
      "date": "1855"
    },
    {
      "headline": "Travel to Italy",
      "text": "Between 1856 and 1859, Degas traveled to Italy, where he studied and copied the works of the Italian Renaissance masters.",
      "date": "1856"
