    {
      "headline": "First Exhibition at the Salon",
      "text": "In 1865, Degas exhibited his painting 'Scene of War in the Middle Ages' at the Salon for the first time.",
      "date": "1865"
    },
    {
      "headline": "Shift to Modern Life Subjects",
      "text": "By the late 1860s, Degas began focusing on modern life subjects, including ballet dancers and horse races.",
      "date": "1868"
    },
    {
      "headline": "Participation in the First Impressionist Exhibition",
      "text": "In 1874, Degas participated in the first Impressionist exhibition, showcasing his works alongside other Impressionist artists.",
      "date": "1874"
    },
    {
      "headline": "Development of Pastel Technique",
      "text": "During the 1880s, Degas developed his technique with pastels, creating some of his most famous works.",
      "date": "1880"
    },
    {
      "headline": "Increasing Eye Problems",
      "text": "In the 1890s, Degas's eyesight began to deteriorate significantly, affecting his ability to paint.",
      "date": "1890"
    },
    {
      "headline": "Final Exhibition",
      "text": "Degas held his last exhibition in 1912, as his eyesight continued to worsen.",
      "date": "1912"
    },
    {
      "headline": "Death of Edgar Degas",
      "text": "Edgar Degas died on September 27, 1917, in Paris, France.",
      "date": "1917-09-27"
    }
  ]
}

