    {
      "headline": "Development of Glasgow Coma Scale",
      "text": "The Glasgow Coma Scale was developed by Graham Teasdale and Bryan Jennett, professors of neurosurgery at the University of Glasgow, in 1974. It was created to provide a reliable and objective way of recording the conscious state of a person for initial as well as subsequent assessment.",
      "date": "1974"
    },
    {
      "headline": "Publication of the Glasgow Coma Scale",
      "text": "The Glasgow Coma Scale was first published in the medical journal 'The Lancet' in 1974. This publication introduced the scale to the wider medical community and established its use in assessing consciousness in patients with acute brain injury.",
      "date": "1974"
    },
    {
      "headline": "Adoption in Medical Practice",
      "text": "Since its development, the Glasgow Coma Scale has been widely adopted in hospitals and emergency medical services worldwide. It has become a standard tool for assessing the level of consciousness in patients with head injuries.",
      "date": "1970s"
    },
    {
      "headline": "Refinements and Updates",
      "text": "Over the years, the Glasgow Coma Scale has undergone refinements to improve its accuracy and applicability. These updates have helped maintain its relevance in modern medical practice.",
      "date": "1980s-2000s"
    },
    {
      "headline": "Inclusion in Medical Protocols",
      "text": "The Glasgow Coma Scale has been included in various medical protocols and guidelines, such as those by the Advanced Trauma Life Support (ATLS) and the Brain Trauma Foundation, underscoring its importance in trauma assessment.",
      "date": "1990s"
    }
  ]
}

