    {
      "headline": "Catiline's First Attempt at Consulship",
      "text": "In 65 BC, Lucius Sergius Catilina (Catiline) made his first attempt to become consul but was unsuccessful.",
      "date": "-0065"
    },
    {
      "headline": "Catiline's Second Attempt at Consulship",
      "text": "In 64 BC, Catiline ran for consul again but was defeated by Marcus Tullius Cicero and Gaius Antonius Hybrida.",
      "date": "-0064"
    },
    {
      "headline": "Catiline's Third Attempt and Conspiracy",
      "text": "In 63 BC, Catiline made a third attempt to become consul. After another defeat, he began plotting to overthrow the government.",
      "date": "-0063"
    },
    {
      "headline": "Cicero's First Oration Against Catiline",
      "text": "On November 8, 63 BC, Cicero delivered his first oration against Catiline in the Senate, exposing the conspiracy.",
      "date": "-0063-11-08"
    },
    {
      "headline": "Catiline Flees Rome",
      "text": "After Cicero's oration, Catiline fled Rome on November 9, 63 BC, to join his army in Etruria.",
      "date": "-0063-11-09"
    },
    {
      "headline": "Senate Declares Catiline a Public Enemy",
      "text": "On December 5, 63 BC, the Senate declared Catiline a public enemy and authorized Cicero to take action against the conspirators.",
      "date": "-0063-12-05"
    },
    {
      "headline": "Battle of Pistoria",
      "text": "In January 62 BC, Catiline's forces were defeated by the Roman army led by Gaius Antonius Hybrida at the Battle of Pistoria, where Catiline was killed.",
      "date": "-0062-01"
    }
  ]
}

