{
  "timeline": [
    {
      "headline": "Arrival of the Dutch East India Company",
      "text": "In 1652, the Dutch East India Company established a supply station at the Cape of Good Hope, marking the beginning of European settlement in the region.",
      "date": "1652"
    },
    {
      "headline": "Emergence of the Free Burghers",
      "text": "In the late 17th century, the Dutch East India Company allowed some employees to become free citizens, known as Free Burghers, who began farming the land.",
      "date": "1670"
    },
    {
      "headline": "Expansion of the Trekboers",
      "text": "During the 18th century, the Trekboers, semi-nomadic pastoralists, began moving inland from the Cape Colony in search of new grazing lands.",
      "date": "1700"
    },
    {
      "headline": "First British Occupation of the Cape",
      "text": "In 1795, the British first occupied the Cape Colony to prevent it from falling into French hands during the Napoleonic Wars.",
      "date": "1795"
    },
    {
      "headline": "Return to Dutch Control",
      "text": "The Cape Colony was returned to Dutch control in 1803 under the Treaty of Amiens.",
      "date": "1803"
    },
    {
      "headline": "British Reoccupation of the Cape",
      "text": "In 1806, the British reoccupied the Cape Colony, which was later formally ceded to them in 1814.",
      "date": "1806"
    },
    {
      "headline": "Great Trek Begins",
      "text": "In the 1830s, many Boers, dissatisfied with British rule, began the Great Trek, migrating northwards to establish independent republics.",
      "date": "1830"
    },
    {
      "headline": "Establishment of Boer Republics",
      "text": "By the mid-19th century, the Boers had established several independent republics, including the South African Republic (Transvaal) and the Orange Free State.",
      "date": "1850"
    },
    {
      "headline": "First Anglo-Boer War",
      "text": "The First Anglo-Boer War took place from 1880 to 1881, resulting in a Boer victory and the restoration of independence to the South African Republic.",
      "date": "1880"
    },
    {
      "headline": "Second Anglo-Boer War",
      "text": "The Second Anglo-Boer War occurred from 1899 to 1902, ending with a British victory and the annexation of the Boer republics into the British Empire.",
      "date": "1899"
    },
    {
      "headline": "Union of South Africa",
      "text": "In 1910, the Union of South Africa was formed, uniting the former Boer republics and British colonies into a single dominion within the British Empire.",
      "date": "1910"
    }
  ]
}

