  "timeline": [
    {
      "headline": "First Recorded Cataract Surgery",
      "text": "The earliest recorded cataract surgery was performed in ancient India. The procedure, known as 'couching', involved dislodging the cataract lens from the line of vision. This practice dates back to around 600 BCE.",
      "date": "-0600"
    },
    {
      "headline": "Cataract Surgery in Ancient Greece",
      "text": "Cataract surgery was also practiced in ancient Greece. The Greek physician Galen described the procedure in the 2nd century CE.",
      "date": "0200"
    },
    {
      "headline": "Development of Extracapsular Cataract Extraction",
      "text": "In the 18th century, the technique of extracapsular cataract extraction was developed, which involved removing the lens but leaving the elastic capsule partially intact to allow implantation of an artificial lens.",
      "date": "1700"
    },
    {
      "headline": "Introduction of Intraocular Lenses",
      "text": "In 1949, British ophthalmologist Harold Ridley introduced the use of intraocular lenses (IOLs) to replace the natural lens after cataract removal, revolutionizing cataract surgery.",
      "date": "1949"
    },
    {
      "headline": "Phacoemulsification Technique Developed",
      "text": "In 1967, American ophthalmologist Charles Kelman developed the phacoemulsification technique, which uses ultrasonic vibrations to emulsify the lens, allowing it to be removed through a smaller incision.",
      "date": "1967"
    },
    {
      "headline": "Foldable Intraocular Lenses Introduced",
      "text": "In the late 1980s, foldable intraocular lenses were introduced, allowing for smaller incisions and quicker recovery times.",
      "date": "1980"
    },
    {
      "headline": "Laser-Assisted Cataract Surgery",
      "text": "In the early 21st century, laser-assisted cataract surgery was developed, which uses femtosecond lasers to perform some of the steps of cataract surgery with increased precision.",
      "date": "2000"
    }
  ]
}

