{
  "timeline": [
    {
      "headline": "Introduction of Public Key Cryptography",
      "text": "In 1976, Whitfield Diffie and Martin Hellman introduced the concept of public key cryptography, which laid the groundwork for digital signatures.",
      "date": "1976"
    },
    {
      "headline": "Development of RSA Algorithm",
      "text": "In 1977, Ron Rivest, Adi Shamir, and Leonard Adleman developed the RSA algorithm, which became one of the first practical public-key cryptosystems and is widely used for secure data transmission, including digital signatures.",
      "date": "1977"
    },
    {
      "headline": "First Digital Signature Algorithm",
      "text": "In 1988, the first digital signature algorithm was proposed by Shafi Goldwasser, Silvio Micali, and Ronald Rivest, which was based on the RSA algorithm.",
      "date": "1988"
    },
    {
      "headline": "Digital Signature Standard (DSS) Adoption",
      "text": "In 1991, the National Institute of Standards and Technology (NIST) proposed the Digital Signature Standard (DSS), which was adopted as a Federal Information Processing Standard (FIPS) in 1994.",
      "date": "1994"
    },
    {
      "headline": "Introduction of the Elliptic Curve Digital Signature Algorithm (ECDSA)",
      "text": "In 1999, the Elliptic Curve Digital Signature Algorithm (ECDSA) was introduced, providing a variant of the Digital Signature Algorithm (DSA) which uses elliptic curve cryptography.",
      "date": "1999"
    },
    {
      "headline": "Adoption of the EU Directive on Electronic Signatures",
      "text": "In 1999, the European Union adopted the Directive 1999/93/EC on a Community framework for electronic signatures, which aimed to facilitate the use of electronic signatures and ensure their legal recognition.",
      "date": "1999"
    },
    {
      "headline": "Introduction of the eIDAS Regulation",
      "text": "In 2014, the European Union introduced the eIDAS Regulation, which established a framework for electronic identification and trust services, including digital signatures, across EU member states.",
      "date": "2014"
    }
  ]
}

