{
  "timeline": [
    {
      "headline": "Discovery of RNA",
      "text": "In 1868, Friedrich Miescher discovered nucleic acids, which later led to the identification of RNA as a distinct molecule.",
      "date": "1868"
    },
    {
      "headline": "Identification of RNA as a distinct molecule",
      "text": "In the early 20th century, RNA was identified as a distinct molecule from DNA, with its own unique functions and properties.",
      "date": "1900"
    },
    {
      "headline": "Discovery of mRNA",
      "text": "In 1961, François Jacob and Jacques Monod discovered messenger RNA (mRNA), which plays a crucial role in conveying genetic information from DNA to the ribosome.",
      "date": "1961"
    },
    {
      "headline": "Discovery of RNA splicing",
      "text": "In 1977, Richard J. Roberts and Phillip A. Sharp independently discovered RNA splicing, a process by which introns are removed from a pre-mRNA transcript and exons are joined together.",
      "date": "1977"
    },
    {
      "headline": "Discovery of catalytic RNA",
      "text": "In 1982, Thomas Cech and Sidney Altman discovered that RNA can have catalytic properties, leading to the concept of ribozymes.",
      "date": "1982"
    },
    {
      "headline": "Discovery of RNA interference",
      "text": "In 1998, Andrew Fire and Craig Mello discovered RNA interference (RNAi), a biological process in which RNA molecules inhibit gene expression or translation.",
      "date": "1998"
    },
