{
  "timeline": [
    {
      "headline": "Discovery of Ozone Layer",
      "text": "The ozone layer was discovered in 1913 by the French physicists Charles Fabry and Henri Buisson.",
      "date": "1913"
    },
    {
      "headline": "Dobson's Ozone Measurement",
      "text": "In the 1920s, British meteorologist G.M.B. Dobson developed a simple spectrophotometer (the Dobsonmeter) to measure stratospheric ozone from the ground.",
      "date": "1920"
    },
    {
      "headline": "Chlorofluorocarbons (CFCs) Invented",
      "text": "In 1928, Thomas Midgley Jr. invented chlorofluorocarbons (CFCs), which later became a significant contributor to ozone depletion.",
      "date": "1928"
    },
    {
      "headline": "Ozone Depletion Hypothesis",
      "text": "In 1974, chemists Mario Molina and F. Sherwood Rowland published a paper in Nature suggesting that CFCs could deplete the ozone layer.",
      "date": "1974"
    },
    {
      "headline": "Antarctic Ozone Hole Discovery",
      "text": "In 1985, British Antarctic Survey scientists Joseph Farman, Brian Gardiner, and Jonathan Shanklin published findings of a large springtime decrease in stratospheric ozone over Antarctica, known as the ozone hole.",
      "date": "1985"
    },
    {
      "headline": "Montreal Protocol Signed",
      "text": "In 1987, the Montreal Protocol was signed, aiming to phase out the production of numerous substances responsible for ozone depletion.",
      "date": "1987"
    },
    {
      "headline": "Nobel Prize in Chemistry",
      "text": "In 1995, the Nobel Prize in Chemistry was awarded to Paul Crutzen, Mario Molina, and F. Sherwood Rowland for their work on atmospheric chemistry, particularly concerning the formation and decomposition of ozone.",
      "date": "1995"
    },
    {
      "headline": "Ozone Layer Recovery",
      "text": "In 2016, a study published in Science reported signs of healing in the Antarctic ozone hole, indicating the effectiveness of the Montreal Protocol.",
      "date": "2016"
    }
  ]
}

