{
  "timeline": [
    {
      "headline": "Emergence of the Seminole People",
      "text": "The Seminole people began to emerge in the early 18th century as a distinct group through a process of ethnogenesis. This process involved the amalgamation of various Native American groups, most significantly northern Muscogee Creeks, who settled in Spanish Florida.",
      "date": "1700"
    },
    {
      "headline": "First Seminole War",
      "text": "The First Seminole War occurred from 1817 to 1818. It was a conflict between the United States and the Seminole people in Florida, largely over the issue of runaway slaves and territorial expansion.",
      "date": "1817"
    },
    {
      "headline": "Second Seminole War",
      "text": "The Second Seminole War, lasting from 1835 to 1842, was the longest and most costly of the Indian Wars in the United States. It was fought over the U.S. government's attempts to forcibly relocate the Seminole people to Indian Territory (present-day Oklahoma).",
      "date": "1835"
    },
    {
      "headline": "Third Seminole War",
      "text": "The Third Seminole War took place from 1855 to 1858. It was the final conflict between the United States and the Seminole people, resulting in the further removal of Seminoles to Indian Territory.",
      "date": "1855"
    },
    {
      "headline": "Seminole Nation of Oklahoma",
      "text": "Following the forced relocations, the Seminole Nation of Oklahoma was established. It is one of the three federally recognized Seminole tribes today.",
      "date": "1850s"
    },
    {
      "headline": "Seminole Tribe of Florida",
      "text": "The Seminole Tribe of Florida was federally recognized in 1957. It is one of the three federally recognized Seminole tribes and represents those who remained in Florida.",
      "date": "1957"
    },
    {
      "headline": "Miccosukee Tribe of Indians of Florida",
      "text": "The Miccosukee Tribe of Indians of Florida gained federal recognition in 1962. It is one of the three federally recognized Seminole tribes, representing a group that split from the Seminole Tribe of Florida.",
      "date": "1962"
    }
  ]
}

