    {
      "headline": "Establishment of Wright-Patterson Air Force Base",
      "text": "Wright-Patterson Air Force Base, a major U.S. Air Force installation, was established in Dayton in 1948, playing a significant role in the city's economy and history.",
      "date": "1948"
