    },
    {
      "headline": "Publication of 'Progress and Poverty'",
      "text": "In 1879, Henry George published his most famous work, 'Progress and Poverty', which laid the foundation for the Georgist economic ideology by arguing for the public collection of rent on land.",
      "date": "1879"
    },
    {
      "headline": "Single Tax Movement Gains Popularity",
      "text": "During the 1880s, the Single Tax Movement, based on Henry George's ideas, gained significant popularity in the United States and other countries, advocating for the replacement of all taxes with a single tax on land value.",
      "date": "1880s"
    },
    {
      "headline": "Henry George's Mayoral Campaign",
      "text": "In 1886, Henry George ran for mayor of New York City as a candidate for the United Labor Party, finishing second and demonstrating the widespread appeal of his ideas.",
      "date": "1886"
    },
    {
      "headline": "Death of Henry George",
      "text": "Henry George died on October 29, 1897, in New York City, leaving behind a legacy of economic thought that continued to influence social reform movements.",
      "date": "1897-10-29"
    },
    {
      "headline": "Establishment of the Henry George Foundation",
      "text": "In 1928, the Henry George Foundation was established in the United Kingdom to promote the study and application of Georgist principles.",
      "date": "1928"
    },
    {
      "headline": "Georgist Influence on Modern Economics",
      "text": "Throughout the 20th and 21st centuries, Georgist ideas have continued to influence economic thought, particularly in discussions about land reform, taxation, and social justice.",
      "date": "1900s-2000s"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Invention of the Astrolabe",
      "text": "The astrolabe is believed to have been invented in ancient Greece around 150 BCE. It was developed as an astronomical instrument to measure the altitude of celestial bodies and solve problems related to time and the position of the stars.",
      "date": "-0150"
    },
    {
      "headline": "Development by Hipparchus",
      "text": "The Greek astronomer Hipparchus is credited with further developing the astrolabe around 150 BCE, enhancing its use for astronomical calculations.",
      "date": "-0150"
    },
    {
      "headline": "Use in the Islamic Golden Age",
      "text": "During the Islamic Golden Age (8th to 14th centuries), the astrolabe was significantly improved by Muslim astronomers. It became a crucial tool for navigation and astronomy, with scholars like Al-Farghani and Al-Sufi contributing to its development.",
      "date": "0800"
    },
    {
      "headline": "Introduction to Europe",
      "text": "The astrolabe was introduced to Europe through translations of Arabic texts in the 12th century. It became an essential instrument for European astronomers and navigators during the Middle Ages.",
      "date": "1100"
    },
    {
      "headline": "Renaissance and Age of Discovery",
      "text": "During the Renaissance and the Age of Discovery (14th to 17th centuries), the astrolabe was widely used by European explorers for navigation. It played a key role in maritime exploration and the expansion of European empires.",
      "date": "1400"
    },
    {
      "headline": "Decline in Use",
      "text": "By the 18th century, the astrolabe began to decline in use as more advanced instruments like the sextant were developed, offering greater accuracy for navigation and astronomical observations.",
      "date": "1700"
    }
  ]
}

