    {
      "headline": "Abolition of the French Republican Calendar",
      "text": "The French Republican Calendar was abolished by Napoleon Bonaparte on January 1, 1806, and the Gregorian calendar was reinstated.",
      "date": "1806-01-01"
    },
    {
      "headline": "Brief Reinstatement by the Paris Commune",
      "text": "The French Republican Calendar was briefly reinstated by the Paris Commune from May 6, 1871, to May 23, 1871.",
