    },
    {
      "headline": "Popularity of X-rated Films",
      "text": "During the late 1960s and 1970s, several films with X ratings gained popularity, including 'Midnight Cowboy' (1969), which won the Academy Award for Best Picture, and 'A Clockwork Orange' (1971), directed by Stanley Kubrick.",
      "date": "1969-1971"
    },
    {
      "headline": "NC-17 Rating Introduced",
      "text": "In 1990, the MPAA introduced the NC-17 rating to replace the X rating. The new rating was intended to distinguish adult-oriented films with artistic merit from pornographic films.",
      "date": "1990"
    },
    {
      "headline": "Decline of the X Rating",
      "text": "Following the introduction of the NC-17 rating, the X rating fell out of official use in the United States. However, it continued to be used informally to describe films with explicit content.",
      "date": "1990s"
    }
  ]
