    {
      "headline": "First Nations Settlement",
      "text": "Vancouver Island has been inhabited by various First Nations for thousands of years, including the Nuu-chah-nulth, Coast Salish, and Kwakwaka'wakw peoples.",
      "date": "-10000"
    },
    {
      "headline": "Juan de Fuca's Exploration",
      "text": "In 1592, Greek explorer Juan de Fuca, sailing for Spain, claimed to have explored the strait that now bears his name, between Vancouver Island and the Olympic Peninsula.",
      "date": "1592"
    },
    {
      "headline": "James Cook's Visit",
      "text": "In 1778, British explorer Captain James Cook visited Nootka Sound on the west coast of Vancouver Island, marking the first known European contact.",
      "date": "1778"
    },
    {
      "headline": "Nootka Crisis",
      "text": "From 1789 to 1794, the Nootka Crisis occurred, a series of disputes between Spain and Britain over territories on the Pacific Northwest coast, including Vancouver Island.",
      "date": "1789"
    },
    {
      "headline": "George Vancouver's Expedition",
      "text": "In 1792, British naval officer George Vancouver explored and mapped the Pacific Northwest, including the island that would later bear his name.",
      "date": "1792"
    },
    {
      "headline": "Hudson's Bay Company Establishment",
      "text": "In 1843, the Hudson's Bay Company established Fort Victoria on Vancouver Island, which later became the capital of the colony of Vancouver Island.",
      "date": "1843"
    },
    {
      "headline": "Colony of Vancouver Island",
      "text": "In 1849, the Colony of Vancouver Island was established by the British government, with Victoria as its capital.",
      "date": "1849"
    },
    {
      "headline": "Union with British Columbia",
      "text": "In 1866, the Colony of Vancouver Island was merged with the Colony of British Columbia, forming a single colony.",
      "date": "1866"
    },
    {
      "headline": "Confederation with Canada",
      "text": "In 1871, British Columbia, including Vancouver Island, joined the Canadian Confederation as the sixth province.",
      "date": "1871"
    },
    {
      "headline": "Completion of the E&N Railway",
      "text": "In 1886, the Esquimalt and Nanaimo Railway was completed, connecting Victoria to Nanaimo and facilitating economic growth on Vancouver Island.",
      "date": "1886"
    }
  ]
}

