{
  "timeline": [
    {
      "headline": "Introduction of the Taft–Hartley Act",
      "text": "The Taft–Hartley Act, officially known as the Labor Management Relations Act, 1947, was introduced in the United States Congress as a response to the growing power of labor unions post-World War II.",
      "date": "1947"
    },
    {
      "headline": "Passage by Congress",
      "text": "The 80th United States Congress passed the Taft–Hartley Act, aiming to amend the National Labor Relations Act of 1935 and to impose certain restrictions on labor unions.",
      "date": "1947"
    },
    {
      "headline": "Presidential Veto",
      "text": "President Harry S. Truman vetoed the Taft–Hartley Act, expressing concerns that it would harm labor rights and was a dangerous intrusion into free speech.",
      "date": "1947"
    },
    {
      "headline": "Congress Overrides Veto",
      "text": "On June 23, 1947, Congress overrode President Truman's veto, and the Taft–Hartley Act became law. This marked a significant shift in U.S. labor policy, restricting union activities and introducing new regulations.",
      "date": "1947-06-23"
    },
    {
      "headline": "Impact on Labor Unions",
      "text": "The Taft–Hartley Act imposed several restrictions on labor unions, including prohibiting jurisdictional strikes, secondary boycotts, and closed shops, and required union leaders to sign affidavits affirming they were not communists.",
      "date": "1947"
    },
    {
      "headline": "Long-term Effects",
      "text": "The Taft–Hartley Act had long-term effects on labor relations in the United States, leading to a decline in union power and membership over the subsequent decades.",
      "date": "1947"
    }
  ]
}

