{
  "timeline": [
    {
      "headline": "Start of the Eighteenth Dynasty",
      "text": "The Eighteenth Dynasty of Egypt marks the beginning of the New Kingdom period, during which the Valley of the Kings began to be used as a royal burial site. This period started around 1550 BCE.",
      "date": "-1550"
    },
    {
      "headline": "First Royal Tombs",
      "text": "The first royal tombs were constructed in the Valley of the Kings during the reign of Thutmose I, who ruled from 1506 to 1493 BCE. His tomb is one of the earliest known in the valley.",
      "date": "-1506"
    },
    {
      "headline": "Reign of Hatshepsut",
      "text": "Hatshepsut, one of the few female pharaohs, ruled from 1479 to 1458 BCE. Her mortuary temple, Djeser-Djeseru, is located near the Valley of the Kings.",
      "date": "-1479"
    },
    {
      "headline": "Reign of Tutankhamun",
      "text": "Tutankhamun, one of the most famous pharaohs, ruled from 1332 to 1323 BCE. His tomb (KV62) was discovered largely intact in 1922, providing significant archaeological insights.",
      "date": "-1332"
    },
    {
      "headline": "End of the Twentieth Dynasty",
      "text": "The Twentieth Dynasty ended around 1077 BCE, marking the conclusion of the New Kingdom period and the primary use of the Valley of the Kings for royal burials.",
      "date": "-1077"
    },
    {
      "headline": "Discovery of Tutankhamun's Tomb",
      "text": "In 1922, British archaeologist Howard Carter discovered the tomb of Tutankhamun (KV62), which was largely intact and became one of the most significant archaeological finds of the 20th century.",
      "date": "1922"
    }
  ]
}

