    {
      "headline": "Death of Richard III",
      "text": "Richard III, the last king of the House of York, was killed during the Battle of Bosworth Field on 22 August 1485. He was the last English monarch to die in battle.",
      "date": "1485-08-22"
    },
    {
      "headline": "Henry Tudor Becomes King",
      "text": "Following his victory at the Battle of Bosworth Field, Henry Tudor became King Henry VII of England, marking the beginning of the Tudor dynasty.",
      "date": "1485-08-22"
    },
    {
      "headline": "End of the Plantagenet Dynasty",
      "text": "The Battle of Bosworth Field is considered by historians to mark the end of the Plantagenet dynasty, making it a defining moment in English history.",
      "date": "1485-08-22"
    },
