{
  "timeline": [
    {
      "headline": "Commissioning of the Pentagon Papers",
      "text": "In 1967, Secretary of Defense Robert McNamara commissioned a comprehensive study of the United States' political and military involvement in Vietnam from 1945 to 1967. This study would later become known as the Pentagon Papers.",
      "date": "1967"
    },
    {
      "headline": "Completion of the Pentagon Papers",
      "text": "The Pentagon Papers were completed in 1969. The study consisted of 47 volumes, totaling about 7,000 pages of historical analysis and original government documents.",
      "date": "1969"
    },
    {
      "headline": "Leak of the Pentagon Papers",
      "text": "In March 1971, Daniel Ellsberg, a former military analyst who had worked on the study, began secretly making photocopies of the Pentagon Papers with the intention of making them public.",
      "date": "1971-03"
    },
    {
      "headline": "Publication by The New York Times",
      "text": "On June 13, 1971, The New York Times began publishing a series of articles based on the Pentagon Papers, revealing that the U.S. government had misled the public and Congress about the Vietnam War.",
      "date": "1971-06-13"
    },
    {
      "headline": "U.S. Government's Legal Action",
      "text": "On June 15, 1971, the U.S. government obtained a temporary restraining order against The New York Times, halting further publication of the Pentagon Papers. This led to a legal battle over freedom of the press.",
      "date": "1971-06-15"
    },
    {
      "headline": "Supreme Court Ruling",
      "text": "On June 30, 1971, the U.S. Supreme Court ruled in a 6-3 decision that the government had not met the heavy burden of proof required for prior restraint, allowing The New York Times and The Washington Post to resume publishing the Pentagon Papers.",
      "date": "1971-06-30"
    },
    {
      "headline": "Full Release of the Pentagon Papers",
      "text": "In 2011, the National Archives and Records Administration released the full text of the Pentagon Papers to the public, marking the 40th anniversary of their initial publication.",
      "date": "2011"
    }
  ]
}

