    {
      "headline": "Outbreak of the First Balkan War",
      "text": "The First Balkan War began in October 1912 when the Balkan League, consisting of Serbia, Montenegro, Greece, and Bulgaria, declared war on the Ottoman Empire.",
      "date": "1912-10"
    },
    {
      "headline": "Battle of Kumanovo",
      "text": "The Battle of Kumanovo took place from October 23 to October 24, 1912, resulting in a decisive victory for the Serbian army against the Ottoman forces.",
      "date": "1912-10-23"
    },
    {
      "headline": "Montenegro Declares War",
      "text": "Montenegro was the first Balkan League member to declare war on the Ottoman Empire on October 8, 1912.",
      "date": "1912-10-08"
    },
    {
      "headline": "Battle of Lule Burgas",
      "text": "The Battle of Lule Burgas occurred from October 28 to November 2, 1912, where Bulgarian forces defeated the Ottomans, marking one of the largest battles of the war.",
      "date": "1912-10-28"
    },
    {
      "headline": "Battle of Monastir",
      "text": "The Battle of Monastir took place from November 16 to November 19, 1912, resulting in a Serbian victory and the capture of the city of Monastir (Bitola).",
      "date": "1912-11-16"
    },
    {
      "headline": "Armistice Signed",
      "text": "An armistice was signed on December 3, 1912, temporarily halting hostilities between the Balkan League and the Ottoman Empire.",
      "date": "1912-12-03"
    },
    {
      "headline": "Resumption of Hostilities",
      "text": "Hostilities resumed on February 3, 1913, after peace negotiations failed.",
      "date": "1913-02-03"
    },
    {
      "headline": "Battle of Bizani",
      "text": "The Battle of Bizani took place from March 4 to March 6, 1913, where Greek forces captured the strategic fortress of Bizani, leading to the fall of Ioannina.",
      "date": "1913-03-04"
    },
    {
      "headline": "Siege of Adrianople",
      "text": "The Siege of Adrianople ended on March 26, 1913, with Bulgarian and Serbian forces capturing the city, a significant victory for the Balkan League.",
      "date": "1913-03-26"
    },
    {
      "headline": "Treaty of London",
      "text": "The Treaty of London was signed on May 30, 1913, officially ending the First Balkan War. The treaty resulted in significant territorial losses for the Ottoman Empire.",
      "date": "1913-05-30"
    }
  ]
}

