{
  "timeline": [
    {
      "headline": "Invention of the Polygraph",
      "text": "In 1921, John Augustus Larson, a medical student at the University of California, Berkeley, and a police officer of the Berkeley Police Department, invented the modern polygraph. Larson's device was the first to continuously and simultaneously measure pulse rate, blood pressure, and respiratory changes during questioning.",
      "date": "1921"
    },
    {
      "headline": "Development of the Polygraph Technique",
      "text": "In 1939, Leonarde Keeler, a student of John Larson, further developed the polygraph technique by adding a galvanic skin response measurement to the device, which measures the electrical conductance of the skin.",
      "date": "1939"
    },
    {
      "headline": "Polygraph in Criminal Investigations",
      "text": "Throughout the mid-20th century, the polygraph became widely used in criminal investigations in the United States, despite ongoing debates about its accuracy and reliability.",
      "date": "1950"
    },
    {
      "headline": "Polygraph and the CIA",
      "text": "In the 1960s, the Central Intelligence Agency (CIA) began using polygraph tests as part of its security clearance process, a practice that continues to some extent today.",
      "date": "1960"
    },
    {
      "headline": "Legal Challenges and Limitations",
      "text": "In 1988, the Employee Polygraph Protection Act was passed in the United States, prohibiting most private employers from using polygraph tests for pre-employment screening or during the course of employment, reflecting skepticism about the test's reliability.",
      "date": "1988"
    },
    {
      "headline": "Scientific Criticism and Controversy",
      "text": "By the late 20th and early 21st centuries, the scientific community largely criticized the polygraph as a pseudoscientific tool, with studies indicating that it is not a reliable method for detecting deception.",
      "date": "2000"
    }
  ]
}

