{
  "timeline": [
    {
      "headline": "Beginning of Spanish Rule",
      "text": "In 1556, the Spanish Netherlands came under the rule of the Spanish branch of the Habsburgs when Charles V abdicated and divided his empire, giving the Spanish territories to his son, Philip II of Spain.",
      "date": "1556"
    },
    {
      "headline": "Outbreak of the Eighty Years' War",
      "text": "The Eighty Years' War began in 1568 as a revolt of the Seventeen Provinces against the political and religious hegemony of Philip II of Spain.",
      "date": "1568"
    },
    {
      "headline": "Union of Arras",
      "text": "On January 6, 1579, the Union of Arras was signed by the southern provinces of the Netherlands, which pledged loyalty to the Spanish Crown.",
      "date": "1579-01-06"
    },
    {
      "headline": "Union of Utrecht",
      "text": "On January 23, 1579, the Union of Utrecht was signed by the northern provinces, which later led to the formation of the Dutch Republic, effectively splitting the Netherlands.",
      "date": "1579-01-23"
    },
    {
      "headline": "Fall of Antwerp",
      "text": "In 1585, the city of Antwerp fell to Spanish forces, marking a significant victory for Spain during the Eighty Years' War.",
      "date": "1585"
    },
    {
      "headline": "Twelve Years' Truce",
      "text": "The Twelve Years' Truce was signed in 1609, temporarily halting hostilities between Spain and the Dutch Republic.",
      "date": "1609"
    },
    {
      "headline": "End of the Eighty Years' War",
      "text": "The Eighty Years' War ended in 1648 with the Treaty of Westphalia, which recognized the independence of the Dutch Republic.",
      "date": "1648"
    },
    {
      "headline": "War of the Spanish Succession",
      "text": "The War of the Spanish Succession began in 1701, involving a struggle for control of the Spanish throne and territories, including the Spanish Netherlands.",
      "date": "1701"
    },
    {
      "headline": "Treaty of Utrecht",
      "text": "In 1713, the Treaty of Utrecht was signed, ending the War of the Spanish Succession and ceding the Spanish Netherlands to the Austrian Habsburgs.",
      "date": "1713"
    },
    {
      "headline": "End of Spanish Rule",
      "text": "In 1714, the Spanish Netherlands officially became part of the Austrian Netherlands following the Treaty of Rastatt, marking the end of Spanish rule.",
      "date": "1714"
    }
  ]
}

