      "headline": "Ottoman Empire Control",
      "text": "Jerusalem was under the control of the Ottoman Empire, which established the 'Status Quo' regarding religious sites, a policy that continues to influence the city's religious environment.",
      "date": "-1517"
    },
    {
      "headline": "British Mandate of Palestine",
      "text": "Following World War I, the British Mandate of Palestine was established, with Jerusalem as its administrative center. This period saw increased tensions between Jewish and Arab communities.",
      "date": "1920"
    },
    {
      "headline": "United Nations Partition Plan",
      "text": "The United Nations proposed a partition plan for Palestine, recommending Jerusalem be established as a corpus separatum under international administration due to its religious significance.",
      "date": "1947"
    },
    {
      "headline": "1948 Arab-Israeli War",
      "text": "Following the declaration of the State of Israel, the 1948 Arab-Israeli War broke out. Jerusalem was divided, with West Jerusalem controlled by Israel and East Jerusalem, including the Old City, controlled by Jordan.",
      "date": "1948"
    },
    {
      "headline": "Jordanian Annexation of East Jerusalem",
      "text": "Jordan formally annexed East Jerusalem and the West Bank, a move recognized only by a few countries.",
      "date": "1950"
    },
    {
      "headline": "Six-Day War and Israeli Occupation",
      "text": "During the Six-Day War, Israel captured East Jerusalem from Jordan and subsequently annexed it, a move not recognized internationally.",
      "date": "1967"
    },
    {
      "headline": "Jerusalem Law",
      "text": "The Israeli Knesset passed the Jerusalem Law, declaring Jerusalem the 'complete and united' capital of Israel, which led to international criticism and a United Nations Security Council resolution condemning the action.",
      "date": "1980"
    },
    {
      "headline": "Oslo Accords",
      "text": "The Oslo Accords were signed, marking the first face-to-face agreement between the government of Israel and the Palestine Liberation Organization (PLO). The status of Jerusalem was left to be decided in future negotiations.",
      "date": "1993"
    },
    {
      "headline": "Camp David Summit",
      "text": "The Camp David Summit was held, where discussions included the status of Jerusalem, but the summit ended without an agreement.",
      "date": "2000"
    },
    {
      "headline": "United States Recognition of Jerusalem as Israel's Capital",
      "text": "The United States officially recognized Jerusalem as the capital of Israel and announced plans to move its embassy there, sparking international controversy and Palestinian protests.",
      "date": "2017-12-06"
    }
  ]
}

