      "headline": "Beginning of the Paleogene Period",
      "text": "The Paleogene Period began approximately 66 million years ago, marking the end of the Cretaceous Period and the start of the Cenozoic Era.",
      "date": "-66000000"
    },
    {
      "headline": "Paleocene Epoch",
      "text": "The Paleocene Epoch is the first epoch of the Paleogene Period, spanning from about 66 million to 56 million years ago. It followed the mass extinction event that ended the Cretaceous Period, leading to the rise of mammals.",
      "date": "-66000000"
    },
    {
      "headline": "Eocene Epoch",
      "text": "The Eocene Epoch followed the Paleocene, lasting from about 56 million to 33.9 million years ago. This epoch saw the emergence of early forms of many modern mammals and the development of the first large mammals.",
      "date": "-56000000"
    },
    {
      "headline": "Oligocene Epoch",
      "text": "The Oligocene Epoch is the final epoch of the Paleogene Period, lasting from about 33.9 million to 23.03 million years ago. It was characterized by the further evolution of mammals and the formation of modern ecosystems.",
      "date": "-33900000"
    },
    {
      "headline": "End of the Paleogene Period",
      "text": "The Paleogene Period ended approximately 23.03 million years ago, transitioning into the Neogene Period.",
      "date": "-23030000"
    }
  ]
}

