{
  "timeline": [
    {
      "headline": "Introduction of Relational Model",
      "text": "In 1970, Edgar F. Codd, a British computer scientist, introduced the relational model for database management, which laid the foundation for database normalization.",
      "date": "1970"
    },
    {
      "headline": "First Normal Form (1NF)",
      "text": "The concept of the First Normal Form (1NF) was introduced as part of Codd's relational model, requiring that the values in a database table be atomic.",
      "date": "1970"
    },
    {
      "headline": "Second Normal Form (2NF)",
      "text": "Second Normal Form (2NF) was defined to eliminate partial dependency of any column on the primary key, ensuring that all non-key attributes are fully functionally dependent on the primary key.",
      "date": "1971"
    },
    {
      "headline": "Third Normal Form (3NF)",
      "text": "Third Normal Form (3NF) was introduced to eliminate transitive dependency, ensuring that non-key attributes are not dependent on other non-key attributes.",
      "date": "1971"
    },
    {
      "headline": "Boyce-Codd Normal Form (BCNF)",
      "text": "Boyce-Codd Normal Form (BCNF) was developed to address certain types of anomalies not covered by 3NF, refining the normalization process further.",
      "date": "1974"
    },
    {
      "headline": "Fourth Normal Form (4NF)",
      "text": "Fourth Normal Form (4NF) was introduced to handle multi-valued dependencies, ensuring that a table is free of such dependencies.",
      "date": "1977"
    },
    {
      "headline": "Fifth Normal Form (5NF)",
      "text": "Fifth Normal Form (5NF), also known as Project-Join Normal Form (PJNF), was defined to deal with join dependencies, ensuring that a table can be reconstructed from its projections.",
      "date": "1981"
    },
    {
      "headline": "Sixth Normal Form (6NF)",
      "text": "Sixth Normal Form (6NF) was introduced to handle temporal databases, focusing on the decomposition of tables to eliminate redundancy in temporal data.",
      "date": "2002"
    }
  ]
}

{
