      "headline": "Skylab 2 Mission Ends",
      "text": "The Skylab 2 mission concluded on June 22, 1973, after 28 days in space.",
      "date": "1973-06-22"
    },
    {
      "headline": "Skylab 3 Mission Begins",
      "text": "The second crewed mission, Skylab 3, was launched on July 28, 1973. The crew conducted scientific experiments and solar observations.",
      "date": "1973-07-28"
    },
    {
      "headline": "Skylab 3 Mission Ends",
      "text": "The Skylab 3 mission ended on September 25, 1973, after 59 days in space.",
      "date": "1973-09-25"
    },
    {
      "headline": "Skylab 4 Mission Begins",
      "text": "The third and final crewed mission, Skylab 4, was launched on November 16, 1973. The crew conducted extensive scientific research and Earth observations.",
      "date": "1973-11-16"
    },
    {
      "headline": "Skylab 4 Mission Ends",
      "text": "The Skylab 4 mission concluded on February 8, 1974, after 84 days in space, marking the end of crewed operations on Skylab.",
      "date": "1974-02-08"
    },
    {
      "headline": "Skylab Re-enters Earth's Atmosphere",
      "text": "Skylab's orbit decayed, and it re-entered Earth's atmosphere on July 11, 1979. It disintegrated, scattering debris across the Indian Ocean and Western Australia.",
