    {
      "headline": "Formation of the Socialist Party of America",
      "text": "The Socialist Party of America (SPA) was formed in 1901 by a merger between the three-year-old Social Democratic Party of America and disaffected elements of the Socialist Labor Party of America who had split from the main organization in 1899.",
      "date": "1901"
    },
    {
      "headline": "Eugene V. Debs Runs for President",
      "text": "Eugene V. Debs, a prominent leader of the Socialist Party of America, ran for President of the United States in 1904, marking the party's first significant national campaign.",
      "date": "1904"
    },
    {
      "headline": "Peak Membership",
      "text": "The Socialist Party of America reached its peak membership in 1912, with over 118,000 members, reflecting its growing influence in American politics.",
      "date": "1912"
    },
    {
      "headline": "Eugene V. Debs' Most Successful Presidential Campaign",
      "text": "In the 1912 presidential election, Eugene V. Debs received 6% of the popular vote, the highest percentage ever achieved by a Socialist Party candidate in the United States.",
      "date": "1912"
    },
    {
      "headline": "Opposition to World War I",
      "text": "The Socialist Party of America strongly opposed the United States' involvement in World War I, leading to internal divisions and government repression.",
      "date": "1917"
    },
    {
      "headline": "Split and Formation of the Communist Party",
      "text": "In 1919, a significant faction of the Socialist Party split to form the Communist Party of America, following ideological differences over the Russian Revolution and the direction of the socialist movement in the U.S.",
      "date": "1919"
    },
    {
      "headline": "Decline in Influence",
      "text": "Throughout the 1920s and 1930s, the Socialist Party of America experienced a decline in influence, as internal divisions and competition with the Communist Party affected its membership and electoral success.",
      "date": "1920"
    },
    {
      "headline": "Norman Thomas' Presidential Campaigns",
      "text": "Norman Thomas, a leading figure in the Socialist Party, ran for President six times between 1928 and 1948, becoming the party's most prominent spokesperson during this period.",
      "date": "1928"
    },
    {
      "headline": "Merger and Transformation",
      "text": "In 1972, the Socialist Party of America merged with the Democratic Socialist Federation to form the Social Democrats, USA, marking the end of the SPA as a distinct political entity.",
      "date": "1972"
    }
  ]
}

