    },
    {
      "headline": "Battle of Kannauj",
      "text": "On May 17, 1540, Sher Shah Suri defeated Humayun again at the Battle of Kannauj, leading to the establishment of the Sur Empire.",
      "date": "1540-05-17"
    },
    {
      "headline": "Reforms and Innovations",
      "text": "During his reign from 1540 to 1545, Sher Shah Suri implemented several administrative reforms, including the introduction of the Rupiya (currency) and improvements in the postal system and road infrastructure.",
      "date": "1540"
    },
    {
      "headline": "Death of Sher Shah Suri",
      "text": "Sher Shah Suri died on May 22, 1545, during the siege of Kalinjar in present-day Uttar Pradesh, India.",
      "date": "1545-05-22"
    }
  ]
}

