{
  "timeline": [
    {
      "headline": "Beginning of the Years of Lead",
      "text": "The Years of Lead in Italy began in the late 1960s, marked by increasing political violence and social upheaval.",
      "date": "1968"
    },
    {
      "headline": "Piazza Fontana Bombing",
      "text": "On December 12, 1969, a bomb exploded at the Banca Nazionale dell'Agricoltura in Piazza Fontana, Milan, killing 17 people and injuring 88. This event is often considered the start of the Years of Lead.",
      "date": "1969-12-12"
    },
    {
      "headline": "Formation of the Red Brigades",
      "text": "The Red Brigades, a far-left terrorist organization, was formed in 1970. They became one of the most notorious groups during the Years of Lead.",
      "date": "1970"
    },
    {
      "headline": "Peteano Attack",
      "text": "On May 31, 1972, a car bomb exploded in Peteano, killing three Carabinieri officers. This attack was initially blamed on the Red Brigades but was later attributed to the far-right group Ordine Nuovo.",
      "date": "1972-05-31"
    },
    {
      "headline": "Murder of Aldo Moro",
      "text": "On March 16, 1978, former Prime Minister Aldo Moro was kidnapped by the Red Brigades. He was murdered on May 9, 1978, after 55 days in captivity.",
      "date": "1978-03-16"
    },
    {
      "headline": "Bologna Massacre",
      "text": "On August 2, 1980, a bomb exploded at the Bologna Central Station, killing 85 people and injuring over 200. It was one of the deadliest attacks during the Years of Lead.",
      "date": "1980-08-02"
    },
    {
      "headline": "End of the Years of Lead",
      "text": "The period of the Years of Lead is generally considered to have ended in the late 1980s, as political violence in Italy began to decrease.",
      "date": "1988"
    }
  ]
}

