    },
    {
      "headline": "Revolution of 1848",
      "text": "In 1848, the Kingdom of the Two Sicilies experienced a revolution as part of the wider series of European revolutions. King Ferdinand II initially granted a constitution but later rescinded it, leading to further unrest.",
      "date": "1848"
    },
    {
      "headline": "Reign of Francis II",
      "text": "Francis II ascended to the throne in 1859 following the death of his father, Ferdinand II. He was the last king of the Kingdom of the Two Sicilies.",
      "date": "1859"
    },
    {
      "headline": "Expedition of the Thousand",
      "text": "In 1860, Giuseppe Garibaldi led the Expedition of the Thousand, a campaign that resulted in the conquest of the Kingdom of the Two Sicilies as part of the unification of Italy.",
      "date": "1860"
    },
    {
      "headline": "Annexation to the Kingdom of Italy",
      "text": "The Kingdom of the Two Sicilies was officially annexed to the Kingdom of Italy on March 17, 1861, marking the end of its existence as a separate entity.",
      "date": "1861-03-17"
    }
  ]
}

