    {
      "headline": "Collaboration with Giorgione",
      "text": "In 1508, Titian collaborated with Giorgione on frescoes for the Fondaco dei Tedeschi in Venice.",
      "date": "1508"
    },
    {
      "headline": "Completion of 'Assumption of the Virgin'",
      "text": "In 1518, Titian completed the 'Assumption of the Virgin', a large altarpiece for the Basilica di Santa Maria Gloriosa dei Frari in Venice.",
      "date": "1518"
    },
    {
      "headline": "Appointment as official painter to the Republic of Venice",
      "text": "In 1516, Titian was appointed as the official painter to the Republic of Venice, succeeding Giovanni Bellini.",
      "date": "1516"
    },
    {
      "headline": "Creation of 'Bacchus and Ariadne'",
      "text": "In 1523, Titian completed 'Bacchus and Ariadne', one of his most famous mythological paintings.",
      "date": "1523"
    },
    {
      "headline": "Completion of 'Venus of Urbino'",
      "text": "In 1538, Titian completed the 'Venus of Urbino', a masterpiece of the Italian Renaissance.",
      "date": "1538"
    },
    {
      "headline": "Titian's work for Emperor Charles V",
      "text": "In 1533, Titian was invited to Bologna to paint a portrait of Emperor Charles V, marking the beginning of his work for the Habsburg court.",
      "date": "1533"
    },
    {
      "headline": "Creation of 'Diana and Actaeon'",
      "text": "Between 1556 and 1559, Titian painted 'Diana and Actaeon', one of his famous mythological works.",
      "date": "1556"
    },
    {
      "headline": "Completion of 'Pietà'",
      "text": "Titian worked on the 'Pietà', intended for his own tomb, until his death in 1576. It was completed by Palma il Giovane.",
      "date": "1576"
    },
    {
      "headline": "Death of Titian",
      "text": "Titian died on August 27, 1576, in Venice, Italy, during a plague outbreak.",
      "date": "1576-08-27"
    }
  ]
}

