{
  "timeline": [
    {
      "headline": "Pope Innocent III Initiates the Crusade",
      "text": "In 1209, Pope Innocent III called for a crusade to eliminate the Cathar heresy in the Languedoc region of southern France.",
      "date": "1209"
    },
    {
      "headline": "Massacre at Béziers",
      "text": "On July 22, 1209, the crusaders captured the city of Béziers. The entire population, including Catholics and Cathars, was massacred.",
      "date": "1209-07-22"
    },
    {
      "headline": "Siege of Carcassonne",
      "text": "In August 1209, the crusaders laid siege to Carcassonne. The city surrendered, and its inhabitants were expelled.",
      "date": "1209-08"
    },
    {
      "headline": "Simon de Montfort Appointed Leader",
      "text": "In 1209, Simon de Montfort was appointed as the leader of the crusader forces, taking control of the campaign against the Cathars.",
      "date": "1209"
    },
    {
      "headline": "Battle of Muret",
      "text": "On September 12, 1213, the Battle of Muret took place. Simon de Montfort's forces defeated the army of Peter II of Aragon, a supporter of the Cathars.",
      "date": "1213-09-12"
    },
    {
      "headline": "Fourth Lateran Council",
      "text": "In 1215, the Fourth Lateran Council was held, which endorsed the crusade and confirmed Simon de Montfort's control over the conquered territories.",
      "date": "1215"
    },
    {
      "headline": "Death of Simon de Montfort",
      "text": "Simon de Montfort was killed on June 25, 1218, during the siege of Toulouse.",
      "date": "1218-06-25"
    },
    {
      "headline": "Treaty of Paris",
      "text": "On April 12, 1229, the Treaty of Paris was signed, effectively ending the Albigensian Crusade. The treaty resulted in the annexation of the County of Toulouse to the French crown.",
      "date": "1229-04-12"
    }
  ]
}

