      "text": "Thebes is traditionally said to have been founded by Cadmus, a Phoenician prince, around the 14th century BCE.",
      "date": "-1400"
    },
    {
      "headline": "Mycenaean Period",
      "text": "Thebes was a major center during the Mycenaean period, with evidence of significant settlement and fortifications.",
      "date": "-1400"
    },
    {
      "headline": "Theban Hegemony",
      "text": "Thebes rose to prominence in the 4th century BCE, particularly under the leadership of Epaminondas, who led Thebes to victory over Sparta at the Battle of Leuctra in 371 BCE.",
      "date": "-0371"
    },
    {
      "headline": "Battle of Leuctra",
      "text": "On July 6, 371 BCE, Thebes defeated Sparta at the Battle of Leuctra, establishing Theban hegemony in Greece.",
      "date": "-0371-07-06"
    },
    {
      "headline": "Battle of Chaeronea",
      "text": "In 338 BCE, Thebes was defeated by Philip II of Macedon at the Battle of Chaeronea, leading to the decline of Theban power.",
      "date": "-0338"
    },
    {
      "headline": "Destruction by Alexander the Great",
      "text": "In 335 BCE, Thebes was destroyed by Alexander the Great as punishment for revolting against Macedonian rule.",
      "date": "-0335"
    },
    {
      "headline": "Rebuilding of Thebes",
      "text": "Thebes was rebuilt by Cassander, a successor of Alexander the Great, in 316 BCE.",
      "date": "-0316"
    },
    {
      "headline": "Roman Period",
      "text": "Thebes became part of the Roman Empire in 146 BCE, following the Roman conquest of Greece.",
      "date": "-0146"
    },
    {
      "headline": "Byzantine Period",
      "text": "During the Byzantine period, Thebes was an important center of silk production and trade.",
      "date": "0500"
    },
    {
      "headline": "Frankish Rule",
      "text": "Thebes came under Frankish rule after the Fourth Crusade in 1204, becoming part of the Duchy of Athens.",
      "date": "1204"
    },
    {
      "headline": "Ottoman Conquest",
      "text": "Thebes was conquered by the Ottoman Empire in 1460, remaining under Ottoman control until the Greek War of Independence.",
      "date": "1460"
    },
    {
      "headline": "Greek War of Independence",
      "text": "Thebes became part of the modern Greek state following the Greek War of Independence in the early 19th century.",
      "date": "1829"
    }
  ]
}

