{
  "timeline": [
    {
      "headline": "Finalization of the Joint Comprehensive Plan of Action",
      "text": "The Joint Comprehensive Plan of Action (JCPOA), also known as the Iran nuclear deal, was finalized in Vienna on 14 July 2015. The agreement was reached between Iran and the P5+1 (the five permanent members of the United Nations Security Council—China, France, Russia, United Kingdom, United States—plus Germany) together with the European Union.",
      "date": "2015-07-14"
    },
    {
      "headline": "Implementation Day",
      "text": "On 16 January 2016, known as Implementation Day, the International Atomic Energy Agency (IAEA) verified that Iran had implemented its nuclear-related commitments under the JCPOA. As a result, the United Nations, European Union, and United States lifted nuclear-related sanctions on Iran.",
      "date": "2016-01-16"
    },
    {
      "headline": "United States Withdrawal from the JCPOA",
      "text": "On 8 May 2018, U.S. President Donald Trump announced that the United States would withdraw from the JCPOA and reinstate nuclear sanctions on Iran. This decision was met with criticism from other signatories of the agreement.",
      "date": "2018-05-08"
    },
    {
      "headline": "Iran Begins Reducing Compliance",
      "text": "In May 2019, Iran announced it would begin reducing its compliance with the JCPOA in response to the U.S. withdrawal and the re-imposition of sanctions. This marked the beginning of a series of steps by Iran to scale back its commitments under the deal.",
      "date": "2019-05"
    },
    {
      "headline": "Resumption of Negotiations",
      "text": "In April 2021, negotiations to restore the JCPOA began in Vienna, involving the remaining signatories and indirect participation by the United States. The talks aimed to bring the U.S. back into the agreement and ensure Iran's compliance with its nuclear commitments.",
      "date": "2021-04"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Ancient City of Ujjain",
      "text": "Ujjain, historically known as Ujjayinī, was one of the most prominent cities in ancient India, serving as a major trade and political center during the time of the Mahājanapadas.",
      "date": "-0600"
    },
    {
      "headline": "Capital of Avanti",
      "text": "Ujjain became the capital of the ancient kingdom of Avanti, one of the sixteen Mahājanapadas, around the 6th century BCE.",
      "date": "-0600"
    },
    {
      "headline": "Mauryan Empire",
      "text": "During the Mauryan Empire (322–185 BCE), Ujjain was an important city and served as the administrative headquarters of the western provinces.",
      "date": "-0322"
    },
    {
      "headline": "Gupta Empire",
      "text": "Under the Gupta Empire (circa 320–550 CE), Ujjain continued to flourish as a center of learning and culture.",
      "date": "0320"
    },
    {
      "headline": "Vikramaditya's Reign",
      "text": "Ujjain is traditionally associated with the legendary king Vikramaditya, who is said to have ruled around the 1st century BCE and established the Vikrama Samvat calendar.",
      "date": "-0057"
    },
    {
      "headline": "Chandragupta II's Rule",
      "text": "Chandragupta II, also known as Vikramaditya, ruled from Ujjain during the Gupta Empire, further enhancing its status as a cultural and political hub.",
      "date": "0380"
    },
    {
      "headline": "Paramara Dynasty",
      "text": "In the 9th and 10th centuries, Ujjain was ruled by the Paramara dynasty, which contributed to the city's architectural and cultural development.",
      "date": "0900"
    },
    {
      "headline": "Invasion by Iltutmish",
      "text": "In 1235, Ujjain was invaded by Iltutmish, the Sultan of Delhi, which led to significant destruction in the city.",
      "date": "1235"
    },
    {
      "headline": "Maratha Rule",
      "text": "In the 18th century, Ujjain became part of the Maratha Empire, under the rule of the Scindia dynasty.",
      "date": "1750"
    },
    {
      "headline": "British Colonization",
      "text": "During the British colonization of India, Ujjain was incorporated into the Central India Agency.",
      "date": "1818"
    },
    {
      "headline": "Post-Independence",
      "text": "After India's independence in 1947, Ujjain became part of the newly formed state of Madhya Pradesh.",
      "date": "1947"
    },
    {
      "headline": "Kumbh Mela (Simhastha)",
      "text": "Ujjain is famous for hosting the Kumbh Mela, known as Simhastha, every 12 years, attracting millions of Hindu pilgrims.",
      "date": "2022"
    }
  ]
}

