    {
      "headline": "Construction on the Site",
      "text": "In the late 1950s, construction of homes and a school began on the Love Canal site, despite warnings about the buried chemical waste.",
      "date": "1950"
    },
    {
      "headline": "Discovery of Environmental Disaster",
      "text": "In 1977, residents of Love Canal began to notice health problems and chemical odors, leading to the discovery of the environmental disaster.",
      "date": "1977"
    },
    {
      "headline": "State of Emergency Declared",
      "text": "In August 1978, President Jimmy Carter declared a federal emergency at Love Canal, leading to the evacuation of over 800 families.",
      "date": "1978-08"
    },
    {
      "headline": "Superfund Law Enacted",
      "text": "In 1980, the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA), commonly known as Superfund, was enacted partly in response to the Love Canal disaster.",
      "date": "1980"
    },
    {
      "headline": "Cleanup Efforts Begin",
      "text": "In the early 1980s, cleanup efforts began at Love Canal under the newly established Superfund program.",
      "date": "1980"
    },
    {
      "headline": "Completion of Cleanup",
      "text": "In 2004, the Environmental Protection Agency declared the cleanup of Love Canal complete, after 21 years of remediation efforts.",
      "date": "2004"
    }
  ]
}

