{
  "timeline": [
    {
      "headline": "First Known Taxation in Ancient Egypt",
      "text": "The first known system of taxation was implemented in Ancient Egypt around 3000–2800 BC. This system required citizens to pay taxes in the form of labor or produce.",
      "date": "-3000"
    },
    {
      "headline": "Taxation in Ancient Greece",
      "text": "In Ancient Greece, taxes were imposed on citizens and metics (foreigners living in the city) to fund public services and military campaigns. These taxes were often levied on property and goods.",
      "date": "-0500"
    },
    {
      "headline": "Roman Taxation System",
      "text": "The Roman Empire developed a sophisticated taxation system, including taxes on land, property, and goods. The Roman tax system was crucial for funding the empire's military and infrastructure projects.",
      "date": "-0027"
    },
    {
      "headline": "Medieval Taxation in Europe",
      "text": "During the medieval period, European monarchs imposed taxes on their subjects to fund wars and royal expenses. These taxes were often levied on land and goods.",
      "date": "1000"
    },
    {
      "headline": "Introduction of Income Tax in Great Britain",
      "text": "In 1799, Great Britain introduced the first modern income tax to fund the Napoleonic Wars. This tax was initially intended as a temporary measure.",
      "date": "1799"
    },
    {
      "headline": "16th Amendment to the U.S. Constitution",
      "text": "In 1913, the 16th Amendment to the United States Constitution was ratified, allowing Congress to levy an income tax without apportioning it among the states or basing it on the U.S. Census.",
      "date": "1913"
    },
    {
      "headline": "Introduction of Value-Added Tax (VAT)",
      "text": "In 1954, France introduced the Value-Added Tax (VAT), a consumption tax placed on a product whenever value is added at each stage of the supply chain.",
      "date": "1954"
    },
    {
      "headline": "Implementation of Goods and Services Tax (GST) in India",
      "text": "On July 1, 2017, India implemented the Goods and Services Tax (GST), a comprehensive indirect tax on the manufacture, sale, and consumption of goods and services.",
      "date": "2017-07-01"
    }
  ]
}

