{
  "timeline": [
    {
      "headline": "Development of the Concept of Limbo",
      "text": "The concept of Limbo began to develop in the early Middle Ages as theologians sought to reconcile the fate of unbaptized infants and righteous individuals who lived before Christ. The idea was to provide a state of natural happiness without the beatific vision of God.",
      "date": "0500"
    },
    {
      "headline": "St. Augustine's Influence",
      "text": "St. Augustine (354-430) influenced the development of the concept of Limbo by emphasizing the necessity of baptism for salvation, which led to the theological problem of the fate of unbaptized infants.",
      "date": "0430"
    },
    {
      "headline": "Medieval Theologians' Descriptions",
      "text": "Medieval theologians, such as Thomas Aquinas, described the underworld as divided into three parts: Hell of the Damned, Limbo of the Fathers, and Limbo of the Infants. Aquinas argued that those in Limbo of the Infants experience natural happiness.",
      "date": "1200"
    },
    {
      "headline": "Council of Florence",
      "text": "The Council of Florence (1431-1449) addressed the issue of the afterlife, but did not definitively settle the question of Limbo, leaving it as a theological speculation rather than official doctrine.",
      "date": "1449"
    },
    {
      "headline": "Pope Pius VI's Declaration",
      "text": "In 1794, Pope Pius VI declared that the concept of Limbo of the Infants was a 'pious belief' but not an official doctrine of the Catholic Church.",
      "date": "1794"
    },
    {
      "headline": "International Theological Commission Report",
      "text": "In 2007, the International Theological Commission released a report suggesting that there are theological reasons to hope that unbaptized infants might be saved and enjoy the beatific vision, moving away from the traditional concept of Limbo.",
      "date": "2007"
    }
  ]
}

