{
  "timeline": [
    {
      "headline": "Establishment of Princely States",
      "text": "Princely states were established in the Indian subcontinent as early as the medieval period, with various local rulers maintaining control over their territories.",
      "date": "-1000"
    },
    {
      "headline": "British East India Company Influence",
      "text": "In the 18th century, the British East India Company began to exert influence over Indian princely states through treaties and alliances.",
      "date": "1700"
    },
    {
      "headline": "Subsidiary Alliance System",
      "text": "In 1798, Lord Wellesley introduced the Subsidiary Alliance System, which required Indian rulers to accept British forces in their territory and pay for their upkeep.",
      "date": "1798"
    },
    {
      "headline": "Doctrine of Lapse",
      "text": "Introduced by Lord Dalhousie in 1848, the Doctrine of Lapse allowed the British to annex princely states without a direct male heir.",
      "date": "1848"
    },
    {
      "headline": "Indian Rebellion of 1857",
      "text": "During the Indian Rebellion of 1857, several princely states played significant roles, either supporting or opposing the British.",
      "date": "1857"
    },
    {
      "headline": "Formation of the British Raj",
      "text": "In 1858, following the suppression of the rebellion, the British Crown took direct control of India, establishing the British Raj and formalizing the status of princely states.",
      "date": "1858"
    },
    {
      "headline": "Chamber of Princes Established",
      "text": "In 1920, the Chamber of Princes was established as an advisory body for the rulers of the princely states.",
      "date": "1920"
    },
    {
      "headline": "Independence of India and Partition",
      "text": "On August 15, 1947, India gained independence from British rule, leading to the partition of India and Pakistan. Princely states were given the option to join either country or remain independent.",
      "date": "1947-08-15"
    },
    {
      "headline": "Integration into India",
      "text": "By 1949, most princely states had acceded to India, with the government integrating them into the Indian Union.",
      "date": "1949"
    }
  ]
}

