    {
      "headline": "Telecommunications Act of 1996",
      "text": "On February 8, 1996, President Bill Clinton signed the Telecommunications Act of 1996, which was an amendment to the Communications Act of 1934. This act set a worldwide example for net neutrality laws and the regulation of ISPs.",
      "date": "1996-02-08"
    },
    {
      "headline": "Coining of the Term 'Net Neutrality'",
      "text": "In 2003, the term 'net neutrality' was coined by Columbia University media law professor Tim Wu in his paper 'Network Neutrality, Broadband Discrimination'.",
      "date": "2003"
    },
    {
      "headline": "FCC's Internet Policy Statement",
      "text": "In August 2005, the Federal Communications Commission (FCC) adopted an Internet Policy Statement to ensure that broadband networks are widely deployed, open, affordable, and accessible to all consumers.",
      "date": "2005-08"
    },
    {
      "headline": "FCC's Open Internet Order",
      "text": "On December 21, 2010, the FCC adopted the Open Internet Order, which established net neutrality rules to prevent ISPs from blocking or throttling lawful content.",
      "date": "2010-12-21"
    },
    {
      "headline": "Verizon v. FCC",
      "text": "In January 2014, the United States Court of Appeals for the District of Columbia Circuit struck down the FCC's Open Internet Order in the case of Verizon v. FCC, ruling that the FCC did not have the authority to impose such regulations.",
      "date": "2014-01"
    },
    {
      "headline": "FCC's 2015 Open Internet Order",
      "text": "On February 26, 2015, the FCC reclassified broadband as a telecommunications service under Title II of the Communications Act, reinstating net neutrality rules.",
      "date": "2015-02-26"
    },
    {
      "headline": "FCC's Repeal of Net Neutrality",
      "text": "On December 14, 2017, the FCC voted to repeal the 2015 net neutrality rules, effectively ending the regulations that required ISPs to treat all internet traffic equally.",
      "date": "2017-12-14"
    },
    {
      "headline": "California's Net Neutrality Law",
      "text": "On September 30, 2018, California Governor Jerry Brown signed into law the California Internet Consumer Protection and Net Neutrality Act of 2018, which aimed to restore net neutrality protections within the state.",
      "date": "2018-09-30"
    }
  ]
}

