      "text": "In 1843, Hannibal Hamlin was elected to the U.S. House of Representatives, serving until 1847.",
      "date": "1843"
    },
    {
      "headline": "Elected to the U.S. Senate",
      "text": "Hannibal Hamlin was elected to the U.S. Senate in 1848, where he served until 1857.",
      "date": "1848"
    },
    {
      "headline": "Governor of Maine",
      "text": "Hannibal Hamlin briefly served as the Governor of Maine in 1857 before returning to the U.S. Senate.",
      "date": "1857"
    },
    {
      "headline": "Vice President of the United States",
      "text": "Hannibal Hamlin served as the 15th Vice President of the United States from March 4, 1861, to March 4, 1865, during Abraham Lincoln's first term.",
      "date": "1861-03-04"
    },
    {
      "headline": "Return to the U.S. Senate",
      "text": "After his term as Vice President, Hannibal Hamlin returned to the U.S. Senate, serving from 1869 to 1881.",
      "date": "1869"
    },
    {
      "headline": "Appointed Minister to Spain",
      "text": "In 1881, Hannibal Hamlin was appointed as the Minister to Spain, serving until 1882.",
      "date": "1881"
    },
    {
      "headline": "Death of Hannibal Hamlin",
      "text": "Hannibal Hamlin died on July 4, 1891, in Bangor, Maine.",
      "date": "1891-07-04"
    }
  ]
}

