{
  "timeline": [
    {
      "headline": "Founding of The Criterion Collection",
      "text": "The Criterion Collection was founded in 1984 as a home-video distribution company focusing on licensing, restoring, and distributing important classic and contemporary films.",
      "date": "1984"
    },
    {
      "headline": "Introduction of Letterboxing Format",
      "text": "In the mid-1980s, The Criterion Collection helped to standardize the letterboxing format for widescreen films, allowing viewers to see the entire image as originally intended by filmmakers.",
      "date": "1985"
    },
    {
      "headline": "Pioneering Commentary Tracks",
      "text": "Criterion pioneered the use of commentary tracks in the late 1980s, providing viewers with additional insights and scholarly analysis of films.",
      "date": "1987"
    },
    {
      "headline": "Release of LaserDisc Editions",
      "text": "Throughout the late 1980s and 1990s, Criterion released numerous special editions of films on LaserDisc, which included bonus features such as scholarly essays and documentary content.",
      "date": "1989"
    },
    {
      "headline": "Transition to DVD Format",
      "text": "In 1998, The Criterion Collection began releasing films on DVD, continuing their tradition of including extensive bonus features and high-quality restorations.",
      "date": "1998"
    },
    {
      "headline": "Introduction of Blu-ray Format",
      "text": "In 2008, Criterion started releasing films on Blu-ray, offering improved picture and sound quality along with their signature special features.",
      "date": "2008"
    },
    {
      "headline": "Launch of The Criterion Channel",
      "text": "In April 2019, The Criterion Collection launched The Criterion Channel, an online streaming service providing access to their extensive library of films and special features.",
      "date": "2019-04"
    },
    {
      "headline": "Release of Ultra HD Blu-ray Editions",
      "text": "In 2020, Criterion began releasing films in the Ultra HD Blu-ray format, further enhancing the viewing experience with higher resolution and improved audio.",
      "date": "2020"
    }
  ]
}

