    {
      "headline": "Development of the Polio Vaccine",
      "text": "In 1952, Jonas Salk developed the first effective polio vaccine, which was tested in a massive field trial in 1954.",
      "date": "1952"
    },
    {
      "headline": "Polio Vaccine Field Trials",
      "text": "The field trials for the polio vaccine, led by Jonas Salk, began in 1954 and were the largest medical experiment in history at the time.",
      "date": "1954"
    },
    {
      "headline": "Announcement of Polio Vaccine Success",
      "text": "On April 12, 1955, the success of the polio vaccine developed by Jonas Salk was announced, marking a major breakthrough in medical science.",
      "date": "1955-04-12"
    },
    {
      "headline": "Founding of the Salk Institute for Biological Studies",
      "text": "In 1963, Jonas Salk founded the Salk Institute for Biological Studies in La Jolla, California, to continue his research.",
      "date": "1963"
    },
    {
      "headline": "Publication of 'Man Unfolding'",
      "text": "Jonas Salk published his book 'Man Unfolding' in 1972, discussing the philosophical implications of biological evolution.",
      "date": "1972"
    },
    {
      "headline": "Publication of 'The Survival of the Wisest'",
      "text": "In 1973, Jonas Salk published 'The Survival of the Wisest', exploring the future of human evolution.",
      "date": "1973"
    },
    {
      "headline": "Death of Jonas Salk",
      "text": "Jonas Salk passed away on June 23, 1995, in La Jolla, California.",
      "date": "1995-06-23"
    }
  ]
}

