    {
      "headline": "Origin of Danse Macabre",
      "text": "The Danse Macabre originated in the Late Middle Ages, around the time of the Black Death in the 14th century. It served as an allegory on the universality of death, reminding people of the inevitability of death regardless of one's status in life.",
      "date": "1300"
    },
    {
      "headline": "First Known Appearance",
      "text": "The earliest known visual depiction of the Danse Macabre is from a mural in the Cemetery of the Holy Innocents in Paris, painted around 1424–1425.",
      "date": "1424"
    },
    {
      "headline": "Danse Macabre in Literature",
      "text": "The theme of the Danse Macabre was also popular in literature, with one of the earliest examples being a poem by Jean le Fèvre in 1376.",
      "date": "1376"
    },
    {
      "headline": "Danse Macabre in Art",
      "text": "The Danse Macabre became a popular subject in art, with notable examples including the Lübeck Dance of Death, a series of paintings created in 1463 in St. Mary's Church, Lübeck, Germany.",
      "date": "1463"
    },
    {
      "headline": "Danse Macabre in Music",
      "text": "The theme of the Danse Macabre was also explored in music, most famously by French composer Camille Saint-Saëns in his symphonic poem 'Danse Macabre', composed in 1874.",
      "date": "1874"
    }
  ]
}

