{
  "timeline": [
    {
      "headline": "Existence of LUCA",
      "text": "The Last Universal Common Ancestor (LUCA) is hypothesized to have existed at latest 3.6 billion years ago, and possibly as early as 4.3 billion years ago or earlier. LUCA is considered the common ancestral cell from which the three domains of life, Bacteria, Archaea, and Eukarya, originated.",
      "date": "-3600000000"
    },
    {
      "headline": "Characteristics of LUCA",
      "text": "LUCA had a lipid bilayer and possessed the genetic code and ribosomes which translated from DNA or RNA to proteins. These features are fundamental to all known life forms.",
      "date": "-3600000000"
    },
    {
      "headline": "Research on LUCA",
      "text": "The nature of LUCA and the point or stage of divergence into the three domains of life remains a topic of ongoing research. Scientists continue to study the characteristics and environment of LUCA to better understand the origins of life on Earth.",
      "date": "2023"
    }
  ]
}

