{
  "timeline": [
    {
      "headline": "Norbert Wiener Coined the Term 'Cybernetics'",
      "text": "In 1948, Norbert Wiener published the book 'Cybernetics: Or Control and Communication in the Animal and the Machine', where he coined the term 'cybernetics' to describe the study of control and communication in animals and machines.",
      "date": "1948"
    },
    {
      "headline": "First Macy Conferences on Cybernetics",
      "text": "From 1946 to 1953, the Macy Conferences were held, bringing together a diverse group of scholars to discuss cybernetics and systems theory. These conferences were instrumental in the development of cybernetics as a field.",
      "date": "1946"
    },
    {
      "headline": "Publication of 'Cybernetics and Society'",
      "text": "In 1950, Norbert Wiener published 'The Human Use of Human Beings: Cybernetics and Society', which explored the implications of cybernetics for society and human life.",
      "date": "1950"
    },
    {
      "headline": "Ross Ashby Publishes 'Design for a Brain'",
      "text": "In 1952, W. Ross Ashby published 'Design for a Brain', which applied cybernetic principles to the study of the brain and adaptive systems.",
      "date": "1952"
    },
    {
      "headline": "Formation of the American Society for Cybernetics",
      "text": "In 1964, the American Society for Cybernetics was founded to promote the study and application of cybernetics.",
      "date": "1964"
    },
    {
      "headline": "Heinz von Foerster's 'Cybernetics of Cybernetics'",
      "text": "In 1974, Heinz von Foerster published 'Cybernetics of Cybernetics', which introduced the concept of second-order cybernetics, focusing on the observer within the system.",
      "date": "1974"
    },
    {
      "headline": "Introduction of Second-Order Cybernetics",
      "text": "During the 1970s, the concept of second-order cybernetics emerged, emphasizing the role of the observer in the system and the recursive nature of observation.",
      "date": "1970"
    },
    {
      "headline": "Gregory Bateson's 'Steps to an Ecology of Mind'",
      "text": "In 1972, Gregory Bateson published 'Steps to an Ecology of Mind', which applied cybernetic principles to anthropology, psychology, and ecology.",
      "date": "1972"
    },
    {
      "headline": "Publication of 'Autopoiesis and Cognition'",
      "text": "In 1980, Humberto Maturana and Francisco Varela published 'Autopoiesis and Cognition: The Realization of the Living', introducing the concept of autopoiesis in biological systems.",
      "date": "1980"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Known Filibuster",
      "text": "The first known filibuster in the United States Senate occurred in 1837 when a group of Whig senators filibustered to prevent the expungement of a censure against President Andrew Jackson.",
      "date": "1837"
    },
    {
      "headline": "Cloture Rule Introduced",
      "text": "In 1917, the Senate adopted Rule 22, known as the cloture rule, which allowed the Senate to end a filibuster with a two-thirds majority vote.",
      "date": "1917"
    },
    {
      "headline": "Civil Rights Filibuster",
      "text": "In 1964, a 60-day filibuster was conducted by Southern senators against the Civil Rights Act of 1964. It was ended by a successful cloture vote, leading to the passage of the Act.",
      "date": "1964"
    },
    {
      "headline": "Cloture Rule Amended",
      "text": "In 1975, the Senate reduced the number of votes required for cloture from two-thirds (67 senators) to three-fifths (60 senators) of the Senate.",
      "date": "1975"
    },
    {
      "headline": "Nuclear Option for Judicial Nominees",
      "text": "In 2013, the Senate Democrats, led by Majority Leader Harry Reid, invoked the 'nuclear option' to eliminate the use of the filibuster for all executive branch nominations and federal judicial appointments, except for the Supreme Court.",
      "date": "2013"
    },
    {
      "headline": "Nuclear Option Extended to Supreme Court",
      "text": "In 2017, Senate Republicans, led by Majority Leader Mitch McConnell, extended the 'nuclear option' to include Supreme Court nominations, allowing them to be confirmed with a simple majority.",
      "date": "2017"
    }
  ]
}

