    {
      "headline": "Battle of Narva",
      "text": "On November 30, 1700, Charles XII achieved a significant victory at the Battle of Narva against the Russian forces.",
      "date": "1700-11-30"
    },
    {
      "headline": "Battle of Poltava",
      "text": "On June 28, 1709, Charles XII suffered a major defeat at the Battle of Poltava against the Russian army, marking a turning point in the Great Northern War.",
      "date": "1709-06-28"
    },
    {
      "headline": "Exile in the Ottoman Empire",
      "text": "Following the defeat at Poltava, Charles XII took refuge in the Ottoman Empire from 1709 to 1714.",
      "date": "1709"
    },
    {
      "headline": "Return to Sweden",
      "text": "Charles XII returned to Sweden in 1714 after his exile in the Ottoman Empire.",
      "date": "1714"
    },
    {
      "headline": "Death of Charles XII",
      "text": "Charles XII died on November 30, 1718, during the Siege of Fredriksten in Norway. His death marked the end of the Swedish Empire as a great power.",
      "date": "1718-11-30"
    }
  ]
}

