{
  "timeline": [
    {
      "headline": "Passage of the Rowlatt Act",
      "text": "The Rowlatt Act, officially known as The Anarchical and Revolutionary Crimes Act of 1919, was passed by the Imperial Legislative Council in Delhi on 18 March 1919. This act extended the emergency measures of preventive indefinite detention, imprisonment without trial, and judicial review that were initially enacted in the Defence of India Act 1915 during World War I.",
      "date": "1919-03-18"
    },
    {
      "headline": "Purpose of the Rowlatt Act",
      "text": "The Rowlatt Act was enacted due to a perceived threat from revolutionary nationalists who might re-engage in conspiracies similar to those during World War I. The British government felt that the lapse of the Defence of India Act would enable such activities.",
      "date": "1919"
    },
    {
      "headline": "Public Reaction and Protests",
      "text": "The Rowlatt Act faced widespread opposition and protests across India. It was seen as repressive and an infringement on civil liberties, leading to significant unrest and demonstrations.",
      "date": "1919"
    },
    {
      "headline": "Jallianwala Bagh Massacre",
      "text": "The opposition to the Rowlatt Act culminated in the Jallianwala Bagh massacre on 13 April 1919, when British troops fired on a large crowd of unarmed Indian protesters in Amritsar, Punjab, killing hundreds.",
      "date": "1919-04-13"
    },
    {
      "headline": "Impact on Indian Independence Movement",
      "text": "The Rowlatt Act and the subsequent Jallianwala Bagh massacre intensified the Indian independence movement, leading to increased support for leaders like Mahatma Gandhi and a push for non-cooperation with the British government.",
      "date": "1919"
    }
  ]
}

