{
  "timeline": [
    {
      "headline": "Origins of Theatre",
      "text": "Theatre originated in ancient Greece, with the earliest recorded performances taking place in the 6th century BCE. These performances were part of religious festivals honoring the god Dionysus.",
      "date": "-0600"
    },
    {
      "headline": "Development of Greek Theatre",
      "text": "By the 5th century BCE, Greek theatre had developed into a sophisticated art form, with playwrights like Aeschylus, Sophocles, and Euripides writing tragedies, and Aristophanes writing comedies.",
      "date": "-0500"
    },
    {
      "headline": "Roman Theatre",
      "text": "Roman theatre was heavily influenced by Greek theatre and began to flourish around the 3rd century BCE. It included both tragedies and comedies, with playwrights like Plautus and Terence.",
      "date": "-0300"
    },
    {
      "headline": "Medieval Theatre",
      "text": "After the fall of the Roman Empire, theatre in Europe was largely dormant until the medieval period, when it re-emerged as liturgical dramas and mystery plays in the 10th century CE.",
      "date": "1000"
    },
    {
      "headline": "Renaissance Theatre",
      "text": "The Renaissance period, beginning in the 14th century, saw a revival of classical themes and the development of new forms such as commedia dell'arte in Italy and the Elizabethan theatre in England, with playwrights like William Shakespeare.",
      "date": "1400"
    },
    {
      "headline": "Theatre in the 18th Century",
      "text": "The 18th century saw the rise of neoclassical theatre in France and the development of opera and ballet as distinct theatrical forms.",
      "date": "1700"
    },
    {
      "headline": "19th Century Theatre",
      "text": "The 19th century was marked by the rise of realism and naturalism in theatre, with playwrights like Henrik Ibsen and Anton Chekhov, and the development of melodrama.",
      "date": "1800"
    },
    {
      "headline": "20th Century Theatre",
      "text": "The 20th century saw the emergence of various avant-garde movements, including expressionism, absurdism, and epic theatre, with influential figures like Bertolt Brecht and Samuel Beckett.",
      "date": "1900"
    },
    {
      "headline": "Contemporary Theatre",
      "text": "In the late 20th and early 21st centuries, theatre has continued to evolve with the integration of technology, multimedia, and diverse cultural influences, expanding the boundaries of traditional theatre.",
      "date": "2000"
    }
  ]
}

