{
  "timeline": [
    {
      "headline": "Foundation of Isfahan",
      "text": "Isfahan's history dates back to ancient times, with evidence of settlement in the area as early as the Paleolithic period. However, the city began to gain prominence during the Achaemenid Empire (550–330 BCE).",
      "date": "-0550"
    },
    {
      "headline": "Isfahan under the Sassanian Empire",
      "text": "During the Sassanian Empire (224–651 CE), Isfahan became an important military and administrative center.",
      "date": "0224"
    },
    {
      "headline": "Arab Conquest of Isfahan",
      "text": "In 642 CE, Isfahan was conquered by Arab Muslims during the Islamic conquest of Persia.",
      "date": "0642"
    },
    {
      "headline": "Isfahan as the Capital of the Seljuk Empire",
      "text": "In 1050, Isfahan became the capital of the Seljuk Empire, marking a period of significant growth and development for the city.",
      "date": "1050"
    },
    {
      "headline": "Mongol Invasion",
      "text": "In 1237, Isfahan was invaded by the Mongols, leading to a period of decline.",
      "date": "1237"
    },
    {
      "headline": "Safavid Dynasty and Isfahan's Golden Age",
      "text": "In 1598, Shah Abbas I of the Safavid dynasty made Isfahan the capital of Persia, initiating a golden age with extensive architectural and cultural development.",
      "date": "1598"
    },
    {
      "headline": "Afghan Invasion",
      "text": "In 1722, Isfahan was besieged and captured by Afghan forces, leading to the decline of the Safavid dynasty.",
      "date": "1722"
    },
    {
      "headline": "Qajar Era",
      "text": "During the Qajar dynasty (1789–1925), Isfahan lost its status as the capital but remained an important cultural and economic center.",
      "date": "1789"
    },
    {
      "headline": "Modern Development",
      "text": "In the 20th century, Isfahan underwent significant modernization and industrialization, becoming one of Iran's major cities.",
      "date": "1900"
    }
  ]
}

