  "timeline": [
    {
      "headline": "Publication of Einstein Field Equations",
      "text": "The Einstein field equations were first published by Albert Einstein in 1915 as part of his general theory of relativity. These equations describe how matter and energy in the universe influence the curvature of spacetime.",
      "date": "1915"
    },
    {
      "headline": "Einstein's Presentation to the Prussian Academy of Sciences",
      "text": "On November 25, 1915, Albert Einstein presented the final form of the Einstein field equations to the Prussian Academy of Sciences.",
      "date": "1915-11-25"
    },
    {
      "headline": "First Exact Solution: Schwarzschild Solution",
      "text": "In 1916, Karl Schwarzschild found the first exact solution to the Einstein field equations, known as the Schwarzschild solution, which describes the gravitational field outside a spherical mass.",
      "date": "1916"
    },
    {
      "headline": "Development of the Friedmann Equations",
      "text": "In 1922, Alexander Friedmann derived solutions to the Einstein field equations that describe an expanding universe, leading to the development of the Friedmann equations.",
      "date": "1922"
    },
    {
      "headline": "Einstein's Addition of the Cosmological Constant",
      "text": "Einstein introduced the cosmological constant (Λ) to the field equations in 1917 to allow for a static universe, which he later abandoned after the discovery of the universe's expansion.",
      "date": "1917"
    },
    {
      "headline": "Discovery of Gravitational Waves",
      "text": "The existence of gravitational waves was predicted by the Einstein field equations, and they were first directly detected by LIGO in 2015, confirming a major prediction of general relativity.",
      "date": "2015"
    }
  ]
}

