{
  "timeline": [
    {
      "headline": "Formation of the Arts and Crafts Movement",
      "text": "The Arts and Crafts movement began in the late 19th century, emerging as a reaction against the industrial revolution and the mass production of goods. It emphasized traditional craftsmanship and simple forms.",
      "date": "1880"
    },
    {
      "headline": "Publication of 'The Nature of Gothic'",
      "text": "In 1892, William Morris published 'The Nature of Gothic', a chapter from John Ruskin's book 'The Stones of Venice'. This work became a manifesto for the Arts and Crafts movement, advocating for the value of craftsmanship.",
      "date": "1892"
    },
    {
      "headline": "Establishment of the Art Workers' Guild",
      "text": "The Art Workers' Guild was established in 1884 in London, bringing together architects, designers, and craftsmen who were part of the Arts and Crafts movement.",
      "date": "1884"
    },
    {
      "headline": "Founding of the Arts and Crafts Exhibition Society",
      "text": "In 1887, the Arts and Crafts Exhibition Society was founded in London. It organized exhibitions to promote the work of artists and craftsmen associated with the movement.",
      "date": "1887"
    },
    {
      "headline": "First Arts and Crafts Exhibition",
      "text": "The first exhibition organized by the Arts and Crafts Exhibition Society took place in 1888, showcasing the works of artists and craftsmen and promoting the movement's ideals.",
      "date": "1888"
    },
    {
      "headline": "Spread to the United States",
      "text": "By the early 20th century, the Arts and Crafts movement had spread to the United States, influencing American architecture and design, particularly through the work of figures like Gustav Stickley.",
      "date": "1900"
    },
    {
      "headline": "Influence on the Bauhaus",
      "text": "The Arts and Crafts movement influenced the Bauhaus, a German art school operational from 1919 to 1933, which combined crafts and the fine arts.",
      "date": "1919"
    },
    {
      "headline": "Decline of the Movement",
      "text": "By the 1920s, the Arts and Crafts movement began to decline as modernist movements gained prominence, but its influence continued to be felt in various design and architectural styles.",
      "date": "1920"
    }
  ]
}

