      "headline": "Battle of Asfeld",
      "text": "In 508, the Lombards defeated the Heruli in the Battle of Asfeld, establishing themselves as a dominant power in the region.",
      "date": "0508"
    },
    {
      "headline": "Settlement in Pannonia",
      "text": "Around 546, the Lombards settled in the region of Pannonia, which is in modern-day Hungary, under the leadership of King Audoin.",
      "date": "0546"
    },
    {
      "headline": "Alboin Becomes King",
      "text": "In 560, Alboin became the king of the Lombards and began preparations for the invasion of Italy.",
      "date": "0560"
    },
    {
      "headline": "Lombard Invasion of Italy",
      "text": "In 568, under the leadership of King Alboin, the Lombards invaded Italy, marking the beginning of their conquest of the Italian Peninsula.",
      "date": "0568"
    },
    {
      "headline": "Capture of Pavia",
      "text": "In 572, the Lombards captured the city of Pavia, which later became the capital of their kingdom in Italy.",
      "date": "0572"
    },
    {
      "headline": "Assassination of Alboin",
      "text": "In 572, King Alboin was assassinated in Verona, leading to a period of instability and internal strife among the Lombards.",
      "date": "0572"
    },
    {
      "headline": "Reign of King Authari",
      "text": "In 584, Authari became king and worked to consolidate Lombard control over Italy, establishing a more stable rule.",
      "date": "0584"
    },
    {
      "headline": "Reign of King Agilulf",
      "text": "In 591, Agilulf became king and continued to strengthen the Lombard kingdom, promoting Christianity and securing alliances.",
      "date": "0591"
    },
    {
      "headline": "Lombard Kingdom at its Height",
      "text": "By the early 7th century, the Lombard Kingdom reached its height, controlling large parts of Italy and establishing a strong cultural and political presence.",
      "date": "0600"
    },
    {
      "headline": "Reign of King Liutprand",
      "text": "From 712 to 744, King Liutprand ruled, known for his legal reforms and efforts to unify the Lombard territories.",
      "date": "0712"
    },
    {
      "headline": "Fall of the Lombard Kingdom",
      "text": "In 774, the Lombard Kingdom fell to the Franks under Charlemagne, who conquered the Lombard territories and ended their rule in Italy.",
      "date": "0774"
    }
  ]
}

