{
  "timeline": [
    {
      "headline": "Arrival of the Serbs in the Balkans",
      "text": "The Serbs, a South Slavic people, migrated to the Balkans during the 6th and 7th centuries. They settled in areas that are now part of Serbia, Bosnia and Herzegovina, Montenegro, and Croatia.",
      "date": "0600"
    },
    {
      "headline": "Formation of the Serbian Principality",
      "text": "In the early 9th century, the Serbian Principality was formed under the Vlastimirović dynasty. This marked the beginning of a distinct Serbian state.",
      "date": "0830"
    },
    {
      "headline": "Christianization of the Serbs",
      "text": "The Serbs were Christianized between the 7th and 9th centuries, with the establishment of Christianity as the state religion under the influence of the Byzantine Empire.",
      "date": "0869"
    },
    {
      "headline": "Reign of Stefan Nemanja",
      "text": "Stefan Nemanja, the founder of the Nemanjić dynasty, ruled from 1166 to 1196. He is credited with consolidating Serbian territories and establishing the Serbian Orthodox Church.",
      "date": "1166"
    },
    {
      "headline": "Establishment of the Serbian Kingdom",
      "text": "In 1217, Stefan Nemanjić, also known as Stefan the First-Crowned, was crowned as the first King of Serbia, marking the establishment of the Serbian Kingdom.",
      "date": "1217"
    },
    {
      "headline": "Battle of Kosovo",
      "text": "On June 28, 1389, the Battle of Kosovo took place between the Serbian army led by Prince Lazar and the Ottoman Empire. The battle is a significant event in Serbian history and culture.",
      "date": "1389-06-28"
    },
    {
      "headline": "Fall of the Serbian Despotate",
      "text": "In 1459, the Serbian Despotate fell to the Ottoman Empire, marking the end of medieval Serbian statehood and the beginning of centuries of Ottoman rule.",
      "date": "1459"
    },
    {
      "headline": "Serbian Revolution",
      "text": "The Serbian Revolution, which began in 1804 and lasted until 1835, was a series of uprisings and wars that led to the establishment of modern Serbia as an autonomous principality within the Ottoman Empire.",
      "date": "1804"
    },
    {
      "headline": "Proclamation of the Kingdom of Serbia",
      "text": "In 1882, the Principality of Serbia was elevated to the status of a kingdom, with Milan I as its first king.",
      "date": "1882"
    },
    {
      "headline": "Assassination of Archduke Franz Ferdinand",
      "text": "On June 28, 1914, Gavrilo Princip, a Bosnian Serb, assassinated Archduke Franz Ferdinand of Austria in Sarajevo, an event that triggered World War I.",
      "date": "1914-06-28"
    },
