{
  "timeline": [
    {
      "headline": "Establishment of APEC",
      "text": "Asia-Pacific Economic Cooperation (APEC) was established in 1989 in response to the growing interdependence of Asia-Pacific economies and the advent of regional trade blocs in other parts of the world.",
      "date": "1989"
    },
    {
      "headline": "First APEC Meeting",
      "text": "The first APEC meeting was held in Canberra, Australia, in November 1989, with 12 founding members participating.",
      "date": "1989-11"
    },
    {
      "headline": "APEC Secretariat Established",
      "text": "In 1993, the APEC Secretariat was established in Singapore to provide coordination, technical and advisory support as well as information management, communications and public outreach services.",
      "date": "1993"
    },
    {
      "headline": "Bogor Goals",
      "text": "In 1994, APEC leaders met in Bogor, Indonesia, and set the Bogor Goals, which aimed for free and open trade and investment in the Asia-Pacific by 2010 for industrialized economies and 2020 for developing economies.",
      "date": "1994"
    },
    {
      "headline": "APEC Business Advisory Council (ABAC) Formed",
      "text": "The APEC Business Advisory Council (ABAC) was formed in 1995 to provide advice to APEC leaders on business sector priorities and concerns.",
      "date": "1995"
    },
    {
      "headline": "Shanghai Accord",
      "text": "In 2001, the Shanghai Accord was adopted, which emphasized the importance of implementing the Bogor Goals and introduced the concept of a 'Pathfinder' approach to advance trade and investment liberalization.",
      "date": "2001"
    },
    {
      "headline": "APEC's 25th Anniversary",
      "text": "In 2014, APEC celebrated its 25th anniversary, marking a quarter-century of promoting free trade and economic cooperation in the Asia-Pacific region.",
      "date": "2014"
    }
  ]
}

