    {
      "headline": "Establishment of the Penal Colony",
      "text": "In 1852, the French government established a penal colony on the Salvation Islands of French Guiana, commonly known as Devil's Island. It was intended to house political prisoners and hardened criminals.",
      "date": "1852"
    },
    {
      "headline": "Alfred Dreyfus Imprisonment",
      "text": "In 1895, Alfred Dreyfus, a French army officer, was wrongfully convicted of treason and sent to Devil's Island. His imprisonment became a major political scandal known as the Dreyfus Affair.",
      "date": "1895"
    },
    {
      "headline": "Dreyfus Exoneration",
      "text": "In 1906, Alfred Dreyfus was exonerated and released from Devil's Island after a long legal battle and public outcry.",
      "date": "1906"
    },
    {
      "headline": "Closure of the Penal Colony",
      "text": "In 1953, the French government officially closed the penal colony on Devil's Island, marking the end of its operation after 100 years.",
      "date": "1953"
    }
  ]
}

