{
  "timeline": [
    {
      "headline": "Founding of Whirlpool Corporation",
      "text": "Whirlpool Corporation was founded on November 11, 1911, as the Upton Machine Company by Louis Upton and Emory Upton in St. Joseph, Michigan.",
      "date": "1911-11-11"
    },
    {
      "headline": "Introduction of Electric Wringer Washer",
      "text": "In 1916, the Upton Machine Company began producing electric wringer washers for Sears, Roebuck & Co., which were sold under the 'Allen' brand.",
      "date": "1916"
    },
    {
      "headline": "Merger with Nineteen Hundred Washer Company",
      "text": "In 1929, Upton Machine Company merged with the Nineteen Hundred Washer Company of Binghamton, New York, to form the Nineteen Hundred Corporation.",
      "date": "1929"
    },
    {
      "headline": "Introduction of First Automatic Washer",
      "text": "In 1947, Whirlpool introduced the first automatic, spinner-type washer, marking a significant innovation in home appliances.",
      "date": "1947"
    },
    {
      "headline": "Renaming to Whirlpool Corporation",
      "text": "In 1950, the Nineteen Hundred Corporation was renamed Whirlpool Corporation.",
      "date": "1950"
    },
    {
      "headline": "Acquisition of RCA's Air Conditioning and Refrigerator Operations",
      "text": "In 1955, Whirlpool acquired RCA's air conditioning and refrigerator operations, expanding its product line.",
      "date": "1955"
    },
    {
      "headline": "Introduction of the Whirlpool Miracle Kitchen",
      "text": "In 1957, Whirlpool introduced the 'Whirlpool Miracle Kitchen,' a futuristic kitchen concept that showcased advanced appliance technology.",
      "date": "1957"
    },
    {
      "headline": "Acquisition of KitchenAid",
      "text": "In 1986, Whirlpool acquired KitchenAid, a premium brand of kitchen appliances, further diversifying its product offerings.",
      "date": "1986"
    },
    {
      "headline": "Acquisition of Maytag Corporation",
      "text": "In 2006, Whirlpool completed the acquisition of Maytag Corporation, significantly increasing its market share in the home appliance industry.",
      "date": "2006"
    },
    {
      "headline": "Centennial Celebration",
      "text": "In 2011, Whirlpool Corporation celebrated its 100th anniversary, marking a century of innovation and growth in the home appliance industry.",
      "date": "2011"
    },
    {
      "headline": "Acquisition of Indesit Company",
      "text": "In 2014, Whirlpool acquired a majority stake in Indesit Company, an Italian appliance manufacturer, to strengthen its presence in the European market.",
      "date": "2014"
    },
    {
      "headline": "Acquisition of Yummly",
      "text": "In 2017, Whirlpool acquired Yummly, a digital recipe and meal planning service, to enhance its digital capabilities and consumer engagement.",
      "date": "2017"
    },
    {
      "headline": "Partnership with Habitat for Humanity",
      "text": "In 2019, Whirlpool announced a partnership with Habitat for Humanity to provide appliances for homes built by the organization, demonstrating its commitment to social responsibility.",
      "date": "2019"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Origin of Hammam",
      "text": "The concept of the hammam originated from the Roman thermae, which were public bathhouses in ancient Rome. The design and function of these baths were adapted by the Islamic world after the spread of Islam.",
      "date": "-0001"
    },
    {
      "headline": "Spread of Hammams in the Islamic World",
      "text": "After the rise of Islam in the 7th century, hammams became a significant part of Muslim culture, spreading across the Middle East, North Africa, and other regions influenced by Islamic civilization.",
      "date": "0700"
    },
    {
      "headline": "Hammams in the Ottoman Empire",
      "text": "During the Ottoman Empire, hammams became a central feature of urban life in cities across the empire, including in Southeastern Europe, where they were known as Turkish baths.",
      "date": "1299"
    },
    {
      "headline": "Hammams in Al-Andalus",
      "text": "In Al-Andalus (Muslim Spain), hammams were an integral part of urban infrastructure, reflecting the sophisticated urban planning and cultural life of the region during the Islamic rule.",
      "date": "0800"
    },
    {
      "headline": "Decline of Traditional Hammams",
      "text": "With the advent of modern plumbing and private bathrooms, the traditional role of hammams began to decline, although they remain a cultural and historical symbol in many regions.",
      "date": "1900"
    },
    {
      "headline": "Revival and Modern Use of Hammams",
      "text": "In recent years, there has been a revival of interest in hammams as a cultural and wellness experience, with many being restored and adapted for modern use.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Discovery of Coley's Toxins",
      "text": "In the 1890s, William B. Coley, a surgeon, developed a treatment using killed bacteria to stimulate the immune system to fight cancer. This was one of the earliest forms of cancer immunotherapy.",
      "date": "1890"
    },
    {
      "headline": "Development of Bacillus Calmette-Guérin (BCG) Vaccine",
      "text": "In 1921, the BCG vaccine was developed as a vaccine for tuberculosis and later found to have immune-stimulating properties useful in treating bladder cancer.",
      "date": "1921"
    },
    {
      "headline": "Introduction of Interferons",
      "text": "In the 1950s, interferons were discovered as proteins that could modulate the immune response, leading to their use in treating certain cancers and viral infections.",
      "date": "1950"
    },
    {
      "headline": "Discovery of Monoclonal Antibodies",
      "text": "In 1975, Georges Köhler and César Milstein developed the hybridoma technique to produce monoclonal antibodies, which became a cornerstone of targeted cancer immunotherapy.",
      "date": "1975"
    },
    {
      "headline": "Approval of Interleukin-2 (IL-2)",
      "text": "In 1992, the FDA approved Interleukin-2 (IL-2) for the treatment of metastatic renal cell carcinoma, marking a significant advancement in cancer immunotherapy.",
      "date": "1992"
    },
    {
      "headline": "Approval of First Cancer Vaccine",
      "text": "In 2010, the FDA approved Sipuleucel-T (Provenge) as the first cancer vaccine for prostate cancer, representing a new approach in immunotherapy.",
      "date": "2010"
    },
    {
      "headline": "Approval of First Immune Checkpoint Inhibitor",
      "text": "In 2011, the FDA approved Ipilimumab (Yervoy), the first immune checkpoint inhibitor for the treatment of melanoma, a breakthrough in cancer immunotherapy.",
      "date": "2011"
    },
    {
      "headline": "Approval of PD-1 Inhibitors",
      "text": "In 2014, the FDA approved Pembrolizumab (Keytruda) and Nivolumab (Opdivo), PD-1 inhibitors that have shown effectiveness in treating various cancers.",
      "date": "2014"
    },
    {
      "headline": "Approval of CAR T-cell Therapy",
      "text": "In 2017, the FDA approved the first CAR T-cell therapy, Tisagenlecleucel (Kymriah), for the treatment of acute lymphoblastic leukemia, marking a new era in personalized cancer treatment.",
      "date": "2017"
    }
  ]
}

