{
  "timeline": [
    {
      "headline": "Founding of OneCoin",
      "text": "OneCoin was founded in 2014 by Ruja Ignatova and Sebastian Greenwood. The company was marketed as a cryptocurrency but was later revealed to be a fraudulent scheme.",
      "date": "2014"
    },
    {
      "headline": "OneCoin's Rapid Expansion",
      "text": "Throughout 2015, OneCoin expanded rapidly, attracting investors worldwide with promises of high returns. The scheme operated as a multi-level marketing network.",
      "date": "2015"
    },
    {
      "headline": "Warnings from Financial Authorities",
      "text": "In 2016, financial authorities in various countries, including Bulgaria, Finland, and India, issued warnings about OneCoin being a potential scam.",
      "date": "2016"
    },
    {
      "headline": "Ruja Ignatova Disappears",
      "text": "In October 2017, Ruja Ignatova, the founder of OneCoin, disappeared and has not been seen since. Her disappearance coincided with increasing scrutiny from law enforcement.",
      "date": "2017-10"
    },
    {
      "headline": "Arrest of Sebastian Greenwood",
      "text": "In 2018, Sebastian Greenwood, co-founder of OneCoin, was arrested in Thailand and extradited to the United States to face charges related to the OneCoin scheme.",
      "date": "2018"
    },
    {
      "headline": "Konstantin Ignatov Arrested",
      "text": "In March 2019, Konstantin Ignatov, Ruja Ignatova's brother, was arrested in the United States. He was charged with wire fraud and conspiracy to commit money laundering.",
      "date": "2019-03"
    },
    {
      "headline": "Guilty Plea by Mark Scott",
      "text": "In November 2019, Mark Scott, a lawyer associated with OneCoin, was found guilty of laundering $400 million for the scheme.",
      "date": "2019-11"
    },
    {
      "headline": "OneCoin Described as a Major Scam",
      "text": "By 2020, OneCoin was widely recognized as one of the largest Ponzi schemes in history, with losses estimated in the billions of dollars.",
      "date": "2020"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Proposal of Kessler Syndrome",
      "text": "In 1978, NASA scientists Donald J. Kessler and Burton G. Cour-Palais proposed the Kessler syndrome. This scenario describes a situation where the density of objects in low Earth orbit (LEO) is high enough that collisions between objects could cause a cascade effect, generating space debris that increases the likelihood of further collisions.",
      "date": "1978"
    },
    {
      "headline": "Kessler's 2009 Analysis",
      "text": "In 2009, Donald J. Kessler wrote that modeling results had concluded the debris environment in low Earth orbit was already unstable. He noted that any attempt to achieve a growth-free small debris environment by eliminating sources of past debris would likely fail because fragments from future collisions would be generated faster than atmospheric drag could remove them.",
      "date": "2009"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Creation of The Arnolfini Portrait",
      "text": "The Arnolfini Portrait was painted by Jan van Eyck in 1434. It is an oil painting on oak panel and is now housed in the National Gallery, London. The painting is a full-length double portrait, believed to depict the Italian merchant Giovanni di Nicolao Arnolfini and his wife, presumably in their residence at the Flemish city of Bruges.",
      "date": "1434"
    },
    {
      "headline": "Acquisition by the National Gallery, London",
      "text": "The Arnolfini Portrait was acquired by the National Gallery, London, in 1842. It has since become one of the most famous paintings in the gallery's collection.",
      "date": "1842"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Founding of Funimation",
      "text": "Funimation was founded in 1994 by Gen Fukunaga and his wife Cindy as a company focused on distributing anime in North America.",
      "date": "1994"
    },
    {
      "headline": "Acquisition of Dragon Ball Z",
      "text": "In 1994, Funimation acquired the rights to the anime series Dragon Ball Z, which became a major success and significantly increased the company's profile.",
