    {
      "headline": "Ancient Use of the Foot",
      "text": "The foot has been used as a unit of length since ancient times. It was based on the length of a human foot and varied in length from place to place.",
      "date": "-03000"
    },
    {
      "headline": "Roman Foot",
      "text": "The Roman foot (pes) was a standardized unit of length used in the Roman Empire, measuring approximately 11.65 inches or 29.6 centimeters.",
      "date": "-00750"
    },
    {
      "headline": "Medieval Variations",
      "text": "During the medieval period, the length of a foot varied widely across Europe, with different regions adopting their own standards.",
      "date": "1000"
    },
    {
      "headline": "Standardization in England",
      "text": "In England, the foot was standardized to 12 inches during the reign of King Henry I, who ruled from 1100 to 1135.",
      "date": "1100"
    },
    {
      "headline": "British Imperial System",
      "text": "The foot became part of the British Imperial System of units, which was officially established in 1824.",
      "date": "1824"
    },
    {
      "headline": "International Agreement on the Foot",
      "text": "In 1959, an international agreement defined the foot as exactly 0.3048 meters, aligning the unit with the metric system.",
      "date": "1959"
    }
  ]
}

