{
  "timeline": [
    {
      "headline": "Creation of BASIC",
      "text": "In 1963, John G. Kemeny and Thomas E. Kurtz at Dartmouth College created the original version of BASIC (Beginner's All-purpose Symbolic Instruction Code). They aimed to enable students in non-scientific fields to use computers, which at the time required writing custom software primarily learned by scientists and mathematicians.",
      "date": "1963"
    },
    {
      "headline": "First Successful Run of BASIC",
      "text": "On May 1, 1964, the first successful run of a BASIC program was executed on a GE-225 mainframe computer at Dartmouth College. This marked the official launch of the BASIC programming language.",
      "date": "1964-05-01"
    },
    {
      "headline": "Introduction of Time-Sharing System",
      "text": "In 1964, along with the development of BASIC, Dartmouth College also introduced the Dartmouth Time-Sharing System (DTSS), which allowed multiple users to run programs simultaneously on the GE-225 computer.",
      "date": "1964"
    },
    {
      "headline": "BASIC Gains Popularity",
      "text": "During the late 1960s and 1970s, BASIC gained popularity as it was implemented on a wide range of minicomputers and microcomputers, becoming one of the most widely used programming languages in the world.",
      "date": "1970"
    },
    {
      "headline": "Microsoft's Version of BASIC",
      "text": "In 1975, Bill Gates and Paul Allen developed a version of BASIC for the Altair 8800 microcomputer, which became Microsoft's first product and helped establish the company.",
      "date": "1975"
    },
    {
      "headline": "Introduction of Visual Basic",
      "text": "In 1991, Microsoft introduced Visual Basic, an event-driven programming language and integrated development environment (IDE) derived from BASIC, which allowed for the rapid development of Windows applications.",
      "date": "1991"
    }
  ]
}

