{
  "timeline": [
    {
      "headline": "Origin of Tetrapods",
      "text": "Tetrapods first appeared in the late Devonian period, around 375 million years ago, evolving from lobe-finned fishes.",
      "date": "-0375000000"
    },
    {
      "headline": "Early Tetrapod Evolution",
      "text": "During the Carboniferous period, around 360 million years ago, tetrapods diversified into various forms, including early amphibians.",
      "date": "-0360000000"
    },
    {
      "headline": "Development of Amniotes",
      "text": "By the late Carboniferous period, approximately 312 million years ago, amniotes, a group of tetrapods that lay eggs on land, began to emerge.",
      "date": "-0312000000"
    },
    {
      "headline": "Evolution of Sauropsids and Synapsids",
      "text": "During the Permian period, around 300 million years ago, tetrapods split into two major clades: sauropsids (leading to reptiles and birds) and synapsids (leading to mammals).",
      "date": "-0300000000"
    },
    {
      "headline": "Tetrapods Survive the Permian-Triassic Extinction",
      "text": "Approximately 252 million years ago, tetrapods survived the Permian-Triassic extinction event, the most severe extinction event in Earth's history.",
      "date": "-0252000000"
    },
    {
      "headline": "Rise of Dinosaurs",
      "text": "During the Mesozoic era, starting around 230 million years ago, dinosaurs, a group of sauropsid tetrapods, became the dominant terrestrial vertebrates.",
      "date": "-0230000000"
    },
    {
      "headline": "Cretaceous-Paleogene Extinction Event",
      "text": "Around 66 million years ago, the Cretaceous-Paleogene extinction event led to the extinction of many tetrapod species, including non-avian dinosaurs.",
      "date": "-0066000000"
    },
    {
      "headline": "Diversification of Mammals and Birds",
      "text": "Following the Cretaceous-Paleogene extinction event, mammals and birds (descendants of tetrapods) diversified and became dominant in various ecological niches.",
      "date": "-0065000000"
    }
  ]
}

