    {
      "headline": "Decline of Vinyl Records",
      "text": "The popularity of vinyl records began to decline in the 1980s with the introduction of the compact disc (CD).",
      "date": "1980"
    },
    {
      "headline": "Vinyl Revival",
      "text": "In the 2000s, vinyl records experienced a revival as collectors and audiophiles sought the analog sound quality and tangible format.",
      "date": "2000"
