{
  "timeline": [
    {
      "headline": "Formation of the Young Turks Movement",
      "text": "The Young Turks movement began to form as a constitutionalist opposition against the absolutist regime of Sultan Abdul Hamid II in the late 19th century.",
      "date": "1889"
    },
    {
      "headline": "Establishment of the Committee of Union and Progress (CUP)",
      "text": "The Committee of Union and Progress (CUP) was established as the most powerful organization within the Young Turks movement, focusing on reform and modernization of the Ottoman Empire.",
      "date": "1889"
    },
    {
      "headline": "Exile of Young Turks",
      "text": "By the 1890s, many Young Turks were exiled and formed a loose network of intelligentsia, spreading their ideas through newspapers and secret communications.",
      "date": "1890"
    },
    {
      "headline": "Young Turk Revolution",
      "text": "The Young Turk Revolution took place in 1908, leading to the restoration of the Ottoman constitution of 1876 and the establishment of a constitutional government.",
      "date": "1908"
    },
    {
      "headline": "Rise to Power",
      "text": "Following the revolution, the Young Turks, particularly the CUP, gained significant political power and influence within the Ottoman Empire.",
      "date": "1908"
    },
    {
      "headline": "Balkan Wars",
      "text": "The Young Turks were in power during the Balkan Wars (1912-1913), which resulted in significant territorial losses for the Ottoman Empire.",
      "date": "1912"
    },
    {
      "headline": "World War I",
      "text": "The Young Turks, under the leadership of the CUP, led the Ottoman Empire into World War I on the side of the Central Powers.",
      "date": "1914"
    },
    {
      "headline": "End of Young Turks' Rule",
      "text": "The defeat of the Ottoman Empire in World War I led to the end of the Young Turks' rule and the eventual dissolution of the empire.",
      "date": "1918"
    }
  ]
}

