    {
      "headline": "Formation of the Mekong River",
      "text": "The Mekong River, one of the world's major rivers, formed over millions of years through geological processes. It originates from the Tibetan Plateau and flows through several countries in East Asia and Southeast Asia.",
      "date": "-10000000"
    },
    {
      "headline": "Early Human Settlements",
      "text": "Human settlements along the Mekong River date back thousands of years. The river has been a vital source of water, food, and transportation for early civilizations in the region.",
      "date": "-3000"
    },
    {
      "headline": "Mekong as a Trade Route",
      "text": "Throughout history, the Mekong River has served as a major trade route, facilitating commerce between Tibet and Southeast Asia. Its strategic location has made it an important economic artery for the region.",
      "date": "0000"
    },
    {
      "headline": "French Exploration",
      "text": "In the 19th century, French explorers, including Francis Garnier, conducted extensive surveys of the Mekong River, contributing to Western knowledge of the region.",
      "date": "1866"
