  "timeline": [
    {
      "headline": "Introduction of the Three-Point Line in Professional Basketball",
      "text": "The three-point line was first introduced in professional basketball by the American Basketball League (ABL) in 1961. This was the first time a shot made from beyond a designated arc was awarded three points.",
      "date": "1961"
    },
    {
      "headline": "Adoption by the American Basketball Association (ABA)",
      "text": "The American Basketball Association (ABA) adopted the three-point line for its inaugural season in 1967-68, popularizing the concept further.",
      "date": "1967"
    },
    {
      "headline": "NBA Adopts the Three-Point Line",
      "text": "The National Basketball Association (NBA) officially adopted the three-point line at the start of the 1979-80 season, marking a significant change in the game's strategy.",
      "date": "1979"
    },
    {
      "headline": "First Three-Point Field Goal in NBA History",
      "text": "Chris Ford of the Boston Celtics made the first three-point field goal in NBA history on October 12, 1979, during a game against the Houston Rockets.",
      "date": "1979-10-12"
    },
    {
      "headline": "Introduction of the Three-Point Line in NCAA Basketball",
      "text": "The NCAA introduced the three-point line for men's basketball on a trial basis in 1980, with a distance of 22 feet. It became a permanent rule in the 1986-87 season.",
      "date": "1986"
    },
    {
      "headline": "FIBA Adopts the Three-Point Line",
      "text": "The International Basketball Federation (FIBA) adopted the three-point line in 1984, further globalizing the rule.",
      "date": "1984"
    },
    {
      "headline": "WNBA Adopts the Three-Point Line",
      "text": "The Women's National Basketball Association (WNBA) adopted the three-point line in its inaugural season in 1997.",
      "date": "1997"
    },
    {
      "headline": "NBA Three-Point Line Distance Change",
      "text": "The NBA changed the distance of the three-point line from 23 feet 9 inches to a uniform 22 feet for the 1994-95, 1995-96, and 1996-97 seasons before reverting to the original distance.",
      "date": "1994"
    }
  ]
}

