{
  "timeline": [
    {
      "headline": "Überlingen Mid-Air Collision",
      "text": "On 1 July 2002, BAL Bashkirian Airlines Flight 2937, a Tupolev Tu-154M passenger jet, and DHL International Aviation ME Flight 611, a Boeing 757 cargo jet, collided in mid-air over Überlingen, a southern German town on Lake Constance, near the Swiss border. All of the passengers and crew aboard both planes were killed, resulting in a total death toll of 71.",
      "date": "2002-07-01"
    },
    {
      "headline": "Investigation Begins",
      "text": "Following the collision on 1 July 2002, investigations were launched by the German Federal Bureau of Aircraft Accident Investigation (BFU) to determine the causes of the accident.",
      "date": "2002-07"
    },
    {
      "headline": "Release of Final Report",
      "text": "On 19 May 2004, the German Federal Bureau of Aircraft Accident Investigation (BFU) released its final report, which concluded that the collision was caused by a series of human errors and technical failures, including issues with air traffic control and the TCAS (Traffic Collision Avoidance System).",
      "date": "2004-05-19"
    },
    {
      "headline": "Peter Nielsen's Death",
      "text": "On 24 February 2004, Peter Nielsen, the air traffic controller on duty at the time of the collision, was stabbed to death by Vitaly Kaloyev, a Russian architect who lost his family in the crash.",
      "date": "2004-02-24"
    },
    {
      "headline": "Vitaly Kaloyev's Conviction",
      "text": "In October 2005, Vitaly Kaloyev was convicted of the murder of Peter Nielsen and was sentenced to eight years in prison by a Swiss court.",
      "date": "2005-10"
    },
    {
      "headline": "Vitaly Kaloyev's Release",
      "text": "On 8 November 2007, Vitaly Kaloyev was released from prison after serving less than three years of his sentence, due to good behavior and the time he had already spent in custody.",
      "date": "2007-11-08"
    }
  ]
}

