{
  "timeline": [
    {
      "headline": "Pre-contact Period",
      "text": "The Mi'kmaq people inhabited the northeastern region of North America, including present-day Nova Scotia, New Brunswick, Prince Edward Island, Newfoundland, and the Gaspé Peninsula of Quebec, as well as parts of Maine. Their society was organized into a loose confederation of seven districts.",
      "date": "-1000"
    },
    {
      "headline": "First European Contact",
      "text": "The Mi'kmaq were among the first Indigenous peoples in North America to have contact with Europeans. This occurred when John Cabot arrived in 1497.",
      "date": "1497"
    },
    {
      "headline": "Mi'kmaq-French Alliance",
      "text": "The Mi'kmaq formed an alliance with the French in the early 17th century, which was solidified through trade and intermarriage. This alliance was crucial during the colonial conflicts between the French and the British.",
      "date": "1600"
    },
    {
      "headline": "Treaty of 1725",
      "text": "The Mi'kmaq signed a series of treaties with the British, starting with the Treaty of 1725, which aimed to establish peace and friendship.",
      "date": "1725"
    },
    {
      "headline": "Mi'kmaq Involvement in the French and Indian War",
      "text": "During the French and Indian War (1754-1763), the Mi'kmaq supported the French against the British, continuing their long-standing alliance.",
      "date": "1754"
    },
    {
      "headline": "Treaty of 1760-1761",
      "text": "The Mi'kmaq signed treaties with the British in 1760 and 1761, reaffirming peace and friendship and allowing for British settlement in their territories.",
      "date": "1760"
    },
    {
      "headline": "Recognition of Mi'kmaq Rights",
      "text": "In the 20th and 21st centuries, the Mi'kmaq have been involved in legal battles to assert their treaty rights, leading to significant court rulings such as the 1999 Supreme Court of Canada decision in R v. Marshall, which affirmed their rights to hunt, fish, and gather for a moderate livelihood.",
      "date": "1999"
    }
  ]
}

