      "headline": "German Invasion of France",
      "text": "In August 1914, the German army invaded France with a plan to win the war in 40 days by occupying Paris and destroying the French and British armies.",
      "date": "1914-08"
    },
    {
      "headline": "Battles of Mons and the Frontiers",
      "text": "The Germans achieved initial successes in August 1914, being victorious in the Battles of Mons and the Frontiers, and overran a large area of northern France and Belgium.",
      "date": "1914-08"
    },
    {
      "headline": "The Great Retreat",
      "text": "Following their victories, the Germans pursued the retreating Franco/British forces more than 250 km (160 mi) southward in what is called the Great Retreat.",
      "date": "1914-08"
    },
    {
      "headline": "Germans Advance to the Marne River",
      "text": "By early September 1914, the German forces advanced to within 40 km of Paris, reaching the Marne River valley.",
      "date": "1914-09"
    },
    {
      "headline": "First Battle of the Marne Begins",
      "text": "The First Battle of the Marne began on September 5, 1914, as the French and British forces halted their retreat and engaged the advancing German army.",
      "date": "1914-09-05"
    },
    {
      "headline": "End of the First Battle of the Marne",
      "text": "The battle concluded on September 12, 1914, with the Allies successfully halting the German advance, marking a significant turning point in the war.",
      "date": "1914-09-12"
    }
  ]
}

