      "headline": "Nabopolassar's Reign",
      "text": "Nabopolassar, a Chaldean, established the Neo-Babylonian Empire and ruled from 626 BCE to 605 BCE, leading a revolt against the Assyrian Empire.",
      "date": "-0626"
    },
    {
      "headline": "Nebuchadnezzar II's Reign",
      "text": "Nebuchadnezzar II, son of Nabopolassar, ruled from 605 BCE to 562 BCE. He is known for his military conquests and the construction of the Hanging Gardens of Babylon.",
      "date": "-0605"
    },
    {
      "headline": "Fall of the Neo-Babylonian Empire",
      "text": "The Neo-Babylonian Empire, under Chaldean rule, fell to the Persian Empire in 539 BCE, leading to the absorption and assimilation of Chaldea into Babylonia.",
      "date": "-0539"
    }
  ]
}

