  "timeline": [
    {
      "headline": "Birth of Omar Khayyam",
      "text": "Omar Khayyam was born on May 18, 1048, in Nishapur, which was then part of the Seljuk Empire.",
      "date": "1048-05-18"
    },
    {
      "headline": "Education in Nishapur",
      "text": "Omar Khayyam received his early education in Nishapur, where he studied under the guidance of renowned scholars of the time.",
      "date": "1060"
    },
    {
      "headline": "Move to Samarkand",
      "text": "In the 1070s, Omar Khayyam moved to Samarkand, a major center of learning, where he continued his studies and began his work in mathematics and astronomy.",
      "date": "1070"
    },
    {
      "headline": "Publication of Treatise on Algebra",
      "text": "Around 1070, Omar Khayyam wrote his famous treatise on algebra, 'Treatise on Demonstration of Problems of Algebra', which included a geometric method for solving cubic equations.",
      "date": "1070"
    },
    {
      "headline": "Appointment at the Seljuk Court",
      "text": "In 1074, Omar Khayyam was invited to the Seljuk court in Isfahan by Sultan Malik Shah I, where he was appointed to reform the calendar and work on astronomical observations.",
      "date": "1074"
    },
    {
      "headline": "Jalali Calendar Reform",
      "text": "In 1079, Omar Khayyam reformed the Persian calendar, creating the Jalali calendar, which was more accurate than the Gregorian calendar in use at the time.",
      "date": "1079"
    },
    {
      "headline": "Return to Nishapur",
      "text": "After the death of Sultan Malik Shah I in 1092, Omar Khayyam returned to Nishapur, where he spent the rest of his life focusing on poetry and philosophy.",
      "date": "1092"
    },
    {
      "headline": "Writing of the Rubaiyat",
      "text": "During his later years in Nishapur, Omar Khayyam composed his famous collection of quatrains, known as the 'Rubaiyat', which gained widespread popularity posthumously.",
      "date": "1100"
    },
    {
      "headline": "Death of Omar Khayyam",
      "text": "Omar Khayyam passed away on December 4, 1131, in Nishapur, leaving behind a legacy of significant contributions to mathematics, astronomy, and literature.",
      "date": "1131-12-04"
    }
  ]
}

