{
  "timeline": [
    {
      "headline": "Creation of Congress Poland",
      "text": "Congress Poland, also known as the Congress Kingdom of Poland, was created in 1815 by the Congress of Vienna. It was established as a semi-autonomous Polish state under the Russian Empire, following the defeat of Napoleon and the ceding of Polish territory by France.",
      "date": "1815"
    },
    {
      "headline": "Constitution of Congress Poland",
      "text": "In 1815, Congress Poland was granted a constitution by Tsar Alexander I of Russia. This constitution provided for a constitutional monarchy with a parliament, although the Tsar retained significant control.",
      "date": "1815"
    },
    {
      "headline": "November Uprising",
      "text": "The November Uprising, also known as the Polish-Russian War 1830-31, began in November 1830. It was an armed rebellion against the Russian Empire's rule over Congress Poland.",
      "date": "1830-11"
    },
    {
      "headline": "Suppression of the November Uprising",
      "text": "The November Uprising was suppressed by the Russian Empire in 1831, leading to the loss of Congress Poland's autonomy and the imposition of stricter Russian control.",
      "date": "1831"
    },
    {
      "headline": "January Uprising",
      "text": "The January Uprising was another major insurrection against Russian rule, beginning in January 1863. It was a widespread movement involving many parts of Poland and Lithuania.",
      "date": "1863-01"
    },
    {
      "headline": "End of the January Uprising",
      "text": "The January Uprising was ultimately crushed by the Russian Empire in 1864, resulting in further repression and the Russification of Congress Poland.",
      "date": "1864"
    },
    {
      "headline": "Abolition of Congress Poland",
      "text": "In 1867, following the suppression of the January Uprising, Congress Poland was effectively abolished as a separate entity and fully integrated into the Russian Empire as the Vistula Land.",
      "date": "1867"
    },
    {
      "headline": "World War I and the Regency Kingdom",
      "text": "During World War I, in 1915, Congress Poland was replaced by the German-controlled nominal Regency Kingdom, as the Central Powers occupied the region.",
      "date": "1915"
    },
    {
      "headline": "Regaining Independence",
      "text": "Poland regained its independence in 1918, following the end of World War I and the collapse of the occupying powers.",
      "date": "1918"
    }
  ]
}

