{
  "timeline": [
    {
      "headline": "Foundation of the Kingdom of Sicily",
      "text": "The Kingdom of Sicily was founded by Roger II of Sicily in 1130. It was established as a successor state to the County of Sicily.",
      "date": "1130"
    },
    {
      "headline": "Coronation of Roger II",
      "text": "Roger II was crowned as the first King of Sicily on December 25, 1130, marking the official establishment of the kingdom.",
      "date": "1130-12-25"
    },
    {
      "headline": "Constitution of Melfi",
      "text": "In 1231, Emperor Frederick II issued the Constitutions of Melfi, a set of laws that centralized royal authority and reformed the administration of the Kingdom of Sicily.",
      "date": "1231"
    },
    {
      "headline": "Sicilian Vespers",
      "text": "The Sicilian Vespers was a rebellion that began on March 30, 1282, against the rule of the Angevin king Charles I of Naples, leading to the War of the Sicilian Vespers.",
      "date": "1282-03-30"
    },
    {
      "headline": "Aragonese Rule",
      "text": "Following the Sicilian Vespers, the Kingdom of Sicily came under the rule of the Crown of Aragon in 1282, marking a significant shift in power.",
      "date": "1282"
    },
    {
      "headline": "Peace of Caltabellotta",
      "text": "The Peace of Caltabellotta was signed in 1302, ending the War of the Sicilian Vespers and confirming Frederick III as King of Sicily.",
      "date": "1302"
    },
    {
      "headline": "Union with the Kingdom of Naples",
      "text": "In 1442, Alfonso V of Aragon united the Kingdom of Sicily with the Kingdom of Naples, creating a personal union under the Crown of Aragon.",
      "date": "1442"
    },
    {
      "headline": "Spanish Rule",
      "text": "The Kingdom of Sicily came under Spanish rule in 1516, following the death of Ferdinand II of Aragon, as part of the Spanish Empire.",
      "date": "1516"
    },
    {
      "headline": "Austrian Rule",
      "text": "The Treaty of Utrecht in 1713 transferred the Kingdom of Sicily to the House of Savoy, but it was later ceded to Austria in 1720.",
      "date": "1720"
    },
    {
      "headline": "Bourbon Rule",
      "text": "In 1735, the Kingdom of Sicily came under the rule of the Bourbon dynasty, which established a separate kingdom from Naples.",
      "date": "1735"
    },
    {
      "headline": "Napoleonic Wars and British Protectorate",
      "text": "During the Napoleonic Wars, the Kingdom of Sicily became a British protectorate from 1806 to 1815, providing refuge for the Bourbon monarchy.",
      "date": "1806"
    },
    {
      "headline": "End of the Kingdom of Sicily",
      "text": "The Kingdom of Sicily was officially dissolved in 1816, when it was merged with the Kingdom of Naples to form the Kingdom of the Two Sicilies.",
      "date": "1816"
    }
  ]
}

