  "timeline": [
    {
      "headline": "Invention of Writing",
      "text": "The earliest writing was invented during the late 4th millennium BC. This period marks the transition from proto-writing to true writing systems capable of encoding spoken language.",
      "date": "-03900"
    },
    {
      "headline": "Development of Cuneiform",
      "text": "Cuneiform script, one of the earliest systems of writing, was developed by the Sumerians of ancient Mesopotamia around 3200 BC. It began as a system of pictographs.",
      "date": "-03200"
    },
    {
      "headline": "Egyptian Hieroglyphs",
      "text": "Egyptian hieroglyphs were developed around 3100 BC. This writing system used a combination of logographic and alphabetic elements.",
      "date": "-03100"
    },
    {
      "headline": "Chinese Oracle Bone Script",
      "text": "The earliest form of Chinese writing, known as Oracle Bone Script, dates back to the late Shang dynasty around 1200 BC.",
      "date": "-01200"
    },
    {
      "headline": "Phoenician Alphabet",
      "text": "The Phoenician alphabet, developed around 1050 BC, is one of the first alphabets and is the ancestor of most modern alphabets.",
      "date": "-01050"
    },
    {
      "headline": "Greek Alphabet",
      "text": "The Greek alphabet was developed around 800 BC. It was the first writing system to have distinct letters for vowels and consonants.",
      "date": "-00800"
    },
    {
      "headline": "Development of Latin Script",
      "text": "The Latin script, which is the basis for the modern English alphabet, was developed around 700 BC by the Romans.",
      "date": "-00700"
    },
    {
      "headline": "Brahmi Script",
      "text": "The Brahmi script, an ancient writing system of India, was developed around the 3rd century BC and is the ancestor of many modern scripts in South Asia.",
      "date": "-0300"
    },
    {
      "headline": "Arabic Script",
      "text": "The Arabic script was developed in the 4th century AD. It is used in a variety of languages, including Arabic and Persian.",
      "date": "0400"
    },
    {
      "headline": "Invention of Printing Press",
      "text": "The invention of the printing press by Johannes Gutenberg in the 15th century revolutionized the dissemination of writing systems and literature.",
      "date": "1450"
    }
  ]
}

