{
  "timeline": [
    {
      "headline": "Foundation of Trier",
      "text": "Trier is believed to have been founded by the Celts in the late 4th century BCE, making it one of the oldest cities in Germany.",
      "date": "-0399"
    },
    {
      "headline": "Roman Conquest",
      "text": "Around 16 BCE, the Romans conquered the region and established Augusta Treverorum, which became an important Roman city.",
      "date": "-0016"
    },
    {
      "headline": "Capital of the Roman Province",
      "text": "In the late 3rd century, Trier became the capital of the Roman province of Gallia Belgica.",
      "date": "0275"
    },
    {
      "headline": "Imperial Residence",
      "text": "From 293 to 395, Trier served as one of the capitals of the Western Roman Empire and was a residence of several Roman emperors.",
      "date": "0293"
    },
    {
      "headline": "Christianization",
      "text": "In the 4th century, Trier became a major center of Christianity in the Roman Empire, with the establishment of the bishopric.",
      "date": "0300"
    },
    {
      "headline": "Destruction by Franks",
      "text": "In 406, Trier was sacked by the Franks, leading to a decline in its importance.",
      "date": "0406"
    },
    {
      "headline": "Frankish Rule",
      "text": "By the 5th century, Trier came under Frankish rule as the Roman Empire's influence waned.",
      "date": "0500"
    },
    {
      "headline": "Medieval Prosperity",
      "text": "During the Middle Ages, Trier regained some of its importance as a religious and cultural center.",
      "date": "1000"
    },
    {
      "headline": "French Occupation",
      "text": "Trier was occupied by French revolutionary troops in 1794 during the French Revolutionary Wars.",
      "date": "1794"
    },
    {
      "headline": "Annexation to Prussia",
      "text": "After the defeat of Napoleon, Trier was annexed to the Kingdom of Prussia in 1815.",
      "date": "1815"
    },
    {
      "headline": "World War II Destruction",
      "text": "Trier suffered significant damage during World War II due to Allied bombing raids.",
      "date": "1944"
    },
    {
      "headline": "Post-War Reconstruction",
      "text": "After World War II, Trier underwent extensive reconstruction and became part of the newly formed state of Rhineland-Palatinate in 1946.",
      "date": "1946"
    }
  ]
}

