{
  "timeline": [
    {
      "headline": "Ancient Bowling Origins",
      "text": "The earliest known forms of bowling date back to ancient Egypt, around 3200 BCE, where objects resembling pins and balls were found in a child's grave.",
      "date": "-3200"
    },
    {
      "headline": "Medieval Bowling in Germany",
      "text": "In 300 CE, a form of bowling was played in Germany, where participants would roll a stone at a club (kegel), which later evolved into the game of Kegeln.",
      "date": "0300"
    },
    {
      "headline": "Bowling in England",
      "text": "By 1366, bowling was popular in England, but King Edward III allegedly banned it to keep his troops focused on archery practice.",
      "date": "1366"
    },
    {
      "headline": "Introduction of Lawn Bowling",
      "text": "In the 15th century, lawn bowling became popular in England, with the oldest surviving bowling green dating back to 1299 in Southampton.",
      "date": "1400"
    },
    {
      "headline": "Nine-Pin Bowling in America",
      "text": "In the 17th century, Dutch settlers brought nine-pin bowling to America, particularly in New York.",
      "date": "1600"
    },
    {
      "headline": "Ten-Pin Bowling Emergence",
      "text": "In the early 19th century, ten-pin bowling emerged in the United States as a variation of the traditional nine-pin game.",
      "date": "1800"
    },
    {
      "headline": "Formation of the American Bowling Congress",
      "text": "On September 9, 1895, the American Bowling Congress (ABC) was formed in New York City to standardize the rules of ten-pin bowling.",
      "date": "1895-09-09"
    },
    {
      "headline": "Invention of the Automatic Pinsetter",
      "text": "In 1951, the automatic pinsetter was invented by Gottfried Schmidt, revolutionizing the game by eliminating the need for manual pinsetters.",
      "date": "1951"
    },
    {
      "headline": "Formation of the Professional Bowlers Association",
      "text": "In 1958, the Professional Bowlers Association (PBA) was founded, providing a platform for professional ten-pin bowlers.",
      "date": "1958"
    },
    {
      "headline": "Bowling in the Olympics",
      "text": "Bowling was featured as a demonstration sport in the 1988 Summer Olympics in Seoul, South Korea.",
      "date": "1988"
    }
  ]
}

