      "headline": "Foundation of Pataliputra",
      "text": "Pataliputra, the ancient name for Patna, was founded in the 5th century BCE by Ajatashatru, the king of Magadha. It was initially built as a small fort (Pataligrama) near the Ganges River.",
      "date": "-0500"
    },
    {
      "headline": "Capital of the Maurya Empire",
      "text": "In the 4th century BCE, Pataliputra became the capital of the Maurya Empire under Chandragupta Maurya. It was a major political, military, and economic center of India.",
      "date": "-0321"
    },
    {
      "headline": "Ashoka's Reign",
      "text": "During the reign of Emperor Ashoka (268–232 BCE), Pataliputra was a center of administration and culture. Ashoka's rule marked the spread of Buddhism from Pataliputra to other parts of Asia.",
      "date": "-0268"
    },
    {
      "headline": "Gupta Empire",
      "text": "Pataliputra served as a significant city during the Gupta Empire, which is often referred to as the Golden Age of India, from the 4th to the 6th century CE.",
      "date": "0320"
    },
    {
      "headline": "Decline and Destruction",
      "text": "Pataliputra faced decline and was eventually destroyed by the invasion of the Huns in the 5th century CE.",
      "date": "0500"
    },
    {
      "headline": "Revival under Sher Shah Suri",
      "text": "In the 16th century, Sher Shah Suri revived the city, renaming it Patna. He built a fort and other structures, marking a period of redevelopment.",
      "date": "1541"
    },
    {
      "headline": "British Colonial Era",
      "text": "During the British colonial period, Patna became an important center for trade and administration in the 18th century.",
      "date": "1765"
    },
    {
      "headline": "Bihar and Orissa Province",
      "text": "In 1912, Patna became the capital of the newly created Bihar and Orissa Province under British rule.",
      "date": "1912"
    },
    {
      "headline": "Independence and Modern Era",
      "text": "After India gained independence in 1947, Patna continued to grow as the capital of Bihar. It developed into a major educational and cultural center.",
      "date": "1947"
    },
    {
      "headline": "Population Growth",
      "text": "By 2018, Patna had a population of 2.35 million, making it the 19th largest city in India.",
      "date": "2018"
    }
  ]
}

