{
  "timeline": [
    {
      "headline": "Inception of the GED Program",
      "text": "The General Educational Development (GED) program was initiated by the American Council on Education in 1942. It was created to help World War II veterans who had not completed high school to demonstrate their academic skills and knowledge.",
      "date": "1942"
    },
    {
      "headline": "Expansion to Civilians",
      "text": "In 1947, the GED testing program was expanded to include civilians. This allowed non-veterans who had not completed high school to also earn a high school equivalency credential.",
      "date": "1947"
    },
    {
      "headline": "First Major Revision",
      "text": "The GED test underwent its first major revision in 1978 to better reflect the changing educational standards and requirements.",
      "date": "1978"
    },
    {
      "headline": "Second Major Revision",
      "text": "In 1988, the GED test was revised again to include a writing component, which required test-takers to write an essay.",
      "date": "1988"
    },
    {
      "headline": "Third Major Revision",
      "text": "The GED test was revised in 2002 to align with the standards of high school curricula and to ensure the test remained a valid measure of high school equivalency.",
      "date": "2002"
    },
    {
      "headline": "Fourth Major Revision",
      "text": "In 2014, the GED test was updated to a computer-based format and aligned with the Common Core State Standards, focusing on critical thinking and problem-solving skills.",
      "date": "2014"
    }
  ]
}

