{
  "timeline": [
    {
      "headline": "Discovery of Photovoltaic Effect",
      "text": "In 1839, French physicist Edmond Becquerel discovered the photovoltaic effect, which is the principle behind solar power generation.",
      "date": "1839"
    },
    {
      "headline": "First Solar Cell",
      "text": "In 1883, Charles Fritts built the first solar cell by coating selenium with a thin layer of gold.",
      "date": "1883"
    },
    {
      "headline": "Einstein's Photoelectric Effect Paper",
      "text": "In 1905, Albert Einstein published a paper on the photoelectric effect, explaining how light can release electrons from a material, which is a fundamental principle of solar power.",
      "date": "1905"
    },
    {
      "headline": "First Practical Photovoltaic Cell",
      "text": "In 1954, Bell Labs developed the first practical photovoltaic cell, which was capable of converting sunlight into electricity with an efficiency of 6%.",
      "date": "1954"
    },
    {
      "headline": "Launch of Vanguard 1",
      "text": "In 1958, Vanguard 1 became the first satellite to use solar power, marking the beginning of solar energy use in space.",
      "date": "1958"
    },
    {
      "headline": "Oil Crisis Spurs Solar Interest",
      "text": "The 1973 oil crisis led to increased interest and investment in solar energy as a renewable energy source.",
      "date": "1973"
    },
    {
      "headline": "First Solar-Powered Building",
      "text": "In 1977, the University of Delaware built 'Solar One,' one of the first solar-powered buildings.",
      "date": "1977"
    },
    {
      "headline": "Formation of Solar Energy Industries Association",
      "text": "In 1974, the Solar Energy Industries Association (SEIA) was formed to promote solar energy development.",
      "date": "1974"
    },
    {
      "headline": "Photovoltaic Manufacturing Technology Program",
      "text": "In 1991, the U.S. Department of Energy launched the Photovoltaic Manufacturing Technology (PVMaT) program to improve solar cell manufacturing processes.",
      "date": "1991"
    },
    {
      "headline": "Germany's Renewable Energy Act",
      "text": "In 2000, Germany passed the Renewable Energy Act, which significantly boosted solar energy adoption through feed-in tariffs.",
      "date": "2000"
    },
    {
      "headline": "Solar Power Becomes Cost-Competitive",
      "text": "By 2010, solar power became increasingly cost-competitive with traditional energy sources, leading to a rapid expansion of solar installations worldwide.",
      "date": "2010"
    },
    {
      "headline": "Largest Solar Farm in the World",
      "text": "In 2016, the Tengger Desert Solar Park in China became the largest solar farm in the world, covering 43 square kilometers.",
      "date": "2016"
    },
    {
      "headline": "Record Solar Capacity Addition",
      "text": "In 2020, global solar capacity additions reached a record high, with over 115 gigawatts of new installations.",
      "date": "2020"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "House Un-American Activities Committee (HUAC) Hearings Begin",
      "text": "In October 1947, the House Un-American Activities Committee (HUAC) began investigating alleged communist influence and infiltration in the Hollywood film industry.",
      "date": "1947-10"
    },
    {
      "headline": "Hollywood Ten Refuse to Testify",
      "text": "On November 25, 1947, ten writers and directors, later known as the Hollywood Ten, refused to testify before HUAC, citing their First Amendment rights.",
      "date": "1947-11-25"
    },
    {
      "headline": "Hollywood Ten Sentenced",
      "text": "In 1948, the Hollywood Ten were convicted of contempt of Congress and sentenced to prison terms.",
      "date": "1948"
    },
    {
      "headline": "Waldorf Statement Issued",
      "text": "On November 25, 1947, the heads of major Hollywood studios issued the Waldorf Statement, announcing the firing of the Hollywood Ten and the establishment of the blacklist.",
      "date": "1947-11-25"
    },
    {
      "headline": "Blacklist Expands",
      "text": "Throughout the late 1940s and 1950s, the blacklist expanded to include hundreds of actors, writers, directors, and other entertainment professionals.",
      "date": "1948-1959"
    },
    {
      "headline": "Dalton Trumbo's Screenwriting Credit",
      "text": "In 1960, Dalton Trumbo, one of the Hollywood Ten, was publicly credited for his work on the films 'Exodus' and 'Spartacus', marking the beginning of the end of the blacklist.",
      "date": "1960"
    },
    {
      "headline": "End of the Blacklist",
      "text": "By the early 1960s, the Hollywood blacklist effectively ended as blacklisted individuals began to be hired again in the industry.",
      "date": "1960-1962"
    }
  ]
}

