      "headline": "Founding of Rouen",
      "text": "Rouen was founded by the Gauls before the Roman conquest of Gaul. The city became an important settlement during the Roman period.",
      "date": "-0050"
    },
    {
      "headline": "Roman Era",
      "text": "During the Roman era, Rouen, known as Rotomagus, became the second city of Gallia Lugdunensis after Lugdunum (Lyon).",
      "date": "0020"
    },
    {
      "headline": "Christianization",
      "text": "Rouen became a center for Christianity in the 3rd century, with the establishment of a bishopric.",
      "date": "0250"
    },
    {
      "headline": "Viking Invasion",
      "text": "Rouen was captured by Viking invaders in 841, marking the beginning of Norse influence in the region.",
      "date": "0841"
    },
    {
      "headline": "Treaty of Saint-Clair-sur-Epte",
      "text": "In 911, the Treaty of Saint-Clair-sur-Epte was signed, granting the Duchy of Normandy to the Viking leader Rollo, with Rouen as its capital.",
      "date": "0911"
    },
    {
      "headline": "Construction of Rouen Cathedral",
      "text": "The construction of Rouen Cathedral began in the 12th century, becoming a major Gothic architectural landmark.",
      "date": "1145"
    },
    {
      "headline": "Hundred Years' War",
      "text": "Rouen was captured by the English in 1419 during the Hundred Years' War and remained under English control until 1449.",
      "date": "1419"
    },
    {
      "headline": "Joan of Arc's Trial and Execution",
      "text": "Joan of Arc was tried and executed in Rouen in 1431, marking a significant event in the city's history.",
      "date": "1431"
    },
    {
      "headline": "Return to French Control",
      "text": "Rouen was recaptured by the French in 1449, ending English control of the city.",
      "date": "1449"
    },
    {
      "headline": "Industrial Revolution",
      "text": "During the 19th century, Rouen became an important industrial center, particularly in the textile industry.",
      "date": "1800"
    },
    {
      "headline": "World War II",
      "text": "Rouen suffered significant damage during World War II, particularly during the Allied bombing raids in 1944.",
      "date": "1944"
    },
    {
      "headline": "Post-War Reconstruction",
      "text": "After World War II, Rouen underwent extensive reconstruction to restore its historical buildings and infrastructure.",
      "date": "1945"
    }
  ]
}

