{
  "timeline": [
    {
      "headline": "Founding of Atari, Inc.",
      "text": "Atari, Inc. was founded by Nolan Bushnell and Ted Dabney in Sunnyvale, California, in June 1972. The company became a pioneer in arcade games, home video game consoles, and home computers.",
      "date": "1972-06"
    },
    {
      "headline": "Release of Pong",
      "text": "In November 1972, Atari released Pong, one of the first arcade video games. Pong became a commercial success and helped establish the video game industry.",
      "date": "1972-11"
    },
    {
      "headline": "Launch of Atari 2600",
      "text": "The Atari 2600, originally branded as the Atari Video Computer System (VCS), was released in September 1977. It became one of the first successful home video game consoles.",
      "date": "1977-09"
    },
    {
      "headline": "Warner Communications Acquisition",
      "text": "In 1976, Atari was acquired by Warner Communications for approximately $28 million. This acquisition provided Atari with the resources to expand its operations.",
      "date": "1976"
    },
    {
      "headline": "Release of Space Invaders for Atari 2600",
      "text": "In 1980, Atari released Space Invaders for the Atari 2600, which became the first 'killer app' for the console, significantly boosting its sales.",
      "date": "1980"
    },
    {
      "headline": "Atari 5200 Release",
      "text": "In November 1982, Atari released the Atari 5200, a new home video game console intended to compete with other consoles like the Intellivision and ColecoVision.",
      "date": "1982-11"
    },
    {
      "headline": "Video Game Crash of 1983",
      "text": "The video game crash of 1983 severely impacted Atari's business, leading to significant financial losses and a decline in the video game industry.",
      "date": "1983"
    },
    {
      "headline": "Split of Atari, Inc.",
      "text": "In July 1984, Warner Communications sold the home console and computer divisions of Atari, Inc. to Jack Tramiel, who founded Atari Corporation. The arcade division was retained by Warner and renamed Atari Games.",
      "date": "1984-07"
    },
    {
      "headline": "Atari ST Release",
      "text": "In 1985, Atari Corporation released the Atari ST, a home computer that became popular for its graphical user interface and MIDI capabilities.",
      "date": "1985"
    },
    {
      "headline": "Release of Atari Jaguar",
      "text": "In 1993, Atari Corporation released the Atari Jaguar, a 64-bit home video game console. Despite its advanced technology, it struggled to compete with other consoles.",
      "date": "1993"
    },
    {
      "headline": "Merger with JTS Corporation",
      "text": "In 1996, Atari Corporation merged with JTS Corporation, a maker of hard disk drives, effectively ending Atari's role as a video game company.",
      "date": "1996"
    },
    {
      "headline": "Acquisition by Hasbro Interactive",
      "text": "In 1998, Hasbro Interactive acquired the Atari brand and intellectual property from JTS Corporation, reviving the Atari name in the video game industry.",
      "date": "1998"
    },
    {
      "headline": "Infogrames Entertainment SA Acquisition",
      "text": "In 2001, Infogrames Entertainment SA acquired Hasbro Interactive, including the Atari brand, and later rebranded itself as Atari SA.",
      "date": "2001"
    }
  ]
}

