    }
  ]
}

{
  "timeline": [
    {
      "headline": "First Mention of Moravia",
      "text": "The first known mention of Moravia is in the 2nd century by the geographer Ptolemy, who referred to the Marcomanni tribe inhabiting the region.",
      "date": "0100"
    },
    {
      "headline": "Formation of Great Moravia",
      "text": "Great Moravia was established as a Slavic state in the early 9th century, around 833, under the leadership of Mojmir I.",
      "date": "0833"
    },
    {
      "headline": "Cyril and Methodius Arrive in Moravia",
      "text": "In 863, the Byzantine brothers Cyril and Methodius arrived in Moravia to spread Christianity and develop the Glagolitic alphabet.",
      "date": "0863"
    },
    {
      "headline": "Decline of Great Moravia",
      "text": "Great Moravia began to decline after the death of its ruler Svatopluk I in 894, eventually collapsing under Magyar attacks by 907.",
      "date": "0907"
    },
    {
      "headline": "Incorporation into the Kingdom of Bohemia",
      "text": "In 1029, Moravia was incorporated into the Kingdom of Bohemia under the rule of the Přemyslid dynasty.",
      "date": "1029"
    },
    {
      "headline": "Moravia Becomes a Margraviate",
      "text": "In the 12th century, Moravia became a margraviate, a border province of the Holy Roman Empire, around 1182.",
      "date": "1182"
    },
    {
      "headline": "Hussite Wars",
      "text": "During the Hussite Wars (1419–1434), Moravia was a battleground between Hussite forces and Catholic loyalists.",
      "date": "1419"
    },
    {
      "headline": "Moravia Under Habsburg Rule",
      "text": "In 1526, Moravia came under Habsburg rule following the Battle of Mohács and the subsequent election of Ferdinand I as King of Bohemia.",
      "date": "1526"
    },
    {
      "headline": "Thirty Years' War Impact",
      "text": "Moravia suffered significant devastation during the Thirty Years' War (1618–1648), with many towns and villages destroyed.",
      "date": "1618"
    },
    {
      "headline": "Austro-Hungarian Compromise",
      "text": "In 1867, the Austro-Hungarian Compromise established the dual monarchy, with Moravia remaining part of the Austrian half.",
      "date": "1867"
    },
    {
      "headline": "Creation of Czechoslovakia",
      "text": "After World War I, Moravia became part of the newly formed Czechoslovakia in 1918.",
      "date": "1918"
    },
    {
      "headline": "Dissolution of Czechoslovakia",
      "text": "In 1993, Czechoslovakia peacefully split into the Czech Republic and Slovakia, with Moravia becoming part of the Czech Republic.",
      "date": "1993"
    }
  ]
}

