{
  "timeline": [
    {
      "headline": "Discovery of Hybridoma Technology",
      "text": "In 1975, Georges Köhler and César Milstein developed the hybridoma technology, which allows for the production of monoclonal antibodies. This groundbreaking work enabled the creation of antibodies that are identical and specific to a single antigen.",
      "date": "1975"
    },
    {
      "headline": "Nobel Prize in Physiology or Medicine",
      "text": "In 1984, Georges Köhler and César Milstein, along with Niels Kaj Jerne, were awarded the Nobel Prize in Physiology or Medicine for their work on the immune system and the development of monoclonal antibody technology.",
      "date": "1984"
    },
    {
      "headline": "First Monoclonal Antibody Approved",
      "text": "In 1986, the first monoclonal antibody, muromonab-CD3 (Orthoclone OKT3), was approved by the U.S. Food and Drug Administration (FDA) for clinical use. It was used to prevent kidney transplant rejection.",
      "date": "1986"
    },
    {
      "headline": "Approval of Rituximab",
      "text": "In 1997, rituximab (Rituxan), a monoclonal antibody used to treat certain types of cancer, was approved by the FDA. It marked a significant advancement in cancer therapy.",
      "date": "1997"
    },
    {
      "headline": "Approval of Trastuzumab",
      "text": "In 1998, trastuzumab (Herceptin) was approved by the FDA for the treatment of HER2-positive breast cancer, representing a major breakthrough in targeted cancer therapy.",
      "date": "1998"
    },
    {
      "headline": "Development of Humanized Monoclonal Antibodies",
      "text": "Throughout the 1990s and 2000s, advancements were made in the development of humanized and fully human monoclonal antibodies, reducing the risk of immune reactions and improving therapeutic efficacy.",
      "date": "1990-2000"
    },
    {
      "headline": "Approval of Adalimumab",
      "text": "In 2002, adalimumab (Humira), the first fully human monoclonal antibody, was approved by the FDA for the treatment of rheumatoid arthritis. It later became one of the best-selling drugs worldwide.",
      "date": "2002"
    },
    {
      "headline": "COVID-19 Pandemic and Monoclonal Antibodies",
      "text": "During the COVID-19 pandemic, monoclonal antibodies were developed and authorized for emergency use to treat COVID-19, providing an important tool in the fight against the virus.",
      "date": "2020"
    }
  ]
}

