    {
      "headline": "Inception of the TOP500 Project",
      "text": "The TOP500 project was initiated in 1993 to rank and detail the 500 most powerful non-distributed computer systems in the world. The project aims to provide a reliable basis for tracking and detecting trends in high-performance computing.",
      "date": "1993"
    },
    {
      "headline": "First TOP500 List Published",
      "text": "The first TOP500 list was published in June 1993, coinciding with the International Supercomputing Conference. This list ranked the most powerful supercomputers based on the HPL benchmark.",
      "date": "1993-06"
    },
    {
      "headline": "Biannual Updates Established",
      "text": "The TOP500 project established a schedule of biannual updates, with lists published in June and November each year. The June update coincides with the International Supercomputing Conference, and the November update is presented at the ACM/IEEE Supercomputing Conference.",
      "date": "1993"
    },
    {
      "headline": "Introduction of HPL Benchmark",
      "text": "The rankings in the TOP500 list are based on the HPL benchmark, a portable implementation of the high-performance LINPACK benchmark written in Fortran for distributed-memory computers.",
      "date": "1993"
    },
    {
      "headline": "25th Anniversary of TOP500",
      "text": "In 2018, the TOP500 project celebrated its 25th anniversary, marking a quarter-century of tracking the evolution of supercomputing power and trends.",
      "date": "2018"
    }
  ]
}

