{
  "timeline": [
    {
      "headline": "Introduction of Jizya",
      "text": "The concept of jizya is introduced in the Quran and hadiths, which mention it as a tax levied on non-Muslim subjects under Islamic rule. The exact date of its introduction is not specified, but it is believed to have been implemented during the early Islamic period.",
      "date": "0632"
    },
    {
      "headline": "Jizya under the Rashidun Caliphate",
      "text": "During the Rashidun Caliphate (632-661), jizya was implemented as part of the Islamic taxation system. It was adapted from pre-existing systems and modified according to Islamic law.",
      "date": "0632"
    },
    {
      "headline": "Jizya under the Umayyad Caliphate",
      "text": "The Umayyad Caliphate (661-750) continued the practice of levying jizya on non-Muslims, further institutionalizing it as a source of revenue for the state.",
      "date": "0661"
    },
    {
      "headline": "Jizya under the Abbasid Caliphate",
      "text": "During the Abbasid Caliphate (750-1258), jizya remained a significant tax, although its application and rates varied across different regions and periods.",
      "date": "0750"
    },
    {
      "headline": "Abolition of Jizya in the Ottoman Empire",
      "text": "In 1856, the Ottoman Empire officially abolished the jizya tax as part of the Tanzimat reforms, which aimed to modernize the empire and promote equality among its subjects.",
      "date": "1856"
    }
  ]
}

