{
  "timeline": [
    {
      "headline": "Declaration of War by France",
      "text": "On April 20, 1792, France declared war on Austria, marking the beginning of the War of the First Coalition.",
      "date": "1792-04-20"
    },
    {
      "headline": "Battle of Valmy",
      "text": "On September 20, 1792, the French army achieved a significant victory against Prussian forces at the Battle of Valmy, boosting French morale and solidifying the French Revolution.",
      "date": "1792-09-20"
    },
    {
      "headline": "Execution of King Louis XVI",
      "text": "On January 21, 1793, King Louis XVI of France was executed by guillotine, leading to increased tensions and the expansion of the coalition against France.",
      "date": "1793-01-21"
    },
    {
      "headline": "Battle of Neerwinden",
      "text": "On March 18, 1793, the French forces were defeated by the Austrians at the Battle of Neerwinden, leading to the loss of Belgium.",
      "date": "1793-03-18"
    },
    {
      "headline": "Reign of Terror Begins",
      "text": "In September 1793, the Reign of Terror began in France, characterized by mass executions of perceived enemies of the revolution.",
      "date": "1793-09"
    },
    {
      "headline": "Battle of Fleurus",
      "text": "On June 26, 1794, the French army won the Battle of Fleurus, which was a turning point that led to the recapture of Belgium.",
      "date": "1794-06-26"
    },
    {
      "headline": "Treaty of Basel",
      "text": "In April 1795, the Treaty of Basel was signed, resulting in Prussia's withdrawal from the coalition against France.",
      "date": "1795-04"
    },
    {
      "headline": "Battle of Rivoli",
      "text": "On January 14-15, 1797, the French forces under Napoleon Bonaparte defeated the Austrians at the Battle of Rivoli, securing French control over northern Italy.",
      "date": "1797-01-14"
    },
    {
      "headline": "Treaty of Campo Formio",
      "text": "On October 17, 1797, the Treaty of Campo Formio was signed between France and Austria, marking the end of the War of the First Coalition.",
      "date": "1797-10-17"
    }
  ]
}

