{
  "timeline": [
    {
      "headline": "Discovery of Phobos",
      "text": "Phobos, the innermost and larger of the two natural satellites of Mars, was discovered by American astronomer Asaph Hall on August 18, 1877.",
      "date": "1877-08-18"
    },
    {
      "headline": "Naming of Phobos",
      "text": "Phobos was named after the Greek god of fear and panic, who is the son of Ares (Mars) and twin brother of Deimos. The name was chosen to reflect its association with Mars.",
      "date": "1877"
    },
    {
      "headline": "First Close-up Images by Mariner 9",
      "text": "In 1971, NASA's Mariner 9 spacecraft became the first to capture close-up images of Phobos, providing detailed information about its surface and characteristics.",
      "date": "1971"
    },
    {
      "headline": "Viking 1 and Viking 2 Observations",
      "text": "The Viking 1 and Viking 2 missions, launched in 1975, provided further observations of Phobos, enhancing our understanding of its orbit and surface features.",
      "date": "1975"
    },
    {
      "headline": "Phobos 2 Mission",
      "text": "The Soviet Union's Phobos 2 mission, launched in 1988, aimed to study Phobos and Mars. Although the mission ended prematurely, it sent back valuable data about Phobos.",
      "date": "1988"
    },
    {
      "headline": "Mars Global Surveyor Observations",
      "text": "In 1998, NASA's Mars Global Surveyor captured high-resolution images of Phobos, revealing new details about its surface and geological history.",
      "date": "1998"
    },
    {
      "headline": "Mars Express Close Flybys",
      "text": "The European Space Agency's Mars Express spacecraft conducted several close flybys of Phobos starting in 2004, providing detailed data on its composition and structure.",
      "date": "2004"
    },
    {
      "headline": "Phobos-Grunt Mission Attempt",
      "text": "In 2011, Russia launched the Phobos-Grunt mission to return samples from Phobos. However, the mission failed to leave Earth's orbit and was eventually lost.",
      "date": "2011"
    }
  ]
}

