{
  "timeline": [
    {
      "headline": "Introduction of BIOS",
      "text": "The term BIOS (Basic Input/Output System) was first coined by Gary Kildall in 1975. It was used in the CP/M operating system to describe the machine-specific part of CP/M loaded during boot time that interfaces directly with the hardware.",
      "date": "1975"
    },
    {
      "headline": "IBM PC and BIOS",
      "text": "In 1981, IBM introduced the IBM PC, which included a BIOS as part of its firmware. This BIOS was responsible for booting the computer and providing a standard interface for the operating system to interact with the hardware.",
      "date": "1981"
    },
    {
      "headline": "Introduction of the AT BIOS",
      "text": "In 1984, IBM released the IBM PC/AT, which featured an updated BIOS. This version of the BIOS added support for the new hardware capabilities of the AT, including the 80286 processor.",
      "date": "1984"
    },
    {
      "headline": "Phoenix Technologies and Cloning of BIOS",
      "text": "In 1984, Phoenix Technologies released a legally reverse-engineered version of the IBM BIOS, which allowed other companies to produce IBM PC-compatible computers without infringing on IBM's copyrights.",
      "date": "1984"
    },
    {
      "headline": "Introduction of Plug and Play BIOS",
      "text": "In 1995, the Plug and Play BIOS was introduced, which allowed the BIOS to automatically configure hardware devices and allocate resources without user intervention.",
      "date": "1995"
    },
    {
      "headline": "Transition to UEFI",
      "text": "In the early 2000s, the Unified Extensible Firmware Interface (UEFI) began to replace the traditional BIOS. UEFI provides a more modern and flexible interface between the operating system and the platform firmware.",
      "date": "2000"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Ancient Egyptian Embalming Practices",
      "text": "The ancient Egyptians developed embalming techniques as early as 2600 BCE. They believed in preserving the body for the afterlife, leading to the creation of mummies. The process involved removing internal organs, treating the body with natron, and wrapping it in linen.",
      "date": "-2600"
    },
    {
      "headline": "Embalming in Ancient China",
      "text": "In ancient China, embalming practices were used during the Han Dynasty (206 BCE – 220 CE). The Chinese used mercury and other substances to preserve bodies, as evidenced by the well-preserved remains found in tombs.",
      "date": "-0206"
    },
    {
      "headline": "Embalming in Ancient Peru",
      "text": "The Chinchorro culture in present-day Chile and Peru practiced mummification as early as 5000 BCE. They are known for creating some of the oldest artificially mummified human remains.",
      "date": "-5000"
    },
    {
      "headline": "Medieval European Embalming",
      "text": "During the Middle Ages, embalming was practiced in Europe primarily for royalty and the wealthy. Techniques were less advanced than those in ancient Egypt, often involving evisceration and the use of spices and alcohol.",
      "date": "1000"
    },
    {
      "headline": "Renaissance Advances in Embalming",
      "text": "The Renaissance period saw advancements in embalming techniques, with figures like Leonardo da Vinci experimenting with injecting wax and other substances into veins to preserve bodies for anatomical study.",
      "date": "1500"
    },
    {
      "headline": "Modern Embalming Techniques Developed",
      "text": "In the 19th century, modern embalming techniques were developed, particularly during the American Civil War (1861-1865), to preserve soldiers' bodies for transport home. Dr. Thomas Holmes is often credited with popularizing embalming in the United States.",
      "date": "1861"
    },
    {
      "headline": "Embalming Becomes Standard Practice",
      "text": "By the late 19th and early 20th centuries, embalming became a standard practice in the funeral industry in the United States and other Western countries, with formaldehyde becoming the primary preservative used.",
      "date": "1900"
    }
  ]
}

