{
  "timeline": [
    {
      "headline": "Executive Order 13769 Issued",
      "text": "On January 27, 2017, U.S. President Donald Trump signed Executive Order 13769, titled 'Protecting the Nation from Foreign Terrorist Entry into the United States.' This order restricted entry into the United States for citizens from seven predominantly Muslim countries: Iran, Iraq, Libya, Somalia, Sudan, Syria, and Yemen.",
      "date": "2017-01-27"
    },
    {
      "headline": "Nationwide Protests and Legal Challenges",
      "text": "Following the issuance of Executive Order 13769, widespread protests erupted across the United States, particularly at major airports. Legal challenges were quickly filed against the order, arguing that it was discriminatory and unconstitutional.",
      "date": "2017-01-28"
    },
    {
      "headline": "Federal Judge Blocks Parts of the Ban",
      "text": "On February 3, 2017, a federal judge in Seattle, James Robart, issued a temporary restraining order that blocked key parts of Executive Order 13769, effectively halting its enforcement nationwide.",
      "date": "2017-02-03"
    },
    {
      "headline": "Executive Order 13780 Issued",
      "text": "In response to legal challenges, President Trump signed a revised travel ban, Executive Order 13780, on March 6, 2017. This order removed Iraq from the list of affected countries and made other changes to address legal concerns.",
      "date": "2017-03-06"
    },
    {
      "headline": "Supreme Court Allows Partial Enforcement",
      "text": "On June 26, 2017, the U.S. Supreme Court allowed parts of Executive Order 13780 to go into effect, pending a full hearing in October. The court allowed the government to enforce the travel ban on individuals from the affected countries who did not have a bona fide relationship with a person or entity in the United States.",
      "date": "2017-06-26"
    },
    {
      "headline": "Presidential Proclamation 9645 Issued",
      "text": "On September 24, 2017, President Trump issued Presidential Proclamation 9645, which replaced the previous travel bans with a new set of restrictions. This proclamation added Chad, North Korea, and certain Venezuelan officials to the list of affected countries, while removing Sudan.",
      "date": "2017-09-24"
    },
    {
      "headline": "Supreme Court Upholds Travel Ban",
      "text": "On June 26, 2018, the U.S. Supreme Court upheld Presidential Proclamation 9645 in a 5-4 decision, ruling that the travel ban was within the president's authority to impose.",
      "date": "2018-06-26"
    }
  ]
}

