{
  "timeline": [
    {
      "headline": "End of the War of 1812",
      "text": "The War of 1812 concluded in 1815, marking the beginning of the Antebellum South era. This period was characterized by the expansion of slavery and the entrenchment of Southern societal norms.",
      "date": "1815"
    },
    {
      "headline": "Missouri Compromise",
      "text": "In 1820, the Missouri Compromise was enacted, admitting Missouri as a slave state and Maine as a free state, maintaining the balance of power between North and South in the U.S. Senate.",
      "date": "1820"
    },
    {
      "headline": "Nat Turner's Rebellion",
      "text": "In August 1831, Nat Turner led a slave rebellion in Southampton County, Virginia. The rebellion resulted in the deaths of approximately 60 white people and led to harsher laws against enslaved people.",
      "date": "1831-08"
    },
    {
      "headline": "Nullification Crisis",
      "text": "The Nullification Crisis occurred in 1832-1833 when South Carolina declared that federal tariffs were unconstitutional and therefore null and void within the state. This crisis highlighted the tension between state and federal authority.",
      "date": "1832"
    },
    {
      "headline": "Texas Annexation",
      "text": "In 1845, the Republic of Texas was annexed into the United States as a slave state, further intensifying the sectional conflict over the expansion of slavery.",
      "date": "1845"
    },
    {
      "headline": "Mexican-American War",
      "text": "The Mexican-American War (1846-1848) resulted in the U.S. acquiring territories in the southwest, raising questions about the extension of slavery into new territories.",
      "date": "1846"
    },
    {
      "headline": "Compromise of 1850",
      "text": "The Compromise of 1850 included measures such as admitting California as a free state and enacting a stricter Fugitive Slave Law, attempting to ease tensions between North and South.",
      "date": "1850"
    },
    {
      "headline": "Kansas-Nebraska Act",
      "text": "In 1854, the Kansas-Nebraska Act allowed territories to decide on the legality of slavery through popular sovereignty, leading to violent conflict known as 'Bleeding Kansas.'",
      "date": "1854"
    },
    {
      "headline": "Dred Scott Decision",
      "text": "In 1857, the U.S. Supreme Court ruled in Dred Scott v. Sandford that African Americans were not U.S. citizens and that Congress could not prohibit slavery in the territories.",
      "date": "1857"
    },
    {
      "headline": "John Brown's Raid on Harpers Ferry",
      "text": "In October 1859, abolitionist John Brown led a raid on the federal armory at Harpers Ferry, Virginia, intending to start a slave uprising. The raid heightened tensions between North and South.",
      "date": "1859-10"
    },
    {
      "headline": "Election of Abraham Lincoln",
      "text": "In November 1860, Abraham Lincoln was elected as the 16th President of the United States. His election prompted Southern states to begin seceding from the Union.",
      "date": "1860-11"
    },
    {
      "headline": "Start of the American Civil War",
      "text": "The American Civil War began on April 12, 1861, when Confederate forces fired on Fort Sumter in South Carolina, marking the end of the Antebellum South era.",
      "date": "1861-04-12"
    }
  ]
}

