{
  "timeline": [
    {
      "headline": "Formation of the Dixiecrat Party",
      "text": "In 1948, the States' Rights Democratic Party, commonly known as the Dixiecrat Party, was formed as a segregationist political party in the United States. It arose due to a Southern regional split in opposition to the national Democratic Party's civil rights platform.",
      "date": "1948"
    },
    {
      "headline": "1948 Democratic National Convention Walkout",
      "text": "On July 17, 1948, Southern delegates walked out of the Democratic National Convention in Philadelphia in protest of the party's civil rights platform, which supported racial integration and civil rights for African Americans.",
      "date": "1948-07-17"
    },
    {
      "headline": "Nomination of Strom Thurmond",
      "text": "On July 17, 1948, the Dixiecrat Party nominated Governor Strom Thurmond of South Carolina as their presidential candidate and Governor Fielding L. Wright of Mississippi as his running mate.",
      "date": "1948-07-17"
    },
    {
      "headline": "1948 Presidential Election",
      "text": "In the 1948 presidential election, held on November 2, 1948, the Dixiecrat ticket of Strom Thurmond and Fielding L. Wright won 39 electoral votes from four Southern states: Alabama, Louisiana, Mississippi, and South Carolina.",
      "date": "1948-11-02"
    },
    {
      "headline": "Dissolution of the Dixiecrat Party",
      "text": "After the 1948 election, the Dixiecrat Party dissolved as a formal organization. Many of its members returned to the Democratic Party, while others eventually joined the Republican Party as the political landscape in the South shifted.",
      "date": "1948"
    }
  ]
}

