    {
      "headline": "Independence of Malaya",
      "text": "On August 31, 1957, the Federation of Malaya gained independence from British rule, and the flag was raised at Merdeka Square in Kuala Lumpur to mark the occasion.",
      "date": "1957-08-31"
    },
    {
      "headline": "Formation of Malaysia",
      "text": "On September 16, 1963, the Federation of Malaya, North Borneo, Sarawak, and Singapore merged to form Malaysia. The flag was modified to include 14 stripes and a 14-point star to represent the new states.",
      "date": "1963-09-16"
    },
    {
      "headline": "Singapore's Separation",
      "text": "On August 9, 1965, Singapore separated from Malaysia to become an independent country. Despite this, the flag of Malaysia remained unchanged with 14 stripes and a 14-point star.",
