{
  "timeline": [
    {
      "headline": "Formation of Early Freikorps",
      "text": "The first so-called Freikorps were formed in the 18th century in German-speaking countries. These units were composed of native volunteers, enemy renegades, and deserters, serving as infantry and cavalry.",
      "date": "1700"
    },
    {
      "headline": "Freikorps in the Seven Years' War",
      "text": "During the Seven Years' War (1756–1763), Freikorps units were used extensively by the Prussian army. They were known for their flexibility and ability to conduct irregular warfare.",
      "date": "1756"
    },
    {
      "headline": "Von Kleist Freikorps",
      "text": "The Prussian von Kleist Freikorps, formed during the Seven Years' War, included a mix of infantry, jäger, dragoons, and hussars, showcasing the diverse composition of these units.",
      "date": "1759"
    },
    {
      "headline": "Freikorps in the Napoleonic Wars",
      "text": "Freikorps units were re-established during the Napoleonic Wars (1803–1815) to fight against Napoleon's forces. They played a significant role in the German campaign against French occupation.",
      "date": "1803"
    },
    {
      "headline": "Lützow Free Corps",
      "text": "One of the most famous Freikorps during the Napoleonic Wars was the Lützow Free Corps, formed in 1813. It was composed of volunteers from all over Germany and became a symbol of German nationalism.",
      "date": "1813"
    },
    {
      "headline": "Post-World War I Freikorps",
      "text": "After World War I, Freikorps units were reformed in Germany. They were used by the Weimar Republic to suppress communist uprisings and were involved in various political conflicts during the early 1920s.",
      "date": "1918"
    },
    {
      "headline": "Kapp Putsch",
      "text": "In March 1920, Freikorps units participated in the Kapp Putsch, an attempted coup against the Weimar Republic. The coup failed, but it highlighted the political instability in post-war Germany.",
      "date": "1920-03"
    },
    {
      "headline": "Disbandment of Freikorps",
      "text": "By the mid-1920s, most Freikorps units were disbanded as the Weimar Republic sought to stabilize and consolidate its power. Many former members joined other paramilitary organizations.",
      "date": "1925"
    }
  ]
}

