{
  "timeline": [
    {
      "headline": "Publication of 'Master and Commander'",
      "text": "The first novel in the Aubrey–Maturin series, 'Master and Commander', was published in 1969. It introduces the main characters, Captain Jack Aubrey and Stephen Maturin, and sets the stage for their adventures during the Napoleonic Wars.",
      "date": "1969"
    },
    {
      "headline": "Publication of 'Post Captain'",
      "text": "The second novel in the series, 'Post Captain', was published in 1972. It continues the story of Aubrey and Maturin as they navigate the challenges of naval warfare and personal relationships.",
      "date": "1972"
    },
    {
      "headline": "Publication of 'H.M.S. Surprise'",
      "text": "The third novel, 'H.M.S. Surprise', was published in 1973. It follows Aubrey and Maturin on a mission to the East Indies, further developing their friendship and adventures.",
      "date": "1973"
    },
    {
      "headline": "Publication of 'The Mauritius Command'",
      "text": "Published in 1977, 'The Mauritius Command' is the fourth novel in the series. It details Aubrey's command of a squadron in the Indian Ocean and the strategic battles against the French.",
      "date": "1977"
    },
    {
      "headline": "Publication of 'Desolation Island'",
      "text": "The fifth novel, 'Desolation Island', was published in 1978. It features a perilous voyage to Australia and introduces new challenges for Aubrey and Maturin.",
      "date": "1978"
    },
    {
      "headline": "Publication of 'The Fortune of War'",
      "text": "Published in 1979, 'The Fortune of War' is the sixth novel in the series. It covers the War of 1812 and Aubrey's capture by the Americans.",
      "date": "1979"
    },
    {
      "headline": "Publication of 'The Surgeon's Mate'",
      "text": "The seventh novel, 'The Surgeon's Mate', was published in 1980. It continues the story of Aubrey and Maturin as they return to England and face new adventures.",
      "date": "1980"
    },
    {
      "headline": "Publication of 'The Ionian Mission'",
      "text": "Published in 1981, 'The Ionian Mission' is the eighth novel in the series. It follows Aubrey and Maturin as they engage in diplomatic and naval missions in the Mediterranean.",
      "date": "1981"
    },
    {
      "headline": "Publication of 'Treason's Harbour'",
      "text": "The ninth novel, 'Treason's Harbour', was published in 1983. It involves espionage and intrigue in the Mediterranean, with Maturin playing a key role.",
      "date": "1983"
    },
    {
      "headline": "Publication of 'The Far Side of the World'",
      "text": "Published in 1984, 'The Far Side of the World' is the tenth novel in the series. It features a long voyage to the Pacific Ocean and encounters with American ships.",
      "date": "1984"
    },
    {
      "headline": "Publication of 'The Reverse of the Medal'",
      "text": "The eleventh novel, 'The Reverse of the Medal', was published in 1986. It deals with Aubrey's legal troubles and the impact on his career.",
      "date": "1986"
    },
    {
      "headline": "Publication of 'The Letter of Marque'",
      "text": "Published in 1988, 'The Letter of Marque' is the twelfth novel in the series. It follows Aubrey as he seeks to restore his reputation and fortune.",
      "date": "1988"
    },
    {
      "headline": "Publication of 'The Thirteen-Gun Salute'",
      "text": "The thirteenth novel, 'The Thirteen-Gun Salute', was published in 1989. It features diplomatic missions and naval engagements in Southeast Asia.",
      "date": "1989"
    },
    {
      "headline": "Publication of 'The Nutmeg of Consolation'",
      "text": "Published in 1991, 'The Nutmeg of Consolation' is the fourteenth novel in the series. It continues the adventures of Aubrey and Maturin in the South China Sea.",
      "date": "1991"
    },
    {
      "headline": "Publication of 'The Truelove'",
      "text": "The fifteenth novel, 'The Truelove', was published in 1992. It involves a voyage to the South Pacific and the challenges faced by the crew.",
      "date": "1992"
    },
    {
      "headline": "Publication of 'The Wine-Dark Sea'",
      "text": "Published in 1993, 'The Wine-Dark Sea' is the sixteenth novel in the series. It features a journey to South America and encounters with revolutionary forces.",
      "date": "1993"
    },
    {
      "headline": "Publication of 'The Commodore'",
      "text": "The seventeenth novel, 'The Commodore', was published in 1994. It follows Aubrey's promotion and his command of a squadron in the Atlantic.",
      "date": "1994"
    },
    {
      "headline": "Publication of 'The Yellow Admiral'",
      "text": "Published in 1996, 'The Yellow Admiral' is the eighteenth novel in the series. It deals with Aubrey's struggles with promotion and the politics of the Admiralty.",
      "date": "1996"
    },
    {
      "headline": "Publication of 'The Hundred Days'",
      "text": "The nineteenth novel, 'The Hundred Days', was published in 1998. It covers the final phase of the Napoleonic Wars and Aubrey's crucial missions.",
      "date": "1998"
    },
    {
      "headline": "Publication of 'Blue at the Mizzen'",
      "text": "The twentieth and final completed novel, 'Blue at the Mizzen', was published in 1999. It concludes the series with Aubrey's post-war career and Maturin's personal life.",
