{
  "timeline": [
    {
      "headline": "Publication of 'An Essay on the Principle of Population'",
      "text": "In 1798, Thomas Robert Malthus published 'An Essay on the Principle of Population', which introduced the theory of Malthusianism. Malthus argued that population growth is potentially exponential while the growth of the food supply or other resources is linear.",
      "date": "1798"
    },
    {
      "headline": "Second Edition of Malthus's Essay",
      "text": "In 1803, Malthus published the second edition of his essay, which expanded on his original ideas and included responses to critics. This edition further solidified the foundation of Malthusian theory.",
      "date": "1803"
    },
    {
      "headline": "Influence on Charles Darwin",
      "text": "In the 1830s, Charles Darwin read Malthus's essay, which influenced his development of the theory of natural selection. Darwin applied Malthusian concepts of competition and survival to biological evolution.",
      "date": "1830"
    },
    {
      "headline": "Neo-Malthusian Movement",
      "text": "In the late 19th and early 20th centuries, the Neo-Malthusian movement emerged, advocating for population control through contraception to prevent the Malthusian catastrophe.",
      "date": "1900"
    },
    {
      "headline": "The Population Bomb",
      "text": "In 1968, Paul R. Ehrlich published 'The Population Bomb', which warned of mass starvation due to overpopulation and advocated for immediate action to limit population growth, echoing Malthusian concerns.",
      "date": "1968"
    },
    {
      "headline": "Club of Rome Report",
      "text": "In 1972, the Club of Rome published 'The Limits to Growth', a report that used computer simulations to predict the consequences of unchecked population growth and resource depletion, aligning with Malthusian theory.",
      "date": "1972"
    },
    {
      "headline": "Criticism and Debate",
      "text": "Throughout the late 20th and early 21st centuries, Malthusianism faced criticism and debate, with opponents arguing that technological advances and improved agricultural methods could prevent the predicted catastrophes.",
      "date": "2000"
    }
  ]
}

