{
  "timeline": [
    {
      "headline": "Archaic Period",
      "text": "Pederasty in ancient Greece is believed to have emerged during the Archaic period, which spans from approximately 800 BCE to 480 BCE. This period saw the establishment of social structures and practices that included pederastic relationships.",
      "date": "-0800"
    },
    {
      "headline": "Classical Period",
      "text": "The practice of pederasty continued into the Classical period, which lasted from around 480 BCE to 323 BCE. During this time, pederasty was integrated into the educational and social systems of many Greek city-states.",
      "date": "-0480"
    },
    {
      "headline": "Role in Education",
      "text": "In many Greek city-states, pederastic relationships were part of the educational system, where the older male (erastes) would mentor the younger male (eromenos) in various subjects, including philosophy, politics, and warfare.",
      "date": "-0480"
    },
    {
      "headline": "Cultural Significance",
      "text": "Pederasty held cultural significance in ancient Greece, being depicted in art and literature. It was considered an important aspect of social and educational life, influencing the development of young men.",
      "date": "-0480"
    },
    {
      "headline": "Philosophical Discussions",
      "text": "Philosophers like Plato discussed pederasty in their works, notably in dialogues such as 'Symposium' and 'Phaedrus', where the nature of love and relationships were explored.",
      "date": "-0380"
    },
    {
      "headline": "Hellenistic Period",
      "text": "During the Hellenistic period (323 BCE to 31 BCE), the practice of pederasty began to decline as Greek culture spread and mixed with other cultures following the conquests of Alexander the Great.",
      "date": "-0323"
    },
    {
      "headline": "Roman Influence",
      "text": "As Rome expanded its influence over Greece, Roman cultural norms began to replace Greek practices, leading to a further decline in the practice of pederasty.",
      "date": "-0146"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Emergence of Command-line Interfaces",
      "text": "Command-line interfaces (CLIs) began to emerge in the mid-1960s as a means of interacting with computer programs by inputting lines of text called command lines. This development occurred on computer terminals, offering an interactive and more user-friendly alternative to the non-interactive interface available with punched cards.",
      "date": "1965"
    },
    {
      "headline": "Introduction of Unix Shell",
      "text": "In 1971, the Unix operating system introduced a command-line interface known as the Unix shell. This became a foundational element for many subsequent command-line interfaces.",
      "date": "1971"
    },
    {
      "headline": "Development of MS-DOS",
      "text": "Microsoft released MS-DOS in 1981, which became one of the most widely used command-line interfaces for personal computers during the 1980s and early 1990s.",
      "date": "1981"
    },
    {
      "headline": "Introduction of Bash",
      "text": "In 1989, the Bourne Again SHell (Bash) was released as a free software replacement for the Bourne shell. Bash became the default shell on many Linux distributions and macOS.",
      "date": "1989"
    },
    {
      "headline": "Windows Command Prompt",
      "text": "The Windows Command Prompt, a command-line interface for Windows operating systems, was introduced with Windows NT in 1993. It provided a way to execute commands and scripts.",
      "date": "1993"
    },
    {
      "headline": "Introduction of PowerShell",
      "text": "Microsoft introduced PowerShell in 2006 as a task automation and configuration management framework, consisting of a command-line shell and associated scripting language.",
      "date": "2006"
    },
    {
      "headline": "Windows Subsystem for Linux (WSL)",
      "text": "In 2016, Microsoft introduced the Windows Subsystem for Linux (WSL), allowing users to run a GNU/Linux environment directly on Windows, including most command-line tools, utilities, and applications.",
      "date": "2016"
    }
  ]
}

