    {
      "headline": "Birth of Ivan Pavlov",
      "text": "Ivan Petrovich Pavlov was born on September 26, 1849, in Ryazan, Russian Empire.",
      "date": "1849-09-26"
    },
    {
      "headline": "Graduation from University of Saint Petersburg",
      "text": "In 1875, Pavlov graduated from the University of Saint Petersburg with a degree in natural sciences.",
      "date": "1875"
    },
    {
      "headline": "Marriage to Seraphima Vasilievna Karchevskaya",
      "text": "In 1881, Pavlov married Seraphima Vasilievna Karchevskaya, a teacher and daughter of a doctor.",
      "date": "1881"
    },
    {
      "headline": "Completion of Doctoral Thesis",
      "text": "In 1883, Pavlov completed his doctoral thesis on the subject of 'The centrifugal nerves of the heart'.",
      "date": "1883"
    },
    {
      "headline": "Appointment as Professor at the Institute of Experimental Medicine",
      "text": "In 1890, Pavlov was appointed as a professor of pharmacology at the Institute of Experimental Medicine in Saint Petersburg.",
      "date": "1890"
    },
    {
      "headline": "Discovery of Classical Conditioning",
      "text": "In the early 1900s, Pavlov discovered the concept of classical conditioning through his experiments with dogs, which demonstrated the conditioned reflex.",
      "date": "1900"
    },
    {
      "headline": "Nobel Prize in Physiology or Medicine",
      "text": "In 1904, Ivan Pavlov was awarded the Nobel Prize in Physiology or Medicine for his research on the physiology of the digestive system.",
      "date": "1904"
    },
    {
      "headline": "Publication of 'Conditioned Reflexes'",
      "text": "In 1927, Pavlov published his book 'Conditioned Reflexes', which detailed his research and findings on classical conditioning.",
      "date": "1927"
    },
    {
      "headline": "Death of Ivan Pavlov",
      "text": "Ivan Pavlov died on February 27, 1936, in Leningrad, Soviet Union.",
      "date": "1936-02-27"
    }
  ]
}

