{
  "timeline": [
    {
      "headline": "Birth of Imhotep",
      "text": "Imhotep was born in the 27th century BCE, during the Third Dynasty of Egypt. The exact date of his birth is unknown.",
      "date": "-02700"
    },
    {
      "headline": "Service under Pharaoh Djoser",
      "text": "Imhotep served as chancellor to Pharaoh Djoser, who reigned from approximately 2670 to 2640 BCE. During this time, Imhotep was a key advisor and administrator.",
      "date": "-02670"
    },
    {
      "headline": "Architect of the Step Pyramid",
      "text": "Imhotep is credited with designing the Step Pyramid at Saqqara, which is considered to be the earliest colossal stone building in Egypt and the first large-scale cut stone construction. This occurred during Djoser's reign, around 2667-2648 BCE.",
      "date": "-02667"
    },
    {
      "headline": "High Priest of Ra at Heliopolis",
      "text": "Imhotep served as the high priest of the sun god Ra at Heliopolis, one of the most important religious centers in ancient Egypt. His exact tenure is not precisely dated but occurred during his lifetime in the 27th century BCE.",
      "date": "-02700"
    },
    {
      "headline": "Death of Imhotep",
      "text": "Imhotep died in the 27th century BCE. The exact date of his death is unknown.",
      "date": "-02700"
    },
    {
      "headline": "Deification of Imhotep",
      "text": "In the 3,000 years following his death, Imhotep was gradually glorified and deified, becoming a god of medicine and healing in the Egyptian pantheon. This process began in the New Kingdom, around the 16th century BCE.",
      "date": "-01500"
    }
  ]
}

