      "headline": "Discovery by Europeans",
      "text": "In 1520, the Portuguese explorer Ferdinand Magellan became the first European to discover the archipelago during his expedition to circumnavigate the globe.",
      "date": "1520"
    },
    {
      "headline": "Naming of Tierra del Fuego",
      "text": "The archipelago was named 'Tierra del Fuego' (Land of Fire) by Ferdinand Magellan in 1520, due to the numerous fires seen along the coast, which were made by the indigenous people.",
      "date": "1520"
    },
    {
      "headline": "First European Settlement",
      "text": "In 1883, the first European settlement was established in Tierra del Fuego by the Anglican missionary Thomas Bridges, who founded Ushuaia.",
      "date": "1883"
    },
    {
      "headline": "Gold Rush",
      "text": "In the late 19th century, a gold rush occurred in Tierra del Fuego, attracting many settlers and prospectors to the region.",
      "date": "1890"
    },
    {
      "headline": "Division of the Archipelago",
      "text": "In 1881, the archipelago was divided between Argentina and Chile through a treaty, with the eastern part going to Argentina and the western part to Chile.",
      "date": "1881"
    },
    {
      "headline": "Creation of Tierra del Fuego Province",
      "text": "In 1990, the Argentine part of the archipelago was established as the Province of Tierra del Fuego, Antártida e Islas del Atlántico Sur.",
      "date": "1990"
    }
  ]
}

