{
  "timeline": [
    {
      "headline": "Birth of Twelver Shīʿism",
      "text": "Twelver Shīʿism began to form as a distinct sect of Shīʿa Islam following the death of the Prophet Muhammad in 632 CE, as followers believed in a line of twelve divinely ordained leaders, starting with Ali ibn Abi Talib.",
      "date": "0632"
    },
    {
      "headline": "First Imam: Ali ibn Abi Talib",
      "text": "Ali ibn Abi Talib, cousin and son-in-law of Prophet Muhammad, is recognized as the first Imam by Twelver Shīʿas. He became the fourth caliph in 656 CE and was assassinated in 661 CE.",
      "date": "0656"
    },
    {
      "headline": "Second Imam: Hasan ibn Ali",
      "text": "Hasan ibn Ali, the eldest son of Ali, became the second Imam in 661 CE. He abdicated the caliphate to Muawiya I in 661 CE and died in 670 CE.",
      "date": "0661"
    },
    {
      "headline": "Third Imam: Husayn ibn Ali",
      "text": "Husayn ibn Ali, the younger son of Ali, became the third Imam in 670 CE. He was martyred at the Battle of Karbala on October 10, 680 CE, a pivotal event in Shīʿa history.",
      "date": "0680-10-10"
    },
    {
      "headline": "Fourth Imam: Ali Zayn al-Abidin",
      "text": "Ali Zayn al-Abidin, son of Husayn, became the fourth Imam after the death of his father in 680 CE. He is known for his piety and the compilation of prayers known as Sahifa Sajjadiyya.",
      "date": "0680"
    },
    {
      "headline": "Fifth Imam: Muhammad al-Baqir",
      "text": "Muhammad al-Baqir, son of Ali Zayn al-Abidin, became the fifth Imam in 713 CE. He is credited with laying the foundation for the development of Shīʿa jurisprudence.",
      "date": "0713"
    },
    {
      "headline": "Sixth Imam: Ja'far al-Sadiq",
      "text": "Ja'far al-Sadiq, son of Muhammad al-Baqir, became the sixth Imam in 733 CE. He is a significant figure in Shīʿa Islam for his contributions to theology and jurisprudence.",
      "date": "0733"
    },
    {
      "headline": "Seventh Imam: Musa al-Kadhim",
      "text": "Musa al-Kadhim, son of Ja'far al-Sadiq, became the seventh Imam in 765 CE. He spent much of his life imprisoned by the Abbasid caliphs and died in 799 CE.",
      "date": "0765"
    },
    {
      "headline": "Eighth Imam: Ali al-Ridha",
      "text": "Ali al-Ridha, son of Musa al-Kadhim, became the eighth Imam in 799 CE. He was appointed as the successor to the Abbasid caliph al-Ma'mun but died in 818 CE.",
      "date": "0799"
    },
    {
      "headline": "Ninth Imam: Muhammad al-Taqi",
      "text": "Muhammad al-Taqi, son of Ali al-Ridha, became the ninth Imam in 818 CE. He was known for his knowledge and piety despite his young age.",
      "date": "0818"
    },
    {
      "headline": "Tenth Imam: Ali al-Hadi",
      "text": "Ali al-Hadi, son of Muhammad al-Taqi, became the tenth Imam in 835 CE. He lived under house arrest in Samarra by the Abbasid caliphs.",
      "date": "0835"
    },
    {
      "headline": "Eleventh Imam: Hasan al-Askari",
      "text": "Hasan al-Askari, son of Ali al-Hadi, became the eleventh Imam in 868 CE. He also lived under house arrest and died in 874 CE.",
      "date": "0868"
    },
    {
      "headline": "Twelfth Imam: Muhammad al-Mahdi",
      "text": "Muhammad al-Mahdi, son of Hasan al-Askari, became the twelfth Imam in 874 CE. He is believed to have gone into Occultation and will reappear as the Mahdi.",
      "date": "0874"
    },
    {
      "headline": "The Greater Occultation",
      "text": "The Greater Occultation began in 941 CE, marking the period when the Twelfth Imam, Muhammad al-Mahdi, is believed to be in hiding and will reappear at the end of times.",
      "date": "0941"
    }
  ]
}

