{
  "timeline": [
    {
      "headline": "Birth of Yudhishthira",
      "text": "Yudhishthira was born to Kunti and Pandu, the king of Hastinapura, through the blessings of the god Dharma. His birth is celebrated as the eldest of the Pandavas.",
      "date": "-0319"
    },
    {
      "headline": "Yudhishthira's Education",
      "text": "Yudhishthira, along with his brothers, received education in various subjects including warfare, administration, and dharma under the guidance of their teacher Drona.",
      "date": "-0305"
    },
    {
      "headline": "Yudhishthira Crowned as Crown Prince",
      "text": "Yudhishthira was appointed as the crown prince of Hastinapura due to his virtues and adherence to dharma.",
      "date": "-0300"
    },
    {
      "headline": "Establishment of Indraprastha",
      "text": "Yudhishthira, along with his brothers, established the city of Indraprastha after a division of the Kuru kingdom.",
      "date": "-0295"
    },
    {
      "headline": "Rajasuya Yajna",
      "text": "Yudhishthira performed the Rajasuya Yajna, a grand sacrifice that established him as an emperor and expanded his influence across the Indian subcontinent.",
      "date": "-0290"
    },
    {
      "headline": "Game of Dice",
      "text": "Yudhishthira lost his kingdom, wealth, and even his brothers and wife Draupadi in a game of dice to Duryodhana, leading to their exile.",
      "date": "-0285"
    },
    {
      "headline": "Exile Period",
      "text": "Yudhishthira and his brothers spent 13 years in exile, including one year in incognito, as per the conditions of the dice game.",
      "date": "-0285"
    },
    {
      "headline": "Kurukshetra War",
      "text": "Yudhishthira led the Pandavas in the Kurukshetra War against the Kauravas, which lasted for 18 days and resulted in the victory of the Pandavas.",
      "date": "-0272"
    },
    {
      "headline": "Yudhishthira's Coronation as King of Hastinapura",
      "text": "After the victory in the Kurukshetra War, Yudhishthira was crowned as the king of Hastinapura, marking the beginning of his reign.",
      "date": "-0272"
    },
    {
      "headline": "Ashwamedha Yajna",
      "text": "Yudhishthira performed the Ashwamedha Yajna to establish his sovereignty and ensure peace in his kingdom.",
      "date": "-0270"
    },
    {
      "headline": "Retirement and Journey to the Himalayas",
      "text": "Yudhishthira, along with his brothers and Draupadi, renounced the throne and embarked on a journey to the Himalayas in search of spiritual liberation.",
      "date": "-0260"
    },
    {
      "headline": "Yudhishthira's Ascension to Heaven",
      "text": "Yudhishthira was the only one among his companions to reach the gates of heaven in his mortal form, symbolizing his adherence to dharma throughout his life.",
      "date": "-0255"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Birth of Friedrich Fröbel",
      "text": "Friedrich Fröbel, the German pedagogue who coined the term 'Kindergarten', was born on April 21, 1782.",
      "date": "1782-04-21"
    },
    {
      "headline": "First Kindergarten Established",
      "text": "In 1837, Friedrich Fröbel opened the first Kindergarten in Bad Blankenburg, Germany, introducing a new educational approach focused on play and activity.",
      "date": "1837"
    },
    {
      "headline": "Coining of the Term 'Kindergarten'",
      "text": "In 1840, Friedrich Fröbel coined the term 'Kindergarten', meaning 'children's garden', to describe his educational approach.",
      "date": "1840"
    },
    {
      "headline": "Spread of Kindergarten in Germany",
      "text": "Throughout the 1840s, the concept of Kindergarten began to spread across Germany, gaining popularity for its innovative approach to early childhood education.",
      "date": "1840s"
    },
    {
      "headline": "Introduction of Kindergarten in the United States",
      "text": "In 1856, the first Kindergarten in the United States was established in Watertown, Wisconsin, by Margarethe Schurz, a student of Fröbel.",
      "date": "1856"
    },
    {
      "headline": "First Public Kindergarten in the United States",
      "text": "In 1873, the first public Kindergarten in the United States was opened in St. Louis, Missouri, by Susan Blow.",
      "date": "1873"
    },
    {
      "headline": "Kindergarten Movement in the United States",
      "text": "By the late 19th century, the Kindergarten movement had gained significant momentum in the United States, with many schools adopting Fröbel's methods.",
      "date": "late 1800s"
    },
    {
      "headline": "Global Adoption of Kindergarten",
      "text": "Throughout the 20th century, the Kindergarten model spread globally, becoming an integral part of early childhood education systems in many countries.",
      "date": "1900s"
    }
  ]
}

