{
  "timeline": [
    {
      "headline": "Invention of the First Atomic Clock",
      "text": "The first atomic clock was invented in 1949 at the U.S. National Bureau of Standards (now NIST). It was based on the ammonia molecule.",
      "date": "1949"
    },
    {
      "headline": "Development of the Caesium Atomic Clock",
      "text": "In 1955, Louis Essen and Jack Parry built the first accurate caesium atomic clock at the National Physical Laboratory in the UK.",
      "date": "1955"
    },
    {
      "headline": "Adoption of the Atomic Second",
      "text": "In 1967, the International System of Units (SI) adopted the atomic second, based on the caesium-133 atom, as the standard unit of time.",
      "date": "1967"
    },
    {
      "headline": "Introduction of the Hydrogen Maser",
      "text": "In 1960, the hydrogen maser was introduced, providing a more stable frequency standard than the caesium clock.",
      "date": "1960"
    },
    {
      "headline": "Development of the Rubidium Atomic Clock",
      "text": "In the 1970s, rubidium atomic clocks were developed, offering a smaller and more portable option compared to caesium clocks.",
      "date": "1970"
    },
    {
      "headline": "Launch of GPS Satellites with Atomic Clocks",
      "text": "In 1978, the first GPS satellite was launched, equipped with atomic clocks to provide precise timing for navigation.",
      "date": "1978"
    },
    {
      "headline": "Introduction of Optical Lattice Clocks",
      "text": "In the early 2000s, optical lattice clocks were developed, offering even greater precision by using atoms trapped in a laser grid.",
      "date": "2000"
    },
    {
      "headline": "Advancements in Strontium Optical Clocks",
      "text": "In 2015, strontium optical clocks achieved unprecedented accuracy, with potential applications in redefining the second.",
      "date": "2015"
    }
  ]
}

