      "headline": "Earliest Known World Maps",
      "text": "The earliest known world maps date to classical antiquity, specifically the 6th to 5th centuries BCE. These maps were based on the flat Earth paradigm.",
      "date": "-0600"
    },
    {
      "headline": "Hellenistic Period Maps",
      "text": "World maps assuming a spherical Earth first appear during the Hellenistic period, which began in the late 4th century BCE.",
      "date": "-0323"
    },
    {
      "headline": "Eratosthenes' Contributions",
      "text": "Eratosthenes, a Greek mathematician and geographer, made significant contributions to geography, including calculating the Earth's circumference around 240 BCE.",
      "date": "-0240"
    },
    {
      "headline": "Posidonius' Work",
      "text": "Posidonius, another Greek scholar, further developed geographical knowledge in the 2nd to 1st century BCE, influencing later Roman cartography.",
      "date": "-0100"
    },
    {
      "headline": "Ptolemy's World Map",
      "text": "In the 2nd century CE, Ptolemy created a world map that would remain authoritative throughout the Middle Ages. His work was based on a spherical Earth and included latitude and longitude lines.",
      "date": "0150"
    },
    {
      "headline": "Medieval Cartography",
      "text": "During the Middle Ages, Ptolemy's world map continued to influence cartographers, who used his work to estimate the extent of geographical knowledge and mark unexplored areas as terra incognita.",
      "date": "0500"
    }
  ]
}

{
  "timeline": [
    {
      "headline": "Proposal of Many-Worlds Interpretation",
      "text": "In 1957, physicist Hugh Everett proposed the many-worlds interpretation of quantum mechanics. This interpretation asserts that the universal wavefunction is objectively real and that there is no wave function collapse, implying that all possible outcomes of quantum measurements are physically realized in different 'worlds'.",
      "date": "1957"
    },
    {
      "headline": "Hugh Everett's PhD Thesis",
      "text": "Hugh Everett completed his PhD thesis at Princeton University in 1957, where he introduced the relative state formulation of quantum mechanics, which later became known as the many-worlds interpretation.",
      "date": "1957"
    },
    {
      "headline": "Publication of Everett's Paper",
      "text": "In 1957, Hugh Everett's paper titled 'Relative State Formulation of Quantum Mechanics' was published in the journal 'Reviews of Modern Physics', formally presenting his ideas to the scientific community.",
      "date": "1957"
    },
    {
      "headline": "Bryce DeWitt Popularizes Many-Worlds",
      "text": "In the 1970s, physicist Bryce DeWitt popularized the many-worlds interpretation and coined the term 'many-worlds'. He contributed significantly to the interpretation's acceptance and understanding within the scientific community.",
      "date": "1970"
    },
    {
      "headline": "Publication of 'The Many-Worlds Interpretation of Quantum Mechanics'",
      "text": "In 1973, Bryce DeWitt and Neill Graham published 'The Many-Worlds Interpretation of Quantum Mechanics', a comprehensive book that compiled and expanded upon the ideas of the many-worlds interpretation.",
      "date": "1973"
    }
  ]
}

