      "headline": "First Korean Migration to Russia",
      "text": "The first Koreans began migrating to the Russian Far East in the late 19th century, seeking better economic opportunities and escaping political turmoil in Korea.",
      "date": "1860"
    },
    {
      "headline": "Establishment of Korean Settlements",
      "text": "By the early 20th century, Korean settlements were established in the Russian Far East, particularly in areas like Primorsky Krai.",
      "date": "1900"
    },
    {
      "headline": "Soviet Deportation of Koreans",
      "text": "In 1937, the Soviet government forcibly deported approximately 172,000 ethnic Koreans from the Russian Far East to Central Asia, primarily to Kazakhstan and Uzbekistan, as part of Stalin's ethnic cleansing policies.",
      "date": "1937"
    },
    {
      "headline": "Life in Central Asia",
      "text": "After their deportation, Koryo-saram adapted to life in Central Asia, contributing to agriculture and local economies while maintaining their cultural heritage.",
      "date": "1940"
    },
    {
      "headline": "Post-Soviet Era",
      "text": "Following the dissolution of the Soviet Union in 1991, Koryo-saram faced new challenges and opportunities, with some migrating to South Korea or other countries, while others remained in Central Asia.",
      "date": "1991"
    },
    {
      "headline": "Cultural Revival",
      "text": "In the 21st century, there has been a revival of Koryo-saram culture, with efforts to preserve the Korean language and traditions among younger generations in Central Asia.",
      "date": "2000"
    }
  ]
}

