    {
      "headline": "First Recorded Eruption",
      "text": "The first recorded eruption of Kīlauea occurred in 1823. This marked the beginning of its documented history as one of the most active volcanoes on Earth.",
      "date": "1823"
    },
    {
      "headline": "Halemaʻumaʻu Crater Eruption",
      "text": "In 1924, a significant explosive eruption occurred at Halemaʻumaʻu Crater, which is part of Kīlauea's summit caldera.",
      "date": "1924"
    },
    {
      "headline": "Puʻu ʻŌʻō Eruption Begins",
      "text": "The Puʻu ʻŌʻō eruption began on January 3, 1983, and continued for over three decades, making it one of the longest-lasting eruptions in history.",
      "date": "1983-01-03"
    },
    {
      "headline": "2018 Lower Puna Eruption",
      "text": "In May 2018, a new eruption began in the lower Puna district, causing significant lava flows and destruction of property.",
      "date": "2018-05"
    },
    {
      "headline": "Most Recent Eruption",
      "text": "The most recent eruption of Kīlauea began in December 2024, continuing its activity as one of the world's most active volcanoes.",
      "date": "2024-12"
    }
  ]
}

{
