    {
      "headline": "Formation of the National Party",
      "text": "The National Party was founded on July 1, 1914, by J.B.M. Hertzog as a breakaway from the South African Party, promoting Afrikaner nationalism.",
      "date": "1914-07-01"
    },
    {
      "headline": "First Governing Party",
      "text": "The National Party first became the governing party of South Africa in 1924, forming a coalition with the Labour Party.",
      "date": "1924"
    },
    {
      "headline": "Merger with South African Party",
      "text": "During the Great Depression, the National Party merged with its rival, the South African Party, in 1934 to form the United Party.",
      "date": "1934"
    },
    {
      "headline": "Re-United National Party",
      "text": "A splinter faction, the Re-United National Party, became the official opposition during World War II.",
      "date": "1939"
    },
    {
      "headline": "Victory in 1948 Elections",
      "text": "The National Party won the 1948 general elections, marking the beginning of its long-term governance and the implementation of apartheid policies.",
      "date": "1948-06-04"
    },
    {
      "headline": "Implementation of Apartheid",
      "text": "The National Party implemented apartheid, a system of institutionalized racial segregation and discrimination, starting in 1948.",
      "date": "1948"
    },
    {
      "headline": "End of National Party Rule",
      "text": "The National Party's rule ended on May 9, 1994, following the first multiracial elections in South Africa, which marked the end of apartheid.",
      "date": "1994-05-09"
    },
    {
      "headline": "Rebranding as New National Party",
      "text": "In 1997, the National Party rebranded itself as the New National Party in an attempt to distance itself from its apartheid past.",
      "date": "1997"
    },
    {
      "headline": "Dissolution of the Party",
      "text": "The New National Party dissolved in 2005, marking the end of the political entity originally founded as the National Party.",
      "date": "2005"
    }
  ]
}

