    {
      "headline": "Battle of Leyte Gulf",
      "text": "The Battle of Leyte Gulf, one of the largest naval battles in history, took place from October 23 to 26, 1944, and marked the beginning of the liberation of the Philippines by Allied forces.",
      "date": "1944-10-23"
    },
    {
      "headline": "Liberation of Manila",
      "text": "The Battle of Manila began on February 3, 1945, and ended on March 3, 1945, resulting in the liberation of the city from Japanese occupation.",
      "date": "1945-02-03"
    },
    {
      "headline": "End of Japanese Occupation",
      "text": "The Japanese occupation of the Philippines effectively ended with the surrender of Japanese forces in the Philippines on September 2, 1945, following Japan's official surrender in World War II.",
      "date": "1945-09-02"
    }
  ]
}

