{
  "timeline": [
    {
      "headline": "Discovery of Electromagnetic Induction",
      "text": "In 1831, Michael Faraday discovered electromagnetic induction, demonstrating that a changing magnetic field can induce an electromotive force (emf) in a conductor.",
      "date": "1831"
    },
    {
      "headline": "Faraday's Law of Induction",
      "text": "Michael Faraday formulated Faraday's Law of Induction in 1831, which quantifies the induced electromotive force in any closed circuit due to a changing magnetic field.",
      "date": "1831"
    },
    {
      "headline": "Joseph Henry's Independent Discovery",
      "text": "In 1832, Joseph Henry independently discovered electromagnetic induction and made significant contributions to the understanding of the phenomenon.",
      "date": "1832"
    },
    {
      "headline": "Development of the Dynamo",
      "text": "In the 1860s, the development of the dynamo, a device that converts mechanical energy into electrical energy using electromagnetic induction, marked a significant technological advancement.",
      "date": "1860"
    },
    {
      "headline": "Heinrich Lenz's Contribution",
      "text": "Heinrich Lenz formulated Lenz's Law in 1834, which states that the direction of the induced current will oppose the change in magnetic flux that produced it.",
      "date": "1834"
    },
    {
      "headline": "James Clerk Maxwell's Equations",
      "text": "In 1865, James Clerk Maxwell published his equations, which included the concept of electromagnetic induction as a fundamental principle of electromagnetism.",
      "date": "1865"
    }
  ]
}

