{
  "timeline": [
    {
      "headline": "Domestication of Maize",
      "text": "The Olmec and Maya civilizations domesticated maize, which became a staple food in Mesoamerican cuisine. This process began around 5000 BCE.",
      "date": "-5000"
    },
    {
      "headline": "Development of Nixtamalization",
      "text": "The process of nixtamalization, which involves soaking and cooking maize in an alkaline solution, was developed by early Mesoamerican cultures. This technique improved the nutritional value of maize and made it easier to grind. It is believed to have been developed around 1500 BCE.",
      "date": "-1500"
    },
    {
      "headline": "Influence of Teotihuacanos and Other Cultures",
      "text": "Successive waves of Mesoamerican groups, including the Teotihuacanos, Toltec, Huastec, Zapotec, Mixtec, Otomi, Purépecha, Totonac, Mazatec, Mazahua, and Nahua, contributed their cooking methods and ingredients to the evolving cuisine. This period spans from approximately 100 BCE to 900 CE.",
      "date": "-0100"
    },
    {
      "headline": "Formation of the Triple Alliance",
      "text": "With the formation of the Mexica's multi-ethnic Triple Alliance in 1428, culinary foodways became infused, leading to a rich and diverse cuisine that incorporated elements from various Mesoamerican cultures.",
      "date": "1428"
    },
    {
      "headline": "Spanish Conquest and Introduction of New Ingredients",
      "text": "Following the Spanish conquest of the Aztec Empire in 1521, new ingredients such as rice, beef, pork, chicken, wine, garlic, and onions were introduced to Mexican cuisine, blending with indigenous ingredients and techniques.",
      "date": "1521"
    },
    {
      "headline": "Development of Mestizo Cuisine",
      "text": "The blending of indigenous and Spanish culinary traditions led to the development of Mestizo cuisine, characterized by dishes such as mole, tamales, and tacos. This evolution took place throughout the colonial period, from the 16th to the 19th century.",
      "date": "1600"
    },
    {
      "headline": "Recognition of Mexican Cuisine by UNESCO",
      "text": "In 2010, traditional Mexican cuisine was recognized by UNESCO as an Intangible Cultural Heritage of Humanity, highlighting its cultural significance and historical roots.",
      "date": "2010"
    }
  ]
}

