{
  "timeline": [
    {
      "headline": "Development of ANOVA",
      "text": "The analysis of variance (ANOVA) was developed by the statistician Ronald Fisher. ANOVA is a collection of statistical models and their associated estimation procedures used to analyze the differences among group means.",
      "date": "1920"
    },
    {
      "headline": "Introduction of F-test",
      "text": "ANOVA uses the F-test to compare variance between groups by taking noise, or assumed normal distribution of group, into consideration by dividing by variance between elements in a group.",
      "date": "1920"
    },
    {
      "headline": "ANOVA and the Law of Total Variance",
      "text": "ANOVA is based on the law of total variance, where the observed variance in a particular variable is partitioned into components attributable to different sources of variation.",
      "date": "1920"
    },
    {
      "headline": "Generalization of the t-test",
      "text": "In its simplest form, ANOVA provides a statistical test of whether two or more population means are equal, and therefore generalizes the t-test beyond two means.",
      "date": "1920"
    }
  ]
}

