{
  "timeline": [
    {
      "headline": "Birth of Claude Shannon",
      "text": "Claude Elwood Shannon was born on April 30, 1916, in Petoskey, Michigan, United States.",
      "date": "1916-04-30"
    },
    {
      "headline": "Graduation from University of Michigan",
      "text": "In 1936, Shannon graduated from the University of Michigan with bachelor's degrees in electrical engineering and mathematics.",
      "date": "1936"
    },
    {
      "headline": "Master's Thesis at MIT",
      "text": "In 1940, Shannon completed his master's thesis at the Massachusetts Institute of Technology (MIT), which demonstrated that electrical applications of Boolean algebra could construct any logical, numerical relationship. This work laid the foundation for digital circuit design theory.",
      "date": "1940"
    },
    {
      "headline": "Publication of 'A Mathematical Theory of Communication'",
      "text": "In 1948, Shannon published 'A Mathematical Theory of Communication' in the Bell System Technical Journal, which founded the field of information theory.",
      "date": "1948"
    },
    {
      "headline": "Development of Shannon's Information Theory",
      "text": "Shannon's work in 1948 on information theory established the principles of data compression and reliable data transmission, which are fundamental to telecommunications and computer science.",
      "date": "1948"
    },
    {
      "headline": "Introduction of the Concept of Bit",
      "text": "In 1948, Shannon introduced the concept of the 'bit' as a unit of information, which became a fundamental concept in digital communications and computing.",
      "date": "1948"
    },
    {
      "headline": "Marriage to Betty Shannon",
      "text": "In 1949, Claude Shannon married Betty Shannon, who was also a mathematician and computer scientist.",
      "date": "1949"
    },
    {
      "headline": "Development of the First Wearable Computer",
      "text": "In the 1960s, Shannon developed the first wearable computer, which was used to improve the odds in the game of roulette.",
      "date": "1960"
    },
    {
      "headline": "Retirement from MIT",
      "text": "In 1978, Shannon retired from MIT, where he had been a professor since 1956.",
      "date": "1978"
    },
    {
      "headline": "Death of Claude Shannon",
      "text": "Claude Shannon passed away on February 24, 2001, in Medford, Massachusetts, United States.",
      "date": "2001-02-24"
    }
  ]
}

