{
  "timeline": [
    {
      "headline": "Unification of Hawaiian Islands",
      "text": "In 1795, Kamehameha I, then Aliʻi nui of Hawaii, conquered the islands of Oʻahu, Maui, Molokaʻi, and Lānaʻi, and unified them under one government.",
      "date": "1795"
    },
    {
      "headline": "Voluntary Unification of Kauaʻi and Niʻihau",
      "text": "In 1810, the Hawaiian Islands were fully unified when the islands of Kauaʻi and Niʻihau voluntarily joined the Hawaiian Kingdom.",
      "date": "1810"
    },
    {
      "headline": "Death of Kamehameha I",
      "text": "Kamehameha I died on May 8, 1819, marking the end of his reign and the beginning of his son Liholiho's rule as Kamehameha II.",
      "date": "1819-05-08"
    },
    {
      "headline": "End of Kapu System",
      "text": "In 1819, after the death of Kamehameha I, the traditional kapu system was abolished under the rule of Kamehameha II.",
      "date": "1819"
    },
    {
      "headline": "Arrival of Christian Missionaries",
      "text": "In 1820, the first Christian missionaries arrived in Hawaii, significantly influencing the culture and religion of the Hawaiian Kingdom.",
      "date": "1820"
    },
    {
      "headline": "Constitution of 1840",
      "text": "In 1840, King Kamehameha III promulgated the first constitution of the Hawaiian Kingdom, establishing a constitutional monarchy.",
      "date": "1840"
    },
    {
      "headline": "Recognition of Hawaiian Independence",
      "text": "On November 28, 1843, the United Kingdom and France formally recognized Hawaiian independence, celebrated as Lā Kūʻokoʻa (Independence Day).",
      "date": "1843-11-28"
    },
    {
      "headline": "Great Mahele Land Redistribution",
      "text": "In 1848, the Great Mahele was enacted, redistributing land in Hawaii and transforming the traditional land tenure system.",
      "date": "1848"
    },
    {
      "headline": "Reign of King Kalākaua",
      "text": "King Kalākaua ascended to the throne on February 12, 1874, and his reign was marked by efforts to restore Hawaiian culture and sovereignty.",
      "date": "1874-02-12"
    },
    {
      "headline": "Bayonet Constitution",
      "text": "In 1887, King Kalākaua was forced to sign the Bayonet Constitution, which significantly reduced the monarch's power and increased the influence of foreign interests.",
      "date": "1887"
    },
    {
      "headline": "Overthrow of the Hawaiian Kingdom",
      "text": "On January 17, 1893, the Hawaiian Kingdom was overthrown by a group of American and European businessmen, leading to the establishment of the Republic of Hawaii.",
      "date": "1893-01-17"
    }
  ]
}

