      "headline": "Foundation of Baalbek",
      "text": "Baalbek was originally a Phoenician city, founded as early as the 3rd millennium BCE. It was known as Heliopolis during the Hellenistic period.",
      "date": "-3000"
    },
    {
      "headline": "Hellenistic Period",
      "text": "During the Hellenistic period, Baalbek was known as Heliopolis, meaning 'City of the Sun'.",
      "date": "-0333"
    },
    {
      "headline": "Roman Conquest",
      "text": "In 64 BCE, Baalbek was annexed by the Roman Empire and became a Roman colony under the name Colonia Julia Augusta Felix Heliopolitana.",
      "date": "-0064"
    },
    {
      "headline": "Construction of Roman Temples",
      "text": "Between the 1st and 3rd centuries CE, the Romans constructed grand temples in Baalbek, including the Temple of Jupiter, the Temple of Bacchus, and the Temple of Venus.",
      "date": "0100"
    },
    {
      "headline": "Byzantine Era",
      "text": "After the decline of the Roman Empire, Baalbek became part of the Byzantine Empire. The temples were converted into churches.",
      "date": "0330"
    },
    {
      "headline": "Arab Conquest",
      "text": "In 637 CE, Baalbek was conquered by the Muslim Arabs, and it became part of the Umayyad Caliphate.",
      "date": "0637"
    },
    {
      "headline": "Crusader Period",
      "text": "During the Crusades, Baalbek was captured by the Crusaders in 1139 but was later recaptured by Muslim forces.",
      "date": "1139"
    },
    {
      "headline": "Ottoman Rule",
      "text": "Baalbek became part of the Ottoman Empire in 1516 and remained under Ottoman control until the end of World War I.",
      "date": "1516"
    },
    {
      "headline": "French Mandate",
      "text": "After World War I, Baalbek was included in the French Mandate of Lebanon.",
      "date": "1920"
    },
    {
      "headline": "Independence of Lebanon",
      "text": "In 1943, Lebanon gained independence from France, and Baalbek became part of the newly independent country.",
      "date": "1943"
    },
    {
      "headline": "UNESCO World Heritage Site",
      "text": "In 1984, the ruins of Baalbek were designated as a UNESCO World Heritage Site due to their historical and architectural significance.",
      "date": "1984"
    },
    {
      "headline": "Syrian Refugee Crisis",
      "text": "By 2017, Baalbek had a large presence of Syrian refugees due to the ongoing Syrian Civil War.",
      "date": "2017"
    }
  ]
}

